    int cell_id;
    time_t timestamp;
    double metric_value;
} Metric;

typedef struct {
    pthread_mutex_t lock;
    Metric metrics[MAX_METRICS];
    int num_metrics;
} MetricsContainer;

MetricsContainer *metrics_container = NULL;

void init_metrics_container() {
    if (metrics_container == NULL) {
        metrics_container = malloc(sizeof(MetricsContainer));
        if (metrics_container != NULL) {
            pthread_mutex_init(&metrics_container->lock, NULL);
            metrics_container->num_metrics = 0;
        }
    }
}

int add_metric(int cell_id, double metric_value) {
    time_t current_time = time(NULL);

    // Find the first empty slot in the array
    int i;
    for (i = 0; i < MAX_METRICS; i++) {
        if (metrics_container->metrics[i].cell_id == 0) {
            break;
        }
    }

    if (i >= MAX_METRICS) {
        return -1; // No space available
    }

    metrics_container->metrics[i].cell_id = cell_id;
    metrics_container->metrics[i].timestamp = current_time;
    metrics_container->metrics[i].metric_value = metric_value;

    // Update the number of metrics
    metrics_container->num_metrics++;

    return 0; // Success
}

int get_latest_metric(int cell_id, double *metric_value) {
    int i;
    for (i = 0; i < MAX_METRICS; i++) {
        if (metrics_container->metrics[i].cell_id == cell_id) {
            break;
        }
    }

    if (i >= MAX_METRICS) {
        return -1; // No metric found
    }

    *metric_value = metrics_container->metrics[i].metric_value;

    return 0; // Success
}

int clear_old_metrics() {
    time_t current_time = time(NULL);

    int i;
    for (i = 0; i < MAX_METRICS; i++) {
        if (current_time - metrics_container->metrics[i].timestamp > RETENTION_PERIOD) {
            // Move the metric to the beginning of the array
            metrics_container->metrics[0] = metrics_container->metrics[i];
            // Shift all other metrics down by one position
            for (int j = i; j < MAX_METRICS - 1; j++) {
                metrics_container->metrics[j + 1] = metrics_container->metrics[j];
            }
            // Decrement the number of metrics
            metrics_container->num_metrics--;
        } else {
            break;
        }
    }

    return 0; // Success
}

int submit_metrics_to_api() {
    // Call the external API with the latest metrics

    return 0; // Success
}

void* periodic_submission_thread(void* args) {
    while (1) {
        // Submit metrics to API every 5 minutes
        sleep(300);
        submit_metrics_to_api();
    }
}

int main() {
    init_metrics_container();

    pthread_t thread;
    pthread_create(&thread, NULL, periodic_submission_thread, NULL);

    return 0; // Success
}
