    void (*function)(void);
} Command;

Command commands[] = {
    {"usage", usage},
    {"process_file", process_file},
    {"generate_report", generate_report}
};

int main(int argc, char** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <command>\n", argv[0]);
        return 1;
    }

    for (Command* command : commands) {
        if (!strcmp(command->name, argv[1])) {
            command->function();
            return 0;
        }
    }

    fprintf(stderr, "Unknown command: %s\n", argv[1]);
    return 1;
}

void usage() {
    printf("Usage: %s <command>\n", argv[0]);
    for (Command* command : commands) {
        printf("%-10s %s\n", command->name, command->function == process_file ? "process_file" : command->function == generate_report ? "generate_report" : "usage");
    }
}

void process_file() {
    // code to process file
}

void generate_report() {
    // code to generate report
}

int read_file(const char* filename, char** content) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        return -1;
    }

    struct stat sb;
    fstat(fd, &sb);

    *content = malloc(sb.st_size + 1);
    if (!*content) {
        close(fd);
        return -1;
    }

    read(fd, *content, sb.st_size);
    (*content)[sb.st_size] = '\0';
    close(fd);
    return 0;
}

void send_request(const char* url, CURL* curl) {
    CURLcode res;

    curl_easy_setopt(curl, CURLOPT_URL, url);
    res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
        fprintf(stderr, "cURL error: %s\n", curl_easy_strerror(res));
    }
}

void validate_input(char* input) {
