    while (1) {
        char command[1024];
        fgets(command, 1024, stdin);

        if (strcmp(command, "exit\n") == 0) {
            break;
        }

        // code to handle commands
    }

    curl_easy_cleanup(curl);
}

void log_event(const char* message) {
    FILE* file = fopen("log.txt", "a");
    if (!file) {
        return;
    }

    fprintf(file, "%s\n", message);

    fclose(file);
}
