#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>

#define BUFFER_SIZE 1024
#define PORT 8080
#define MAX_CLIENTS 10

typedef struct {
    int socket;
    pthread_t thread;
} Client;

void *process_request(void *arg) {
    Client *client = (Client *) arg;
    char buffer[BUFFER_SIZE];

    // Receive request from client
    recv(client->socket, buffer, BUFFER_SIZE, 0);

    // Process request and send response
    // ...

    // Send response to client
    send(client->socket, "Response", strlen("Response"), 0);

    close(client->socket); // Close the socket after processing

    return NULL;
}

int main() {
    int server_socket = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (server_socket < 0) {
        perror("Socket creation failed");
        exit(1);
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_address.sin_addr);

    bind(server_socket, (struct sockaddr *) &server_address, sizeof(server_address));
    listen(server_socket, MAX_CLIENTS);

    Client *clients = (Client *) malloc(sizeof(Client) * MAX_CLIENTS);
    int i = 0;
    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_length = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *) &client_address, &client_length);

        if (client_socket < 0) {
            perror("Client connection failed");
            continue;
        }

        clients[i].socket = client_socket;
        pthread_create(&clients[i].thread, NULL, process_request, &clients[i]);
        i++;
    }

    return 0;
}

