import os
import hashlib
import threading
from logging import Logger
from logging.config import dictConfigFromDict
from typing import List

class FileMonitor:
    def __init__(self, root_dir: str, exclusion_criteria: List[str]):
        self.root_dir = root_dir
        self.exclusion_criteria = exclusion_criteria
        self.logger = Logger('file_monitor')
        dictConfigFromDict({
            'version': 1,
            'formatters': {'default': {'format': '%(asctime)s - %(name)s - %(levelname)s - %(message)s'}},
            'handlers': {'file_handler': {'filename': 'monitor.log', 'level': Logger.INFO, 'formatter': 'default'}},
            'loggers': {'file_monitor': {'level': Logger.INFO, 'handlers': ['file_handler']}},
        }, disable_existing_loggers=False)
        self.hash_cache = {}

    def compute_hash(self, file_path: str) -> dict:
        try:
            with open(file_path, 'rb') as file:
                chunk_size = 4096
                chunks = []
                while True:
                    chunk = file.read(chunk_size)
                    if not chunk:
                        break
                    chunks.append(chunk)
                hash_object = hashlib.md5()
                for chunk in chunks:
                    hash_object.update(chunk)
                return {'file_path': file_path, 'hash': hash_object.hexdigest()}
        except Exception as e:
            self.logger.error(f"Error computing hash for {file_path}: {str(e)}")

    def monitor(self):
        while True:
            files = os.listdir(self.root_dir)
            for file in files:
                file_path = os.path.join(self.root_dir, file)
                if not any(file.lower().endswith(exclusion) for exclusion in self.exclusion_criteria):
                    if os.path.isfile(file_path):
                        try:
                            hash_result = self.compute_hash(file_path)
                            self.logger.info(f"File {file_path} modified. Hash: {hash_result['hash']}")
                        except Exception as e:
                            self.logger.error(f"Error processing file {file_path}: {str(e)}")
                    elif os.path.isdir(file_path):
                        t = threading.Thread(target=self.monitor, args=(file_path,))
                        t.start()
            time.sleep(1)

    def run(self):
        self.monitor()

class AsyncFileProcessor(threading.Thread):
    def __init__(self, file_path: str, callback: callable):
        super().__init__()
        self.file_path = file_path
        self.callback = callback

    def run(self):
        try:
            hash_result = self.compute_hash(self.file_path)
            self.callback(hash_result)
        except Exception as e:
            self.logger.error(f"Error processing file {self.file_path}: {str(e)}")

if __name__ == "__main__":
    root_dir = '/path/to/monitor'
    exclusion_criteria = ['*.txt', '*.py']
    monitor = FileMonitor(root_dir, exclusion_criteria)
    monitor.run()
