import os
import yaml
from jinja2 import Template
import requests
import logging
from packaging.version import Version
from git import Repo

class ConfigurationGenerator:
    def __init__(self, config_file_path):
        self.config = yaml.safe_load(open(config_file_path, 'r'))
        self.env = os.environ
        self.api_cache = {}

    def generate_config_files(self):
        for file_config in self.config['files']:
            template = Template(file_config['template'])
            data = {}
            if 'variables' in file_config:
                data.update(file_config['variables'])
            if 'api_data' in file_config:
                data.update(self.fetch_api_data(file_config['api_data']))
            if 'env_vars' in file_config:
                data.update({key: self.env.get(key) for key in file_config['env_vars']})
            output_file_path = os.path.join(self.config['output_dir'], file_config['file_name'])
            with open(output_file_path, 'w') as f:
                f.write(template.render(**data))

    def fetch_api_data(self, api_configs):
        data = {}
        for config in api_configs:
            if config['endpoint'] not in self.api_cache:
                try:
                    response = requests.get(config['endpoint'])
                    if response.status_code == 200:
                        self.api_cache[config['endpoint']] = response.json()
                    else:
                        raise Exception(f"Failed to fetch data from {config['endpoint']} with status code {response.status_code}")
                except Exception as e:
                    logging.error(f"Error fetching data from {config['endpoint']}: {str(e)}")
                    self.api_cache[config['endpoint']] = None
            if self.api_cache[config['endpoint']] is not None:
                data[config['key']] = self.api_cache[config['endpoint']].get(config['key'])
        return data

    def commit_config_files(self, repo_path):
        repo = Repo(repo_path)
        for file in self.config['files']:
            output_file_path = os.path.join(self.config['output_dir'], file['file_name'])
            if os.path.exists(output_file_path):
                try:
                    repo.index.add([output_file_path])
                    repo.index.commit(f"Updated configuration file {file['file_name']}")
                except Exception as e:
                    logging.error(f"Error committing changes to repository: {str(e)}")

    def main(self, config_file_path, output_dir, repo_path):
        self.config = yaml.safe_load(open(config_file_path, 'r'))
        self.env = os.environ
        self.api_cache = {}
        for file_config in self.config['files']:
            template = Template(file_config['template'])
            data = {}
            if 'variables' in file_config:
                data.update(file_config['variables'])
            if 'api_data' in file_config:
                data.update(self.fetch_api_data(file_config['api_data']))
            if 'env_vars' in file_config:
                data.update({key: self.env.get(key) for key in file_config['env_vars']})
            output_file_path = os.path.join(output_dir, file_config['file_name'])
            with open(output_file_path, 'w') as f:
                f.write(template.render(**data))
        self.commit_config_files(repo_path)

if __name__ == "__main__":
    generator = ConfigurationGenerator('config.yml')
    generator.main('config.yml', 'output', 'repo')
