@Service
public class PokemonReportService {

    @Autowired
    private PokemonRepository pokemonRepository;

    @Autowired
    private MovesetApi movesetApi;

    @Autowired
    private TypeEffectivenessRepository typeEffectivenessRepository;

    public PokemonBattleReport getBattleReport(String pokemonName) {
        // fetch pokemon data and movesets
        Pokemon pokemon = pokemonRepository.getPokemon(pokemonName);
        List<Moveset> movesets = movesetApi.getMovesets(pokemonName).collectList();

        // calculate type effectiveness
        Map<String, Double> typeEffectivenessMap = typeEffectivenessRepository.getTypeEffectiveness();

        // generate battle report
        PokemonBattleReport battleReport = new PokemonBattleReport(
            pokemon,
            movesets,
            typeEffectivenessMap
        );
        return battleReport;
    }
}

