    int (*encrypt)(const uint8_t*, const uint8_t*, size_t);
    int (*decrypt)(const uint8_t*, const uint8_t*, size_t);
} Algorithm;

Algorithm algos[] = {
    {"AES-128-CBC", aes_encrypt, aes_decrypt},
    {"DES-64-EBC", des_encrypt, des_decrypt}
};

// Define structures for encryption contexts
typedef struct {
    char *algorithm;
    int mode;
    uint8_t key[32];
} Context;

Context *contexts = NULL;

// Function to initialize encryption context
void init_context(Context *ctx) {
    ctx->algorithm = "AES-128-CBC";
    ctx->mode = CBC_MODE;
}

// Function to encrypt data using selected algorithm and mode
int encrypt_data(const uint8_t* plain, const uint8_t* key, size_t size) {
    Algorithm *algo = find_algorithm(ctx->algorithm);
    if (!algo) return -1;

    // Perform encryption operation
    uint8_t *cipher = (uint8_t*)malloc(size);
    algo->encrypt(plain, key, size);

    free(cipher);
    return 0;
}

// Function to decrypt data using selected algorithm and mode
int decrypt_data(const uint8_t* cipher, const uint8_t* key, size_t size) {
    Algorithm *algo = find_algorithm(ctx->algorithm);
    if (!algo) return -1;

    // Perform decryption operation
    uint8_t *plain = (uint8_t*)malloc(size);
    algo->decrypt(cipher, key, size);

    free(plain);
    return 0;
}

// Function to select encryption algorithm based on configuration settings or environment variables
Algorithm* find_algorithm(const char* name) {
    int i;
    for(i = 0; i < sizeof(algos)/sizeof(algos[0]); i++) {
        if (strcmp(algos[i].name, name) == 0) return &algs[i];
    }
    return NULL;
}

// Function to handle concurrent requests from multiple clients
void* process_request(void* arg) {
    // Handle request and encrypt/decrypt data
    Context *ctx = (Context*)arg;
    uint8_t *plain = (uint8_t*)malloc(size);
    uint8_t *cipher = (uint8_t*)malloc(size);

    // Perform encryption operation
    encrypt_data(plain, ctx->key, size);

    // Log encryption details and result
    log_event(ctx->algorithm, "start");
    log_event("completion time", "end");

    // Perform decryption operation
    decrypt_data(cipher, ctx->key, size);

    free(plain);
    free(cipher);
}

int main() {
    // Initialize contexts for concurrent requests
    pthread_t threads[10];
    Context *ctxs[10];

    int i;
    for(i = 0; i < 10; i++) {
        init_context(&ctxs[i]);
        pthread_create(&threads[i], NULL, process_request, &ctxs[i]);
    }

    // Wait for all threads to complete
    for(i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
