['```cpp
#include <forward_list>
#include <string>
#include <iostream>
#include <mutex>

class DynamicStringContainer {
public:
    struct SearchResult {
        bool found;
        size_t position;
    };

    DynamicStringContainer() : logLevel(0) {}

    void setLogLevel(int level) { logLevel = level; }

    SearchResult insertAfterOrAppend(const std::string& search, const std::string& str) {
        SearchResult result;

        auto it = strings.begin();
        bool found = false;
        size_t position = 0;

        for (; it != strings.end() && !found; ++it, ++position) {
            if (*it == search) {
                found = true;
                break;
            }
        }

        if (found) {
            std::unique_lock<std::mutex> lock(mutex);
            logOperation(search, str, "inserted after");
            strings.insert_after(it, str);
        } else {
            std::unique_lock<std::mutex> lock(mutex);
            logOperation(search, str, "appended");
            strings.push_front(str);
        }

        result.found = found;
        result.position = position;

        return result;
    }

private:
    void logOperation(const std::string& search, const std::string& str, const std::string& operation) {
        if (logLevel > 0) {
            switch (logLevel) {
                case 1: {
                    std::cout << "Search: " << search << ", Operation: " << operation << ", String: " << str << std::endl;
                    break;
                }
                case 2: {
                    std::cout << "LogLevel 2" << std::endl;
                    break;
                }
            }
        }
    }

    mutable std::mutex mutex;
    forward_list<std::string> strings;
    int logLevel;
};
