using System;
using System.Data.SqlClient;
using System.Threading.Tasks;

public static class ExecuteParameterizedQuery
{
    public static async Task<T> ExecuteAsync<T>(string connectionString, string commandText, object[] parameters, Func<SqlDataReader, T> callback)
    {
        if (string.IsNullOrEmpty(connectionString))
            throw new ArgumentNullException(nameof(connectionString), "Connection string is required");

        if (string.IsNullOrEmpty(commandText))
            throw new ArgumentNullException(nameof(commandText), "SQL command text is required");

        if (parameters == null || parameters.Length == 0)
            throw new ArgumentNullException(nameof(parameters), "Parameter list is required");

        if (callback == null)
            throw new ArgumentNullException(nameof(callback), "Callback function is required");

        using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync();

        try
        {
            using var command = new SqlCommand(commandText, connection);
            foreach (var parameter in parameters)
            {
                // Dynamically fetch query parameters from the external API if necessary
                if (parameter is Dictionary<string, string> dictParam && dictParam.ContainsKey("ExternalAPIParameterValue"))
                    command.Parameters.AddWithValue(dictParam["ParameterName"], dictParam["ExternalAPIParameterValue"]);
                else
                    command.Parameters.AddWithValue(parameter.ToString(), parameter);
            }

            using var reader = await command.ExecuteReaderAsync();
            return callback(reader);
        }
        catch (SqlException ex)
        {
            // Handle SQL-related errors and log them
            LogError(ex.Message, ex);
            throw;
        }
        catch (InvalidOperationException ex)
        {
            // Handle invalid operation exceptions and log them
            LogError(ex.Message, ex);
            throw;
        }
        catch (Exception ex)
        {
            // Handle any other exceptions and log them
            LogError(ex.Message, ex);
            throw;
        }
    }

    private static void LogError(string message, Exception ex)
    {
        // Implement your logging mechanism here
        Console.WriteLine($"Error executing query: {message}");
        Console.WriteLine(ex.StackTrace);
    }
}
