            var config = JsonConvert.DeserializeObject<Configuration>(configJson);

            // Initialize weather API connections and caching
            await _weatherApiService.InitializeAsync();
            _cacheManager.Initialize(config.CachingStrategy);

            // Start concurrent requests and updates from multiple clients
