class Octree {
public:
    using Ptr = std::unique_ptr<Octree>;
    using ChildPtrs = std::array<Ptr, 8>;

    Octree(size_t depth) : depth_(depth), children_({}) {}

    void init() {
        for (auto& child : children_) {
            child.reset(new Octree(depth_ - 1));
        }
    }

    void insert(const std::vector<float>& feature) {
        if (feature.empty()) return;

        size_t index = getInsertIndex(feature);
        Ptr& child = children_[index];
        if (!child) {
            child = Ptr(new Octree(depth_ - 1));
        }
        child->insert(feature.substr(index * 3, 3));
    }

private:
