import java.io.IOException;
import java.util.concurrent.*;

public class MoSTStateService {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final CachingConfigStore configStore;
    private final LoggingService loggingService;

    public MoSTStateService(CachingConfigStore configStore, LoggingService loggingService) {
        this.configStore = configStore;
        this.loggingService = loggingService;
    }

    public Future<MOSTState> loadMoSTState(String clientId, String desiredVersion) {
        return executor.submit(() -> loadMoSTStateInternal(clientId, desiredVersion));
    }

    private MOSTState loadMoSTStateInternal(String clientId, String desiredVersion) throws IOException, InterruptedException {
        try {
            MoSTState state = configStore.loadState(desiredVersion);
            if (state == null) {
                throw new IOException("Invalid or missing configuration");
            }
            return state;
        } catch (IOException e) {
            int retryDelayMs = 1000; // initial delay
            int maxRetries = 6; // maximum retries
            int currentRetryCount = 1;

            while (true) {
                try {
                    state = configStore.loadState(desiredVersion);
                    return state;
                } catch (IOException e2) {
                    if (currentRetryCount >= maxRetries) {
                        loggingService.logError("MoST State Load failed after " + currentRetryCount + " retries: " + e2.getMessage());
                        throw new IOException("Failed to load MoST State", e2);
                    }
                    Thread.sleep(retryDelayMs);
                    retryDelayMs *= 2; // exponential backoff
                    currentRetryCount++;
                }
            }
        } finally {
            executor.shutdown();
        }
    }

    public static class CachingConfigStore implements ConfigStore {
        private final Map<String, MoSTState> cache = new ConcurrentHashMap<>();
        private final ConfigStore delegate;

        public CachingConfigStore(ConfigStore delegate) {
            this.delegate = delegate;
        }

        @Override
        public MoSTState loadState(String desiredVersion) throws IOException {
            MoSTState state = cache.get(desiredVersion);
            if (state != null) {
                return state;
            }
            try {
                state = delegate.loadState(desiredVersion);
                cache.put(desiredVersion, state);
                return state;
            } catch (IOException e) {
                throw new IOException("Failed to load MoST State", e);
            }
        }
    }

    public static class LoggingService {
        private final Logger logger;

        public LoggingService(Logger logger) {
            this.logger = logger;
        }

        public void logInfo(String message) {
            logger.info(message);
        }

        public void logError(String message) {
            logger.error(message);
        }
    }
}
