const fs = require('fs');
const path = require('path');
const json2x = require('json2xml');
const axios = require('axios');
const express = require('express');
const app = express();
const pluginManager = require('./plugins');

app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Load plugins
pluginManager.loadPlugins();

// Set up caching mechanism
const cache = {};

// Define API endpoint for rate-limited data fetching
app.get('/api/data/:id', async (req, res) => {
  const id = req.params.id;
  if (!cache[id]) {
    try {
      const response = await axios.get(`https://api.example.com/${id}`);
      cache[id] = response.data;
    } catch (error) {
      console.error(`Error fetching data for ${id}:`, error);
      res.status(500).send({ message: 'Failed to fetch data' });
    }
  }
  res.send(cache[id]);
});

// Define endpoint for processing JSON files
app.post('/process', async (req, res) => {
  const jsonFile = req.body.jsonFile;
  const pluginName = req.body.pluginName;

  // Load JSON file and apply transformation using the specified plugin
  try {
    const jsonContent = await fs.readFile(jsonFile);
    const jsonObject = JSON.parse(jsonContent.toString());
    const transformedData = await pluginManager.applyPlugin(jsonObject, pluginName);

    // Cache processed data for future lookups
    cache[jsonFile] = transformedData;

    res.send(transformedData);
  } catch (error) {
    console.error(`Error processing ${jsonFile}:`, error);
    res.status(500).send({ message: 'Failed to process JSON file' });
  }
});

// Define endpoint for parallel processing of multiple files
app.post('/process/multi', async (req, res) => {
  const files = req.body.files;
  const pluginName = req.body.pluginName;

  // Run parallel processing using the specified plugin
  try {
    const results = await Promise.all(files.map((file) => {
      return fs.readFile(file).then((content) => {
        const jsonObject = JSON.parse(content.toString());
        return pluginManager.applyPlugin(jsonObject, pluginName);
      });
    }));

    res.send(results);
  } catch (error) {
    console.error(`Error processing multiple files:`, error);
    res.status(500).send({ message: 'Failed to process multiple files' });
  }
});

// Start the service
const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Service started on port ${port}`);
});
