const { fork } = require('child_process');
const { promisify } = require('util');
const { setTimeout } = require('timers');

class TestRunner {
  constructor() {
    this.modules = {};
    this.logLevel = 'info';
  }

  async loadModule(moduleName) {
    if (!this.modules[moduleName]) {
      try {
        const moduleCode = await fs.readFile(moduleName, 'utf8');
        this.modules[moduleName] = new Function('module', 'exports', `(${moduleCode})`);
      } catch (err) {
        throw new Error(`Failed to load module ${moduleName}: ${err.message}`);
      }
    }
  }

  async runTest(moduleName, testLabel, testFunction) {
    try {
      const result = await this.modules[moduleName].call(null, 'module', 'exports')(testFunction);
      if (result.passed) {
        console.log(`Test '${testLabel}' in module ${moduleName} passed`);
      } else {
        throw new Error(`Test '${testLabel}' in module ${moduleName} failed`);
      }
    } catch (err) {
      if (this.logLevel === 'debug') {
        console.error(err.stack);
      } else if (this.logLevel === 'info') {
        console.error(`Test '${testLabel}' in module ${moduleName} failed: ${err.message}`);
      }
    }
  }

  async runTests(moduleName, testLabels) {
    for (const testLabel of testLabels) {
      await this.runTest(moduleName, testLabel, null);
    }
  }

  async runConcurrently(moduleName, testLabels) {
    const childProcesses = [];
    for (const testLabel of testLabels) {
      childProcesses.push(fork('./run-test.js', [moduleName, testLabel]));
    }
    for (childProcess of childProcesses) {
      await promisify(childProcess.kill.bind(childProcess))('SIGTERM');
    }
  }

  async runAndLog(moduleName, testLabels) {
    try {
      const result = await this.runTests(moduleName, testLabels);
      if (result.passed) {
        console.log(`All tests in module ${moduleName} passed`);
      } else {
        throw new Error(`Some tests in module ${moduleName} failed`);
      }
    } catch (err) {
      console.error(err.message);
    }
  }

  async runAndLogConcurrently(moduleName, testLabels) {
    try {
      await this.runConcurrently(moduleName, testLabels);
      console.log(`All tests in module ${moduleName} passed`);
    } catch (err) {
      console.error(err.message);
    }
  }

  async retryFailedTests(moduleName, testLabels, maxRetries = 3) {
    let retriesLeft = maxRetries;
    while (retriesLeft > 0) {
      try {
        await this.runAndLogConcurrently(moduleName, testLabels);
        return;
      } catch (err) {
        if (this.logLevel === 'debug') {
          console.error(err.stack);
        } else if (this.logLevel === 'info') {
          console.error(`Retrying failed tests in module ${moduleName}: ${err.message}`);
        }
        await setTimeout(() => {}, 2 ** retriesLeft * 1000); // exponential backoff
      }
      retriesLeft--;
    }
    throw new Error(`Failed to run tests in module ${moduleName} after ${maxRetries} retries`);
  }

  async run(moduleName, testLabel) {
    await this.loadModule(moduleName);
    try {
      if (!testLabel) {
        console.log('Running all tests in module');
        await this.runAndLogConcurrently(moduleName, Object.keys(this.modules[moduleName]));
      } else {
        console.log(`Running test '${testLabel}' in module ${moduleName}`);
        await this.runTest(moduleName, testLabel, null);
      }
    } catch (err) {
      if (this.logLevel === 'debug') {
        console.error(err.stack);
      } else if (this.logLevel === 'info') {
        console.error(`Failed to run tests in module ${moduleName}: ${err.message}`);
      }
    }
  }

  async main() {
    const args = process.argv.slice(2);
    let moduleName, testLabel;
    for (const arg of args) {
      if (arg.includes('=')) {
        [testLabel, value] = arg.split('=');
        switch (testLabel) {
          case '--moduleName':
            moduleName = value;
            break;
          case '--testLabel':
            testLabel = value;
            break;
          default:
            throw new Error(`Invalid command-line option: ${arg}`);
        }
      } else {
        throw new Error(`Invalid command-line argument: ${arg}`);
      }
    }
    await this.run(moduleName, testLabel);
  }

  start() {
    return this.main();
  }
}

const { fs } = require('fs/promises');
const testRunner = new TestRunner();

testRunner.start();"]

