      try {
        loadingIndicator.textContent = `Loading data for ${resourceId}...`;

        const response = await fetch(`${apiEndpoint}/${url}`);
        const responseData = await response.json();

        if (response.ok) {
          // Validate and process the fetched data here
          // ...

          return responseData;
        } else {
          throw new Error(`Failed to load data for ${resourceId}: ${response.statusText}`);
        }
      } catch (error) {
        console.error(error);
        loadingIndicator.textContent = `Error: ${error.message}`;

        return null;
      } finally {
        loadingIndicator.textContent = '';
      }
    };

    const processDialogField = async (field) => {
      if (!cachingMechanism.has(field.resourceId)) {
        const cachedData = await validateAndProcessData(field.resourceId, field.url);

        cachingMechanism.set(field.resourceId, cachedData);
      }

      const cachedResponse = cachingMechanism.get(field.resourceId);

      if (cachedResponse) {
        // Process the cached data here
        // ...
      } else {
        // Field not found in cache; refresh the field and retry processing
        await validateAndProcessData(field.resourceId, field.url);

        const updatedCachedResponse = cachingMechanism.get(field.resourceId);

        if (updatedCachedResponse) {
          // Process the updated cached data here
          // ...
        }
      }
    };

    Promise.all(refreshIdsAndUrls.map(processDialogField))
      .then(() => {
        // Extract Old Testament book references from processed fields here
        // ...
      })
      .catch((error) => console.error(error));
  };
}

