function iotDataCollector() {
  const cache = {};
  let themeBitmaps = {};
  let defaultThemeDir;

  async function collectData() {
    try {
      const response = await fetch('https://api.example.com/sensors');
      const data = await response.json();

      // Handle streaming and store data in local cache
      for (const sensorData of data) {
        if (!cache[sensorData.deviceId]) {
          cache[sensorData.deviceId] = [];
        }
        cache[sensorData.deviceId].push(sensorData);

        // Pause collection after 1000 records, resume after 500ms
        if (cache.length >= 1000) {
          await pause(500);
          cache = {};
        }
      }
    } catch (error) {
      console.error('Error collecting data:', error);
    }
  }

  async function pause(timeout) {
    return new Promise((resolve) => setTimeout(() => resolve(), timeout));
  }

  // Manage theme bitmap caching
  async function updateThemeCache() {
    const cacheRoot = await getCacheRoot();
    if (!cacheRoot) return;

    try {
      const files = await fs.readdir(cacheRoot);
      for (const file of files) {
        if (file.endsWith('.png')) {
          const bitmap = await fs.readFile(`${cacheRoot}/${file}`);
          themeBitmaps[file] = bitmap;
        }
      }

      // Periodically update the cache
      setInterval(() => {
        updateThemeCache();
      }, 1000 * 60); // Update every 1 minute
    } catch (error) {
      console.error('Error updating theme cache:', error);
    }
  }

  async function getCacheRoot() {
    try {
      const storage = await Storage.local.get();
      defaultThemeDir = storage.defaultThemeDir;
      if (!defaultThemeDir) {
        defaultThemeDir = 'themes';
        await Storage.local.set({ defaultThemeDir });
      }
      return `${storage.cacheRoot}/${defaultThemeDir}`;
    } catch (error) {
      console.error('Error getting cache root:', error);
      return null;
    }
  }

  // Main entry point
  async function start() {
    try {
      await updateThemeCache();
      while (true) {
        await collectData();
      }
    } catch (error) {
      console.error('Error starting data collector:', error);
    }
  }

  start();
}
