#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define BUNDLE_FILE_PATH_MAX_LENGTH 256
#define BUNDLE_ITEM_SIZE sizeof(struct BundleItem)

struct BundleItem {
    char* key;
    int value;
};

int loadBundle(const char* filePath, pthread_mutex_t* mutex) {
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        return -1; // File not found or unable to open
    }

    pthread_mutex_lock(mutex);
    struct BundleItem* bundleItems = (struct BundleItem*)malloc(BUNDLE_ITEM_SIZE * 10); // Initialize with a reasonable size
    int itemCount = 0;

    while (fread(&bundleItems[itemCount], BUNDLE_ITEM_SIZE, 1, file) == 1) {
        itemCount++;
        if (itemCount > 10000) { // Check for large dataset and allocate more memory as needed
            bundleItems = (struct BundleItem*)realloc(bundleItems, BUNDLE_ITEM_SIZE * (itemCount + 10));
        }
    }

    fclose(file);

    pthread_mutex_unlock(mutex);
    return itemCount;
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int itemCount = loadBundle("bundle_file.txt", &mutex);
    printf("Number of items in the bundle: %d\n", itemCount);
    return 0;
}
