async function loadModule(moduleName) {
  try {
    const module = await require(moduleName);
    return module;
  } catch (err) {
    console.error(err);
    throw err;
  }
}

// cache.js
class Cache {
  constructor() {
    this.cache = {};
  }

  async get(moduleName) {
    if (this.cache[moduleName]) {
      return this.cache[moduleName];
    }
    const module = await loadModule(moduleName);
    this.cache[moduleName] = module;
    return module;
  }

  async stats() {
    const hits = Object.keys(this.cache).reduce((acc, key) => acc + (this.cache[key] ? 1 : 0), 0);
    const misses = Object.keys(this.cache).length - hits;
    return { hits, misses };
  }
}

