import java.util.*;
import java.io.*;

public class EventProcessor {
    private Map<Integer, UnionFind> unionFinds;
    private Map<String, Long> eventCounters;

    public EventProcessor() {
        this.unionFinds = new HashMap<>();
        this.eventCounters = new HashMap<>();
    }

    public void processEvents(EventLog log) throws IOException {
        for (Event event : log.getEvents()) {
            int start = event.getStart();
            int end = event.getEnd();

            // Update the union find data structure
            if (!unionFinds.containsKey(start)) {
                UnionFind uf = new UnionFind();
                unionFinds.put(start, uf);
            }
            if (!unionFinds.containsKey(end)) {
                UnionFind uf = new UnionFind();
                unionFinds.put(end, uf);
            }
            unionFinds.get(start).addInterval(event);
            unionFinds.get(end).addInterval(event);

            // Update the event counters
            eventCounters.computeIfAbsent(log.getLogName(), k -> 0L);
            eventCounters.computeIfPresent(log.getLogName(), (k, v) -> v + 1L);
        }
    }

    public Map<String, Long> getEventCounts() {
        return Collections.unmodifiableMap(eventCounters);
    }

    public Map<Integer, Long> getIntervalCounts(String logName) {
        UnionFind uf = unionFinds.get(start);
        Map<Integer, Long> intervalCounts = new HashMap<>();
        for (int interval : uf.getIntervals()) {
            intervalCounts.put(interval, 1L);
        }
        return Collections.unmodifiableMap(intervalCounts);
    }

    public static class Event {
        int start;
        int end;

        public Event(int start, int end) {
            this.start = start;
            this.end = end;
        }

        public int getStart() {
            return start;
        }

        public int getEnd() {
            return end;
        }
    }

    public static class UnionFind {
        private Map<Integer, Set<Integer>> intervals;

        public UnionFind() {
            this.intervals = new HashMap<>();
        }

        public void addInterval(Event event) {
            if (!intervals.containsKey(event.getStart())) {
                intervals.put(event.getStart(), new HashSet<>());
            }
            if (!intervals.containsKey(event.getEnd())) {
                intervals.put(event.getEnd(), new HashSet<>());
            }
            intervals.get(event.getStart()).add(event.getEnd());
            intervals.get(event.getEnd()).add(event.getStart());
        }

        public Set<Integer> getIntervals() {
            return Collections.unmodifiableSet(new HashSet<>(intervals.values()));
        }
    }

    public static class EventLog implements Serializable {
        List<Event> events;
        String logName;

        public EventLog(String logName) {
            this.logName = logName;
            this.events = new ArrayList<>();
        }

        public void addEvent(Event event) {
            events.add(event);
        }

        public List<Event> getEvents() {
            return Collections.unmodifiableList(events);
        }
    }
}
