package com.sessionmanagement;

import java.util.*;
import java.util.concurrent.*;

public class SessionManager {
    private static final int SESSION_VALIDATION_THRESHOLD = 300; // in seconds
    private static final long LOCK_TIMEOUT = 5000L;
    private static final long MAX_WAIT = 10000L;

    private Map<String, Session> sessions = new ConcurrentHashMap<>();
    private BlockingQueue<Runnable> backgroundTasks = new LinkedBlockingQueue<>();

    public void addSession(String userId, String token) {
        Session session = new Session(userId, token);
        sessions.put(token, session);
    }

    public boolean validateToken(String token) {
        if (!sessions.containsKey(token)) return false;
        Session session = sessions.get(token);
        if (session.isExpired()) return false;
        if (session.isRevoked()) return false;
        if (session.isCompromised()) return false;
        return true;
    }

    public void renewToken(String token) {
        if (!sessions.containsKey(token)) return;
        Session session = sessions.get(token);
        session.setLastAccessed(System.currentTimeMillis());
    }

    public void cleanupExpiredSessions() {
        Iterator<Map.Entry<String, Session>> it = sessions.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<String, Session> entry = it.next();
            if (entry.getValue().isExpired()) {
                it.remove();
                backgroundTasks.add(() -> removeSession(entry.getKey()));
            }
        }
    }

    public void startBackgroundJob() {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        try {
            while (!backgroundTasks.isEmpty()) {
                Runnable task = backgroundTasks.take();
                executor.submit(task);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            executor.shutdownNow();
        }
    }

    private void removeSession(String token) {
        // implement your logic to remove the session
    }
}

