        reqwest::Method::Get => get(&url)
            .headers(headers)
            .timeout(config.timeout)
            .send()
            .await
            .map_err(|e| HttpClientError::ReqwestError(e))?,
        reqwest::Method::Post => post(&url)
            .headers(headers)
            .body(body.unwrap())
            .timeout(config.timeout)
            .send()
            .await
            .map_err(|e| HttpClientError::ReqwestError(e))?,
        reqwest::Method::Put => put(&url)
            .headers(headers)
            .body(body.unwrap())
            .timeout(config.timeout)
            .send()
            .await
            .map_err(|e| HttpClientError::ReqwestError(e))?,
        reqwest::Method::Delete => delete(&url)
            .headers(headers)
            .timeout(config.timeout)
            .send()
            .await
            .map_err(|e| HttpClientError::ReqwestError(e))?,
