<?php

class ClinicStatusUpdater {
    private $dbConnection;
    private $semaphore;

    public function __construct($dbConfig, $semaphoreValue) {
        $this->dbConnection = new mysqli($dbConfig['host'], $dbConfig['username'], $dbConfig['password'], $dbConfig['database']);
        if ($this->dbConnection->connect_error) {
            throw new Exception('Database connection failed: ' . $this->dbConnection->connect_error);
        }

        $this->semaphore = sem_open(SEM_NANOSECONDS, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR, $semaphoreValue);
    }

    public function updateStatus(int $clinicId, string $newStatus) {
        if (!$this->dbConnection->begin()) {
            throw new Exception('Failed to start transaction');
        }

        sem_acquire($this->semaphore);

        try {
            $stmt = $this->dbConnection->prepare("UPDATE clinic_status SET status = ?, last_modified_ip = inet_aton(?), timestamp = ? WHERE id = ?");
            $stmt->bind_param('sssi', $newStatus, $_SERVER['REMOTE_ADDR'], date('Y-m-d H:i:s'), $clinicId);
            $stmt->execute();
        } catch (Exception $e) {
            $this->dbConnection->rollback();
            throw $e;
        } finally {
            sem_release($this->semaphore);
        }

        if (!$this->dbConnection->commit()) {
            throw new Exception('Transaction failed to commit');
        }
    }

    public function logDebugMessage(string $message) {
        error_log(date('Y-m-d H:i:s') . ': ' . $message);
    }
}

// C utility code
#include <semaphore.h>
#include <pthread.h>

sem_t *clinicStatusUpdaterSem;

void* clinicStatusUpdaterThread(void* args) {
    sem_wait(clinicStatusUpdaterSem);

    // Perform operations that require synchronization

    sem_post(clinicStatusUpdaterSem);
    return NULL;
}

int main() {
    int semaphoreValue = 5; // Set the initial semaphore value
    clinicStatusUpdaterSem = sem_open(SEM_NANOSECONDS, O_RDWR | O_CREAT, S_IRUSR | S_IWUSR, semaphoreValue);

    pthread_t thread;
    pthread_create(&thread, NULL, clinicStatusUpdaterThread, NULL);
    pthread_join(thread, NULL);

    sem_close(clinicStatusUpdaterSem);
    return 0;
}

