use std::fs;
use std::path::{Path, PathBuf};
use tokio::fs::File;
use tokio::io::{self, BufReader};
use reqwest::blocking::get;
use openssl::ssl::Session;
use reqwest::Client;

#[derive(Debug)]
struct OAuthCertManager {
    oauth_token: String,
    cache_path: String,
}

impl OAuthCertManager {
    async fn new(oauth_token: &str, cache_path: &str) -> Result<Self, Box<dyn std::error::Error>> {
        Ok(OAuthCertManager {
            oauth_token: oauth_token.to_string(),
            cache_path: cache_path.to_string(),
        })
    }

    async fn get_cert_chain(&self) -> Result<(String, String), Box<dyn std::error::Error>> {
        // Retrieve certificate chain from remote server using OAuth token
        let client = Client::new();
        let response = client
            .get("https://example.com/cert-chain")
            .header("Authorization", format!("Bearer {}", self.oauth_token))
            .send()
            .await?
            .error_for_status()?;

        // Check if response was successful and certificate is present
        if response.status().is_success() && response.bytes().is_some() {
            let cert_chain = response.bytes().unwrap();
            // Cache the certificate chain for future requests
            self.cache_cert_chain(&cert_chain).await?;
            Ok((response.text().unwrap(), String::from("cached cert-chain")))
        } else {
            Err(Box::new(std::io::Error::new(
                std::io::ErrorKind::Other,
                "Failed to retrieve certificate chain",
            )))
        }
    }

    async fn cache_cert_chain(&self, cert_chain: &[u8]) -> Result<(), Box<dyn std::error::Error>> {
        // Create or update the cache file
        let mut cache_file = File::create(Path::new(&self.cache_path)).await?;
        BufReader::new(cache_file).write_all(cert_chain).await?;

        Ok(())
    }

    async fn invalidate_cache(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Clear the cache file when OAuth token expires or certificate is renewed
        let mut cache_file = File::create(Path::new(&self.cache_path)).await?;
        BufReader::new(cache_file).write_all(b"").await?;

        Ok(())
    }
}
