struct OctreeNode {
    bool hasPoint;
    std::vector<OctreeNode*> children;
};

class Octree {
public:
    void insert(int x, int y, int z) {
        // Find the correct leaf node to insert
        OctreeNode* current = &root;
        for (int i = 0; i < 3; i++) {
            if ((x >> i) % 2) {
                if (!current->children.size()) {
                    current->children.push_back(new OctreeNode());
                }
                current = current->children.back();
            } else {
                current = current->children.front();
            }
        }

        // Insert the point into the leaf node
        current->hasPoint = true;
    }

    void search(int x, int y, int z) {
        // Find the correct leaf node to search
        OctreeNode* current = &root;
        for (int i = 0; i < 3; i++) {
            if ((x >> i) % 2) {
                if (!current->children.size()) {
                    return; // No point found
                }
                current = current->children.back();
            } else {
                current = current->children.front();
            }
        }

        // Check if the leaf node contains a point
        if (current->hasPoint) {
            std::cout << "Found point at (" << x << ", " << y << ", " << z << ")" << std::endl;
        } else {
            std::cout << "No point found at (" << x << ", " << y << ", " << z << ")" << std::endl;
        }
    }

private:
    OctreeNode root;

};

