import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.module.kotlin.*;
import org.apache.commons.pool2.impl.GenericObjectPoolConfig;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.Jackson2JsonRedisSerializer;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;

@SpringBootApplication
public class TransactionProcessor {

    @Bean
    public Jackson2JsonRedisSerializer jackson2JsonRedisSerializer() {
        return new Jackson2JsonRedisSerializer<>(KotlinModule.INSTANCE);
    }

    @Bean
    public RedisTemplate<String, Transaction> redisTemplate(RedisTemplate<String, String> template) {
        RedisTemplate<String, Transaction> redisTemplate = new RedisTemplate<>();
        redisTemplate.setConnectionFactory(template.getConnectionFactory());
        redisTemplate.setValueSerializer(jackson2JsonRedisSerializer());
        return redisTemplate;
    }

    @Bean
    public ThreadPoolTaskExecutor threadPoolTaskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setMaxPoolSize(10);
        executor.setCorePoolSize(5);
        executor.setKeepAliveSeconds(60);
        return executor;
    }

    @Bean
    public GenericObjectPoolConfig transactionPoolConfig() {
        GenericObjectPoolConfig config = new GenericObjectPoolConfig();
        config.setMaxActive(10000);
        config.setMaxIdle(5000);
        config.setMaxWait(Duration.ofSeconds(30));
        return config;
    }

    @Bean
    public ObjectMapper objectMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.INDENT_OUTPUT);
        mapper.configure(SerializationFeature.FAIL_ON_EMPTY_ARRAYS, false);
        return mapper;
    }

    public static void main(String[] args) {
        SpringApplication.run(TransactionProcessor.class, args);
    }
}
