#include <condition_variable>
#include <string>
#include <fstream>

class AttackSelector {
public:
    AttackSelector(int cooldownPeriod) : cooldownPeriod_(cooldownPeriod), lastAttackTime_(std::chrono::steady_clock::now()), attackQueue_() {}

    void addAttack(const std::string& name, int delay) {
        attacks_.emplace(name, {delay, 0});
    }

    void updateAttackUsage(const std::string& name) {
        if (attacks_.find(name) != attacks_.end()) {
            auto& attack = attacks_[name];
            attack.second++;
        }
    }

    bool selectAttack() {
        if (!attackQueue_.empty()) {
            return true;
        }

        auto now = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastAttackTime_) < cooldownPeriod_) {
            return false;
        }

        // Validate attack with remote service
        bool isValid = validateAttack();
        if (!isValid) {
            return false;
        }

        // Select and enqueue the next attack
        int delay = getDelay();
        attackQueue_.emplace(delay, true);
        lastAttackTime_ = now;

        return true;
    }

    void run() {
        while (true) {
            if (attackQueue_.empty()) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
                continue;
            }

