using System;
using System.Threading;
using System.Threading.Tasks;

public class DynamicRandomValueGenerator
{
    private readonly Random _random = new Random();
    private readonly object _syncRoot = new object();

    public DynamicRandomValueGenerator()
    {
        // Initialize default range
        _range = (int, int)(1, 100);
    }

    public DynamicRandomValueGenerator((int, int) range)
    {
        SetRange(range);
    }

    public void SetRange((int, int) range)
    {
        if (_random.Thread != null)
        {
            throw new InvalidOperationException("Cannot change range after initialization.");
        }
        _range = range;
    }

    public async Task<int> GenerateRandomIntegerAsync(int min, int max, CancellationToken cancellationToken = default)
    {
        await ValidateRange(min, max);
        return _random.Next(min, max + 1);
    }

    public async Task<double> GenerateRandomDoubleAsync(double min, double max, CancellationToken cancellationToken = default)
    {
        await ValidateRange((int)min, (int)max);
        return _random.NextDouble() * (max - min) + min;
    }

    public async Task<int[]> GenerateSequenceOfRandomIntegersAsync(int length, CancellationToken cancellationToken = default)
    {
        var sequence = new HashSet<int>();
        for (var i = 0; i < length; i++)
        {
            while (!sequence.Add(await GenerateRandomIntegerAsync(_range.Item1, _range.Item2, cancellationToken)))
            {
                // If we reach here, it means we need to generate a new value
                await Task.Delay(5);
            }
        }
        return sequence.ToArray();
    }

    public override string ToString()
    {
        return $"Range: {GetRange().Item1} - {GetRange().Item2}";
    }

    private (int, int) GetRange() => _range;

    private async Task ValidateRange(int min, int max)
    {
        if (min > max)
        {
            throw new InvalidOperationException("Minimum value cannot be greater than maximum.");
        }
        await ValidateExternalServiceAsync(min, max);
    }

    private async Task ValidateExternalServiceAsync(int min, int max)
    {
        // Call external service for range validation
        await Task.Delay(10); // Simulate latency
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        var generator = new DynamicRandomValueGenerator((1, 100));

        // Generate random integers and doubles
        var randomIntegers = await generator.GenerateRandomIntegerAsync(1, 100);
        var randomDoubles = await generator.GenerateRandomDoubleAsync(0.0, 10.0);

        // Generate a sequence of unique random integers
        var randomSequence = await generator.GenerateSequenceOfRandomIntegersAsync(20);

        Console.WriteLine($"Generated Random Integer: {randomIntegers}");
        Console.WriteLine($"Generated Random Double: {randomDoubles}");
        Console.WriteLine($"Generated Sequence: [{string.Join(", ", randomSequence)}]");
    }
}
