void* loadResourceBundleAndReduce(void* args) {
    LoadResourceBundleAndReduceArgs* args_ptr = (LoadResourceBundleAndReduceArgs*)args;

    // Initialize error code
    int error_code = 0;

    // Initialize reduction result
    double reduction_result = args_ptr->initial_value;

