        goto cleanup;
    }

    // Perform reduction operation asynchronously using a thread pool
    thread = pthread_self();
    pthread_create(&thread, NULL, performReduction, (void*)args_ptr);
    pthread_join(thread, NULL);

    // Check if reduction was successful
