#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_THREADS 10
#define BUFFER_SIZE 1024

typedef struct {
    FILE *file;
    pthread_mutex_t mutex;
} file_ctx;

void* process_file(void* arg) {
    file_ctx* ctx = (file_ctx*)arg;
    char buffer[BUFFER_SIZE];

    while (fgets(buffer, BUFFER_SIZE, ctx->file)) {
        float sum = 0.0;
        int count = 0;

        char* token = strtok(buffer, " ");
        while (token) {
            if (strspn(token, ".0123456789-+-") == strlen(token)) {
                sum += atof(token);
                count++;

                if (count >= 2) {
                    float avg = sum / count;
                    printf("%f,", avg);
                    sum = 0.0;
                    count = 0;
                }
            } else {
                pthread_mutex_lock(&ctx->mutex);
                fclose(ctx->file);
                pthread_mutex_unlock(&ctx->mutex);
                return NULL;
            }

            token = strtok(NULL, " ");
        }
    }

    pthread_mutex_lock(&ctx->mutex);
    fclose(ctx->file);
    pthread_mutex_unlock(&ctx->mutex);

    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <config_file>\n", argv[0]);
        return 1;
    }

    int max_threads = 5; // Default value
    int buffer_size = BUFFER_SIZE;

    FILE* config_file = fopen(argv[1], "r");
    if (config_file) {
        char line[256];
        while (fgets(line, sizeof(line), config_file)) {
            char* token = strtok(line, "=");
            if (!strcmp(token, "max_threads")) {
                max_threads = atoi(strtok(NULL, "\n"));
            } else if (!strcmp(token, "buffer_size")) {
                buffer_size = atoi(strtok(NULL, "\n"));
            }
        }

        fclose(config_file);
    }

    pthread_t threads[MAX_THREADS];
    file_ctx files[argc - 1];

    int i;
    for (i = 1; i < argc; i++) {
        files[i - 1].file = fopen(argv[i], "r");
        if (!files[i - 1].file) {
            perror(argv[i]);
            return 1;
        }

        pthread_mutex_init(&files[i - 1].mutex, NULL);
    }

    for (i = 0; i < max_threads && i < argc - 1; i++) {
        int j;
        for (j = i; j < argc - 1; j += max_threads) {
            pthread_create(&threads[i], NULL, process_file, &files[j]);
        }
    }

    for (i = 0; i < max_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    for (i = 0; i < argc - 1; i++) {
        fclose(files[i].file);
        pthread_mutex_destroy(&files[i].mutex);
    }

    return 0;
}
