#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#define MAX_FILENAME_LENGTH 255
#define MAX_METADATA_SERVICE_RETRIES 3
#define PlaceholderCharacter 'X'
#define MetadataServiceQueryTimeout 1000 // in milliseconds

typedef struct {
    char *filename;
    int retries;
} metadata_service_request;

metadata_service_request generateUniqueFilename(const char *input_filename) {
    metadata_service_request request = { input_filename, 0 };

    // Validate input filename
    if (strlen(input_filename) > MAX_FILENAME_LENGTH) {
        char temp[MAX_FILENAME_LENGTH + 1];
        strncpy(temp, input_filename, MIN(MAX_FILENAME_LENGTH, strlen(input_filename)) - 1);
        temp[MAX_FILENAME_LENGTH] = '\0';
        request.filename = temp;
    } else if (strlen(input_filename) < 4) {
        char temp[5];
        strncpy(temp, input_filename, strlen(input_filename));
        temp[4] = PlaceholderCharacter;
        temp[4] = '\0';
        request.filename = temp;
    }

    // Query metadata service
    for (int i = 0; i <= MAX_METADATA_SERVICE_RETRIES; i++) {
        int fd = open("/dev/metadata_service", O_RDONLY);
        if (fd != -1) {
            char buffer[7];
            read(fd, buffer, sizeof(buffer));
            close(fd);

            // Format unique filename
            char unique_filename[MAX_FILENAME_LENGTH + 1];
            sprintf(unique_filename, "%s_%06d", request.filename, atoi(buffer));

            return request;
        } else if (i < MAX_METADATA_SERVICE_RETRIES) {
            sleep(1); // wait before retrying
        }
    }

    // Handle metadata service failure
    char error_message[256];
    sprintf(error_message, "Failed to query metadata service after %d retries", MAX_METADATA_SERVICE_RETRIES);
    request.filename = error_message;
    return request;
}
