public class CommandExecutor {
    private static final Logger LOGGER = LoggerFactory.getLogger(CommandExecutor.class);
    private Map<String, Command> commands;
    private Map<String, String> config;

    public CommandExecutor(Map<String, String> config) {
        this.config = config;
        this.commands = new HashMap<>();
    }

    public void registerCommand(String commandName, Command command) {
        commands.put(commandName, command);
    }

    public void executeCommand(String commandName, Map<String, String> parameters) throws Exception {
        Command command = commands.get(commandName);
        if (command == null) {
            throw new Exception("Unknown command: " + commandName);
        }
        try {
            command.execute(parameters);
        } catch (Exception e) {
            LOGGER.error("Failed to execute command: " + commandName, e);
            // implement retry mechanism here
        }
    }

    public interface Command {
        void execute(Map<String, String> parameters) throws Exception;
    }

    public static class LinuxCommand implements Command {
        @Override
        public void execute(Map<String, String> parameters) throws IOException {
            ProcessBuilder builder = new ProcessBuilder("bash", "-c", "command --param1=" + parameters.get("param1") + " --param2=" + parameters.get("param2"));
            builder.redirectErrorStream(true);
            Process process = builder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    public static class WindowsCommand implements Command {
        @Override
        public void execute(Map<String, String> parameters) throws IOException {
            ProcessBuilder builder = new ProcessBuilder("cmd.exe", "/c", "command --param1=" + parameters.get("param1") + " --param2=" + parameters.get("param2"));
            builder.redirectErrorStream(true);
            Process process = builder.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        Map<String, String> config = new HashMap<>();
        CommandExecutor executor = new CommandExecutor(config);

        // register commands
        executor.registerCommand("command1", new LinuxCommand());
        executor.registerCommand("command2", new WindowsCommand());

        // execute command
        Map<String, String> parameters = new HashMap<>();
        parameters.put("param1", "value1");
        parameters.put("param2", "value2");
        executor.executeCommand("command1", parameters);
    }
}
