                // Parse the decrypted message into an integer list
                List<int> integers = ParseIntegerList(decryptedBytes);

                // Identify and return the largest integer from the list
                int largestInteger = GetLargestInteger(integers);
                Console.WriteLine($"The largest integer is: {largestInteger}");
            }
        }

