    private readonly string _cloudStorageServiceUrl;

    public SecureBinaryDeserializer(string secretManagerKey, string cloudStorageServiceUrl)
    {
        _secretManagerKey = secretManagerKey;
        _cloudStorageServiceUrl = cloudStorageServiceUrl;
    }

    public async Task<TDataStructure> DeserializeAsync<TDataStructure>(string fileId) where TDataStructure : class
    {
        using var aes = Aes.Create();
        aes.Key = Encoding.UTF8.GetBytes(_secretManagerKey);
        aes.IV = Encoding.UTF8.GetBytes(_secretManagerKey);

        var request = new HttpRequestMessage(HttpMethod.Get, $"{_cloudStorageServiceUrl}/{fileId}");
        var response = await MakeApiCallAsync(request);

        if (!response.IsSuccessStatusCode)
        {
            throw new Exception($"Failed to retrieve file {fileId}: {response.StatusCode}");
        }

        using var memoryStream = new MemoryStream();
        await response.Content.CopyToAsync(memoryStream);
        memoryStream.Position = 0;

        using var decryptor = aes.CreateDecryptor(aes.Key, aes.IV);
        using var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);

        try
        {
            return JsonConvert.DeserializeObject<TDataStructure>(ReadFully(cryptoStream));
        }
        catch (JsonReaderException ex)
        {
            throw new Exception($"Failed to deserialize file {fileId}: {ex.Message}");
        }
    }

    private async Task<HttpResponseMessage> MakeApiCallAsync(HttpRequestMessage request)
    {
        // Implement your API call logic here
        return await Task.Run(() => { /* Return the HTTP response */ });
    }

    private byte[] ReadFully(Stream stream)
    {
        using var memoryStream = new MemoryStream();
        stream.CopyTo(memoryStream);
        return memoryStream.ToArray();
    }
}

