import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class DeserializationService {

    private final VersionChecker versionChecker;
    private final List<Deserializer> deserializers;
    private final ForkJoinPool forkJoinPool;

    public DeserializationService(VersionChecker versionChecker, List<Deserializer> deserializers) {
        this.versionChecker = versionChecker;
        this.deserializers = deserializers;
        this.forkJoinPool = new ForkJoinPool();
    }

    public <T> T deserialize(byte[] bytes, Class<T> targetType, int timeoutMs) throws IOException {
        try {
            VersionInfo versionInfo = getVersionInfo();
            return deserialize(bytes, targetType, timeoutMs, versionInfo.getVersion());
        } catch (Exception e) {
            logError(e);
            return handleDeserializationFailure(bytes, targetType, timeoutMs);
        }
