package com.graphdb.module;

import java.util.HashMap;
import java.util.Map;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
import org.neo4j.graphdb.GraphDatabase;
import org.neo4j.graphdb.Label;
import org.neo4j.graphdb.Node;
import org.neo4j.graphdb.Relationship;
import org.neo4j.graphdb.RelationshipType;
import org.neo4j.graphdb.Transaction;

public class GraphModule {
    private static final String ALIAS = "AES";
    private static final String KEY = "mySecretKey";
    private static final int BLOCK_SIZE = 128;

    public void initialize(GraphDatabase db) throws Exception {
        // Initialize Bouncy Castle provider for EVP_add_digest_alias
        Security.addProvider(new BouncyCastleProvider());
        // Register the AES alias for compatibility with OpenSSL
        Cipher cipher = Cipher.getInstance(ALIAS + "/ECB/NOPad");
        SecretKeySpec keySpec = new SecretKeySpec(KEY.getBytes(), ALIAS);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);
    }

    public void createVertex(Node node) {
        try (Transaction tx = db.beginTx()) {
            // Create a vertex with unique identifier and properties
            node.createLabel(Label.label("myVertexLabel"));
            // Encrypt properties using AES
            String encryptedProps = encryptProperties(node.getProperties());
            node.setProperty("encryptedProps", encryptedProps);
            tx.commit();
        } catch (Exception e) {
            // Handle errors and inconsistencies
            throw new GraphModuleException("Failed to create vertex: " + e.getMessage(), e);
        }
    }

    public void createEdge(Relationship relationship) {
        try (Transaction tx = db.beginTx()) {
            // Create an edge with unique identifier and properties
            relationship.createType(RelationshipType.withName("myEdgeType"));
            // Encrypt properties using AES
            String encryptedProps = encryptProperties(relationship.getProperties());
            relationship.setProperty("encryptedProps", encryptedProps);
            tx.commit();
        } catch (Exception e) {
            // Handle errors and inconsistencies
            throw new GraphModuleException("Failed to create edge: " + e.getMessage(), e);
        }
    }

    public void updateVertex(Node node) {
        try (Transaction tx = db.beginTx()) {
            // Update vertex properties
            Map<String, String> props = new HashMap<>();
            props.put("newProp", "newValue");
            node.setProperty("encryptedProps", encryptProperties(props));
            tx.commit();
        } catch (Exception e) {
            // Handle errors and inconsistencies
            throw new GraphModuleException("Failed to update vertex: " + e.getMessage(), e);
        }
    }

    public void updateEdge(Relationship relationship) {
        try (Transaction tx = db.beginTx()) {
            // Update edge properties
            Map<String, String> props = new HashMap<>();
            props.put("newProp", "newValue");
            relationship.setProperty("encryptedProps", encryptProperties(props));
            tx.commit();
        } catch (Exception e) {
            // Handle errors and inconsistencies
            throw new GraphModuleException("Failed to update edge: " + e.getMessage(), e);
        }
    }

    private String encryptProperties(Map<String, String> props) throws Exception {
        Cipher cipher = Cipher.getInstance(ALIAS + "/ECB/NOPad");
        SecretKeySpec keySpec = new SecretKeySpec(KEY.getBytes(), ALIAS);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);
        StringBuilder encryptedProps = new StringBuilder();
        for (Map.Entry<String, String> entry : props.entrySet()) {
            byte[] plainText = entry.getValue().getBytes();
            byte[] cipherText = cipher.doFinal(plainText);
            encryptedProps.append(new String(cipherText)).append("\n");
        }
        return encryptedProps.toString();
    }

    public void close() {
        // Close the graph database
        db.close();
    }
}

class GraphModuleException extends Exception {
    public GraphModuleException(String message, Throwable cause) {
        super(message, cause);
    }
}
