use tokio::runtime;
use std::path::Path;

#[tokio::main]
async fn main() {
    let mut runtime = runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .unwrap();

    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <library_name> [function_name]", &args[0]);
        return;
    }

    let library_name = &args[1];
    let function_name = args.get(2).cloned();

    let lib_path = format!("{}/{}", std::env::current_dir().unwrap(), library_name);
    if !Path::new(&lib_path).exists() {
        println!("Library not found: {}", library_name);
        return;
    }

    // Load the library
    let lib = runtime.block_on(load_library(&lib_path));
    if lib.is_none() {
        println!("Failed to load library: {}", library_name);
        return;
    }
    let lib = lib.unwrap();

    // Resolve and execute the function
    let func = match function_name {
        Some(name) => lib.get_function(name).unwrap(),
        None => {
            let functions = lib.functions().clone();
            println!("Available functions:");
            for func in functions {
                println!("{}", func);
            }
            return;
        }
    };

    let result = runtime.block_on(func());
    println!("{}", result);
}

async fn load_library(path: &str) -> Option<Library> {
    // Load the library using Tokio's file I/O
    let lib_file = tokio::fs::read_dir(path).await?;
    let mut lib = Library::new();
    for entry in lib_file {
        let entry = entry.unwrap();
        if entry.file_type().unwrap().is_dir() {
            // Recursively load subdirectories as libraries
            let sublib = load_library(&entry.path()).await;
            if let Some(sublib) = sublib {
                lib.merge(sublib);
            }
        } else {
            // Load individual files as functions
            let func = entry.file_name().unwrap().to_str().unwrap();
            lib.add_function(func, |file| {
                // Read the file contents and execute the function
                let contents = tokio::fs::read_to_end(file).await.unwrap();
                Box::new(move || {
                    // Execute the function with the file contents
                    println!("Executing function: {}", func);
                    // Simulate some computation here
                    std::thread::sleep(std::time::Duration::from_millis(100));
                    println!("Function executed successfully");
                    Ok(contents)
                })
            });
        }
    }
    Some(lib)
}

struct Library {
    functions: Vec<String>,
    library_name: String,
}

impl Library {
    fn new() -> Self {
        Library { functions: vec![], library_name: "".to_string() }
    }

    fn add_function(&mut self, name: &str, func: Box<dyn FnOnce() + Send>) {
        self.functions.push(name.to_string());
    }

    fn get_function(&self, name: &str) -> Option<Box<dyn FnOnce() + Send>> {
        if let Some(func) = self.functions.iter().find(|&&f| f == name.to_string()) {
            Some(func)
        } else {
            None
        }
    }

    fn merge(&mut self, other: Library) {
        self.functions.extend(other.functions);
        self.library_name = other.library_name;
    }
}
