impl UserService {
    async fn create_user_directory(&self, user_id: &str) -> Result<(), CloudStorageError> {
        let mut directory_name = format!("user-{}", user_id);
        let mut dir_path = Path::new("cloud-storage");
        loop {
            match fs::create_dir_all(dir_path.join(directory_name.clone())) {
                Ok(_) => break,
                Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                    directory_name.push_str("-1");
                }
                Err(e) => {
                    self.logger.error(&format!("Failed to create user directory: {}", e)).await?;
                    continue;
                }
            }
        }

        self.cloud_storage.put_file(Path::new("cloud-storage").join(directory_name.clone()), "user.txt", b"Hello, World!").await?;

        Ok(())
    }
}

