import asyncio
from typing import Dict, Any, Callable

class JSONParserRegistry:
    def __init__(self):
        self.registry: Dict[str, Callable[[Dict], Any]] = {}

    def register_parser(self, parser_name: str, parser_function: Callable[[Dict], Any]) -> None:
        self.registry[parser_name] = parser_function

    def get_parser(self, parser_name: str) -> Callable[[Dict], Any]:
        return self.registry.get(parser_name)

class JSONParser:
    def __init__(self, registry: JSONParserRegistry):
        self.registry = registry

    async def parse_json(self, json_data: Dict, parser_name: str) -> Any:
        if not isinstance(json_data, dict):
            raise ValueError("Invalid JSON format")
        try:
            parser_function = self.registry.get_parser(parser_name)
            if parser_function is None:
                raise ValueError(f"Parser '{parser_name}' not found")
            return await asyncio.to_thread(parser_function, json_data)
        except Exception as e:
            raise ValueError(f"Error parsing JSON: {str(e)}")

    async def create_json(self, data: Any) -> Dict:
        try:
            if isinstance(data, dict):
                return data
            else:
                raise ValueError("Invalid data type")
        except Exception as e:
            raise ValueError(f"Error creating JSON: {str(e)}")

class JSONHandler:
    def __init__(self, parser_registry: JSONParserRegistry):
        self.parser_registry = parser_registry

    async def handle_json_request(self, request_data: Dict) -> Any:
        try:
            json_data = await self.parser_registry.parse_json(request_data, 'my_parser')
            return await self.parser_registry.create_json(json_data)
        except Exception as e:
            raise ValueError(f"Error handling JSON request: {str(e)}")

if __name__ == "__main__":
    registry = JSONParserRegistry()
    parser_registry = JSONParser(registry)

    @registry.register_parser('my_parser', 'my_unique_identifier')
    def my_parser(json_data: Dict) -> Any:
        # your custom parser logic here
        pass

    handler = JSONHandler(parser_registry)
    asyncio.run(handler.handle_json_request({'key': 'value'}))
