int validateOAuth2AccessToken(char* accessTokenResponse) {
    JSON_Object* jsonObject = json_object_from_string(accessTokenResponse);
    if(jsonObject == NULL || json_object_get_type(jsonObject, "access_token") != JSON_TYPE_STRING ||
       json_object_get_type(jsonObject, "expires_in") != JSON_TYPE_INTEGER ||
       json_object_get_type(jsonObject, "token_type") != JSON_TYPE_STRING) {
        return 0;
    }
    const char* accessToken = json_object_get_string(jsonObject, "access_token");
    int expiresIn = json_object_get_int(jsonObject, "expires_in");
    const char* tokenType = json_object_get_string(jsonObject, "token_type");

    // Verify the presence and validity of required fields
    if(strlen(accessToken) == 0 || expiresIn <= 0 || strcmp(tokenType, "Bearer") != 0) {
        return 0;
    }
    return 1;
}

