using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;

namespace DynamicRandomValueGenerator
{
    public class DynamicRandomValueGenerator
    {
        private readonly Random _random = new();
        private readonly Dictionary<string, Distribution> _distributions = new();
        private readonly object _lock = new();

        public event EventHandler<RangeChangedEventArgs> RangeChanged;

        public void Initialize(string configurationFilePath)
        {
            if (!File.Exists(configurationFilePath))
                throw new FileNotFoundException("Configuration file not found", configurationFilePath);

            var lines = File.ReadAllLines(configurationFilePath);
            foreach (var line in lines)
            {
                var parts = line.Split(',');
                _distributions.Add(parts[0], new Distribution(double.Parse(parts[1]), double.Parse(parts[2])));
            }
        }

        public int GenerateRandomInt(int min, int max, bool inclusive)
        {
            ValidateRange(min, max);
            return inclusive ? _random.Next(min, max + 1) : _random.Next(min, max);
        }

        public double GenerateRandomDouble(double min, double max, bool inclusive)
        {
            ValidateRange(min, max);
            return inclusive ? _random.NextDouble() * (max - min) + min : _random.NextDouble() * (max - min) + min;
        }

        public int[] GenerateRandomSequence(int length, int min, int max, bool inclusive)
        {
            var sequence = new HashSet<int>();
            while (sequence.Count < length)
                sequence.Add(GenerateRandomInt(min, max, inclusive));
            return sequence.ToArray();
        }

        public double[] GenerateRandomSequence(double length, double min, double max, bool inclusive)
        {
            var sequence = new HashSet<double>();
            while (sequence.Count < (int)length)
                sequence.Add(GenerateRandomDouble(min, max, inclusive));
            return sequence.ToArray();
        }

        private void ValidateRange(double min, double max)
        {
            if (_distributions.ContainsKey("default"))
                _distributions["default"].ValidateRange(min, max);
            else
                throw new ArgumentException("Invalid range");
        }

        public class Distribution
        {
            public double Min { get; }
            public double Max { get; }

            public Distribution(double min, double max)
            {
                Min = min;
                Max = max;
            }

            public void ValidateRange(double min, double max)
            {
                if (min < this.Min || max > this.Max)
                    throw new ArgumentException("Invalid range");
            }
        }

        public class RangeChangedEventArgs : EventArgs
        {
            public int Min { get; set; }
            public int Max { get; set; }
        }
    }
}
