namespace RealtimeDataGenerator
{
    public class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly IConfiguration _configuration;
        private readonly IExternalApiService _externalApiService;
        private readonly ILogger _logger;
        private readonly ICacheService _cacheService;
        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1);

        public RandomValueGenerator(IConfiguration configuration, IExternalApiService externalApiService, ILogger logger, ICacheService cacheService)
        {
            _configuration = configuration;
            _externalApiService = externalApiService;
            _logger = logger;
            _cacheService = cacheService;
        }

        public async Task<int> GenerateRandomIntExclusive(int min, int max)
        {
            await ValidateRange(min, max);
            return _rng.Next(min, max + 1);
        }

        public async Task<int> GenerateRandomIntInclusive(int min, int max)
        {
            await ValidateRange(min, max);
            return _rng.Next(min - 1, max + 1);
        }

        public async Task<float> GenerateRandomFloatExclusive(float min, float max)
        {
            await ValidateRange(min, max);
            return _rng.NextSingle() * (max - min) + min;
        }

        public async Task<float> GenerateRandomFloatInclusive(float min, float max)
        {
            await ValidateRange(min, max);
            return (_rng.NextDouble() * (max - min)) + min;
        }

        public async Task<List<T>> GenerateRandomSequence<T>(int length, Func<int, T> generator) where T : IEquatable<T>
        {
            List<T> sequence = new List<T>();
            while (sequence.Count < length)
            {
                int value;
                if (_cacheService.TryGetNextValue(out value))
                {
                    sequence.Add(generator(value));
                }
                else
                {
                    await TryGenerateAndCacheNextValue();
                    await TryAddToSequence(generator);
                }
            }
            return sequence.Distinct().ToList();
        }

        private async Task ValidateRange(int min, int max)
        {
            if (_cacheService.TryGetCachedRange(out (int, int) cachedMinMax))
            {
                if ((min >= cachedMinMax.Item1 && min <= cachedMinMax.Item2) ||
                    (max >= cachedMinMax.Item1 && max <= cachedMinMax.Item2))
                {
                    return;
                }
            }

            await _externalApiService.ValidateRange(min, max);
            _cacheService.SetCachedRange(min, max);
        }

        private async Task TryGenerateAndCacheNextValue()
        {
            while (true)
            {
                try
                {
                    int value = await GenerateRandomIntExclusive(0, 1000000);
                    if (_cacheService.TrySetNextValue(value))
                    {
                        return;
                    }
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex.Message);
                    await Task.Delay(TimeSpan.FromMilliseconds(500));
                }
            }
        }

        private async Task TryAddToSequence(Func<int, T> generator)
        {
            while (true)
            {
                try
                {
                    T value = generator(_cacheService.NextValue());
                    return;
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex.Message);
                    await Task.Delay(TimeSpan.FromMilliseconds(500));
                }
            }
        }

        private readonly Random _rng = new Random();
    }
}
