// Define constants for logging levels and priorities
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_ERROR 2
#define LOG_PRIORITY_HIGH 3
#define LOG_PRIORITY_LOW 4

// Structure to hold log event details
typedef struct {
    int level; // Logging level (INFO, ERROR)
    int priority; // Logging priority (HIGH, LOW)
    char* message; // Log message
    char* tags; // Custom log tags
} LogEvent;

// Function prototypes
void init_logging();
void log_event(LogEvent event);
int send_log_to_cloud(const LogEvent event);
int send_log_to_file(const LogEvent event);

// Global variables
FILE* log_file;
int cloud_socket;
char* cloud_address = "localhost:8080";
int cloud_port = 8081;

int main() {
    init_logging();

    // Example usage:
    LogEvent event;
    event.level = LOG_LEVEL_ERROR;
    event.priority = LOG_PRIORITY_HIGH;
    event.message = "Error occurred!";
    event.tags = "error=500,service=A";

    log_event(event);
    return 0;
}

void init_logging() {
    log_file = fopen("log.txt", "a");
    if (!log_file) {
        printf("Failed to open log file!\n");
        exit(1);
    }

    // Set up cloud logging
    cloud_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (cloud_socket < 0) {
        printf("Failed to create cloud socket!\n");
        exit(1);
    }

    struct sockaddr_in cloud_addr;
    cloud_addr.sin_family = AF_INET;
    cloud_addr.sin_port = htons(cloud_port);
    inet_pton(AF_INET, cloud_address, &cloud_addr.sin_addr);

    if (connect(cloud_socket, (struct sockaddr*) &cloud_addr, sizeof(cloud_addr)) < 0) {
        printf("Failed to connect to cloud logging!\n");
        exit(1);
    }
}

void log_event(LogEvent event) {
    // Log to file
    fprintf(log_file, "[%s] %s (%s)\n", event.tags, event.message, event.level == LOG_LEVEL_ERROR ? "ERROR" : "INFO");
    fflush(log_file);

    // Log to cloud (if available)
    if (send_log_to_cloud(event)) {
        printf("Failed to send log to cloud!\n");
    }

    // Log to file (again) as a fallback
    fprintf(log_file, "[%s] %s (%s)\n", event.tags, event.message, event.level == LOG_LEVEL_ERROR ? "ERROR" : "INFO");
    fflush(log_file);
}

