import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

import javax.persistence.EntityManagerFactory;
import java.util.List;
import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;

@SpringBootApplication
@EnableCaching
@EnableDiscoveryClient
public class DynamicRandomValueGeneratorApplication {

    public static void main(String[] args) {
        SpringApplication.run(DynamicRandomValueGeneratorApplication.class, args);
    }

    @Bean
    public JpaCacheRepository jpaCacheRepository(EntityManagerFactory entityManagerFactory) {
        return new JpaCacheRepository(entityManagerFactory);
    }

    @RestController
    public class RandomValueController {

        private final Random random;
        private final AtomicInteger requestCount;

        public RandomValueController(Random random, AtomicInteger requestCount) {
            this.random = random;
            this.requestCount = requestCount;
        }

        @GetMapping("/generate/{rangeStart}/{rangeEnd}")
        public List<Double> generateRandomValues(@PathVariable int rangeStart, @PathVariable int rangeEnd) {
            // Generate random values within the specified range
            return IntStream.rangeClosed(rangeStart, rangeEnd)
                    .mapToObj(i -> (double) random.nextInt(10000) / 100.0d)
                    .collect(Collectors.toList());
        }
    }

    @Bean
    public Random random() {
        return new Random();
    }

    @Bean
    public AtomicInteger requestCount() {
        return new AtomicInteger();
    }
}

