    int id;
    float version;
    void (*init)(void);
    void (*deinit)(void);
    void (*crypt)(void);
} Algorithm;

// Array of algorithms
Algorithm* algos[10];
int algo_count = 0;

// Initialize the library
void init_lib() {
    // Load algorithms from external libraries
    for (int i = 0; i < algo_count; i++) {
        algos[i]->init();
    }
}

// Deinitialize the library
void deinit_lib() {
    // Unload algorithms from external libraries
    for (int i = 0; i < algo_count; i++) {
        algos[i]->deinit();
    }
}

// Load an algorithm into memory
Algorithm* load_algorithm(const char* name, int id) {
    Algorithm* algo = malloc(sizeof(Algorithm));
    algo->name = strdup(name);
    algo->id = id;
    // Initialize the algorithm
    algo->init();
    return algo;
}

// Unload an algorithm from memory
void unload_algorithm(Algorithm* algo) {
    free(algo->name);
    free(algo);
}

// Function to query the status of algorithms
int query_status(const char* name) {
    for (int i = 0; i < algo_count; i++) {
        if (strcmp(algos[i]->name, name) == 0) {
            return 1;
        }
    }
    return -1;
}

// Thread-safe error handling and logging
void log_error(const char* message) {
    // Log the error to a file or console
    printf("%s\n", message);
}

