        char *input = "Hello, World!";
        char output[1024];
        encrypt(input, output);
        printf("Encrypted text: %s\n", output);
    } else if (choice == 2) {
        // RSA encryption/decryption implementation
        // ...
    } else if (choice == 3) {
        // DES encryption/decryption implementation
        // ...
    }

    // Clean up OpenSSL library
    SSL_shutdown();

    return 0;
}

void encrypt(char *input, char *output) {
    // AES encryption using OpenSSL
    EVP_CIPHER_CTX ctx;
    unsigned char iv[16];
    int len;

    // Initialize the encryption context
    EVP_EncryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, input, strlen(input));

    // Set the initialization vector (IV)
    RAND_bytes(iv, 16);

    // Perform AES encryption
    EVP_EncryptUpdate(&ctx, output, &len, iv, 16);
    EVP_EncryptFinal_ex(&ctx, output + len, &len);

    return;
}

void decrypt(char *input, char *output) {
    // AES decryption using OpenSSL
    EVP_CIPHER_CTX ctx;
    unsigned char iv[16];
    int len;

    // Initialize the decryption context
    EVP_DecryptInit_ex(&ctx, EVP_aes_256_cbc(), NULL, input, strlen(input));

    // Set the initialization vector (IV)
    RAND_bytes(iv, 16);

    // Perform AES decryption
    EVP_DecryptUpdate(&ctx, output, &len, iv, 16);
    EVP_DecryptFinal_ex(&ctx, output + len, &len);

    return;
}
