        self.redis_client.set(queue_name, '[]')

    def delete_queue(self, queue_name: str) -> None:
        self.redis_client.delete(queue_name)

    def enqueue(self, queue_name: str, message: Dict[str, Any]) -> None:
        self.redis_client.lpush(queue_name, json.dumps(message))

    def dequeue(self, queue_name: str) -> Dict[str, Any]:
        return json.loads(self.redis_client.rpop(queue_name).decode('utf-8'))

    def update_queue(self, queue_name: str, message: Dict[str, Any]) -> None:
        self.enqueue(queue_name, message)

    def get_queue_depth(self, queue_name: str) -> int:
        return len(self.redis_client.lrange(queue_name, 0, -1))

    def start_consumer(self, topic_name: str):
