#include <atomic>
#include <condition_variable>
#include <memory>
#include <mutex>
#include <queue>
#include <thread>

namespace distributed_kv_store {

class Node {
public:
    Node(size_t id) : id_(id), in_progress_(false), conflicts_({}) {}

    void start() {
        thread_ = std::thread(&Node::run, this);
    }

    void stop() {
        if (thread_) {
            thread_.join();
            thread_.detach();
            thread_ = nullptr;
        }
    }

private:
    size_t id_;
    bool in_progress_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::queue<std::function<void()> > queue_;
    std::unique_ptr<std::thread> thread_;

    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            condition_.wait_for(lock, std::chrono::milliseconds(10));
            if (!queue_.empty()) {
                auto task = queue_.front();
                queue_.pop();
                task();
                in_progress_ = false;
            }
        }
    }

    void post(std::function<void()> task) {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (in_progress_) {
                conflicts_.push(task);
            } else {
                queue_.push(task);
            }
        }
        condition_.notify_one();
    }

    void resolve_conflict() {
        while (!conflicts_.empty()) {
            auto task = conflicts_.front();
            conflicts_.pop();
            post([this, task]() {
                in_progress_ = true;
                task();
            });
        }
    }

    std::map<std::string, std::any> data_;
};

class KeyValueStore {
public:
    KeyValueStore(size_t node_count) : nodes_(node_count) {}

    void start() {
        for (auto& node : nodes_) {
            node.start();
        }
    }

    void stop() {
        for (auto& node : nodes_) {
            node.stop();
        }
    }

    template <typename K, typename V>
    void put(K key, V value) {
        for (auto& node : nodes_) {
            node.post([this, key, value]() {
                data_.insert({key, value});
            });
        }
    }

private:
    std::vector<Node> nodes_;
};

}

