class TestRunner {
  constructor(config) {
    this.config = config;
    this.testResults = [];
    this.errorCount = 0;
  }

  async loadTests(moduleName) {
    const tests = await fs.readdirSync(`./tests/${moduleName}`);
    return tests.filter((test) => test.endsWith('.js'));
  }

  async runTests(tests, concurrency) {
    const childProcesses = [];

    for (const test of tests) {
      let process = spawn('node', [path.join(__dirname, `../tests/${moduleName}/${test}`)]);

      process.stdout.on('data', (data) => {
        console.log(`Test ${test} stdout: ${data.toString()}`);
      });

      childProcesses.push(process);
    }

    await Promise.all(childProcesses.map((process) => new Promise((resolve) => {
      process.on('exit', () => resolve());
    })));

    for (const process of childProcesses) {
      process.kill();
    }
  }

  async monitorTests(concurrency, interval) {
    let testCount = 0;
    let errorCount = 0;

    setInterval(() => {
      console.log(`Current Test Count: ${testCount}`);
      console.log(`Error Count: ${errorCount}`);

      if (errorCount > 0 && testCount >= this.config.threshold) {
        const emailSubject = `Failed Tests in Module ${moduleName}`;
        const emailBody = `Failed tests in module ${moduleName}: ${this.testResults.filter((result) => result.status === 'failed')}`;

        await sendEmail(emailSubject, emailBody);
      }
    }, interval * 1000);

    for (const process of childProcesses) {
      process.stdout.on('data', (data) => {
        const testResult = JSON.parse(data.toString());

        if (testResult.status === 'passed') {
          testCount++;
        } else {
          errorCount++;
          this.testResults.push(testResult);
        }
      });

      process.stderr.on('data', (error) => {
