use tokio::prelude::*;
use std::sync::{Arc,Mutex};
use serde_json::{json,Tuple};

#[tokio::main]
async fn main() {
    let cache = Arc::new(Mutex::new(cache::InMemoryCache::default()));
    let api_client = ApiClient::new("https://your-api.com");
    let mut collector = Collector::new(api_client, cache);

    // Start the data collection
    tokio::spawn(collector.collect_data().await);
}

struct Collector {
    api_client: Arc<ApiClient>,
    cache: Arc<Mutex<InMemoryCache>>,
}

impl Collector {
    async fn collect_data(&self) -> Result<(), Box<dyn std::error::Error>> {
        loop {
            // Fetch new data from the API
            let data = self.api_client.fetch_data().await?;

            // Store the data in the cache
            self.cache.lock().unwrap().store(data.clone())?;

            // Check for pause/resume signals
            if self.should_pause() {
                self.pause().await?;
            } else {
                self.resume().await?;
            }
        }
    }

    async fn should_pause(&self) -> bool {
        // Implement your logic to determine when to pause
        false
    }

    async fn pause(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Pause the data collection and notify any waiting threads
        self.cache.lock().unwrap().pause()?;

        tokio::time::sleep(std::time::Duration::from_millis(100)).await;

        Ok(())
    }

    async fn resume(&self) -> Result<(), Box<dyn std::error::Error>> {
        // Resume the data collection and notify any waiting threads
        self.cache.lock().unwrap().resume()?;

        Ok(())
    }
}

struct ApiClient {
    base_url: String,
}

impl ApiClient {
    fn new(base_url: &str) -> Self {
        ApiClient { base_url: base_url.to_string() }
    }

    async fn fetch_data(&self) -> Result<String, Box<dyn std::error::Error>> {
        // Make the API request and return the response
        let client = reqwest::blocking::get(self.base_url.clone()).await?;
        let data = client.text().await?;

        Ok(data)
    }
}

struct InMemoryCache {
    data: Vec<String>,
    paused: bool,
}

impl InMemoryCache {
    fn default() -> Self {
        InMemoryCache { data: vec![], paused: false }
    }

    fn store(&mut self, data: String) -> Result<(), Box<dyn std::error::Error>> {
        // Store the data in the cache
        self.data.push(data.clone());

        Ok(())
    }

    fn pause(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        self.paused = true;

        Ok(())
    }

    fn resume(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        self.paused = false;

        Ok(())
    }
}
