// Add a new network metric to the library
void add_network_metric(NetworkMetrics* metrics, int cell_id, time_t timestamp, const char* location, double value) {
    // Check if the metric array needs to be resized
    if (metrics->count >= metrics->capacity) {
        // Double the capacity of the metrics array
        metrics->capacity *= 2;
        // Realocate memory for the metrics array
        metrics->metrics = (NetworkMetric*)realloc(metrics->metrics, metrics->capacity * sizeof(NetworkMetric));
    }

    // Add the new metric to the end of the array
    NetworkMetric* new_metric = &metrics->metrics[metrics->count++];
    new_metric->cell_id = cell_id;
    new_metric->timestamp = timestamp;
    strcpy(new_metric->location, location);
    new_metric->metric_value = value;
