    private int currentInstance;

    // Constructor for creating new AdaptiveRouter instances
    public AdaptiveRouter() {
        this.currentInstance = 0;
    }

    // Route log events to the next available instance based on load balancing and data skew detection
    public void routeLogEvent(LogEvent event) {
        if (isDataSkewed()) {
            // Adjust routing based on detected data skew
            currentInstance = getAdjustedInstance();
        } else {
            // Default to a round-robin strategy for load balancing
            currentInstance = (currentInstance + 1) % 100;
        }

        // Route the log event to the selected instance
