#include <iostream>
#include <string>
#include <map>
#include <thread>
#include <mutex>

class KVStore {
public:
    KVStore(size_t numNodes) : nodes(numNodes), leaderNodeId(0) {}

    void put(const std::string& key, const std::string& value) {
        // Distributed write operation
        write(key, value);
    }

    std::string get(const std::string& key) {
        // Distributed read operation
        return read(key);
    }

private:
    std::map<std::string, std::string> localData;
    std::vector<KVNode*> nodes;
    size_t leaderNodeId;

    void write(const std::string& key, const std::string& value) {
        // Write to the current node's local data
        localData[key] = value;

        // Replicate the write to other nodes (asynchronous)
        for (size_t i = 0; i < nodes.size(); ++i) {
            if (i != leaderNodeId) {
                nodes[i]->receiveWrite(key, value);
            }
        }
    }

    std::string read(const std::string& key) {
        // First try to find the value in the local data
        auto it = localData.find(key);
        if (it != localData.end()) {
            return it->second;
        }

        // If not found, query other nodes
        for (size_t i = 0; i < nodes.size(); ++i) {
            if (i != leaderNodeId) {
                std::string value = nodes[i]->read(key);
                if (!value.empty()) {
                    return value;
                }
            }
        }

        // Not found in any node
        return "";
    }
};

class KVNode {
public:
    KVNode(size_t id, KVStore* store) : id(id), store(store) {}

    void receiveWrite(const std::string& key, const std::string& value) {
        // Update local data and notify other nodes (asynchronous)
        store->localData[key] = value;
        for (size_t i = 0; i < store->nodes.size(); ++i) {
            if (i != id) {
                store->nodes[i]->receiveWrite(key, value);
            }
        }
    }

    std::string read(const std::string& key) {
        // Return the value from local data
        auto it = store->localData.find(key);
        if (it != store->localData.end()) {
            return it->second;
        }

        // If not found, query other nodes
        for (size_t i = 0; i < store->nodes.size(); ++i) {
            if (i != id) {
                std::string value = store->nodes[i]->read(key);
                if (!value.empty()) {
                    return value;
                }
            }
        }

        // Not found in any node
        return "";
    }

private:
    size_t id;
    KVStore* store;
};

int main() {
    KVStore kvStore(4); // 4 nodes

    // Initialize the nodes with their respective roles (e.g., leader, follower)
    std::vector<std::unique_ptr<KVNode>> nodes = {
        std::make_unique<KVNode>(0, &kvStore),
        std::make_unique<KVNode>(1, &kvStore),
        std::make_unique<KVNode>(2, &kvStore),
        std::make_unique<KVNode>(3, &kvStore)
    };

    // Start the nodes in separate threads
    for (auto& node : nodes) {
        std::thread t([node = std::move(node)]() {
            node->start();
        });
        t.detach();
    }

    return 0;
}
