import java.util.*;

public class EventLogProcessor {
    private static final int MAX_EVENTS = (int) Math.pow(10, 7);
    private Map<String, List<Event>> eventsByTime;
    private Map<Integer, UnionFind> eventGroups;

    public EventLogProcessor() {
        this.eventsByTime = new HashMap<>();
        this.eventGroups = new HashMap<>();
    }

    public void processEvents(List<Event> events) {
        for (Event event : events) {
            int startTime = event.getStart();
            int endTime = event.getEnd();

            // Group events by time
            if (!eventsByTime.containsKey(String.valueOf(startTime))) {
                eventsByTime.put(String.valueOf(startTime), new ArrayList<>());
            }
            eventsByTime.get(String.valueOf(startTime)).add(event);

            // Update event groups
            for (Map.Entry<Integer, UnionFind> entry : eventGroups.entrySet()) {
                if (entry.getKey() >= startTime && entry.getKey() < endTime) {
                    union(entry.getValue(), findGroup(endTime));
                }
            }

            // Create a new group for this event
