class ClinicStatusManager {
    private $mysqlConfig;
    private $semaphore;

    public function __construct($mysqlConfig) {
        $this->mysqlConfig = $mysqlConfig;
        $this->semaphore = new Semaphores();
    }

    public function updateClinicStatus(int $clinicId, string $status, string $lastModifiedIp, int $timestamp): void {
        $db = new PDO('mysql:host=' . $this->mysqlConfig['host'] . ';dbname=' . $this->mysqlConfig['database'], $this->mysqlConfig['username'], $this->mysqlConfig['password']);
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        try {
            $stmt = $db->prepare("UPDATE clinic_status SET status = ?, last_modified_ip = ?, timestamp = ? WHERE id = ?");
            $stmt->execute([$status, $lastModifiedIp, $timestamp, $clinicId]);
            $this->semaphore->release();
        } catch (PDOException $e) {
            // Handle transient errors and reconnect if necessary
            if ($e->getCode() == 2013) { // MySQL connection lost
                $this->mysqlConfig['retries']++;
                if ($this->mysqlConfig['retries'] > 5) {
                    throw new Exception('Maximum retries exceeded');
                }
                sleep(1);
                $this->updateClinicStatus($clinicId, $status, $lastModifiedIp, $timestamp);
            } else {
                // Log and rethrow the exception
                error_log('Error updating clinic status: ' . $e->getMessage());
                throw $e;
            }
        }
    }
}

