@app.route('/aggregate', methods=['POST'])
def aggregate_data():
    data = request.get_json()
    if not data:
        return jsonify({'message': 'No data provided'}), 400

    try:
        df = pd.DataFrame(data)

        aggregated_data = defaultdict(dict)
        for index, row in df.iterrows():
            user_id = str(row['user_id'])
            event_type = str(row['event_type'])

            if not aggregated_data[user_id]:
                aggregated_data[user_id] = {}

            if event_type not in aggregated_data[user_id]:
                aggregated_data[user_id][event_type] = 0

            aggregated_data[user_id][event_type] += row['count']

        return jsonify(aggregated_data), 200

    except Exception as e:
        q.enqueue('error_handler', str(e))
        return jsonify({'message': 'Error occurred during aggregation'}), 500

@app.route('/report', methods=['GET'])
def generate_report():
    params = request.args
    if not params:
        return jsonify({'message': 'No parameters provided'}), 400

    try:
        user_id = str(params['user_id'])
        time_interval = str(params['time_interval'])

        report_data = defaultdict(dict)
        for user, events in aggregated_data.items():
            if user != user_id:
                continue

            for event_type, count in events.items():
                if time_interval == 'all':
                    report_data[event_type][count]
                else:
                    start_time, end_time = time_interval.split('-')
                    start_time = pd.to_datetime(start_time)
                    end_time = pd.to_datetime(end_time)

                    if start_time <= events[0]['timestamp'] <= end_time:
                        report_data[event_type][count] += 1

        return jsonify(report_data), 200

    except Exception as e:
        q.enqueue('error_handler', str(e))
        return jsonify({'message': 'Error occurred during report generation'}), 500

if __name__ == '__main__':
