// Define the function that verifies the OAuth2 access token response
bool verifyOAuth2Token(const std::string& jsonStr) {
    Json::Value root;
    Json::Reader reader;

    try {
        if (!reader.parse(jsonStr, root)) {
            return false; // JSON parsing failed
        }

        if (root["access_token"].asString().empty()) {
            return false; // "access_token" field is missing or empty
        }

        if (root["token_type"].asString() != "Bearer") {
            return false; // "token_type" must be 'Bearer'
        }

        int expiresIn = root["expires_in"].asInt();
        if (expiresIn <= 0) {
            return false; // "expires_in" must be a positive integer
        }

        std::string refreshTokenStr = root["refresh_token"].asString();
        if (!refreshTokenStr.empty()) {
            // Check the refresh token validity (optional)
        }

        return true;
    } catch (Json::Exception& e) {
        return false; // JSON parsing exception occurred
    }
}

int main() {
    std::string jsonStr = R"({
        "access_token": "some-access-token",
        "token_type": "Bearer",
        "expires_in": 3600,
        "refresh_token": "some-refresh-token"
    })";

    if (verifyOAuth2Token(jsonStr)) {
        std::cout << "OAuth2 token is valid." << std::endl;
    } else {
        std::cout << "OAuth2 token is invalid." << std::endl;
    }

    return 0;
}
