import logging
from kafka import KafkaProducer
from elasticsearch import Elasticsearch
from celery import Celery
import json

class DistributedLogger:
    def __init__(self):
        self.logger = logging.getLogger('distributed_logger')
        self.producer = KafkaProducer(bootstrap_servers=['localhost:9092'])
        self.es = Elasticsearch(['es-node-1:9200', 'es-node-2:9200'], 
                                 timeout=60, max_retries=10, retry_on_timeout=True)
        self.celery_app = Celery('logger', broker='amqp://guest@localhost')

    def send_log(self, log_entry):
        try:
            self.producer.send('logs_topic', json.dumps(log_entry).encode())
        except Exception as e:
            self.logger.error(f"Error sending log to Kafka: {e}")

    def process_log(self, log_entry):
        try:
            self.es.index(index='logs_index', body=json.dumps(log_entry))
        except Exception as e:
            self.logger.error(f"Error indexing log in Elasticsearch: {e}")

    def filter_logs(self, query):
        try:
            results = self.es.search(body=query)
            return [log['source'] for log in results['hits']['hits']]
        except Exception as e:
            self.logger.error(f"Error filtering logs in Elasticsearch: {e}")

app = DistributedLogger()

@app.task
def process_log_entry(log_entry):
    app.process_log(log_entry)

if __name__ == '__main__':
    app.listen(['0.0.0.0', 8000])
