#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgen.h>

#define MAX_LINE_LENGTH 1024
#define MAX_LOG_FILES 1000
#define MAX_FIELDS_PER_LINE 50

typedef struct {
    char filename[256];
    int numFields;
} LogFile;

void process_log_file(LogFile *log_file) {
    int fd = open(log_file->filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fd)) {
        // Tokenize the line into fields
        char *fields[MAX_FIELDS_PER_LINE];
        int num_fields = 0;
        char *token = strtok(line, " ");
        while (token && num_fields < MAX_FIELDS_PER_LINE) {
            fields[num_fields++] = token;
            token = strtok(NULL, " ");
        }

        // Find the last three numeric fields
        int sum = 0;
        for (int i = num_fields - 3; i >= 0; i--) {
            if (strtol(fields[i], NULL, 10) != LONG_MIN && strtol(fields[i], NULL, 10) != LONG_MAX) {
                sum += strtol(fields[i], NULL, 10);
            }
        }

        // Calculate the average
        double avg = (double)sum / num_fields;

        printf("File: %s, Average: %.2f\n", log_file->filename, avg);

        close(fd);
    }

    close(fd);
}

int main(int argc, char *argv[]) {
    LogFile log_files[MAX_LOG_FILES];
    int num_log_files = 0;

    // Read the configuration file
    FILE *config = fopen("config.json", "r");
    if (config == NULL) {
        perror("Error opening config file");
        return -1;
    }

    // Parse the configuration file and initialize log files
    while (!feof(config)) {
        char line[256];
        fgets(line, 256, config);
        LogFile *log_file = &log_files[num_log_files++];
        sscanf(line, "%s %d", log_file->filename, &log_file->numFields);
    }

    fclose(config);

    // Process the log files concurrently
    int num_processes = sysconf(_SC_NPROCESSORS_ONLN);
    pthread_t threads[num_processes];
    for (int i = 0; i < num_log_files; i++) {
        pthread_create(&threads[i], NULL, process_log_file, &log_files[i]);
    }

    for (int i = 0; i < num_log_files; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
