#define TIFF_MAX_SAMPLES 4 // Adjust according to the TIFF standard

typedef struct {
    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    char compression_method[16];
    uint32_t extra_samples;
} tiff_image_info;

void extract_tiff_metadata(const char* file_path, MYSQL *mysql) {
    TIFF* tif = TIFFOpen(file_path, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open %s\n", file_path);
        return;
    }

    uint16_t bits_per_sample;
    uint16_t samples_per_pixel;
    char compression_method[16];
    uint32_t extra_samples;

    // Parse TIFF metadata
    if (TIFFGetField(tif, TIFF_FIELD_IMAGE_WIDTH, &bits_per_sample) ||
        TIFFGetField(tif, TIFF_FIELD_IMAGE_HEIGHT, &samples_per_pixel) ||
        TIFFGetField(tif, TIFF_FIELD_COMPRESSION, compression_method) ||
        TIFFGetField(tif, TIFF_FIELD_EXTRA_SAMPLES, &extra_samples)) {
        fprintf(stderr, "Error parsing TIFF metadata\n");
        return;
    }

    // Store extracted metadata in a database
    mysql_query(mysql, "INSERT INTO tiff_images (bits_per_sample, samples_per_pixel, compression_method, extra_samples) VALUES (?, ?, ?, ?)");
    mysql_stmt_bind_param(stmt, "iiii", bits_per_sample, samples_per_pixel, strlen(compression_method), extra_samples);
    mysql_stmt_execute(stmt);

    // Close TIFF file
    TIFFClose(tif);
}

int main(int argc, char** argv) {
    MYSQL* mysql = mysql_init(NULL);
    if (!mysql) {
        fprintf(stderr, "Failed to initialize MySQL connection\n");
        return 1;
    }

    // Establish a database connection
    if (mysql_real_connect(mysql, "localhost", "username", "password", "database", 0, NULL, 0)) {
        // Parse and extract TIFF metadata for each file
        for (int i = 0; i < argc; i++) {
            const char* file_path = argv[i];
            extract_tiff_metadata(file_path, mysql);
        }

        // Close the database connection
        mysql_close(mysql);
    } else {
        fprintf(stderr, "Failed to establish MySQL connection\n");
        return 1;
    }

    return 0;
}
