from abc import ABC, abstractmethod
from threading import Lock
from enum import Enum

class CryptoAlgorithm(Enum):
    AES = 1
    Camellia = 2
    MD5 = 3
    SHA256 = 4
    RSA_SHA1 = 5

class CryptoPlugin(ABC):
    @abstractmethod
    def encrypt(self, data: bytes) -> bytes:
        pass

    @abstractmethod
    def decrypt(self, data: bytes) -> bytes:
        pass

class PluginRegistry:
    _registry = {}
    _lock = Lock()

    @classmethod
    def register(cls, algorithm_name: str):
        with cls._lock:
            if algorithm_name in cls._registry:
                raise ValueError(f"Algorithm {algorithm_name} already registered")
            cls._registry[algorithm_name] = None

    @classmethod
    def get_plugin(cls, algorithm_name: str):
        with cls._lock:
            return cls._registry.get(algorithm_name)

class CryptoManager:
    _plugins = {}
    _logger = logging.getLogger(__name__)

    def __init__(self, config_file: str):
        self.load_plugins(config_file)

    def load_plugins(self, config_file: str):
        if not os.path.exists(config_file):
            raise FileNotFoundError(f"Config file {config_file} not found")

        with open(config_file, 'r') as f:
            config = json.load(f)

        for algo in config.get('algorithms', []):
            plugin_name = algo['name']
            PluginRegistry.register(plugin_name)
            self._plugins[plugin_name] = None

    def get_plugin(self, algorithm_name: str) -> CryptoPlugin:
        return PluginRegistry.get_plugin(algorithm_name)

    # ... (other methods for encryption, decryption, etc.)
