import logging
from queue import Queue
from threading import Thread
import time

class LogProcessor:
    def __init__(self):
        self.logger = logging.getLogger("LogProcessor")
        self.logger.setLevel(logging.INFO)
        formatter = logging.Formatter("%(asctime)s - %(name)s - %(levelname)s - %(message)s")
        file_handler = logging.FileHandler("log.txt")
        file_handler.setFormatter(formatter)
        self.logger.addHandler(file_handler)

    def process_log(self, log_event):
        if log_event["level"] == "ERROR":
            self.logger.error(log_event["message"])
        elif log_event["level"] == "WARNING":
            self.logger.warning(log_event["message"])
        else:
            self.logger.info(log_event["message"])

class LogProducer:
    def __init__(self, queue):
        self.queue = queue

    def produce_log(self):
        while True:
            log_event = {"level": "INFO", "message": f"Log event at {time.time()}"}
            self.queue.put(log_event)
            time.sleep(0.1)

class LogConsumer(Thread):
    def __init__(self, queue, processor):
        Thread.__init__(self)
        self.queue = queue
        self.processor = processor

    def run(self):
        while True:
            log_event = self.queue.get()
            if log_event is None:
                break
            self.processor.process_log(log_event)

if __name__ == "__main__":
    log_queue = Queue()

    producer = LogProducer(log_queue)
    producer.produce_log()

    processor = LogProcessor()

    consumer = LogConsumer(log_queue, processor)
    consumer.start()
