#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>

#define MAX_WORKERS 5
#define MAX_CONCURRENT_TASKS 10
#define RATE_LIMITING_INTERVAL 1000 // in milliseconds

// Worker thread function
void* worker_thread(void* arg) {
    // Extract task from argument
    int task_id = *(int*)arg;

    // Process the task
    printf("Worker %d processing task %d\n", pthread_self(), task_id);

    // Release resources when finished
    free(arg);
    return NULL;
}

// Task structure to store task ID and worker thread handle
typedef struct {
    int id;
    pthread_t thread;
} Task;

// Task queue data structure (double-ended queue)
typedef struct {
    Task* head;
    Task* tail;
    int size;
} Queue;

// Initialize the task queue
Queue* init_queue() {
    Queue* queue = malloc(sizeof(Queue));
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
    return queue;
}

// Add a task to the queue
void enqueue(Queue* queue, int task_id) {
    Task* new_task = malloc(sizeof(Task));
    new_task->id = task_id;
    if (queue->head == NULL) {
        queue->head = new_task;
        queue->tail = new_task;
    } else {
        queue->tail->next = new_task;
        queue->tail = new_task;
    }
    queue->size++;
}

// Start a worker thread
void start_worker(Queue* queue, int worker_id) {
    pthread_t thread;
    Task* task;

    // Create the worker thread
