import logging
import asyncio
from typing import List, Dict

def initialize_monitoring_system(config: Dict) -> int:
    try:
        # Validate configuration
        if not all(key in config for key in ["collectors", "alerts", "endpoints"]):
            return 1  # Configuration error

        # Initialize metric collectors
        collectors = []
        for collector_config in config["collectors"]:
            collector = Collector(collector_config)
            collectors.append(collector)

        # Initialize alert rules
        alerts = []
        for rule_config in config["alerts"]:
            alert = Alert(rule_config, collectors)
            alerts.append(alert)

        # Set up periodic polling and alerting
        loop = asyncio.get_event_loop()
        loop.create_task(poll_metrics( collectors ))
        loop.create_task(send_alerts( alerts ))

        return 0  # Initialization successful

    except Exception as e:
        logging.error(f"Initialization failed: {e}")
        return 1  # Error during initialization

class Collector:
    def __init__(self, config):
        self.config = config
        self.instance = None  # Initialize collector instance later

class Alert:
    def __init__(self, config, collectors):
        self.config = config
        self.collectors = collectors

async def poll_metrics(collectors: List[Collector]):
    while True:
        for collector in collectors:
            await collector.poll_metric()
        await asyncio.sleep(10)  # Optimize polling interval

async def send_alerts(alerts: List[Alert]):
    while True:
        for alert in alerts:
            if alert.check_threshold():
                await alert.send_notification()
        await asyncio.sleep(30)  # Optimize alerting interval
