['Here is the Rust program using Tokio runtime to process input files asynchronously and generate LLVM IR code:

```rust
use tokio::prelude::*;
use llvm_ir::{LLVMContext, LLVMModule};
use std::fs;
use std::path::{Path, PathBuf};

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        println!("Usage: {} <input_file> <output_directory>", &args[0]);
        return;
    }

    let input_file_path = PathBuf::from(&args[1]);
    let output_directory = &args[2];

    tokio::fs::read_dir(input_file_path)
        .await
        .unwrap()
        .flatten()
        .filter_map(|entry| entry.ok())
        .for_each(async |file_entry| {
            if let Ok(file) = file_entry {
                process_file(&file.path(), output_directory).await;
            }
        });
}

async fn process_file(file_path: &Path, output_directory: &str) {
    let llvm_context = LLVMContext::new();
    let llvm_module = LLVMModule::create("main", &llvm_context);

    // Process the file here...
    println!("Processing file: {}", file_path.display());

    // Generate LLVM IR code...
    let ir_code = format!("{:?}", llvm_module);

    // Save the LLVM IR code to a file...
    let output_file_path = Path::join(output_directory, file_path.file_name().unwrap());
    fs::write(output_file_path, ir_code.as_bytes()).await.unwrap();
}
