from threading import Lock, Semaphore
from queue import Queue
from logging import getLogger

class JsonParser:
    def __init__(self):
        self.lock = Lock()
        self.semaphore = Semaphore(5)
        self.cache = defaultdict(dict)

    def parse_json(self, json_data):
        with self.lock:
            if not self.cache.get(json_data):
                try:
                    # Call external REST API
                    response = requests.post('https://api.example.com/parse', json=json_data)
                    response.raise_for_status()
                    data = response.json()

                    # Store parsed JSON in cache
                    self.cache[json_data] = data

                except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
                    logger.error(f"Failed to parse JSON: {e}")
                    return None

            return self.cache.get(json_data)

    def create_json(self, data):
        with self.lock:
            try:
                # Serialize data into JSON
                json_data = json.dumps(data)

                # Store JSON in cache for faster parsing
                self.cache[json_data] = data

                return json_data

            except (ValueError, TypeError) as e:
                logger.error(f"Failed to create JSON: {e}")
                return None


class JsonProcessor:
    def __init__(self):
        self.parser = JsonParser()
        self.queue = Queue()

    def process_json(self, json_data):
        try:
            # Parse JSON
            data = self.parser.parse_json(json_data)

            if data:
                # Process parsed JSON
                processed_data = process_data(data)
                return processed_data

        except Exception as e:
            logger.error(f"Failed to process JSON: {e}")

    def run(self):
        while True:
            try:
                # Get next JSON request from queue
                json_data = self.queue.get()
                result = self.process_json(json_data)

                if result:
                    # Send processed data back to the API or store it
                    send_data(result)
                else:
                    logger.error(f"Failed to process JSON: {json_data}")

            except Exception as e:
                logger.error(f"Internal error: {e}")
