    public class AuthenticationController : ControllerBase
    {
        private readonly IAuthenticationService _authService;
        private readonly IAuthorizationService _authorizationService;

        public AuthenticationController(IAuthenticationService authService, IAuthorizationService authorizationService)
        {
            _authService = authService;
            _authorizationService = authorizationService;
        }

        [HttpPost]
        [Route("Login")]
        public async Task<IActionResult> Login([FromBody]LoginModel model)
        {
            var result = await _authService.AuthenticateAsync(model.Username, model.Password);
            if (result.IsSuccess)
            {
                return await GenerateToken(result.User);
            }
            else
            {
                return BadRequest("Invalid credentials");
            }
        }

        [HttpPost]
        [Route("SocialLogin")]
        public async Task<IActionResult> SocialLogin([FromBody]SocialLoginModel model)
        {
            var result = await _authService.AuthenticateAsync(model.Provider, model.Code);
            if (result.IsSuccess)
            {
                return await GenerateToken(result.User);
            }
            else
            {
                return BadRequest("Invalid social login credentials");
            }
        }

        [HttpGet]
        [Route("Roles")]
        public async Task<IActionResult> GetRoles([FromClaim] int UserId)
        {
            var roles = await _authorizationService.GetRolesAsync(UserId);
            return Json(roles);
        }

        private async Task<IActionResult> GenerateToken(ClaimUser user)
        {
            var token = await _authService.GenerateTokenAsync(user);
            return Ok(new { token });
        }
    }
}
