	return &ApiClient{
		client: client,
		auth:   auth,
	}, nil
}

func (c *ApiClient) Get(ctx context.Context, endpoint string) (*http.Response, error) {
	req, err := c.client.R().SetContext(ctx).Get(endpoint)
	if err != nil {
		return nil, err
	}
	resp, err := req.Execute()
	if err != nil {
		return nil, err
	}
	return resp, nil
}

func (c *ApiClient) Post(ctx context.Context, endpoint string, body interface{}) (*http.Response, error) {
	req, err := c.client.R().SetContext(ctx).SetBody(body).Post(endpoint)
	if err != nil {
		return nil, err
	}
	resp, err := req.Execute()
	if err != nil {
		return nil, err
	}
	return resp, nil
}

type Auth struct {
	token    string
	tokenExp time.Time
}

func (a *Auth) Validate(ctx context.Context) error {
	if a.tokenExp.Before(time.Now()) {
		a/token = "" // expire token
	}
	if a.token == "" {
		// handle unauthorized request
		return errors.New("unauthorized")
	}
	return nil
}

func (c *ApiClient) SetToken(token string, exp time.Time) {
	c.auth.token = token
	c.auth.tokenExp = exp
}

func main() {
