import os
import hashlib
import logging
from concurrent.futures import ThreadPoolExecutor
import subprocess
import json

class FileTracker:
    def __init__(self, dir_path, ignore_extensions=None):
        self.dir_path = dir_path
        self.ignore_extensions = ignore_extensions if ignore_extensions else []
        self.md5_hashes = {}
        self.logger = logging.getLogger('FileTracker')
        self.logger.setLevel(logging.INFO)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        file_handler = logging.FileHandler('file_tracker.log')
        file_handler.setFormatter(formatter)
        self.logger.addHandler(file_handler)

    def track_files(self):
        with os.scandir(self.dir_path) as entries:
            for entry in entries:
                if entry.is_file():
                    if entry.name.endswith(tuple(self.ignore_extensions)):
                        continue
                    md5_hash = hashlib.md5(open(entry.path, 'rb').read()).hexdigest()
                    self.md5_hashes[entry.name] = md5_hash
                    self.logger.info(f"File {entry.name} with MD5 hash {md5_hash}")

    def start_monitoring(self):
        while True:
            try:
                os.listdir(self.dir_path)
                if any(not file.exists() for file in self.md5_hashes.values()):
                    self.track_files()
            except Exception as e:
                self.logger.error(f"Error occurred: {str(e)}")
            time.sleep(1)

class LoggingService:
    def __init__(self, service_name):
        self.service_name = service_name
        self.logger = logging.getLogger(self.service_name)
        self.logger.setLevel(logging.INFO)
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        file_handler = logging.FileHandler(f'{service_name}.log')
        file_handler.setFormatter(formatter)
        self.logger.addHandler(file_handler)

    def log_message(self, message):
        self.logger.info(message)

class CloudStorage:
