        output = execute_shell_command('find /path/to/monitor -type f')
        res.send(output)
    except Exception as e:
        res.send(f"Error occurred: {str(e)}")

app.get('/get_logs', (lambda req, res):
    try:
        with open('file_tracker.log') as file:
            log_data = file.read()
        res.send(log_data)
    except Exception as e:
        res.send(f"Error occurred: {str(e)}")
