    DistributedKeyValueStore(int numNodes) : nodes(numNodes), lock(std::make_unique<std::mutex>()) {}

    void put(const std::string& key, const std::string& value) {
        for (int i = 0; i < nodes.size(); i++) {
            Node& node = nodes[i];
            node.put(key, value);
        }
    }

    std::string get(const std::string& key) {
        for (int i = 0; i < nodes.size(); i++) {
            Node& node = nodes[i];
            if (node.exists(key)) {
                return node.get(key);
            }
        }
        return "";
    }

private:
    struct Node {
        std::vector<std::pair<std::string, std::string>> data;
        std::unique_ptr<std::mutex> lock;

        void put(const std::string& key, const std::string& value) {
            {
                std::unique_lock<std::mutex>(*lock);
                data.emplace_back(key, value);
            }
            std::cout << "Node " << this << ": Put " << key << " -> " << value << std::endl;
        }

        bool exists(const std::string& key) {
            for (const auto& pair : data) {
                if (pair.first == key) {
                    return true;
                }
            }
            return false;
        }

        std::string get(const std::string& key) {
            for (const auto& pair : data) {
                if (pair.first == key) {
                    return pair.second;
                }
            }
            return "";
        }
    };

    std::vector<Node> nodes;
    std::unique_ptr<std::mutex> lock;
};

int main() {
    DistributedKeyValueStore kv(3);
    kv.put("key1", "value1");
    std::cout << "Get key1: " << kv.get("key1") << std::endl;
    return 0;
}
```']

