class DistributedFileProcessor : public FileProcessor {
public:
    DistributedFileProcessor(std::string filename, std::string transformationRule, int numNodes)
        : FileProcessor(filename, transformationRule), numNodes_(numNodes) {}

    void processFile() override {
        std::vector<std::thread> threads;

        for (int i = 0; i < numNodes_; ++i) {
            threads.emplace_back([this] {
