class ConfigCache {
public:
    ConfigCache(size_t initialCapacity) : cache_(initialCapacity), rateLimits_({}), retryPolicy_({}) {}

    template<typename T>
    void put(const std::string& key, const T& value) {
        if (!validate(value)) return;
        cache_[key] = value;
    }

    template<typename T>
    bool get(const std::string& key, T& result) {
        auto it = cache_.find(key);
        if (it == cache_.end()) {
            // Miss
            updateHitRate(false);
            tryFetchFromAPI(key, result);
            return false;
        }
        // Hit
        updateHitRate(true);
        result = it->second;
        return true;
    }

    void startPurger(size_t purgeInterval) {
        purger_ = std::thread([this, purgeInterval]() {
            while (true) {
                // Proactive cache purging
                for (auto& entry : cache_) {
                    if (entry.second.expired()) {
                        cache_.erase(entry.first);
                    }
                }
                std::this_thread::sleep_for(std::chrono::seconds(purgeInterval));
            }
        });
    }

    void stopPurger() {
        if (purger_.joinable()) purger_.join();
    }

private:
    std::map<std::string, std::any> cache_;
    std::map<std::string, size_t> rateLimits_;
