        self.plugins[plugin_name] = __import__(f"plugins.{plugin_name}")

    def get(self, endpoint: str, params: Dict[str, str]) -> requests.Response:
        if not self.auth_token or time.time() > self.token_expiration_time:
            self.refresh_token()
        response = self.session.get(f"{self.base_url}{endpoint}", params=params)
        return response

    def post(self, endpoint: str, data: Dict[str, str]) -> requests.Response:
        if not self.auth_token or time.time() > self.token_expiration_time:
            self.refresh_token()
        response = self.session.post(f"{self.base_url}{endpoint}", json=data)
        return response

