  const metricsData = await Promise.all(
    Object.keys(metrics).map((metricName) => metrics[metricName]())
  );
  // Alert on anomalies and degradation
  if (metricsData.some((data) => data.anomaly)) {
    console.log('Anomaly detected!');
  }
}

// Start the service
