using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace RealTimeDataGenerator
{
    public class RealTimeDataGenerator
    {
        private readonly Dictionary<string, (int, int)> _rangeParameters = new Dictionary<string, (int, int)>();
        private readonly Dictionary<string, object> _cache = new Dictionary<string, object>(new LruCachePolicy(1000));
        private readonly IValidator _validator;
        private readonly ILogger _logger;
        private readonly IEventBus _eventBus;

        public RealTimeDataGenerator(IValidator validator, ILogger logger, IEventBus eventBus)
        {
            _validator = validator;
            _logger = logger;
            _eventBus = eventBus;
        }

        public async Task<int> GenerateRandomIntegerAsync(int min, int max, bool exclusive = false)
        {
            if (await ValidateRangeParameterAsync(min, max) == false)
                return -1;

            while (true)
            {
                int value = new Random().Next(min, max + (exclusive ? 0 : 1));
                if (_cache.TryGetValue($"{min}_{max}", out object cachedValue))
                    _cache.Remove($"{min}_{max}");

                _cache.Add($"{min}_{max}", value);

                await Task.Delay(10);
            }
        }

        public async Task<double> GenerateRandomFloatAsync(double min, double max, bool exclusive = false)
        {
            if (await ValidateRangeParameterAsync(min, max) == false)
                return -1.0;

            while (true)
            {
                double value = new Random().NextDouble() * (max - min) + min;
                if (_cache.TryGetValue($"{min}_{max}", out object cachedValue))
                    _cache.Remove($"{min}_{max}");

                _cache.Add($"{min}_{max}", value);

                await Task.Delay(10);
            }
        }

        public async Task ValidateRangeParameterAsync(int min, int max)
        {
            return await _validator.ValidateRangeParameterAsync(min, max);
        }

        public async Task SendNotificationAsync(string message)
        {
            await _eventBus.PublishAsync(message);
        }

        public async Task LogErrorAsync(Exception exception)
        {
            await _logger.LogErrorAsync(exception);
        }
    }

    public class LruCachePolicy : IEqualityComparer<string>
    {
        private int _size;

        public LruCachePolicy(int size)
        {
            _size = size;
        }

        public bool Equals(string x, string y)
        {
            return x == y;
        }

        public int GetHashCode(string obj)
        {
            return obj.GetHashCode();
        }
    }

    public interface IValidator
    {
        Task<bool> ValidateRangeParameterAsync(int min, int max);
    }

    public interface ILogger
    {
        Task LogErrorAsync(Exception exception);
    }

    public interface IEventBus
    {
        Task PublishAsync(string message);
    }
}
