typedef struct {
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int populate_array(int n, NFAPI_CRC_INDICATION_PDU_T **array) {
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < n; i++) {
        (*array)[i].rnti = rand() % 100;
        (*array)[i].crcflag = rand() % 2; // Randomly set CRCFLAG
    }
    return 0;
}

u_char* resolve_dns(const char* hostname) {
    struct sockaddr_in addr;
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        return NULL; // Socket creation failed
    }

    struct hostent* he = gethostbyname(hostname);
    if (he == NULL) {
        close(sock);
        return NULL; // DNS resolution failed
    }

    addr.sin_family = AF_INET;
    addr.sin_port = htons(53);
    memcpy(&addr.sin_addr, he->h_addr, sizeof(addr.sin_addr));

    int ret = connect(sock, (struct sockaddr*)&addr, sizeof(addr));
    if (ret < 0) {
        close(sock);
        return NULL; // Network connection failed
    }

    char* ip = inet_ntop(AF_INET, &addr.sin_addr, NULL, 0);
    if (ip == NULL) {
        close(sock);
        return NULL; // IP address conversion failed
    }

    close(sock);
    return (u_char*)ip;
}

int main() {
    int n = 10; // Set the number of structures to populate
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    if (populate_array(n, &array) < 0) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < n; i++) {
        printf("RNTI: %d, CRCFLAG: %d\n", array[i].rnti, array[i].crcflag);
    }

    free(array);

    const char* hostname = "example.com";
    u_char* ip = resolve_dns(hostname);
    if (ip == NULL) {
        printf("DNS resolution failed.\n");
        return -1;
    }
    printf("IP address: %s\n", ip);

    return 0;
}
