import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

import org.apache.http.HttpException;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.json.JSONArray;
import org.json.JSONObject;

public class PokemonWeaknessProcessor {
    private static final int MAX_CONCURRENT_REQUESTS = 5;
    private static final String API_ENDPOINT = "https://pokemon-api.com/types";
    private static final String API_KEY = "your_api_key_here";

    private Map<String, Map<String, String>> pokemonTypes; // cache
    private ConcurrentHashMap<String, Map<String, String>> concurrentPokemonTypes; // concurrent cache
    private ExecutorService executor;

    public PokemonWeaknessProcessor() {
        pokemonTypes = new HashMap<>();
        concurrentPokemonTypes = new ConcurrentHashMap<>();
        executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
    }

    public void processPokemon(String pokemonName) throws IOException, HttpException {
        Map<String, String> weaknesses;
        if (concurrentPokemonTypes.containsKey(pokemonName)) {
            // retrieve from concurrent cache
            weaknesses = concurrentPokemonTypes.get(pokemonName);
        } else if (pokemonTypes.containsKey(pokemonName)) {
            // retrieve from regular cache
            weaknesses = pokemonTypes.get(pokemonName);
        } else {
            // query API and update caches
            CloseableHttpClient client = HttpClients.createDefault();
            try (CloseableHttpResponse response = client.execute(new HttpRequest(API_ENDPOINT))) {
                String json = IOUtils.toString(response.getEntity().getContent());
                JSONObject jsonObject = new JSONObject(json);
                JSONArray typesArray = jsonObject.getJSONArray("types");
                Map<String, String> weaknessesMap = new HashMap<>();
                for (int i = 0; i < typesArray.length(); i++) {
                    JSONObject typeObject = typesArray.getJSONObject(i);
                    weaknessesMap.put(typeObject.getString("name"), typeObject.getString("weakness"));
                }
                pokemonTypes.put(pokemonName, weaknessesMap);
                concurrentPokemonTypes.put(pokemonName, weaknessesMap);
            } finally {
                client.close();
            }
        }
        // process the weaknesses
    }

    private class HttpRequest extends HttpGet {
        public HttpRequest(String endpoint) {
            super(endpoint);
            addHeader("Authorization", "Bearer " + API_KEY);
        }
    }

    public static void main(String[] args) throws IOException, HttpException {
        PokemonWeaknessProcessor processor = new PokemonWeaknessProcessor();
        processor.processPokemon("Pikachu");
    }
}

