static Algorithm* algorithms[1000] = {NULL};

// Thread-safe function to load an algorithm
void* thread_load_algorithm(void* arg) {
    char* filename = (char*)arg;
    Algorithm* alg = load_algorithm(filename);
    pthread_mutex_lock(&alg_lock);
    // Add loaded algorithm to the global list
    for(int i = 0; i < 1000; i++) {
        if(algorithms[i] == NULL) {
            algorithms[i] = alg;
            break;
        }
    }
    pthread_mutex_unlock(&alg_lock);
    return NULL;
}

// Thread-safe function to unload an algorithm
void thread_unload_algorithm(Algorithm* alg) {
    pthread_mutex_lock(&alg_lock);
    // Find the loaded algorithm in the global list and remove it
    for(int i = 0; i < 1000; i++) {
        if(algorithms[i] == alg) {
            algorithms[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&alg_lock);
}

// Function to print the status of all loaded algorithms
void thread_print_status() {
    pthread_mutex_lock(&alg_lock);
    for(int i = 0; i < 1000; i++) {
        if(algorithms[i] != NULL) {
            print_status(algorithms[i]);
        }
    }
    pthread_mutex_unlock(&alg_lock);
}

// Main function to demonstrate thread-safe algorithm management
