#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

// Semaphore management structures
typedef struct {
    sem_t *sem;
    pthread_mutex_t lock;
    int count;
} semaphore_t;

// External monitoring service interface
typedef struct {
    void (*log_event)(const char* event);
    void (*send_alert)(const char* alert);
} monitor_service_t;

// Library initialization function
int semaphore_init(monitor_service_t* service) {
    // Initialize semaphores and locks
    return 0;
}

// Create a new semaphore with the given name and initial count
semaphore_t* semaphore_create(const char* name, int initial_count) {
    semaphore_t* sem = malloc(sizeof(semaphore_t));
    sem->sem = sem_open(name, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, initial_count);
    pthread_mutex_init(&sem->lock, NULL);
    sem->count = initial_count;
    return sem;
}

// Delete a semaphore and release its resources
void semaphore_destroy(semaphore_t* sem) {
    // Release the semaphore
    sem_close(sem->sem);
    free(sem);
}

// Pthread routine to acquire a semaphore
void* semaphore_p(void* arg) {
    // Acquire the semaphore
    pthread_mutex_lock(&((semaphore_t*)arg)->lock);
    while (sem_getvalue(((semaphore_t*)arg)->sem, NULL) <= 0) {
        // Wait for the semaphore to be released
        sem_wait(((semaphore_t*)arg)->sem);
    }
    ((semaphore_t*)arg)->count--;
    pthread_mutex_unlock(&((semaphore_t*)arg)->lock);
    return NULL;
}

// Pthread routine to release a semaphore
void* semaphore_v(void* arg) {
    // Release the semaphore
    pthread_mutex_lock(&((semaphore_t*)arg)->lock);
    ((semaphore_t*)arg)->count++;
    sem_post(((semaphore_t*)arg)->sem);
    pthread_mutex_unlock(&((semaphore_t*)arg)->lock);
    return NULL;
}

// Failover strategy: switch to a backup semaphore if the primary becomes unavailable
void* failover(void* arg) {
    // Acquire the backup semaphore
    sem_wait(((semaphore_t*)arg)->backup_sem);
    // Release the primary semaphore
    sem_close(((semaphore_t*)arg)->sem);
    free(((semaphore_t*)arg));
    ((semaphore_t*)arg)->sem = ((semaphore_t*)arg)->backup_sem;
    ((semaphore_t*)arg)->backup_sem = NULL;
    return NULL;
}

// Dynamic thread creation and deletion
int semaphore_thread_create(semaphore_t* sem, pthread_t* thread) {
    // Create a new thread
    pthread_create(thread, NULL, semaphore_p, sem);
    return 0;
}

int semaphore_thread_delete(pthread_t thread) {
    // Delete the thread
    pthread_join(thread, NULL);
    return 0;
}

// Library API functions
semaphore_t* semaphore_open(const char* name, int initial_count) {
    return semaphore_create(name, initial_count);
}

void semaphore_close(semaphore_t* sem) {
    // Release the semaphore
    sem_close(sem->sem);
    free(sem);
}

int main() {
    // Initialize the library and monitoring service
    monitor_service_t service;
    service.log_event = log_event;
    service.send_alert = send_alert;

    // Create a new semaphore with an initial count of 5
    semaphore_t* sem = semaphore_open("my_semaphore", 5);

    // Acquire the semaphore in separate threads
    pthread_t thread1, thread2, thread3;
    semaphore_thread_create(sem, &thread1);
    semaphore_thread_create(sem, &thread2);
    semaphore_thread_create(sem, &thread3);

    // Release the semaphore and join the threads
    semaphore_close(sem);
    semaphore_thread_delete(thread1);
    semaphore_thread_delete(thread2);
    semaphore_thread_delete(thread3);

    return 0;
}
```

Please note that this code block is a part of the overall solution for managing POSIX semaphores in a highly available, distributed, multi-threaded environment. The actual implementation might require additional code and logic to fully meet the requirements outlined in the programming task.']

