    void insertAfterOrAppend(const std::string& searchStr, const std::string& newStr) {
        // Custom logging framework for structured logging and asynchronous message queuing
        logOperation("Insert After or Append", "Search: " + searchStr + ", New String: " + newStr);

        if (searchStr.size() > MAX_SEARCH_LENGTH || newStr.size() > MAX_NEW_STRING_LENGTH) {
            throw std::invalid_argument("Search string and/or new string exceeds allowed length limits");
        }

        // Custom hash-based indexing for improved search times
        auto it = strings.find(searchStr);
        if (it != strings.end()) {
            // Insert after the first occurrence of the search string
            strings.insert({searchStr + "_inserted", newStr});
        } else {
            // Append to the end of the container
            strings[std::to_string(strings.size() + 1)] = newStr;
        }
    }

private:
    struct StringPair {
        std::string key;
        std::string value;
    };

    std::unordered_map<std::string, StringPair> strings;
    mutable std::mutex mutex;

    void logOperation(const std::string& operation, const std::string& message) {
