  if (cachedPrice) return cachedPrice;

  try {
    const price = await fetchPricingAPI(productId);
    setPriceInCache(productId, price);
    return price;
  } catch (error) {
    // Handle unavailable or inconsistent data from external service
    console.error(error);
    return getPriceFromLocalCacheOrDefault(productId);
  }
