                XPathDocument xmlDocument = new XPathDocument(xmlDocumentPath);

                // Parse XML using XPath
                XPathNavigator navigator = xmlDocument.CreateNavigator();

                // Retrieve elements based on configurable names
                XPathExpression expression = navigator.Compile("//element[@name='configuredName']");

                // Process retrieved elements
                foreach (XPathNodeIterator iterator in expression.Evaluate())
                {
                    // Fetch XML document from external API or cache
                    string xmlContent;
                    try
                    {
                        xmlContent = await _httpClientFactory.GetXmlContentFromApi(iterator.Value);
                    }
                    catch (HttpRequestException ex)
                    {
                        _logger.LogError(ex, "Failed to fetch XML content");
                        continue;
                    }

                    // Parse and process fetched XML document
                    XPathDocument apiXmlDocument = new XPathDocument(new MemoryStream(Encoding.UTF8.GetBytes(xmlContent)));
                    XPathNavigator apiNavigator = apiXmlDocument.CreateNavigator();

                    // Process elements based on configurable names
                    foreach (XPathNodeIterator apiIterator in expression.Evaluate())
                    {
                        // ...
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing XML document");
            }
        }

        public async Task FetchXmlDocumentFromApi(string apiEndpoint, string apiKey)
        {
            try
            {
                // Create HTTP request with API key and authentication headers
                HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Get, apiEndpoint);
                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);

                // Send HTTP request to API and retrieve response
                HttpResponseMessage response = await _httpClientFactory.SendAsync(request);

                // Check for successful response (200-299)
                if (!response.IsSuccessStatusCode)
                {
                    throw new HttpRequestException($"Failed to fetch XML content: {response.StatusCode}");
                }

                // Read response content as XML string
                string xmlContent;
                using (Stream stream = await response.Content.ReadAsStreamAsync())
                {
                    xmlContent = Encoding.UTF8.GetString(await StreamExtensions.ReadAsStringAsync(stream));
                }
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to fetch XML content");
            }
        }

        public async Task CacheXmlDocument(string apiEndpoint, string apiKey)
        {
            try
            {
                // Create HTTP request with API key and authentication headers
                HttpRequestMessage request = new HttpRequestMessage(HttpMethod.Get, apiEndpoint);
                request.Headers.Authorization = new AuthenticationHeaderValue("Bearer", apiKey);

                // Send HTTP request to API and retrieve response
                HttpResponseMessage response = await _httpClientFactory.SendAsync(request);

                // Check for successful response (200-299)
                if (!response.IsSuccessStatusCode)
                {
                    throw new HttpRequestException($"Failed to fetch XML content: {response.StatusCode}");
                }

                // Read response content as XML string
                string xmlContent;
                using (Stream stream = await response.Content.ReadAsStreamAsync())
                {
                    xmlContent = Encoding.UTF8.GetString(await StreamExtensions.ReadAsStringAsync(stream));
                }

                // Cache XML document
                _cacheProvider.Set(apiEndpoint, xmlContent);
            }
            catch (HttpRequestException ex)
            {
                _logger.LogError(ex, "Failed to cache XML content");
            }
        }
    }
}
