    public void processLogEntry(LogEntry entry) {
        String userId = entry.getUserId();
        Instant timestamp = entry.getTimestamp();
        String deviceId = entry.getDeviceId();

        Session session = getSession(userId);
        if (session == null || !isInSession(timestamp, session)) {
            // Start a new session
            session = startSession(userId, timestamp);
