        DeviceType deviceType = getDeviceType(deviceId);
        session.addLogEntry(entry);

        // Calculate most active user and device type for each session
        updateSessionMetrics(session, deviceType);

        // Periodically save sessions to disk or database
        if (timestamp.toEpochMilli() % 1000 == 0) {
            saveSessions();
        }
    }

    private Session getSession(String userId) {
