import java.util.*;
import java.util.concurrent.*;

public class DistributedSystem {
    private Map<String, List<ServiceInstance>> fleet;
    private int numDataCenters;
    private static final String STARTING = "STARTING";
    private static final String RUNNING = "RUNNING";
    private static final String STOPPING = "STOPPING";
    private static final String STOPPED = "STOPPED";

    public DistributedSystem(int numDataCenters) {
        this.numDataCenters = numDataCenters;
        this.fleet = new HashMap<>();
        for (int i = 0; i < numDataCenters; i++) {
            fleet.put("DC-" + i, new ArrayList<>());
        }
    }

    public void initializeFleet(int numInstances) {
        // Initialize the fleet with a configurable number of service instances
        for (int i = 0; i < numInstances; i++) {
            int dataCenterIndex = i % numDataCenters;
            ServiceInstance instance = new ServiceInstance();
            instance.setState(STARTING);
            fleet.get("DC-" + dataCenterIndex).add(instance);
        }
    }

    public void scaleFleet(int numNewInstances) {
        // Support dynamic scaling by adding or removing service instances
        for (int i = 0; i < numNewInstances; i++) {
            int dataCenterIndex = i % numDataCenters;
            ServiceInstance instance = new ServiceInstance();
            instance.setState(STARTING);
            fleet.get("DC-" + dataCenterIndex).add(instance);
        }
    }

    public void startService(String serviceId) {
        // Start a specific service instance
        List<ServiceInstance> instancesInDataCenter = fleet.get(serviceId);
        for (ServiceInstance instance : instancesInDataCenter) {
            if (instance.getState().equals(STARTING)) {
                instance.setState(RUNNING);
                return;
            }
        }
    }

    public void stopService(String serviceId) {
        // Stop a specific service instance
        List<ServiceInstance> instancesInDataCenter = fleet.get(serviceId);
        for (ServiceInstance instance : instancesInDataCenter) {
            if (instance.getState().equals(RUNNING)) {
                instance.setState(STOPPING);
                return;
            }
        }
    }

    public void stopService(String serviceId, boolean forceStop) {
        // Stop a specific service instance with optional force stop
        List<ServiceInstance> instancesInDataCenter = fleet.get(serviceId);
        for (ServiceInstance instance : instancesInDataCenter) {
            if (instance.getState().equals(RUNNING)) {
                if (forceStop) {
                    instance.setState(STOPPED);
                } else {
                    instance.setState(STOPPING);
                }
                return;
            }
        }
    }

    public void transitionInstanceState(String serviceId, String state) {
        // Transition a specific service instance to a new state
        List<ServiceInstance> instancesInDataCenter = fleet.get(serviceId);
        for (ServiceInstance instance : instancesInDataCenter) {
            if (instance.getState().equals(state)) {
                // Ensure seamless failover mechanisms for service instances in case of node failures
