use reqwest::blocking::{get,post};
use reqwest::header;
use std::sync::Arc;
use std::time::Duration;

pub struct HttpClient {
    timeout: Duration,
    retries: u32,
    rate_limit: Option<(u64, u64)>,
}

impl HttpClient {
    pub fn new(timeout: Duration, retries: u32, rate_limit: Option<(u64, u64)>) -> Self {
        HttpClient { timeout, retries, rate_limit }
    }

    async fn send_request(&self, method: &str, url: &str, headers: Vec<(&str, &str)>) -> reqwest::Result<String> {
        let client = Arc::new(reqwest::blocking::ClientBuilder::new(reqwest::blocking::default_client()).timeout(self.timeout).build()?);
        match method {
            "GET" => get(url).headers(headers).send().await,
            "POST" => post(url).headers(headers).send().await,
            _ => unreachable!("Only GET and POST methods are supported"),
        }
    }

    async fn execute(&self, request: &str) -> reqwest::Result<String> {
        let headers = vec![
            ("Accept", "*/*"),
            ("Content-Type", "application/json"),
        ];
        self.send_request(request, "https://api.example.com/path", headers).await
    }
}

// Example usage:
let client = HttpClient::new(Duration::from_secs(10), 3, Some((5, 60)));
