using System;
using System.Data;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DatabaseClient
{
    private readonly string _connectionString;

    public DatabaseClient(string connectionString)
    {
        _connectionString = connectionString;
    }

    public DataTableReader ExecuteQuery(byte[] query)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            connection.Open();

            using (var command = new SqlCommand())
            {
                command.Connection = connection;

                // Encrypt the query
                var encryptedQuery = Encrypt(query);

                // Send the query to the database server
                command.CommandText = "EXEC sp_executesql @query";
                command.Parameters.AddWithValue("@query", encryptedQuery);

                using (var reader = command.ExecuteReader())
                {
                    return new DataTableReader(reader);
                }
            }
        }
    }

    private byte[] Encrypt(byte[] input)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = Convert.FromBase64String("your_secret_key_here");
            aes.IV = Convert.FromBase64String("your_initialization_vector_here");

            using (var encryptor = aes.CreateEncryptor())
            {
                using (var ms = new MemoryStream())
                {
                    using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                    {
                        cs.Write(input, 0, input.Length);
                        cs.FlushFinalBlock();
                    }
                    return ms.ToArray();
                }
            }
        }
    }
}
