package filemonitor;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.codec.binary.Hex;
import org.apache.commons.io.input.Tailer;

public class FileMonitor {

    private static final int BUFFER_SIZE = 1024 * 1024; // 1MB
    private static final String DEFAULT_ALGORITHM = "AES";
    private static final String DEFAULT_KEY = "your_secret_key_here";

    public void startMonitoring(String directory) throws Exception {
        new Thread(() -> {
            try (Tailer tailer = new Tailer(new File(directory))) {
                while (true) {
                    File file = tailer.read();
                    if (file != null) {
                        String md5Hash = computeMD5Hash(file);
                        encryptFile(file, md5Hash);
                    }
                }
            } catch (IOException e) {
                System.out.println("Error monitoring directory: " + e.getMessage());
            }
        }).start();
    }

    private String computeMD5Hash(File file) throws IOException, NoSuchAlgorithmException {
        try (MessageDigest md = MessageDigest.getInstance("MD5")) {
            try (FileInputStream fis = new FileInputStream(file)) {
                byte[] buffer = new byte[BUFFER_SIZE];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) > 0) {
                    md.update(buffer, 0, bytesRead);
                }
                return Hex.encodeHexString(md.digest());
            }
        }
    }

    private void encryptFile(File file, String md5Hash) throws Exception {
        Cipher cipher = Cipher.getInstance(DEFAULT_ALGORITHM + "/PKCS5PBEWithHmacSHA1");
        SecretKeySpec keySpec = new SecretKeySpec(DEFAULT_KEY.getBytes(), DEFAULT_ALGORITHM);
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);

        try (FileInputStream fis = new FileInputStream(file);
             FileOutputStream fos = new FileOutputStream("encrypted_" + file.getName())) {
            byte[] buffer = new byte[BUFFER_SIZE];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) > 0) {
                cipher.update(buffer, 0, bytesRead);
                fos.write(cipher.doFinal());
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FileMonitor fileMonitor = new FileMonitor();
        fileMonitor.startMonitoring("path/to/your/directory");
    }
```']

