        ExecutorService executor = Executors.newCachedThreadPool(MAX_THREADS);

        try {
            startMonitoring(rootDir, executor);
        } catch (IOException e) {
            // Handle IO exceptions
        }
    }

    private static void startMonitoring(File dir, ExecutorService executor) throws IOException {
        File[] files = dir.listFiles();

        for (File file : files) {
            if (file.isDirectory()) {
                startMonitoring(file, executor);
            } else {
                executor.submit(() -> processFile(file));
            }
        }
    }

    private static void processFile(File file) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");

            try (java.io.FileInputStream fis = new java.io.FileInputStream(file)) {
                int bytesRead;
                byte[] buffer = new byte[BUFFER_SIZE];

                while ((bytesRead = fis.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }

                String md5Hash = bytesToHex(md.digest());

                // Perform encryption/decryption operations here
            } catch (NoSuchAlgorithmException e) {
                // Handle algorithm exceptions
            } catch (IOException e) {
                // Handle IO exceptions
            }
        } catch (RuntimeException e) {
            // Handle runtime exceptions
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();

        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }
