// Define the structure to hold network statistics metrics
typedef struct {
    int cell_id;
    long timestamp;
    int priority;
    char metric_data[];
} Metric;

// Define the structure to hold a dynamic list of metrics
typedef struct {
    pthread_mutex_t lock; // Mutex for thread-safe access
    size_t capacity;
    size_t size;
    Metric* metrics;
} Metrics;

// Create a new metrics container with initial capacity and no metrics
Metrics* create_metrics(size_t capacity) {
    Metrics* metrics = (Metrics*)malloc(sizeof(Metrics));
    metrics->capacity = capacity;
    metrics->size = 0;
    metrics->metrics = (Metric*)calloc(capacity, sizeof(Metric));
    pthread_mutex_init(&metrics->lock, NULL);
    return metrics;
}

// Add a new metric to the container
void add_metric(Metrics* metrics, int cell_id, long timestamp, int priority, char* data) {
    pthread_mutex_lock(&metrics->lock);

    // Check if the metric exceeds the current capacity
    if (metrics->size >= metrics->capacity) {
        metrics->capacity *= 2; // Double the capacity for growth
        metrics->metrics = (Metric*)realloc(metrics->metrics, metrics->capacity * sizeof(Metric));
    }

    Metric* new_metric = &metrics->metrics[metrics->size];
    new_metric->cell_id = cell_id;
    new_metric->timestamp = timestamp;
    new_metric->priority = priority;
    strcpy(new_metric->metric_data, data);
    metrics->size++;

    pthread_mutex_unlock(&metrics->lock);
}

// Update an existing metric in the container
void update_metric(Metrics* metrics, int cell_id, long timestamp, int priority, char* data) {
    pthread_mutex_lock(&metrics->lock);

    for (int i = 0; i < metrics->size; i++) {
        if (metrics->metrics[i].cell_id == cell_id) {
            strcpy(metrics->metrics[i].metric_data, data);
            return;
        }
    }

    // If the metric is not found, add a new one
    add_metric(metrics, cell_id, timestamp, priority, data);

    pthread_mutex_unlock(&metrics->lock);
}

// Retrieve the latest metric for a given cell ID
Metric* get_latest_metric(Metrics* metrics, int cell_id) {
    pthread_mutex_lock(&metrics->lock);

    Metric* latest_metric = NULL;
    long max_timestamp = 0;

    for (int i = 0; i < metrics->size; i++) {
        if (metrics->metrics[i].cell_id == cell_id && metrics->metrics[i].timestamp > max_timestamp) {
            max_timestamp = metrics->metrics[i].timestamp;
            latest_metric = &metrics->metrics[i];
        }
    }

    pthread_mutex_unlock(&metrics->lock);
    return latest_metric;
}

// Clear all metrics older than a specified retention period
void clear_metrics(Metrics* metrics, long retention_period) {
    pthread_mutex_lock(&metrics->lock);

    for (int i = 0; i < metrics->size; i++) {
        if (metrics->metrics[i].timestamp <= retention_period) {
            // Shift the remaining metrics down to fill the gap
            memmove(metrics->metrics, &metrics->metrics[i + 1], (metrics->size - i - 1) * sizeof(Metric));
            metrics->size -= i;
            break; // Stop processing once we've cleared all old metrics
        }
    }

    pthread_mutex_unlock(&metrics->lock);
}

// Initialize the priority queue mechanism
void init_priority_queue() {
    // TO DO: Implement priority queue logic using a combination of heap and linked list data structures
}

int main() {
