    add_metric(metrics, 2, 1643723500, 2, "Metric 2");
    add_metric(metrics, 1, 1643723600, 3, "Metric 3");

    // Update an existing metric
    update_metric(metrics, 1, 1643723700, 3, "Updated Metric 1");

    // Retrieve the latest metric for a given cell ID
