    Metric* metric = (Metric*)malloc(sizeof(Metric));
    metric->cell_id = (char*)malloc(strlen(cell_id) + 1);
    strcpy(metric->cell_id, cell_id);
    metric->timestamp = timestamp;
    metric->priority = priority;
    metric->data = data;

    // Add the new metric to the list
    if (metrics_list->head == metrics_list->tail) {
        metrics_list->head = metric;
        metrics_list->tail = metric;
    } else {
        metrics_list->tail->next = metric;
        metrics_list->tail = metric;
    }

    metrics_list->size++;
}

// Function to update an existing metric
void update_metric(MetricsList* metrics_list, char* cell_id, time_t timestamp, int priority, void* data) {
    // Find the metric to be updated
    Metric* metric = metrics_list->head;
    while (metric != NULL && strcmp(metric->cell_id, cell_id) != 0) {
        metric = metric->next;
    }

    if (metric != NULL) {
        metric->timestamp = timestamp;
        metric->priority = priority;
        metric->data = data;
    }
}

// Function to retrieve a metric from the list
void* get_metric(MetricsList* metrics_list, char* cell_id) {
    // Find the metric with the given cell ID
    Metric* metric = metrics_list->head;
    while (metric != NULL && strcmp(metric->cell_id, cell_id) != 0) {
        metric = metric->next;
    }

    if (metric != NULL) {
        return metric->data;
    } else {
        return NULL;
    }
}

