#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>

class Node {
public:
    std::string id;
    std::mutex lock;
    std::condition_variable cv;
    std::queue<std::pair<int, int>> updates;

    Node(std::string _id) : id(_id) {}

    void processUpdates() {
        while (true) {
            std::unique_lock<std::mutex> lk(lock);
            cv.wait(lk, [this] { return !updates.empty(); });
            auto update = updates.front();
            updates.pop();

            // apply the update
            int value = update.second;
            if (value % 2 == 0) {
                // even number, increment the value
                update.second++;
            } else {
                // odd number, decrement the value
                update.second--;
            }

            std::cout << "Node " << id << ": processed update " << update.first << " with new value " << update.second << std::endl;

            lk.unlock();
        }
    }

    void applyUpdate(int key, int value) {
        updates.push({key, value});
        cv.notify_one();
    }
};

class DistributedKeyValueStore {
public:
    Node* nodes;
    std::mutex lock;
    std::condition_variable cv;
    std::unordered_map<int, int> data;

    DistributedKeyValueStore(size_t numNodes) : nodes(new Node[numNodes]) {
        for (size_t i = 0; i < numNodes; ++i) {
            nodes[i].id = "Node-" + std::to_string(i);
            std::thread([this, &nodes[i]]() { nodes[i].processUpdates(); }).detach();
        }
    }

    ~DistributedKeyValueStore() {
        delete[] nodes;
    }

    void put(int key, int value) {
        for (auto& node : nodes) {
            node->applyUpdate(key, value);
        }
    }

    int get(int key) {
        // read the latest value from any node
        for (auto& node : nodes) {
            if (node->id.find("Node-0") != std::string::npos) {
                return node->data[key];
            }
        }
        return -1;
    }

    void notify() {
        cv.notify_all();
    }
};

int main() {
    DistributedKeyValueStore store(4);

    // simulate put operations
    for (int i = 0; i < 10; ++i) {
        store.put(i, i * 2);
    }

    std::this_thread::sleep_for(std::chrono::seconds(5));

    // simulate get operations
    for (int i = 0; i < 5; ++i) {
        int value = store.get(i);
        if (value == -1) {
            std::cout << "Key not found." << std::endl;
        } else {
            std::cout << "Got value: " << value << std::endl;
        }
    }

    return 0;
}
