```csharp
using System;
using System.Threading.Tasks;

namespace DistributedKeyValueStore
{
    public interface I KeyValueStore : IDisposable
    {
        Task PutAsync(string key, string value);
        Task GetAsync(string key);
        Task DeleteAsync(string key);
    }

    public class DistributedKeyValueStore<T> : IKVStore where T : IKVStore
    {
        private readonly List<ITransaction> _transactions;
        private readonly ConcurrentDictionary<string, string> _store;

        public DistributedKeyValueStore(IKVStore[] nodes)
        {
            _transactions = new List<ITransaction>();
            _store = new ConcurrentDictionary<string, string>();
            foreach (var node in nodes)
            {
                _transactions.Add(new Transaction(node));
            }
        }

        public async Task PutAsync(string key, string value)
        {
            await Task.WhenAll(_transactions.Select(t => t.PutAsync(key, value)));
            _store.TryUpdate(key, value);
        }

        public async Task<string> GetAsync(string key)
        {
            return await Task.WhenAll(_transactions.Select(t => t.GetAsync(key))).Min();
        }

        public async Task DeleteAsync(string key)
        {
            await Task.WhenAll(_transactions.Select(t => t.DeleteAsync(key)));
            _store.TryRemove(key);
        }
    }

    public interface ITransaction : IDisposable
    {
        Task PutAsync(string key, string value);
        Task<string> GetAsync(string key);
        Task DeleteAsync(string key);
    }

    public class Transaction<T> : ITransaction where T : IKVStore
    {
        private readonly T _node;

        public Transaction(T node)
        {
            _node = node;
        }

        public async Task PutAsync(string key, string value)
        {
            await _node.PutAsync(key, value);
        }

        public async Task<string> GetAsync(string key)
        {
            return await _node.GetAsync(key);
        }

        public async Task DeleteAsync(string key)
        {
            await _node.DeleteAsync(key);
        }
    }
}
