const fs = require('fs');
const crypto = require('crypto');
const path = require('path');
const childProcess = require('child_process');

class FileMonitor {
  constructor(rootDir, encryptionAlgo) {
    this.rootDir = rootDir;
    this.encryptionAlgo = encryptionAlgo;
    this.fileHashes = {};
    this.excludedPaths = [];
    this.excludedExtensions = [];

    fs.watch(this.rootDir, (eventType, filename) => {
      if (eventType === 'change') {
        const filePath = path.join(this.rootDir, filename);
        if (!this.isExcluded(filePath)) {
          try {
            const fileBuffer = fs.readFileSync(filePath, { encoding: 'utf8', flag: 'r' });
            const fileHash = crypto.createHash('md5').update(fileBuffer).digest();
            this.fileHashes[filePath] = fileHash;
            this.encryptFile(filePath);
          } catch (err) {
            console.error(`Error processing file ${filePath}:`, err);
          }
        }
      }
    });

    childProcess.exec(`sudo chown -R $(whoami) ${this.rootDir}`);
  }

  isExcluded(filePath) {
    for (const excludedPath of this.excludedPaths) {
      if (path.isAbsolute(excludedPath)) {
        if (filePath.startsWith(excludedPath)) return true;
      } else {
        if (path.normalize(filePath).startsWith(path.normalize(excludedPath))) return true;
      }
    }

    for (const extension of this.excludedExtensions) {
      const filePathLower = filePath.toLowerCase();
      if (filePathLower.endsWith(`.${extension}`)) return true;
    }

    return false;
  }

  encryptFile(filePath) {
    try {
      const fileBuffer = fs.readFileSync(filePath, { encoding: 'utf8', flag: 'r' });
      const fileHash = this.fileHashes[filePath];
      const encryptedBuffer = crypto.createCipher('aes-256-cbc', 'your_secret_key').update(fileBuffer);
      const decryptedBuffer = crypto.createDecipher('aes-256-cbc', 'your_secret_key').update(encryptedBuffer, 0, encryptedBuffer.length);

      fs.writeFileSync(filePath + '.enc', decryptedBuffer);
    } catch (err) {
      console.error(`Error encrypting file ${filePath}:`, err);
    }
  }

  startMonitoring() {
    this.monitoring = true;
    childProcess.exec(`sudo chown -R $(whoami) ${this.rootDir}`);
  }

  stopMonitoring() {
    this.monitoring = false;
  }
}

module.exports = FileMonitor;
