// OctreeNode represents a node in the octree
class OctreeNode {
public:
    // Constructor for leaf nodes
    OctreeNode(int x, int y, int z) : x(x), y(y), z(z) {}

    // Constructor for internal nodes
    OctreeNode(int x, int y, int z, std::vector<OctreeNode*> children)
        : x(x), y(y), z(z), children(children) {}

    int x, y, z;
    std::vector<OctreeNode*> children;

    void addEntity(int entityX, int entityY, int entityZ) {
        // TBI: implement insertion logic
    }

    bool contains(int entityX, int entityY, int entityZ) {
        // TBI: implement search logic
    }
};

// Octree represents the spatial indexing system
class Octree {
public:
    Octree() : root(nullptr), lock(false) {}

    void addEntity(int x, int y, int z, int entityId) {
        std::unique_lock<std::mutex> lk(lock);
        if (!root) {
            root = new OctreeNode(0, 0, 0);
        }
        OctreeNode* node = &root;
        for (int i = 0; i < 3; i++) {
            if (node->children.empty()) {
                node->children.push_back(new OctreeNode(x - (1 << i), y - (1 << i), z - (1 << i)));
                break;
            }
            node = node->children.back();
        }
        node->addEntity(entityX, entityY, entityZ);
    }

    bool contains(int x, int y, int z) {
        std::unique_lock<std::mutex> lk(lock);
        if (!root) return false;
        OctreeNode* node = &root;
        for (int i = 0; i < 3; i++) {
            if (x >= node->children.empty() ? node->x + (1 << i) : node->children.front()->x &&
                y >= node->children.empty() ? node->y + (1 << i) : node->children.front()->y &&
                z >= node->children.empty() ? node->z + (1 << i) : node->children.front()->z &&
                x < node->children.empty() ? 0 : node->children.front()->x ||
                y < node->children.empty() ? 0 : node->children.front()->y ||
                z < node->children.empty() ? 0 : node->children.front()->z) {
                node = &node->children.back();
            } else {
                return false;
            }
        }
        return node->contains(x, y, z);
    }

private:
    OctreeNode* root;
    std::mutex lock;

};

