<?php

function generateRandomString(int $length, string $chars): string {
    $random_string = '';
    for ($i = 0; $i < $length; $i++) {
        $random_string .= $chars[rand(0, strlen($chars) - 1)];
    }
    return $random_string;
}

function hashPassword(string $password, int $hash_length): string {
    $hashed_password = hash('sha256', $password);
    return substr($hashed_password, 0, $hash_length);
