#include <iostream>
#include <forward_list>
#include <string>

void insertAfter(const std::forward_list<std::string>& list, const std::string& target, const std::string& value) {
    auto it = list.begin();
    bool found = false;

    for (it = list.begin(); it != list.end(); ++it) {
        if (*it == target) {
            found = true;
            break;
        }
    }

    if (!found) {
        list.append(value);
    } else {
        list.insert_after(it, value);
    }
}

int main() {
    std::forward_list<std::string> list = {"a", "b", "c"};
    insertAfter(list, "b", "d");
    for (const auto& str : list) {
        std::cout << str << std::endl;
    }
    return 0;
}
