#include <iostream>
#include <vector>
#include <algorithm>

void insertSorted(std::vector<int>& vec, int val) {
    auto it = std::lower_bound(vec.begin(), vec.end(), val);
    if (it == vec.end() || *it != val) {
        vec.insert(it, val);
    } else {
        // Move all occurrences of the value to the front
        auto startIt = it;
        while (startIt != vec.end() && *startIt == val) {
            ++startIt;
        }
        std::rotate(vec.begin(), startIt, vec.end());
    }
}

int main() {
    std::vector<int> vec = {1, 3, 4, 5};
    insertSorted(vec, 2);
    for (int i : vec) {
        std::cout << i << " ";
    }
    return 0;
}
