namespace fs = std::filesystem;

class ImageConverter {
public:
    static void convert(const fs::path& inputDir, const fs::path& outputDir) {
        for (const auto& entry : fs::directory_iterator(inputDir)) {
            if (entry.is_regular_file()) {
                std::string extension = entry.path().extension().string();
                if (extension == ".jpg" || extension == ".jpeg") {
                    // Convert JPEG to SVG
                    imageconverter::JpegConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    converter.convert(svgPath);
                } else if (extension == ".png") {
                    // Convert PNG to SVG
                    imageconverter::PngConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    converter.convert(svgPath);
                } else if (extension == ".bmp") {
                    // Convert BMP to SVG
                    imageconverter::BmpConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    converter.convert(svgPath);
                } else if (extension == ".heic") {
                    // Convert HEIC to SVG
                    imageconverter::HeicConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    converter.convert(svgPath);
                }
            }
        }
    }

    static void convertAsync(const fs::path& inputDir, const fs::path& outputDir) {
        std::vector<std::future<void>> futures;
        for (const auto& entry : fs::directory_iterator(inputDir)) {
            if (entry.is_regular_file()) {
                std::string extension = entry.path().extension().string();
                if (extension == ".jpg" || extension == ".jpeg") {
                    // Convert JPEG to SVG asynchronously
                    imageconverter::JpegConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    futures.emplace_back(std::async(std::launch::async, [&converter, &svgPath]() {
                        converter.convert(svgPath);
                    }));
                } else if (extension == ".png") {
                    // Convert PNG to SVG asynchronously
                    imageconverter::PngConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    futures.emplace_back(std::async(std::launch::async, [&converter, &svgPath]() {
                        converter.convert(svgPath);
                    }));
                } else if (extension == ".bmp") {
                    // Convert BMP to SVG asynchronously
                    imageconverter::BmpConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    futures.emplace_back(std::async(std::launch::async, [&converter, &svgPath]() {
                        converter.convert(svgPath);
                    }));
                } else if (extension == ".heic") {
                    // Convert HEIC to SVG asynchronously
                    imageconverter::HeicConverter converter(entry.path());
                    std::string svgPath = outputDir / (entry.path().filename().stem().string() + ".svg");
                    futures.emplace_back(std::async(std::launch::async, [&converter, &svgPath]() {
                        converter.convert(svgPath);
                    }));
                }
            }
        }

        // Wait for all asynchronous conversions to complete
        for (auto& future : futures) {
            future.get();
        }
    }
};
