package com.example;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class LogManager {
    private Map<String, Object> configMap;
    private Lock lock = new ReentrantLock();

    public int countDisjointPairs(int[][] array) {
        UnionFind uf = new UnionFind(array.length);
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (!uf.isConnected(i, j)) {
                    System.out.println("Disjoint pair found: " + Arrays.toString(array[i]) + " and " + Arrays.toString(array[j]));
                    long endTime = System.currentTimeMillis();
                    System.out.println("Time taken to check disjointness for this pair: " + (endTime - startTime) + " milliseconds");
                }
            }
        }

        return uf.getCount();
    }

    public class UnionFind {
        private int[] parent;
        private int count;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
            count = n;
        }

        public boolean isConnected(int a, int b) {
            lock.lock();
            try {
                if (parent[a] == parent[b]) {
                    return true;
                } else {
                    union(a, b);
                    return false;
                }
            } finally {
                lock.unlock();
            }
        }

        public void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);

            if (rootA != rootB) {
                parent[rootA] = rootB;
                count--;
            }
        }

        private int find(int x) {
            lock.lock();
            try {
                while (parent[x] != x) {
                    x = parent[x];
                }
                return x;
            } finally {
                lock.unlock();
            }
        }

        public int getCount() {
            return count;
        }
    }
}
