        if not all(key in config for key in ["metric_collectors", "alert_rules", "api_endpoints"]):
            raise ValueError("Invalid configuration")

        metric_collectors = config["metric_collectors"]
        alert_rules = config["alert_rules"]
        api_endpoints = config["api_endpoints"]

        # Initialize and validate each metric collector instance
        collectors = []
        for collector_config in metric_collectors:
            collector = None
            try:
                if collector_config["type"] == "prometheus":
                    collector = PrometheusCollector(**collector_config)
                elif collector_config["type"] == "datadog":
                    collector = DatadogCollector(**collector_config)
                # Add support for other types of collectors
                else:
                    raise ValueError("Unsupported metric collector type")
            except Exception as e:
                print(f"Error initializing {collector_config['name']}: {str(e)}")
            if collector:
                collectors.append(collector)

        # Set up background thread to periodically poll metrics
        import threading
        def periodic_polling():
            while True:
                for collector in collectors:
                    try:
                        collector.poll_metrics()
                    except Exception as e:
                        print(f"Error polling {collector.name}: {str(e)}")
                time.sleep(config["polling_interval"])

        thread = threading.Thread(target=periodic_polling)
