// modular architecture for file upload
const FileUpload = (file, provider) => {
  if (!provider) throw new Error("Provider not specified");

  const s3 = require('aws-sdk').S3({
    accessKeyId: process.env.S3_ACCESS_KEY_ID,
    secretAccessKey: process.env.S3_SECRET_ACCESS_KEY,
    region: 'us-west-2'
  });

  const azure = require('azure-storage-blob');

  let upload;

  switch (provider) {
    case 's3':
      upload = s3.upload({
        Bucket: 'my-bucket',
        Key: file.name,
        Body: file.buffer
      });
      break;
    case 'azure':
      const blobSvc = new azure.BlobService('https://my-storage-account.blob.core.windows.net/', process.env.AZURE_STORAGE_ACCESS_KEY, process.env.AZURE_STORAGE_ACCOUNT_NAME);
      upload = blobSvc.createBlockBlobFromText('my-container', file.name, file.buffer.toString());
      break;
    default:
      throw new Error("Invalid provider");
  }

  return upload.on('httpUploadProgress', (chunk) => console.log(`Uploaded ${chunk bytes} so far`))
    .on('error', (err) => {
      console.error(err);
      // retry with exponential backoff
      setTimeout(() => FileUpload(file, provider), Math.pow(2, Math.floor(Math.random() * 10)) * 1000);
    })
    .on('complete', () => {
      console.log(`File uploaded successfully: ${file.name}`);
      // notify user of successful upload
    });
};

// HTTP client in Rust for secure and flexible requests
const rust_http_client = require('rust-http-client');

const requestBuilder = (url, disableCertificateValidation) => {
  const req = new rust_http_client.RequestBuilder(url);
  if (!disableCertificateValidation) {
    // enable certificate validation by default
    req.setCaCertFilepath(process.env.CA_CERT_FILEPATH);
  }
  return req;
};

// user interface for real-time feedback and retrying failed uploads
