  const form = document.createElement('form');
  form.method = 'POST';
  form.enctype = 'multipart/form-data';

  const fileInput = document.createElement('input');
  fileInput.type = 'file';
  fileInput.accept = 'image/*, application/octet-stream';
  fileInput.name = 'file';

  const providerSelect = document.createElement('select');
  providerSelect.name = 'provider';
  ['s3', 'azure'].forEach((option) => {
    const opt = document.createElement('option');
    opt.value = option;
    opt.text = option;
    providerSelect.appendChild(opt);
  });

  form.appendChild(fileInput);
  form.appendChild(providerSelect);

  const uploadButton = document.createElement('button');
  uploadButton.textContent = 'Upload';
  uploadButton.addEventListener('click', () => {
    FileUpload(file, providerSelect.value);
  });

  const retryButton = document.createElement('button');
  retryButton.textContent = 'Retry';
  retryButton.addEventListener('click', () => {
    // retry failed uploads with exponential backoff
    setTimeout(() => FileUpload(file, providerSelect.value), Math.pow(2, Math.floor(Math.random() * 10)) * 1000);
  });

  form.appendChild(uploadButton);
  form.appendChild(retryButton);

  return form;
};
