// system.js
const { Worker } = require('worker_threads');
const fs = require('fs');
const Papa = require('papaparse');
const axios = require('axios');

class FileProcessor {
  constructor({ files, apiEndpoint }) {
    this.files = files;
    this.apiEndpoint = apiEndpoint;
    this.workers = [];
  }

  async processFile(file) {
    return new Promise((resolve, reject) => {
      const worker = new Worker(`
        const csvData = Papa.parse(fs.readFileSync('${file}'), { header: true });

        axios.post('${apiEndpoint}', csvData.data)
          .then(response => resolve(response))
          .catch(error => reject(error));
      `);

      this.workers.push(worker);
    });
  }

  async startProcessing() {
    await Promise.all(this.files.map(file => this.processFile(file)));

    return new Promise((resolve, reject) => {
      this.workers.forEach(worker => worker.on('exit', () => resolve()));
    });
  }
}

// error handling and logging
class Logger {
  log(message) {
    console.log(message);
  }

  error(error) {
    console.error(error);
  }
}

const logger = new Logger();

// retry strategy for transient errors
function retryPromise(promise, maxAttempts = 3) {
  return promise.catch(error => {
    if (error.name === 'TimeoutError' || error.name === 'NetworkError') {
      return retryPromise(promise, --maxAttempts);
    } else {
      throw error;
    }
  });
}

// job queue for managing workloads dynamically
class JobQueue {
  constructor({ maxConcurrency = 5 }) {
    this.queue = [];
    this.maxConcurrency = maxConcurrency;
  }

  addJob(job) {
    this.queue.push(job);

    if (this.queue.length >= this.maxConcurrency) {
      this.startProcessing();
    }
  }

  startProcessing() {
    return new Promise((resolve, reject) => {
      const jobs = this.queue.splice(0, this.maxConcurrency);

      Promise.all(jobs.map(job => job()))
        .then(() => resolve())
        .catch(error => reject(error));
    });
  }
}

// main entry point
const fileProcessor = new FileProcessor({ files: [], apiEndpoint: '' });
const jobQueue = new JobQueue();

fs.readdir('./', (error, files) => {
  if (error) {
    logger.error(error);
  } else {
    fileProcessor.files = files;

    fileProcessor.startProcessing()
      .then(() => console.log('Files processed successfully!'))
      .catch(error => logger.error(error));
  }
});

// example usage
fs.readdir('./', (error, files) => {
  if (error) {
    logger.error(error);
  } else {
    jobQueue.addJob(() => fileProcessor.processFile(file));

    jobQueue.startProcessing()
      .then(() => console.log('Files processed successfully!'))
      .catch(error => logger.error(error));
  }
});
