using namespace std;

class CommandExecutor {
private:
    mutex mtx;
    condition_variable cv;
    int status = 0; // Initialize status as 0 (success)

public:
    void executeCommand(string command) {
        thread t([this, command]() {
            pid_t pid = fork();
            if (pid < 0) {
                cerr << "Fork failed." << endl;
                return;
            } else if (pid == 0) { // Child process
                FILE* pipe = popen(command.c_str(), "r");
                if (!pipe) {
                    status = -1; // Set failure status
                    perror("popen");
                    exit(1);
                }
                char buffer[1024];
                while (fgets(buffer, sizeof(buffer), pipe)) {
                    cout << buffer;
                }
                pclose(pipe);
            } else { // Parent process
                unique_lock<mutex> lock(mtx);
                wait_for(lock, cv, chrono::seconds(5)); // Wait for 5 seconds before considering the command failed
                if (status == -1) {
                    cerr << "Command execution failed." << endl;
                }
            }
        });
        t.detach(); // Detach thread to execute in background
    }

    int getStatus() {
        return status;
    }
};

int main(int argc, char* argv[]) {
    CommandExecutor executor;

    string command = "your_external_command";
    executor.executeCommand(command);

    cout << "Status: " << executor.getStatus() << endl; // Output the status of the executed command

    return 0;
}

