#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure to represent a connection status notification
typedef struct {
    uint32_t ue_id;
    time_t timestamp;
    int status; // ESTABLISHED or DISCONNECTED
} ConnectionStatusNotification;

// Define the type of the list and its corresponding operations
typedef struct {
    size_t capacity;
    size_t size;
    ConnectionStatusNotification** notifications;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NotificationList;

// Initialize a new notification list with an initial capacity
NotificationList* notification_list_new(size_t initial_capacity) {
    NotificationList* list = (NotificationList*)malloc(sizeof(NotificationList));
    list->capacity = initial_capacity;
    list->size = 0;
    list->notifications = (ConnectionStatusNotification**)malloc(list->capacity * sizeof(ConnectionStatusNotification*));
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

// Add a new notification to the list
void notification_list_add(NotificationList* list, ConnectionStatusNotification* notification) {
    if (list->size >= list->capacity) {
        // Resize the list if it's full
        size_t new_capacity = list->capacity * 2;
        list->notifications = (ConnectionStatusNotification**)realloc(list->notifications, new_capacity * sizeof(ConnectionStatusNotification*));
        list->capacity = new_capacity;
    }
    pthread_mutex_lock(&list->mutex);
    list->notifications[list->size++] = notification;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

// Get the most recent connection status notification from the list
ConnectionStatusNotification* notification_list_get_latest(NotificationList* list) {
    pthread_mutex_lock(&list->mutex);
    ConnectionStatusNotification* latest_notification = list->notifications[list->size - 1];
    pthread_mutex_unlock(&list->mutex);
    return latest_notification;
}

// Clean up resources when the notification list is no longer needed
void notification_list_free(NotificationList* list) {
    for (int i = 0; i < list->size; ++i) {
        free(list->notifications[i]);
    }
    free(list->notifications);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}
