#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Structure to represent connection status notification
typedef struct {
    uint32_t ue_id;
    time_t timestamp;
    enum { ESTABLISHED, DISCONNECTED } status;
} ConnectionStatusNotification;

// Thread-safe data structure for managing list of notifications
typedef struct {
    ConnectionStatusNotification *notifications;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NotificationList;

// Initialize notification list
void init_notification_list(NotificationList *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->size = 0;
    list->notifications = (ConnectionStatusNotification *)malloc(initial_capacity * sizeof(ConnectionStatusNotification));
    pthread_mutex_init(&list->lock, NULL);
}

// Add notification to the list
void add_notification(NotificationList *list, ConnectionStatusNotification *notification) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        // Reallocating memory if the capacity is exceeded
        size_t new_capacity = list->capacity * 2;
        list->notifications = (ConnectionStatusNotification *)realloc(list->notifications, new_capacity * sizeof(ConnectionStatusNotification));
        list->capacity = new_capacity;
    }
    list->notifications[list->size++] = *notification;
    pthread_mutex_unlock(&list->lock);
}

// Get notification at a specific index
ConnectionStatusNotification *get_notification(NotificationList *list, size_t index) {
    if (index >= list->size || index < 0) {
        return NULL;
    }
    pthread_mutex_lock(&list->lock);
    ConnectionStatusNotification *notification = &list->notifications[index];
    pthread_mutex_unlock(&list->lock);
    return notification;
}

// Free memory allocated for the notification list
void free_notification_list(NotificationList *list) {
    if (list->notifications != NULL) {
        free(list->notifications);
        pthread_mutex_destroy(&list->lock);
    }
}

// Main function to manage connection status notifications
int main() {
    // Initialize the notification list with initial capacity of 1000
    NotificationList list;
    init_notification_list(&list, 1000);

    // Add some sample notifications
    for (int i = 0; i < 10; i++) {
        ConnectionStatusNotification notification;
        notification.ue_id = i;
        notification.timestamp = time(NULL);
        if (i % 2 == 0) {
            notification.status = ESTABLISHED;
        } else {
            notification.status = DISCONNECTED;
        }
        add_notification(&list, &notification);
    }

    // Get a specific notification
    ConnectionStatusNotification *notification = get_notification(&list, 5);
    if (notification != NULL) {
        printf("UE ID: %u\n", notification->ue_id);
        printf("Timestamp: %lu\n", notification->timestamp);
        printf("Status: %s\n",
               notification->status == ESTABLISHED ? "ESTABLISHED" : "DISCONNECTED");
    } else {
        printf("Notification not found.\n");
    }

    // Free the memory allocated for the notification list
    free_notification_list(&list);

    return 0;
}
