#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>

typedef struct {
    int ue_id;
    time_t timestamp;
    int status;
} ConnectionStatusNotification;

// Thread-safe data structure to manage a dynamically sized list of notifications
struct NotificationList {
    ConnectionStatusNotification *notifications;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

// Function to create a new notification list with initial capacity
struct NotificationList* create_notification_list(size_t initial_capacity) {
    struct NotificationList* list = (struct NotificationList*)malloc(sizeof(struct NotificationList));
    list->notifications = (ConnectionStatusNotification*)malloc(initial_capacity * sizeof(ConnectionStatusNotification));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a new notification to the list
void add_notification(struct NotificationList* list, ConnectionStatusNotification notification) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        // Reallocate memory and update capacity
        list->notifications = (ConnectionStatusNotification*)realloc(list->notifications, (list->capacity * 2 + 1) * sizeof(ConnectionStatusNotification));
        list->capacity *= 2;
    }

    list->notifications[list->size++] = notification;
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a notification from the list
ConnectionStatusNotification* get_notification(struct NotificationList* list, int index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        // Handle out-of-bounds error
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    ConnectionStatusNotification* notification = &list->notifications[index];
    pthread_mutex_unlock(&list->mutex);

    return notification;
}

// Function to free the memory allocated for a notification list
void free_notification_list(struct NotificationList* list) {
    free(list->notifications);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Main function to test the notification list implementation
int main() {
    // Create a new notification list with initial capacity of 1000
    struct NotificationList* list = create_notification_list(1000);

    // Add some sample notifications to the list
    for (int i = 0; i < 10; i++) {
        ConnectionStatusNotification notification;
        notification.ue_id = i + 1;
        notification.timestamp = time(NULL);
        notification.status = (i % 2 == 0) ? ESTABLISHED : DISCONNECTED;
        add_notification(list, notification);
    }

    // Retrieve and print the first notification
    ConnectionStatusNotification* notification = get_notification(list, 0);
    printf("UE ID: %d, Timestamp: %ld, Status: %s\n", notification->ue_id, notification->timestamp, (notification->status == ESTABLISHED) ? "ESTABLISHED" : "DISCONNECTED");

    // Free the memory allocated for the notification list
    free_notification_list(list);

    return 0;
}
