public sealed class ConnectionStatusManager
{
    private readonly ConcurrentBag<ConnectionStatusNotification> _notifications = new();
    private readonly SemaphoreSlim _semaphore = new(1);
    private readonly int _maxNotificationsPerBatch;
    private readonly TimeSpan _batchInterval;

    public ConnectionStatusManager(int maxNotificationsPerBatch, TimeSpan batchInterval)
    {
        _maxNotificationsPerBatch = maxNotificationsPerBatch;
        _batchInterval = batchInterval;
    }

    public void AddNotification(ConnectionStatusNotification notification)
    {
        _semaphore.Wait();
        try
        {
            _notifications.Add(notification);
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public async Task<IEnumerable<ConnectionStatusNotification>> GetNotificationsAsync()
    {
        await _semaphore.WaitAsync();
        try
        {
            return new List<ConnectionStatusNotification>(_notifications.Take(_maxNotificationsPerBatch));
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public void ClearNotifications()
    {
        _semaphore.Wait();
        try
        {
            _notifications.Clear();
        }
        finally
        {
            _semaphore.Release();
        }
    }

    public async Task ProcessNotificationsAsync()
    {
