#include <condition_variable>

class SensorData {
public:
    std::string id;
    double value;

    SensorData(const std::string& id, double value) : id(id), value(value) {}
};

class Aggregator {
private:
    std::map<std::string, double> aggregatedData;
    std::mutex mutex;
    std::condition_variable condVar;

public:
    void addSensorData(SensorData data) {
        std::unique_lock<std::mutex> lock(mutex);
        if (aggregatedData.find(data.id) == aggregatedData.end()) {
            aggregatedData[data.id] = 0.0;
        }
        aggregatedData[data.id] += data.value;
        lock.unlock();
        condVar.notify_one();
    }

    void getAggregatedData() {
        std::unique_lock<std::mutex> lock(mutex);
        while (aggregatedData.empty()) {
            condVar.wait(lock);
        }
        for (const auto& entry : aggregatedData) {
            std::cout << "Sensor ID: " << entry.first << ", Value: " << entry.second << std::endl;
        }
    }

    void startAggregationThread() {
        std::thread aggregationThread([this] {
            while (true) {
                getAggregatedData();
                // Sleep for 1 second
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        });
        aggregationThread.detach();
    }
};

int main() {
    Aggregator aggregator;
    aggregator.startAggregationThread();

    SensorData sensorData1("Sensor1", 10.0);
    SensorData sensorData2("Sensor2", 20.0);
    SensorData sensorData3("Sensor3", 30.0);

    aggregator.addSensorData(sensorData1);
    aggregator.addSensorData(sensorData2);
    aggregator.addSensorData(sensorData3);

    return 0;
}
```

This code implements a simple sensor data aggregation system using C++ threads, mutexes, and condition variables. It simulates multiple sensors sending data to the aggregator, which then processes and stores this data in memory. The `getAggregatedData` method allows other parts of the program to query the aggregated sensor readings.']

