using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace RealtimeDataGenerator
{
    public enum RandomType { Integer, FloatingPoint }

    public class RealtimeDataGenerator
    {
        private readonly Random _random;
        private readonly Dictionary<string, (int, int)> _rangeSettings;
        private readonly Dictionary<string, double> _customDistributions;
        private readonly CancellationTokenSource _cts;

        public event EventHandler<RangeUpdatedEventArgs> RangeUpdated;

        public RealtimeDataGenerator()
        {
            _random = new Random();
            _rangeSettings = new Dictionary<string, (int, int)>();
            _customDistributions = new Dictionary<string, double>();
            _cts = new CancellationTokenSource();

            LoadConfigurations();
        }

        private void LoadConfigurations()
        {
            // Load configurations from external file
            var configFilePath = Environment.GetEnvironmentVariable("CONFIG_FILE_PATH");
            if (File.Exists(configFilePath))
            {
                var configJson = File.ReadAllText(configFilePath);
                var config = JsonConvert.DeserializeObject<Configuration>(configJson);

                foreach (var range in config.Ranges)
                {
                    _rangeSettings.Add(range.Name, (range.Min, range.Max));
                }

                foreach (var distribution in config.Distributions)
                {
                    _customDistributions.Add(distribution.Name, distribution.Value);
                }
            }
        }

        public int GenerateRandomValue(RandomType type, string rangeName)
        {
            if (!_rangeSettings.ContainsKey(rangeName))
                throw new ArgumentException("Invalid range name");

            var (min, max) = _rangeSettings[rangeName];

            switch (type)
            {
                case RandomType.Integer:
                    return _random.Next(min, max + 1);
                case RandomType.FloatingPoint:
                    return _random.NextDouble() * (max - min) + min;
            }
        }

        public async Task UpdateRangeAsync(string rangeName, int minValue, int maxValue)
        {
            if (_rangeSettings.ContainsKey(rangeName))
                throw new ArgumentException("Range already exists");

            _rangeSettings.Add(rangeName, (minValue, maxValue));

            await RaiseRangeUpdatedEvent();
        }

        private async Task RaiseRangeUpdatedEvent()
        {
            RangeUpdated?.Invoke(this, new RangeUpdatedEventArgs(_rangeSettings));
        }
    }

    public class RangeUpdatedEventArgs : EventArgs
    {
        public Dictionary<string, (int, int)> UpdatedRanges { get; }

        public RangeUpdatedEventArgs(Dictionary<string, (int, int)> updatedRanges)
        {
            UpdatedRanges = updatedRanges;
        }
    }

    public class Configuration
    {
        public List<Range> Ranges { get; set; }
        public List<Distribution> Distributions { get; set; }
    }

    public class Range
    {
        public string Name { get; set; }
        public int Min { get; set; }
        public int Max { get; set; }
    }

    public class Distribution
    {
        public string Name { get; set; }
        public double Value { get; set; }
    }
}
