// Define the connection event structure
typedef struct ConnectionEvent {
    time_t timestamp;
    int eventType;
    char* metadata;
} ConnectionEvent;

// Define the library handle structure
typedef struct LibraryHandle {
    pthread_mutex_t mutex; // Mutex for thread safety
    ConnectionEvent** events; // Dynamic array of connection events
    size_t eventCount; // Number of events in the collection
} LibraryHandle;

// Create a new library handle
LibraryHandle* createLibraryHandle() {
    LibraryHandle* lib = (LibraryHandle*)malloc(sizeof(LibraryHandle));
    if (!lib) {
        return NULL;
    }

    lib->events = NULL;
    lib->eventCount = 0;
    pthread_mutex_init(&lib->mutex, NULL);
    return lib;
}

// Add a new connection event to the library
int addEvent(LibraryHandle* lib, ConnectionEvent* event) {
    if (!lib || !event) {
        return -1; // Invalid library or event handle
    }

    pthread_mutex_lock(&lib->mutex); // Lock for thread safety

    // Resize the array if necessary
    size_t newSize = lib->eventCount + 1;
    ConnectionEvent** newEvents = (ConnectionEvent**)realloc(lib->events, newSize * sizeof(ConnectionEvent*));
    if (!newEvents) {
        pthread_mutex_unlock(&lib->mutex);
        return -2; // Memory allocation failure
    }

    lib->events = newEvents;

    // Copy the event metadata to ensure thread safety
    char* eventMetadata = strdup(event->metadata);
    if (!eventMetadata) {
        free(newEvents);
        pthread_mutex_unlock(&lib->mutex);
        return -2; // Memory allocation failure
    }

    lib->events[lib->eventCount] = (ConnectionEvent*)malloc(sizeof(ConnectionEvent));
    if (!lib->events[lib->eventCount]) {
        free(eventMetadata);
        free(newEvents);
        pthread_mutex_unlock(&lib->mutex);
        return -2; // Memory allocation failure
    }

    lib->events[lib->eventCount]->timestamp = event->timestamp;
    lib->events[lib->eventCount]->eventType = event->eventType;
    lib->events[lib->eventCount]->metadata = eventMetadata;
    lib->eventCount++;

    pthread_mutex_unlock(&lib->mutex);
    return 0; // Success
}

// Retrieve a connection event by its index
ConnectionEvent* getEvent(LibraryHandle* lib, int index) {
    if (!lib || index >= lib->eventCount) {
        return NULL; // Invalid library or index
    }

    pthread_mutex_lock(&lib->mutex); // Lock for thread safety

    ConnectionEvent* event = lib->events[index];
    pthread_mutex_unlock(&lib->mutex);
    return event;
}

// Remove a connection event by its index
int removeEvent(LibraryHandle* lib, int index) {
    if (!lib || index >= lib->eventCount) {
        return -1; // Invalid library or index
    }

    pthread_mutex_lock(&lib->mutex); // Lock for thread safety

    // Free the metadata to avoid memory leaks
    free(lib->events[index]->metadata);
    free(lib->events[index]);

    memmove(lib->events + index, lib->events + index + 1, (lib->eventCount - index - 1) * sizeof(ConnectionEvent*));
    lib->eventCount--;

    pthread_mutex_unlock(&lib->mutex);
    return 0; // Success
}

// Filter events by type and time using a callback function
int filterEvents(LibraryHandle* lib, int (*callback)(ConnectionEvent*, void*), void* context) {
    if (!lib || !callback) {
        return -1; // Invalid library or callback
    }

    pthread_mutex_lock(&lib->mutex); // Lock for thread safety

    for (int i = 0; i < lib->eventCount; i++) {
        ConnectionEvent* event = lib->events[i];
        if (callback(event, context) == -1) {
            break;
        }
    }

    pthread_mutex_unlock(&lib->mutex);
    return 0; // Success
}

// Free the library handle and its resources
void freeLibraryHandle(LibraryHandle* lib) {
    if (!lib) {
        return;
    }

    for (int i = 0; i < lib->eventCount; i++) {
        free(lib->events[i]->metadata);
        free(lib->events[i]);
    }

    free(lib->events);
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}

// Example usage: Add events, retrieve an event, and filter events
int main() {
    LibraryHandle* lib = createLibraryHandle();
    ConnectionEvent* event1 = (ConnectionEvent*)malloc(sizeof(ConnectionEvent));
    event1->timestamp = time(NULL);
    event1->eventType = 0;
    event1->metadata = "Initial connection";

    addEvent(lib, event1);

    ConnectionEvent* event2 = (ConnectionEvent*)malloc(sizeof(ConnectionEvent));
    event2->timestamp = time(NULL) + 10;
    event2->eventType = 1;
    event2->metadata = "Reconnection after 10 seconds";

    addEvent(lib, event2);

    ConnectionEvent* retrievedEvent = getEvent(lib, 0);
    printf("Retrieved event: %s\n", retrievedEvent->metadata);

    int eventType = 0;
    filterEvents(lib, (int (*)(ConnectionEvent*, void*))eventTypeFilter, &eventType);

    freeLibraryHandle(lib);
    return 0;
}

// Example callback function for filtering events
int eventTypeFilter(ConnectionEvent* event, void* context) {
    int* type = (int*)context;
    if (event->eventType == *type) {
        printf("Filtered event: %s\n", event->metadata);
        return 0; // Continue filtering
    }
    return -1; // Stop filtering
}
