}

impl LLVMParser {
    pub fn new(grammar: &str) -> Self {
        LLVMParser { grammar: grammar.to_string() }
    }

    pub async fn parse_async(&self) -> Result<String, Box<dyn std::error::Error>> {
        // Parse grammar using Rust module
        let mut parser = LLVMLexer::new(self.grammar.as_bytes());
        let ast = parser.parse().await?;

        Ok(ast.to_string())
    }
}
