class Cache {
public:
    struct Entry {
        std::string value;
        std::time_t expirationTime;
        int version;
        int hitCount;
        bool isValid;
        std::time_t lastAccessed;
    };

    Cache(int maxCacheSize) : maxCacheSize_(maxCacheSize), cache_({}) {}

    void put(const std::string& key, const std::string& value, std::time_t expirationTime) {
        Entry entry = {value, expirationTime, 1, 0, true, std::time(nullptr)};
        if (cache_.size() >= maxCacheSize_) {
            // evict the least recently used cache entry
            auto it = cache_.begin();
            for (; it != cache_.end(); ++it) {
                if (it->second.lastAccessed < entry.lastAccessed) {
                    break;
                }
            }
            cache_.erase(it);
        }
        cache_[key] = entry;
    }

    std::string get(const std::string& key) {
        auto it = cache_.find(key);
        if (it == cache_.end()) return ""; // not found
        Entry &entry = it->second;
        if (!entry.isValid || entry.expirationTime < std::time(nullptr)) {
            // expired or invalid, evict and try to re-fetch
