    public class FileMonitoringAndEncryptionService : IDisposable
    {
        private readonly string _directoryPath;
        private readonly string[] _ignoreExtensions;
        private readonly string[] _supportedAlgorithms;
        private readonly int _batchSize;
        private readonly string _storageConnectionString;
        private readonly int _maxConcurrentOperations;

        public FileMonitoringAndEncryptionService(
            string directoryPath, 
            string[] ignoreExtensions, 
            string[] supportedAlgorithms, 
            int batchSize, 
            string storageConnectionString, 
            int maxConcurrentOperations)
        {
            _directoryPath = directoryPath;
            _ignoreExtensions = ignoreExtensions;
            _supportedAlgorithms = supportedAlgorithms;
            _batchSize = batchSize;
            _storageConnectionString = storageConnectionString;
            _maxConcurrentOperations = maxConcurrentOperations;
        }

        public void StartMonitoring()
        {
            Task.Run(() =>
            {
                using (var watcher = new FileSystemWatcher(_directoryPath, "*.*"))
                {
                    watcher.NotifyFilter = NotifyFilters.LastWrite | NotifyFilters.FileName;
                    watcher.Filter = "*.*";
                    watcher.Error += (sender, e) => { Console.WriteLine($"Error: {e.GetException().Message}"); };
                    watcher.Created += (sender, e) =>
                    {
                        if (!IsIgnoredFile(e.FullPath))
                        {
                            ProcessNewFile(e.FullPath);
                        }
                    };
                    watcher.Changed += (sender, e) =>
                    {
                        if (!IsIgnoredFile(e.FullPath))
                        {
                            ProcessModifiedFile(e.FullPath);
                        }
                    };

                    watcher.EnableRaisingEvents = true;
                }
            });
        }

        private bool IsIgnoredFile(string filePath)
        {
            foreach (var extension in _ignoreExtensions)
            {
                if (filePath.EndsWith(extension, StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }
            return false;
        }

        private void ProcessNewFile(string filePath)
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var md5Hash = GetMd5Hash(fileStream);
                EncryptFile(filePath, md5Hash);
            }
        }

        private void ProcessModifiedFile(string filePath)
        {
            using (var fileStream = File.OpenRead(filePath))
            {
                var md5Hash = GetMd5Hash(fileStream);
                EncryptFile(filePath, md5Hash);
            }
        }

        private string GetMd5Hash(Stream fileStream)
        {
            using (var md5 = MD5.Create())
            {
                return BitConverter.ToString(md5.ComputeHash(fileStream)).Replace("-", "").ToLower();
            }
        }

        private void EncryptFile(string filePath, string md5Hash)
        {
            foreach (var algorithm in _supportedAlgorithms)
            {
                try
                {
                    using (var encryptor = GetEncryptionAlgorithm(algorithm))
                    {
                        var encryptedBytes = EncryptFile(fileStream, encryptor);
                        StoreEncryptedData(filePath, md5Hash, encryptedBytes);
                    }
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error: {ex.Message}");
                }
            }
        }

        private ICryptoTransform GetEncryptionAlgorithm(string algorithm)
        {
            switch (algorithm)
            {
                case "AES":
                    return AesEncryption.Create();
                case "RSA":
                    return RsAEncryption.Create();
                default:
                    throw new ArgumentException("Unsupported encryption algorithm", nameof(algorithm));
            }
        }

        private void StoreEncryptedData(string filePath, string md5Hash, byte[] encryptedBytes)
        {
            // Implement storage logic using _storageConnectionString
        }
    }

