    {
        public static AesEncryption Create()
        {
            return new AesEncryption();
        }

        public void Encrypt(byte[] input, byte[] output)
        {
            // AES encryption implementation
        }
    }

    public class RsAEncryption : ICryptoTransform
    {
        public static RsAEncryption Create()
        {
            return new RsAEncryption();
        }

        public void Encrypt(byte[] input, byte[] output)
        {
            // RSA encryption implementation
        }
    }

    public interface ICryptoTransform
    {
        void Encrypt(byte[] input, byte[] output);
    }

    public class Program : IDisposable
    {
        public static void Main(string[] args)
        {
            var service = new FileMonitoringAndEncryptionService(
                @"C:\Path\To\Directory\",
                new string[] { ".txt", ".log" },
                new string[] { "AES", "RSA" },
                100,
                "Data Storage Connection String",
