#include <mutex>
#include <condition_variable>
#include <iostream>

std::unique_ptr<std::vector<NFAPI_CRC_INDICATION_PDU_T>> createNFAPIList() {
    return std::make_unique<std::vector<NFAPI_CRC_INDICATION_PDU_T>>();
}

void populateNFAPIList(std::unique_ptr<std::vector<NFAPI_CRC_INDICATION_PDU_T>>& nfaPIL, int numElements) {
    for (int i = 0; i < numElements; ++i) {
        NFAPI_CRC_INDICATION_PDU_T& pdu = nfaPIL->back();
        pdu.RX_UE_INFORMATION_TAG = static_cast<uint32_t>(i);
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? NFAPI_CRC_FLAG_ENABLE : NFAPI_CRC_FLAG_DISABLE;
    }
}

std::unique_ptr<std::vector TIFFInfo>> parseTIFFImages(int numFiles) {
    std::unique_ptr<std::vector<TIFFInfo>> tiffList;
    for (int i = 0; i < numFiles; ++i) {
        TIFF* tifFile = TIFFOpen(("file" + std::to_string(i) + ".tif").c_str(), "r");
        if (!tifFile) {
            continue;
        }
        int bitsPerSample, samplesPerPixel, extraSamples;
        tiffList->push_back({bitsPerSample, samplesPerPixel, extraSamples});
        TIFFClose(tifFile);
    }
}

struct NFAPI_Parser {
public:
    NFAPI_Parser(std::unique_ptr<std::vector<NFAPI_CRC_INDICATION_PDU_T>>& nfaPIL)
        : nfaPIL_(nfaPIL) {}

    void operator()(const std::unique_ptr<TIFFInfo>& tiffInfo) {
        int bitsPerSample, samplesPerPixel, extraSamples;
        TIFFGetFieldDefaulted(tifFile, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
        TIFFGetFieldDefaulted(tifFile, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);
        if (extraSamples > 0) {
            // Log the type and count of extra samples
            std::cout << "Extra Samples: " << extraSamples << "\n";
        }
    }

private:
    std::unique_ptr<std::vector<NFAPI_CRC_INDICATION_PDU_T>>& nfaPIL_;
};

int main() {
    std::unique_ptr<std::vector<NFAPI_CRC_INDICATION_PDU_T>> nfaPIL = createNFAPIList();
    populateNFAPIList(nfaPIL, 1000);

    // Start parsing TIFF images concurrently
    int numFiles = 10;
    std::vector<std::thread> tiffThreads;
    for (int i = 0; i < numFiles; ++i) {
        tiffThreads.emplace_back([this, &nfaPIL]() { parseTIFFImages(numFiles); });
    }

    // Wait for all threads to finish
    for (auto& thread : tiffThreads) {
        thread.join();
    }

    return 0;
}
