from jinja2 import Template
import logging
from datetime import datetime
from apscheduler.schedulers.background import BackgroundScheduler

class ConfigGenerator:
    def __init__(self):
        self.config = None
        self.api_keys = {}
        self.rate_limiter = None
        self.cache = {}

    def load_config(self, filename):
        with open(filename, 'r') as f:
            self.config = yaml.safe_load(f)

    def generate_config(self, template_name):
        template = Template(open(f'templates/{template_name}.jinja', 'r').read())
        config_data = {}
        for section in self.config['sections']:
            if section['type'] == 'api':
                api_key = self.api_keys[section['api']]
                response = requests.get(section['url'], headers={'Authorization': f'Bearer {api_key}'})
                config_data.update(yaml.safe_load(response.content))
            elif section['type'] == 'file':
                with open(section['path']) as f:
                    config_data.update(yaml.safe_load(f.read()))
        return template.render(**config_data)

    def update_config(self):
        for filename in self.config['files']:
            if os.path.exists(filename):
                os.remove(filename)
        for section in self.config['sections']:
            if section['type'] == 'file':
                with open(section['path']) as f:
                    data = yaml.safe_load(f.read())
                    template_name = self.generate_config(section['template'])
                    with open(filename, 'w') as f:
                        f.write(template.render(**data))
        for filename in self.config['files']:
            if not os.path.exists(filename):
                raise Exception(f"File {filename} does not exist")

    def start_scheduler(self):
        scheduler = BackgroundScheduler()
        scheduler.add_job(self.update_config, 'interval', minutes=5)
        scheduler.start()

if __name__ == '__main__':
    generator = ConfigGenerator()
    generator.load_config('config.yaml')
    generator.api_keys = {'api1': 'key1', 'api2': 'key2'}
    generator.rate_limiter = RateLimiter()
    generator.cache = Cache()
    generator.start_scheduler()
