**C++ Code for In-Game Attack System**

```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>

// Attack class
class Attack {
public:
    std::string name;
    int cooldownTime; // in seconds
    bool isValid;

    Attack(std::string name, int cooldownTime) : name(name), cooldownTime(cooldownTime), isValid(true) {}
};

// In-Game Attack System
class AttackSystem {
private:
    std::queue<Attack> attackQueue;
    std::map<std::string, int> cooldownMap;
    std::mutex lock;
    std::condition_variable cv;

public:
    void addAttack(Attack attack) {
        lock.lock();
        attackQueue.push(attack);
        cooldownMap[attack.name] = 0; // reset cooldown
        lock.unlock();
    }

    void updateCooldown() {
        lock.lock();
        for (auto& pair : cooldownMap) {
            if (--pair.second <= 0) {
                pair.second = pair.first.length(); // set cooldown to attack length
            }
        }
        lock.unlock();
    }

    Attack selectAttack() {
        lock.lock();
        while (!attackQueue.empty()) {
            Attack attack = attackQueue.front();
            attackQueue.pop();
            if (cooldownMap[attack.name] > 0) {
                continue;
            }
            return attack;
        }
        lock.unlock();
        return Attack("", 0); // no valid attacks available
    }

    void validateAttack(Attack attack, bool isValid) {
        lock.lock();
        if (isValid) {
            cooldownMap[attack.name] = attack.cooldownTime; // update cooldown
        } else {
            cooldownMap.erase(attack.name);
        }
        lock.unlock();
    }
};

