import os
import hashlib
import threading
from kafka import KafkaProducer

# Monitor class
class Monitor:
    def __init__(self, directory, excluded_paths):
        self.directory = directory
        self.excluded_paths = set(excluded_paths)
        self.producer = KafkaProducer(bootstrap_servers=['localhost:9092'])
        self.hash_queue = []

    def start_monitoring(self):
        while True:
            files = os.listdir(self.directory)
            for file in files:
                if file.lower().endswith(tuple(['.txt', '.csv', '.json'])):  # ignore specific file extensions
                    continue
                if os.path.join(self.directory, file) in self.excluded_paths:
                    continue
                try:
                    with open(os.path.join(self.directory, file), 'rb') as f:
                        file_hash = hashlib.md5(f.read()).hexdigest()
                    self.hash_queue.append((file, file_hash))
                    self.producer.send('monitor_topic', file_hash.encode())
                except Exception as e:
                    print(f"Error processing file {file}: {str(e)}")
            time.sleep(1)

    def process_hashes(self):
        while True:
            for file, hash in self.hash_queue:
                if not os.path.exists(os.path.join(self.directory, file)):
                    print(f"File {file} has been deleted!")
                elif hashlib.md5(open(os.path.join(self.directory, file), 'rb').read()).hexdigest() != hash:
                    print(f"File {file} has been modified!")
            self.hash_queue = []
