#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <map>

// Worker node class
class WorkerNode {
public:
    std::queue<Attack> attackQueue;
    std::mutex lock;
    std::condition_variable cv;

    void start_processing() {
        while (true) {
            lock.lock();
            if (!attackQueue.empty()) {
                Attack attack = attackQueue.front();
                attackQueue.pop();
                // process attack
                lock.unlock();
            } else {
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::seconds(1));
            }
        }
    }

    void add_attack(Attack attack) {
        lock.lock();
        attackQueue.push(attack);
        lock.unlock();
    }
};

// Load balancer class
class LoadBalancer {
public:
    std::vector<WorkerNode*> worker_nodes;
    std::mutex lock;

    void add_worker_node(WorkerNode* node) {
        lock.lock();
        worker_nodes.push_back(node);
        lock.unlock();
    }

    void dispatch_attack(Attack attack) {
        lock.lock();
        for (auto& node : worker_nodes) {
            node->add_attack(attack);
        }
        lock.unlock();
    }
};
