#include <iostream>
#include <mutex>
#include <thread>
#include <vector>
#include <map>
#include <string>

class DistributedKVStore {
public:
    DistributedKVStore(int numNodes);
    void put(const std::string& key, const std::string& value);
    std::string get(const std::string& key);

private:
    int numNodes;
    std::vector<std::mutex> nodeLocks;
    std::map<std::string, std::string> data;

    void replicateData();
    bool resolveConflict(const std::string& key, const std::string& value);
};

DistributedKVStore::DistributedKVStore(int numNodes) : numNodes(numNodes), nodeLocks(numNodes) {}

void DistributedKVStore::put(const std::string& key, const std::string& value) {
    // Lock the node corresponding to this process
    int currentNode = 0;
    for (int i = 0; i < numNodes; ++i) {
        if (nodeLocks[i].try_lock()) {
            currentNode = i;
            break;
        }
    }

    // Update local data and replicate
    data[key] = value;
    replicateData();

    // Unlock the node
    nodeLocks[currentNode].unlock();
}

std::string DistributedKVStore::get(const std::string& key) {
    // Find the most recent value for this key
    return resolveConflict(key, data[key]);
}

void DistributedKVStore::replicateData() {
    // Replicate data to other nodes
    for (int i = 0; i < numNodes; ++i) {
        if (i != currentNode) {
            // Lock the node and update local copy of data
            nodeLocks[i].lock();
            data[i] = data;
            nodeLocks[i].unlock();
        }
    }
}

bool DistributedKVStore::resolveConflict(const std::string& key, const std::string& value) {
    // Resolve conflict by choosing the most recent value
    int currentNode = 0;
    for (int i = 0; i < numNodes; ++i) {
        if (nodeLocks[i].try_lock()) {
            if (data[i][key] != value) {
                data[key] = value;
                replicateData();
            }
            nodeLocks[i].unlock();
            currentNode = i;
        }
    }
}
