class DistributedKVStore {
public:
    DistributedKVStore(int num_nodes) : nodes(num_nodes), lock(true) {}

    void put(const std::string& key, const std::string& value) {
        auto node = get_available_node();
        if (node == -1) {
            // Handle full nodes
            return;
        }
        node->store[key] = value;
        notify(node);
    }

    std::string get(const std::string& key) {
        auto node = get_available_node();
        if (node == -1) {
            // Handle full nodes
            return "";
        }
        return node->store.find(key)->second;
    }

private:
    struct Node {
        std::unordered_map<std::string, std::string> store;
        bool available;
    };

    int get_available_node() {
        for (auto& node : nodes) {
            if (!node.available) {
                return &node;
            }
        }
        return -1; // No available node
    }

    void notify(Node* node) {
        std::unique_lock<std::mutex> lock(node->lock);
        node->available = false;
        cv.notify_one();
        cv.wait(lock, [this, node] { return !node->available; });
        node->available = true;
    }

    std::vector<Node> nodes;
    std::mutex lock;
    std::condition_variable cv;
};

int main() {
