// Define a struct to represent an attack
struct Attack {
    std::string name;
    int cooldown; // in seconds
    bool isValid;

    Attack(const std::string& n, int c) : name(n), cooldown(c), isValid(false) {}
};

// Define a class for the game character's attack manager
class AttackManager {
public:
    AttackManager();

    void selectAttack();
    void updateAttackCooldown(int seconds);
    void validateAttack();
    bool isAttackValid();

private:
    std::mutex mtx;
    std::condition_variable cv;
    std::random_device rd;
    std::mt19937 gen;
    std::uniform_real_distribution<double> dis;
    Attack currentAttack;

    // Helper function to simulate a validation request to an external service
    void simulateValidationRequest();
};

// Implementation of the AttackManager class
AttackManager::AttackManager() {
    currentAttack = Attack("Basic Attack", 9, false);
}

void AttackManager::selectAttack() {
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    // Simulate selecting an attack from a pool of available attacks
    simulateValidationRequest();
}

void AttackManager::updateAttackCooldown(int seconds) {
    currentAttack.cooldown = seconds;
}

void AttackManager::validateAttack() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait_for(lock, std::chrono::seconds(1));
    if (currentAttack.isValid) {
        // Validation successful
        currentAttack.name += " [Valid]";
    } else {
        // Validation failed
        currentAttack.name += " [Invalid]";
    }
}

bool AttackManager::isAttackValid() {
    return currentAttack.isValid;
}

void AttackManager::simulateValidationRequest() {
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
    if (dis(gen) < 0.5) {
        // Validation request successful
        currentAttack.isValid = true;
    } else {
        // Validation request failed
        currentAttack.isValid = false;
    }
    cv.notify_one();
}

int main() {
    AttackManager manager;

    while (true) {
        manager.selectAttack();
        std::cout << "Selected attack: " << manager.currentAttack.name << std::endl;
        if (!manager.isAttackValid()) {
            std::cout << "Attack invalid. Waiting for cooldown..." << std::endl;
            manager.updateAttackCooldown(9);
        }
        std::this_thread::sleep_for(std::chrono::seconds(2));
    }

    return 0;
}
```

