class Node {
public:
    int id;
    std::string key;
    int value;

    Node(int id, const std::string& key, int value) : id(id), key(key), value(value) {}

    friend std::ostream& operator<<(std::ostream& os, const Node& node) {
        os << "Node { id: " << node.id << ", key: " << node.key << ", value: " << node.value << " }";
        return os;
    }
};

class DistributedKeyValueStore {
public:
    DistributedKeyValueStore();

    void put(const std::string& key, int value);
    int get(const std::string& key);

private:
    std::unordered_map<std::string, Node> storage;
    std::mutex lock;
    std::condition_variable cv;

    void replicate();
    void resolveConflict(Node& node);
};

DistributedKeyValueStore::DistributedKeyValueStore() {
    // Initialize the distributed store
}

void DistributedKeyValueStore::put(const std::string& key, int value) {
    Node node(0, key, value);

    // Put the data in local storage and notify other nodes to replicate
    {
        std::lock_guard<std::mutex> lock(lock);
        storage[key] = node;
    }

    cv.notify_all();

    // Replicate the data asynchronously
    std::thread([this]() { replicate(); }).detach();
}

int DistributedKeyValueStore::get(const std::string& key) {
    Node node;

    // Check if the key exists in local storage
    if (storage.find(key) != storage.end()) {
        return storage[key].value;
    }

    // If not, wait for a replication to occur and then get the value
    {
        std::unique_lock<std::mutex> lock(lock);
        cv.wait_for(lock, std::chrono::seconds(1), [this]() { replicate(); });
        if (storage.find(key) != storage.end()) {
