        private double _minValue, _maxValue;
        private object _lockObject = new object();

        public event EventHandler<RangeChangedEventArgs> RangeChanged;

        public RealtimeDataGenerator()
        {
            // Initialize default range values
            _minValue = 0.0;
            _maxValue = 100.0;
        }

        public double GenerateRandomDouble()
        {
            lock (_lockObject)
            {
                return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
            }
        }

        public int GenerateRandomInt()
        {
            lock (_lockObject)
            {
                return _random.Next((int)_minValue, (int)_maxValue);
            }
        }

        public void SetRange(double minValue, double maxValue)
        {
            if (_minValue != minValue || _maxValue != maxValue)
            {
                _minValue = minValue;
                _maxValue = maxValue;
                OnRangeChanged(new RangeChangedEventArgs(minValue, maxValue));
            }
        }

        protected virtual void OnRangeChanged(RangeChangedEventArgs e)
        {
            EventHandler<RangeChangedEventArgs> handler = RangeChanged;
            if (handler != null) handler(this, e);
        }
    }

    public class RangeChangedEventArgs : EventArgs
    {
