using System;
using System.Runtime.Serialization.Formatters.Binary;
using System.IO;
using Newtonsoft.Json;

public class RandomValueGenerator
{
    private readonly Random _random;
    private int _seed;
    private bool _inclusiveRange;
    private (int, int) _range;

    public RandomValueGenerator()
    {
        _seed = Environment.TickCount;
        _random = new Random(_seed);
        _inclusiveRange = true;
    }

    public void SetSeed(int seed)
    {
        _seed = seed;
        _random = new Random(seed);
    }

    public float NextFloat((float, float) range)
    {
        if (range == null || range.Item1 > range.Item2)
            throw new ArgumentException("Invalid range", nameof(range));
        return (float)_random.NextDouble() * (range.Item2 - range.Item1) + range.Item1;
    }

    public int NextInt((int, int) range)
    {
        if (range == null || range.Item1 > range.Item2)
            throw new ArgumentException("Invalid range", nameof(range));
        return _random.Next(range.Item1, range.Item2);
    }

    public long NextLong((long, long) range)
    {
        if (range == null || range.Item1 > range.Item2)
            throw new ArgumentException("Invalid range", nameof(range));
        return _random.NextLong(range.Item1, range.Item2);
    }

    public void SetRange((int, int) range, bool isExclusive)
    {
        if (range == null || range.Item1 > range.Item2)
            throw new ArgumentException("Invalid range", nameof(range));
        _range = range;
        _inclusiveRange = isExclusive;
    }

    public string ToString()
    {
        return $"RandomValueGenerator: Seed={_seed}, Range=({_range.Item1}, {_range.Item2}){(_inclusiveRange ? "" : " (exclusive)")}";
    }

    public void Dispose()
    {
        // Release resources
    }

    [Serializable]
    public class SerializedState
    {
        public int Seed { get; set; }
        public (int, int) Range { get; set; }
        public bool IsExclusive { get; set; }
    }

    public string Serialize()
    {
        var state = new SerializedState
        {
            Seed = _seed,
            Range = _range,
            IsExclusive = _inclusiveRange
        };
        return JsonConvert.SerializeObject(state);
    }

    public void Deserialize(string serializedState)
    {
        var state = JsonConvert.DeserializeObject<SerializedState>(serializedState);
        _seed = state.Seed;
        _range = state.Range;
        _inclusiveRange = state.IsExclusive;
        _random = new Random(_seed);
    }
}
