using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;

public class DynamicConfigManager
{
    private readonly Dictionary<string, string> _config = new();
    private readonly Dictionary<string, DateTime> _cacheExpiration = new();
    private readonly int _maxCacheStalenessHours = 2;
    private readonly int _retryCount = 3;
    private readonly int _backoffIntervalSeconds = 30;

    public DynamicConfigManager(string configServiceUrl)
    {
        _configServiceUrl = configServiceUrl;
    }

    [HttpGet]
    public async Task<Dictionary<string, string>> GetCurrentConfiguration()
    {
        return await GetUpdatedConfiguration();
    }

    private async Task<Dictionary<string, string>> GetUpdatedConfiguration()
    {
        Dictionary<string, string> updatedConfig;

        // Check cache
        if (_config.Any() && DateTime.Now - _cacheExpiration.Values.Min() <= TimeSpan.FromHours(_maxCacheStalenessHours))
        {
            return _config;
        }

        // Retrieve configuration from service
        try
        {
            using (var client = new HttpClient())
            {
                client.BaseAddress = new Uri(_configServiceUrl);
                HttpResponseMessage response = await client.GetAsync("configuration");

                if (response.IsSuccessStatusCode)
                {
                    updatedConfig = JsonConvert.DeserializeObject<Dictionary<string, string>>(await response.Content.ReadAsStringAsync());
                }
                else
                {
                    // Fallback to default settings or previous cached values
                    updatedConfig = _config;
                }
            }
        }
        catch (HttpRequestException ex)
        {
            // Error handling for API failures
            await HandleApiFailure(ex);
        }

        // Update cache and expiration timestamp
        if (updatedConfig.Any())
        {
            _config = updatedConfig;
            _cacheExpiration.Add(DateTime.Now.ToString(), DateTime.Now);
        }

        return updatedConfig;
    }

    private async Task HandleApiFailure(Exception ex)
    {
        // Retry mechanism with configurable backoff intervals and a maximum retry count
        for (int i = 0; i < _retryCount; i++)
        {
            await Task.Delay(TimeSpan.FromSeconds(_backoffIntervalSeconds * Math.Pow(2, i)));
            try
            {
                return await GetUpdatedConfiguration();
            }
            catch (HttpRequestException)
            {
                // Continue retrying
            }
        }

        // Fallback to default settings or previous cached values
        _config = new Dictionary<string, string>();
    }
}
