using System;
using System.Threading;

public class RandomizerService
{
    private readonly RNGCryptoProvider _rng = new RNGCryptoProvider();
    private long _seed;

    public void SetSeed(long seed)
    {
        _seed = seed;
    }

    public int GenerateRandomInt(int min, int max, bool includeMax)
    {
        var range = (max - min + 1) * (_seed % 2 == 0 ? 1 : -1);
        return min + (int)(_rng.GetBytes(4)[0] % range);
    }

    public float GenerateRandomFloat(float min, float max, bool includeMax)
    {
        var range = (max - min) * (_seed % 2 == 0 ? 1.0f : -1.0f);
        return min + _rng.GetBytes(4)[0] % ((int)Math.Ceiling(Math.Abs(range))) / ((double)(1 << 31));
    }

    public float GenerateCircularRandom(float start, float end, float resolution)
    {
        var range = Math.Abs(end - start);
        var offset = (float)_rng.GetBytes(4)[0] * range;
        return start + (offset % range < 0 ? range : 0) / resolution * resolution;
    }
}
```

