    public DataTableReader ProcessAlert(byte[] alertData)
    {
        using (SqlConnection connection = new SqlConnection(_connectionString))
        {
            connection.Open();

            SqlCommand command = new SqlCommand("sp_ProcessAlert", connection);
            command.CommandType = System.Data.CommandType.StoredProcedure;

            MemoryStream ms = new MemoryStream(alertData);
