class SensorReading {
public:
    int id;
    double value;
    std::time_t timestamp;

    SensorReading(int id, double value) : id(id), value(value), timestamp(std::time(nullptr)) {}
};

class DynamicCollection {
private:
    std::vector<SensorReading> readings;
    std::mutex mutex;
    std::condition_variable condVar;
    std::atomic<bool> isStopped(false);

public:
    void addReading(SensorReading reading) {
        std::unique_lock<std::mutex> lock(mutex);
        readings.push_back(reading);
        lock.unlock();
        condVar.notify_one();
    }

    void stop() {
        std::unique_lock<std::mutex> lock(mutex);
        isStopped = true;
        lock.unlock();
        condVar.notify_all();
    }

    void startConsuming() {
        while (!isStopped) {
            SensorReading reading;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condVar.wait(lock, [this]{ return !readings.empty(); });
                if (isStopped) break;
                reading = readings.back();
                readings.pop_back();
            }
            // Process the reading here
        }
    }

};

class DataIngestionPipeline {
public:
    void process(SensorReading reading) {
        // Handle transient failures and partial data ingestion
        // Provide real-time feedback on ingestion status
    }
};

