using System;
using System.Threading;

public class DynamicRandomValueGenerator
{
    private float _minValue;
    private float _maxValue;

    public float MinValue
    {
        get { return _minValue; }
        set
        {
            if (value > MaxValue)
                throw new InvalidOperationException("Minimum value cannot exceed maximum value.");
            _minValue = value;
        }
    }

    public float MaxValue
    {
        get { return _maxValue; }
        set
        {
            if (_minValue > value)
                throw new InvalidOperationException("Maximum value cannot be less than minimum value.");
            _maxValue = value;
        }
    }

    private readonly Random _random;

    public DynamicRandomValueGenerator(long seed = 1)
    {
        ResetSeed(seed);
    }

    public float GetRandomFloatInclusive()
    {
        return _random.NextSingle() * (_maxValue - _minValue) + _minValue;
    }

    public float GetRandomFloatExclusive()
    {
        return (float)(Math.Floor((_maxValue - _minValue) * _random.NextDouble()) + _minValue);
    }

    public int GetRandomIntInclusive()
    {
        return _random.Next((int)_maxValue, (int)(_maxValue + 1));
    }

    public int GetRandomIntExclusive()
    {
        return _random.Next((int)_minValue, (int)_maxValue);
    }

    public void ResetSeed(long seed)
    {
        Interlocked.CompareExchange(ref _random, new Random(seed), null);
    }
}
