using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace RandomValueGenerator
{
    public class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly RNGCryptoServiceProvider _rng;
        private readonly Aes _aes;
        private readonly MD5 _md5;
        private readonly SHA256 _sha256;
        private readonly RSAPrivateKey _rsaPrivateKey;

        public RandomValueGenerator()
        {
            _rng = new RNGCryptoServiceProvider();
            _aes = Aes.Create();
            _md5 = MD5.Create();
            _sha256 = SHA256.Create();
            _rsaPrivateKey = RSA.Create();
        }

        public int GenerateRandomInt(int min, int max, bool exclusive)
        {
            var range = (max - min);
            if (!exclusive) range++;

            var randomBytes = new byte[4];
            _rng.GetBytes(randomBytes);

            var randomValue = BitConverter.ToInt32(randomBytes, 0) % range + (min * (exclusive ? -1 : 1));

            return Math.Min(Math.Max(randomValue, min), max);
        }

        public double GenerateRandomDouble(double min, double max, bool exclusive)
        {
            var range = (max - min);
            if (!exclusive) range++;

            var randomBytes = new byte[8];
            _rng.GetBytes(randomBytes);

            var randomValue = BitConverter.ToDouble(randomBytes, 0);
            randomValue = (randomValue % range) + (min * (exclusive ? -1 : 1));

            return Math.Min(Math.Max(randomValue, min), max);
        }

        public string GenerateRandomString(int length)
        {
            var randomBytes = new byte[length];
            _rng.GetBytes(randomBytes);

            return BitConverter.ToString(randomBytes).Replace("-", "").Substring(0, length);
        }
    }
}
