class DistributedKVStore {
public:
    // Initialize the store with a map to store key-value pairs
    void init(std::map<std::string, std::string> initial_data) {
        data = initial_data;
    }

    // Put a new key-value pair into the store
    void put(const std::string& key, const std::string& value) {
        // Acquire lock to ensure thread safety
        std::unique_lock<std::mutex> lock(mutex);

        // Try to update the data; if it's being written by another node, wait and retry
        while (true) {
            try {
                data[key] = value;
                break;
            } catch (const std::exception& e) {
                // If an exception is thrown, another node has updated the data. Wait and retry.
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::microseconds(100));
                lock.lock();
            }
        }
    }

    // Get a key-value pair from the store
    std::string get(const std::string& key) {
        // Acquire lock to ensure thread safety
        std::unique_lock<std::mutex> lock(mutex);

        // Check if the data is available; if not, wait and retry
        while (true) {
            try {
                return data.at(key);
            } catch (const std::exception& e) {
                // If an exception is thrown, another node has updated the data. Wait and retry.
                lock.unlock();
                std::this_thread::sleep_for(std::chrono::microseconds(100));
                lock.lock();
            }
        }
    }

private:
    std::map<std::string, std::string> data;
    std::mutex mutex;
};

int main() {
