#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Structure to hold network statistics metrics
typedef struct {
    char cell_id[16];
    uint64_t timestamp;
    int priority;
    float value;
} Metric;

// Lock-free data structure for dynamic list of metrics
typedef struct {
    Metric* head;
    Metric* tail;
    pthread_spinlock_t lock;
} MetricsList;

MetricsList metrics_list = {
    NULL,
    NULL,
    PTHREAD_SPINLOCK_INITIALIZER
};

// Function to add a new metric
void add_metric(const char* cell_id, uint64_t timestamp, int priority, float value) {
    Metric* new_metric = (Metric*)malloc(sizeof(Metric));
    strcpy(new_metric->cell_id, cell_id);
    new_metric->timestamp = timestamp;
    new_metric->priority = priority;
    new_metric->value = value;

    pthread_spin_lock(&metrics_list.lock);
    if (!metrics_list.head) {
        metrics_list.head = metrics_list.tail = new_metric;
    } else {
        metrics_list.tail->next = new_metric;
        metrics_list.tail = new_metric;
    }
    pthread_spin_unlock(&metrics_list.lock);
}

// Function to retrieve the latest metric for a given cell
Metric* get_latest_metric(const char* cell_id) {
    Metric* current = metrics_list.head;
    while (current && strcmp(current->cell_id, cell_id)) {
        current = current->next;
    }
    return current;
}

// Function to clear all metrics older than a specified retention period
void clear_old_metrics(uint64_t retention_period) {
    pthread_spin_lock(&metrics_list.lock);
    Metric* current = metrics_list.head;
    while (current) {
        if (current->timestamp < retention_period) {
            Metric* next = current->next;
            free(current);
            current = next;
        } else {
            break;
        }
    }
    if (!current) {
        metrics_list.head = NULL;
        metrics_list.tail = NULL;
    }
    pthread_spin_unlock(&metrics_list.lock);
}

// Function to submit data to the external metrics API
void submit_data() {
    Metric* current = metrics_list.head;
    while (current) {
        // Call the API with the metric's cell_id, timestamp, and value
        printf("Submitting metric: %s, %llu, %.2f\n", current->cell_id, current->timestamp, current->value);
        current = current->next;
    }
}

// Function to periodically submit data to the external metrics API
void* periodic_submission(void* arg) {
    while (1) {
        sleep(5); // Submit data every 5 seconds
        submit_data();
    }
    return NULL;
}

int main() {
    pthread_t submission_thread;

    pthread_create(&submission_thread, NULL, periodic_submission, NULL);

    add_metric("cell-1", 1643723400, 2, 10.5);
    add_metric("cell-2", 1643723410, 3, 12.8);
    add_metric("cell-3", 1643723420, 1, 7.9);

    Metric* latest_metric = get_latest_metric("cell-2");
    printf("Latest metric for cell-2: %s, %llu, %.2f\n", latest_metric->cell_id, latest_metric->timestamp, latest_metric->value);

    clear_old_metrics(1643723450);

    return 0;
}

