    MetricsList* list = (MetricsList*) malloc(sizeof(MetricsList));
    list->metrics = (Metric*) calloc(capacity, sizeof(Metric));
    list->capacity = capacity;
    list->size = 0;
    return list;
}

void add_metric(MetricsList* list, int cell_id, time_t timestamp, int priority) {
    if (list->size >= list->capacity) {
        // Resize the array
        size_t new_capacity = list->capacity * 2;
        Metric* new_metrics = (Metric*) realloc(list->metrics, new_capacity * sizeof(Metric));
        list->metrics = new_metrics;
        list->capacity = new_capacity;
    }
    list->metrics[list->size].cell_id = cell_id;
    list->metrics[list->size].timestamp = timestamp;
    list->metrics[list->size].priority = priority;
    list->size++;
}

Metric* get_latest_metric(MetricsList* list, int cell_id) {
    for (int i = list->size - 1; i >= 0; i--) {
        if (list->metrics[i].cell_id == cell_id) {
            return &list->metrics[i];
        }
    }
    return NULL;
}

void clear_old_metrics(MetricsList* list, time_t retention_period) {
    for (int i = list->size - 1; i >= 0; i--) {
        if (time(NULL) - list->metrics[i].timestamp > retention_period) {
            memmove(&list->metrics[i], &list->metrics[i + 1], (list->size - i - 1) * sizeof(Metric));
            list->size--;
        }
    }
}

