```go
package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"

	"github.com/dgrijak/oauth2"
	"github.com/dgrijak/jwt"
	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
)

// Config holds the API server configuration
type Config struct {
	Port int `json:"port"`
}

// API holds the API server state
type API struct {
	config   *Config
	oauth2   *oauth2.Client
	jwtToken *jwt.Token
}

func NewAPI(config *Config) (*API, error) {
	a := &API{
		config: config,
	}
	return a, nil
}

// Main function to start the server
func main() {
	// Initialize the API with configuration
	cfg := &Config{Port: 8080}
	api, _ := NewAPI(cfg)

	// Create OAuth2 client for third-party providers
	oauth2Client, _ := oauth2.NewClient("provider1", "clientID", "clientSecret")

	// Initialize JWT token
	jwtToken, _ := jwt.NewToken("secretKey", 3600) // 1 hour expiration

	// Define API endpoints
	routes := chi.NewRouter()
	routes.Use(middleware.RequestID)
	routes.Route("/register", func(r chi.Router) {
		r.Post("/", api.registerUser)
	})
	routes.Route("/login", func(r chi.Router) {
		r.Post("/", api.authenticateUser)
	})
	routes.Route("/protected", func(r chi.Router) {
		r.Get("/", api.protectedEndpoint, middleware.Authorize(api.oauth2, api.jwtToken))
	})

	// Start the server
	http.ListenAndServe(fmt.Sprintf(":%d", cfg.Port), routes)
}

func (api *API) registerUser(w http.ResponseWriter, r *http.Request) {
	// Handle user registration logic
	fmt.Fprint(w, "User registered successfully")
}

func (api *API) authenticateUser(w http.ResponseWriter, r *http.Request) {
	// Handle user authentication logic
	fmt.Fprint(w, "User authenticated successfully")
}

func (api *API) protectedEndpoint(w http.ResponseWriter, r *http.Request) {
	// Protected endpoint with JWT and OAuth2 validation
	fmt.Fprint(w, "Protected endpoint accessed")
}
