#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>
#include <vector>
#include <unordered_map>

// Forward declarations
class RNGInstance;
class ExternalSeedAPI;

class RNGInstance {
public:
    RNGInstance(ExternalSeedAPI& externalSeed, int seed);
    void setSeed(int seed) { this->seed = seed; }
    int generateRandomNumber();
private:
    int seed;
    std::mutex mtx;
};

class ExternalSeedAPI {
public:
    virtual ~ExternalSeedAPI() {}
    virtual int getNewSeed() = 0;
};

// Base class for RNG algorithms
class RNGAlgorithm {
public:
    virtual int generateRandomNumber(int seed) = 0;
    virtual ~RNGAlgorithm() {}
};

// Implementation of a simple linear congruential generator (LCG)
class LCG : public RNGAlgorithm {
public:
    int generateRandomNumber(int seed) override {
        return (seed * 1103515245 + 12345) % 2^31;
    }
};

// Implementation of the Mersenne Twister algorithm
class MersenneTwister : public RNGAlgorithm {
