public void ConfigureUserAccountValidation(IConfiguration configuration)
{
    services.Configure<IdentityOptions>(options =>
    {
        options.Password.RequireDigit = configuration["PasswordRequireDigit"];
        options.Password.RequireLowercase = configuration["PasswordRequireLowercase"];
        options.Password.RequireNonAlphanumeric = configuration["PasswordRequireNonAlphanumeric"];
        options.Password.RequireUppercase = configuration["PasswordRequireUppercase"];
        options.Password.RequiredLength = Convert.ToInt32(configuration["PasswordRequiredLength"]);
    });

    services.AddAuthentication(options =>
    {
        options.DefaultAuthenticateScheme = "Identity.Application";
        options.DefaultChallengeScheme = "Identity.Application";
    })
    .AddIdentity<IdentityUser, IdentityRole>(options =>
    {
        options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(5);
        options.Lockout.MaxAttempts = 5;
    });

    services.AddTransient<UserAccountValidator>();
}

public class UserAccountValidator : IValidationService
{
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly UserManager<IdentityUser> _userManager;
    private readonly ILDAPServer _ldapServer;
    private readonly IThirdPartyIdentityProvider _thirdPartyIdentityProvider;
    private readonly ISqlDatabase _sqlDatabase;

    public UserAccountValidator(IHttpContextAccessor httpContextAccessor, 
                                 UserManager<IdentityUser> userManager,
                                 ILDAPServer ldapServer,
                                 IThirdPartyIdentityProvider thirdPartyIdentityProvider,
                                 ISqlDatabase sqlDatabase)
    {
        _httpContextAccessor = httpContextAccessor;
        _userManager = userManager;
        _ldapServer = ldapServer;
        _thirdPartyIdentityProvider = thirdPartyIdentityProvider;
        _sqlDatabase = sqlDatabase;
    }

    public async Task<ValidationResult> ValidateUserAsync(string username, string password)
    {
        var result = new ValidationResult();

        try
        {
            // Perform LDAP validation
            if (!await _ldapServer.ValidateUsernamePassword(username, password))
            {
                result.AddError("LDAP", "Invalid credentials");
            }

            // Perform third-party identity provider validation
            if (!await _thirdPartyIdentityProvider.ValidateUsernamePassword(username, password))
            {
                result.AddError("Third-Party Identity Provider", "Invalid credentials");
            }

            // Perform SQL database validation
            if (!await _sqlDatabase.ValidateUsernamePassword(username, password))
            {
                result.AddError("SQL Database", "Invalid credentials");
            }
        }
        catch (Exception ex)
        {
            result.AddError("Unknown", $"Validation failed: {ex.Message}");
        }

        return result;
    }
}

public class ValidationResult
{
    public List<string> Errors { get; set; } = new List<string>();

    public void AddError(string source, string message)
    {
        Errors.Add($"{source}: {message}");
    }
}

public interface IValidationService
{
    Task<ValidationResult> ValidateUserAsync(string username, string password);
}
