using System;
using System.Xml.Linq;
using System.Threading.Tasks;

namespace XmlParserLib
{
    public class XmlParser
    {
        public async Task<XElement> ParseXmlAsync(string xmlString, string xpathQuery)
        {
            try
            {
                XDocument xmlDoc = XDocument.Parse(xmlString);
                XElement firstMatch = xmlDoc.XPathSelectElements(xpathQuery).FirstOrDefault();

                if (firstMatch == null)
                    throw new Exception("No elements found matching the specified XPath query.");

                return await Task.FromResult(firstMatch);
            }
            catch (Exception ex)
            {
                // Log error and rethrow
                Console.WriteLine($"Error parsing XML: {ex.Message}");
                throw;
            }
        }

        public event EventHandler<XElement> XmlParsed;

        protected virtual void OnXmlParsed(XElement xmlElement)
        {
            XmlParsed?.Invoke(this, xmlElement);
        }
    }
}
