import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import io.swagger.annotations.ApiResponse;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Optional;

@SpringBootApplication
@RestController
@RequestMapping("/users")
@Api(value = "User Profile Management", description = "CRUD operations for managing user profiles")
public class UserProfileService {

    private final UserDAO userDAO;

    public UserProfileService(UserDAO userDAO) {
        this.userDAO = userDAO;
    }

    @GetMapping
    @ApiOperation(value = "Retrieve a list of users", notes = "Returns a list of all registered users")
    @ApiResponse(code = 200, message = "OK", response = List.class)
    public ResponseEntity<List<User>> getUsers() {
        return new ResponseEntity<>(userDAO.findAll(), HttpStatus.OK);
    }

    @GetMapping("/{id}")
    @ApiOperation(value = "Retrieve a user profile", notes = "Returns the specified user's profile")
    @ApiResponse(code = 200, message = "OK", response = User.class)
    public ResponseEntity<User> getUser(@PathVariable Long id) {
        Optional<User> optionalUser = userDAO.findById(id);
        return optionalUser.map(ResponseEntity::ok).orElseGet(() -> new ResponseEntity<>(HttpStatus.NOT_FOUND));
    }

    @PostMapping
    @ApiOperation(value = "Create a new user profile", notes = "Creates a new user profile with provided credentials")
    @ApiResponse(code = 201, message = "Created")
    public ResponseEntity<User> createUser(@RequestBody User user) {
        return new ResponseEntity<>(userDAO.save(user), HttpStatus.CREATED);
    }

    @PutMapping("/{id}")
    @ApiOperation(value = "Update an existing user profile", notes = "Updates the specified user's profile with provided credentials")
    @ApiResponse(code = 200, message = "OK")
    public ResponseEntity<User> updateUser(@PathVariable Long id, @RequestBody User user) {
        Optional<User> optionalUser = userDAO.findById(id);
        if (optionalUser.isPresent()) {
            User updatedUser = optionalUser.get().patch(user);
            return new ResponseEntity<>(userDAO.save(updatedUser), HttpStatus.OK);
        } else {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
    }

    @DeleteMapping("/{id}")
    @ApiOperation(value = "Remove a user profile", notes = "Removes the specified user's profile")
    @ApiResponse(code = 200, message = "OK")
    public ResponseEntity<HttpStatus> deleteUser(@PathVariable Long id) {
        userDAO.deleteById(id);
        return new ResponseEntity<>(HttpStatus.OK);
    }

}
