function processUserOperation() {
    $request = $_REQUEST;
    $operationId = $request['id'];
    $subAction = $request['sub_action'];

    switch ($subAction) {
        case 'create':
            return createUser($request);
        case 'update':
            return updateUser($request, $operationId);
        case 'delete':
            return deleteUser($request, $operationId);
        case 'retrieve':
            return retrieveUser($request, $operationId);
        default:
            return json_encode(array('status' => 'error', 'message' => 'Invalid sub_action'));
    }
