function createUser($request) {
    // Validate and hash password
    if (!validatePassword($request['password'])) {
        return json_encode(array('status' => 'error', 'message' => 'Invalid password'));
    }

    $db = connectToDB();
    try {
        $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
        $stmt->execute(array(':name' => $request['name'], ':email' => $request['email'], ':password' => hashPassword($request['password'])));
        return json_encode(array('status' => 'success', 'message' => 'User created successfully'));
