class DynamicRandomValueGenerator:
    def __init__(self):
        self.thread_local = threading.local()

    def generate_random_value(self, min_value: float, max_value: float, inclusive: bool = False) -> float:
        if not hasattr(self.thread_local, 'random_state'):
            self.thread_local.random_state = random.getstate()
        try:
            if inclusive:
                return random.uniform(min_value, max_value)
            else:
                return random.randint(int(min_value), int(max_value))
