function renderDynamicGrid(items) {
  // Data Validation and Sanitization
  items = items.filter((item) => {
    const isValid = item.id && item.text;
    if (!isValid) console.error('Invalid item:', item);
    return isValid;
  });

  for (const item of items) {
    if (item.width < 1 || item.height < 1) {
      console.error('Invalid dimensions:', item);
      continue;
    }
    if (typeof item.text !== 'string') {
      console.error('Invalid text type:', item);
      continue;
    }
    const sanitizedText = sanitizeHTML(item.text); // implement sanitization function
    item.text = sanitizedText;
  }

  // Responsive Grid Layout
  const gridContainer = document.createElement('div');
  gridContainer.style.display = 'grid';
  gridContainer.style.gridTemplateColumns = 'repeat(auto-fill, minmax(200px, 1fr))'; // adjust grid column width based on available space

  for (const item of items) {
    const gridCell = document.createElement('div');
    gridCell.style.gridColumnStart = Math.floor(Math.random() * 5); // randomly assign a starting grid column
    if (item.image_url) {
      fetchImage(item.image_url).then((image) => {
        gridCell.innerHTML = `<img src="${image}" alt="item image">`;
      });
    } else {
      gridCell.textContent = item.text;
    }
    gridContainer.appendChild(gridCell);
  }

  document.body.appendChild(gridContainer);

  // Advanced Responsive Design
  function handleResize() {
    const gridSize = getComputedStyle(gridContainer).gridTemplateColumns;
    if (gridSize.includes('auto-fill')) {
      const newGridSize = `repeat(${Math.floor(Math.max(...items.map((item) => item.width)) / 200)}, minmax(200px, 1fr))`;
      gridContainer.style.gridTemplateColumns = newGridSize;
    }
  }

  window.addEventListener('resize', handleResize);

