using System.Threading.Tasks;

namespace DynamicDataGenerator
{
    public class DynamicDataGenerator
    {
        private readonly Random _random = new Random();
        private readonly Dictionary<int, (int Min, int Max)> _integerRanges = new Dictionary<int, (int Min, int Max)>();
        private readonly Dictionary<double, (double Min, double Max)> _floatRanges = new Dictionary<double, (double Min, double Max)>();

        public void AddIntegerRange(int typeId, int min, int max)
        {
            _integerRanges.Add(typeId, (min, max));
        }

        public void AddFloatRange(double typeId, double min, double max)
        {
            _floatRanges.Add(typeId, (min, max));
        }

        public async Task<int> GenerateIntegerAsync(int typeId)
        {
            var (min, max) = _integerRanges[typeId];
            return await Task.Run(() => _random.Next(min, max + 1));
        }

        public async Task<double> GenerateFloatAsync(double typeId)
        {
            var (min, max) = _floatRanges[typeId];
            return await Task.Run(() => _random.NextDouble() * (max - min) + min);
        }

        public async Task<int[]> GenerateIntegerSequenceAsync(int typeId, int count)
        {
            var (min, max) = _integerRanges[typeId];
            var sequence = new List<int>();

            for (int i = 0; i < count; i++)
            {
                while (true)
                {
                    int value = await GenerateIntegerAsync(typeId);
                    if (!sequence.Contains(value))
                    {
                        sequence.Add(value);
                        break;
                    }
                }
            }

            return sequence.ToArray();
        }

        public async Task<double[]> GenerateFloatSequenceAsync(double typeId, int count)
        {
            var (min, max) = _floatRanges[typeId];
            var sequence = new List<double>();

            for (int i = 0; i < count; i++)
            {
                while (true)
                {
                    double value = await GenerateFloatAsync(typeId);
                    if (!sequence.Contains(value))
                    {
                        sequence.Add(value);
                        break;
                    }
                }
            }

            return sequence.ToArray();
        }
    }
}
