                                "ports": [{"containerPort": 8080}]
                            }
                        ]
                    }
                }
            }
        }))

    # Apply deployment YAML file to k8s cluster
    subprocess.run(["kubectl", "apply", "-f", "deployment.yaml"])

    # Wait for deployment to complete
    while True:
        try:
            deployment_status = subprocess.check_output(["kubectl", "get", "deployment", "logging-library", "-o", "yaml"])
            if deployment_status.decode().startswith("status:"):
