using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using StackExchange.Redis;

namespace DynamicTokenManager
{
    public class TokenManager : ITokenManager
    {
        private readonly ILogger<TokenManager> _logger;
        private readonly IConfiguration _config;
        private readonly IDatabase _redis;

        public TokenManager(ILogger<TokenManager> logger, IConfiguration config, IConnectionMultiplexer redis)
        {
            _logger = logger;
            _config = config;
            _redis = redis.GetDatabase();
        }

        public async Task<string> GenerateTokenAsync(string username, string audience, string issuer)
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            var tokenDescriptor = new SecurityTokenDescriptor
            {
                Audience = audience,
                Issuer = issuer,
                Expires = DateTime.UtcNow.AddMinutes(int.Parse(_config["TokenExpiration"])),
                SigningCredentials = new SigningCredentials(new SymmetricSecurityKey Convert.FromBase64String(_config["TokenSigningKey"])), 
                Claims = new[] 
                { 
                    new Claim(ClaimTypes.Name, username), 
                    new Claim(JwtRegisteredClaimNames.Audience, audience), 
                    new Claim(JwtRegisteredClaimNames.Issuer, issuer) 
                }
            };

            var token = tokenHandler.CreateToken(tokenDescriptor);
            return tokenHandler.WriteToken(token);
        }

        public async Task<string> ValidateAndRefreshTokenAsync(string oldToken)
        {
            try
            {
                var jwtSecurityToken = (JwtSecurityToken)(await ValidateTokenAsync(oldToken));
                var newToken = await GenerateTokenAsync(jwtSecurityToken.Claims.FirstOrDefault(c => c.Type == ClaimTypes.Name).Value, jwtSecurityToken.Audience, jwtSecurityToken.Issuer);
                return newToken;
            }
            catch
            {
                throw new Exception("Invalid token");
            }
        }

        public async Task<bool> ValidateTokenAsync(string token)
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            try
            {
                var validatingRequest = new Microsoft.AspNetCore.Authentication.JwtBearerJwtSecurityTokenValidatingRequest(token);
                await _config.GetSettings().ValidationContext.ValidateToken(validatingRequest, out var validatedToken);
                return true;
            }
            catch
            {
                return false;
            }
        }

        public async Task<string> GetTokenAsync(string token)
        {
            try
            {
                var cacheKey = $"token:{token}";
                var cachedValue = await _redis.StringGetAsync(cacheKey);

                if (cachedValue.HasValue)
                {
                    return cachedValue;
                }
                else
                {
                    await _redis.StringSetAsync(cacheKey, token, TimeSpan.FromMinutes(int.Parse(_config["TokenExpiration"])));
                    return token;
                }
            }
            catch
            {
                throw new Exception("Failed to get token from Redis");
            }
        }

        public async Task InvalidateTokenAsync(string token)
        {
            try
            {
                var cacheKey = $"token:{token}";
                await _redis.StringDeleteAsync(cacheKey);
            }
            catch
            {
                throw new Exception("Failed to invalidate token in Redis");
            }
        }
    }
}
```']

