        public int GenerateFromCustomDistribution(IConfigurationSection section)
        {
            // Parse and normalize custom distribution configuration
            var min = int.Parse(section["min"]);
            var max = int.Parse(section["max"]);

            // Validate range and throw exception if invalid
            if (!ValidateRange(min, max))
            {
                return -1; // or throw an exception
            }

            // Simulate concurrent access using a lock
            lock (_lock)
            {
                return _random.Next(min, max + 1);
            }
        }

        public override string ToString()
        {
            return $"RandomValueGenerator (Range: {0} - {1})";
