// Define the structure for a network statistics metric
typedef struct {
    char cell_id[20];
    time_t timestamp;
    double value;
} Metric;

// Define the structure for the dynamic list of metrics
typedef struct {
    int size;
    Metric* data;
} MetricList;

// Initialize the metric list with default values
MetricList* init_metric_list() {
    MetricList* ml = (MetricList*)malloc(sizeof(MetricList));
    ml->size = 0;
    ml->data = NULL;
    return ml;
}

// Add a new metric to the list
void add_metric(MetricList* ml, char cell_id[], time_t timestamp, double value) {
    // Dynamically allocate memory for the new metric
    Metric* new_metric = (Metric*)malloc(sizeof(Metric));
    strcpy(new_metric->cell_id, cell_id);
    new_metric->timestamp = timestamp;
    new_metric->value = value;

    // Resize the existing list if necessary
    if (ml->size >= ml->data) {
        int new_size = ml->size * 2 + 1;
        Metric* new_data = (Metric*)malloc(new_size * sizeof(Metric));
        memcpy(new_data, ml->data, ml->size * sizeof(Metric));
        free(ml->data);
        ml->data = new_data;
    }

    // Insert the new metric at the end of the list
    ml->data[ml->size] = *new_metric;
    ml->size++;
}

// Update an existing metric in the list
void update_metric(MetricList* ml, char cell_id[], time_t timestamp, double value) {
    for (int i = 0; i < ml->size; i++) {
