#include <iostream>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <vector>

class DistributedKeyValueStore {
public:
    DistributedKeyValueStore(size_t numNodes) : nodes(numNodes), mutex(), cv() {}

    void put(const std::string& key, const std::string& value) {
        for (size_t i = 0; i < nodes.size(); ++i) {
            if (!nodes[i]->isAvailable()) continue;
            auto node = nodes[i];
            std::unique_lock<std::mutex> lock(node->mutex);
            while (!node->isReady()) {
                cv.wait(lock);
            }
            node->setValue(key, value);
        }
    }

    std::string get(const std::string& key) {
        for (size_t i = 0; i < nodes.size(); ++i) {
            if (!nodes[i]->isAvailable()) continue;
            auto node = nodes[i];
            std::unique_lock<std::mutex> lock(node->mutex);
            while (!node->isReady()) {
                cv.wait(lock);
            }
            return node->getValue(key);
        }
        return "";
    }

private:
    class Node {
    public:
        Node(size_t id) : id(id), valueMap(), mutex(), cv() {}
        bool isAvailable() const { return available; }
        void setAvailable(bool b) { available = b; }
        bool isReady() const { return ready; }
        void setReady(bool b) { ready = b; }
        std::unique_lock<std::mutex> lock() { return std::unique_lock<std::mutex>(mutex); }

        void setValue(const std::string& key, const std::string& value) {
            valueMap[key] = value;
            cv.notify_one();
        }

        std::string getValue(const std::string& key) {
            if (valueMap.find(key) != valueMap.end()) {
                return valueMap.at(key);
            }
            return "";
        }

    private:
        size_t id;
        std::map<std::string, std::string> valueMap;
        bool available = true;
        bool ready = false;
        std::mutex mutex;
        std::condition_variable cv;
    };

    std::vector<Node*> nodes;
};

int main() {
    DistributedKeyValueStore store(5);
    // use the library
    return 0;
}
