        self.log_queue.put(event)

    def process_log_events(self):
        while True:
            if not self.log_queue.empty():
                events = [self.log_queue.get() for _ in range(min(100, self.log_queue.qsize()))]
                try:
                    for event in events:
                        # Send log events to the MAS
                        send_to_mas(event)
                    self.rotate_buffer()
                except Exception as e:
                    self.logger.error(f"Error processing logs: {e}")
            time.sleep(0.1)

    def rotate_buffer(self):
        if len(self.rotation_buffer) >= self.buffer_size / 2:
            self.write_rotation_file()
            self.rotation_buffer.clear()

