bool validateOAuth2Token(const std::string& jsonResp) {
    Json::Value root;
    try {
        root = Json::parse(jsonResp);
    } catch (Json::Exception& e) {
        return false; // invalid JSON
    }

    if (!root.isObject()) {
        return false; // not an object
    }

    const std::string accessToken = root["access_token"].asString();
    int expiresIn = root["expires_in"].asInt();
    const std::string tokenType = root["token_type"].asString();

    if (accessToken.empty() || tokenType != "Bearer" || expiresIn <= 0) {
        return false; // invalid or missing fields
    }

    return true;
}

