```
using System;
using System.Text.Json;

public class OAuth2TokenValidator
{
    public bool ValidateToken(string token)
    {
        if (string.IsNullOrEmpty(token)) return false;

        var json = JsonSerializer.Deserialize<OAuth2Token>(token);

        if (!json.AccessToken.HasValue || !json.ExpiresIn.HasValue ||
            string.Compare(json.TokenType, "Bearer", StringComparison.OrdinalIgnoreCase) != 0)
        {
            return false;
        }

        if (json.ExpiresIn.Value <= 0) return false;

        if (string.IsNullOrEmpty(json.RefreshToken)) return true; // optional

        return true;
    }
}

public class OAuth2Token
{
    public int? ExpiresIn { get; set; }
    public string TokenType { get; set; }
    public string AccessToken { get; set; }
    public string RefreshToken { get; set; }
}
