using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using OidcClient;

namespace MicroserviceAuth
{
    public class Startup
    {
        public Startup(IConfiguration configuration)
        {
            Configuration = configuration;
        }

        public IConfiguration Configuration { get; }

        // This method gets called by the runtime. Use this method to add services to the container.
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = "Bearer";
                options.DefaultChallengeScheme = "Bearer";
            })
            .AddJwtBearer(options =>
            {
                options.Audience = "https://your-audience.com";
                options.Authority = "https://your-authority.com";
                options.TokenValidationParameters = new TokenValidationParameters
                {
                    ValidateIssuer = true,
                    ValidIssuer = "https://your-issuer.com",
                    ValidateAudience = true,
                    ValidAudience = "https://your-audience.com"
                };
            })
            .AddOpenIdConnect(options =>
            {
                options.Authority = "https://your-authority.com";
                options.ClientId = "your-client-id";
                options.ClientSecret = "your-client-secret";
                options.RedirectUri = "https://your-redirect-uri.com";
                options.ResponseType = "code";
                options.Scope.Add("profile");
                options.Scope.Add("email");
            });

            services.AddAuthorization(options =>
            {
                options.AddPolicy("RequireRole", policy => policy.RequireClaim(ClaimTypes.Role));
            });

            services.AddControllers();

            // Custom cache
            services.AddSingleton<ICache>(provider => new DistributedCache(provider));

            // Custom load balancer
            services.AddSingleton<IHostedService>(provider => new LoadBalancer());

            // Custom adapter framework for new identity providers
            services.AddTransient<IApiAdapter, GoogleApiAdapter>();
            services.AddTransient<IApiAdapter, FacebookApiAdapter>();

            services.AddHealthChecks()
                .AddRabbitMq("rabbitmq://guest:guest@localhost")
                .SetTags("rabbitmq");
        }

        // This method gets called by the runtime. Use this method to configure the HTTP request pipeline.
        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
            }

            app.UseRouting();

            app.UseAuthentication();
            app.UseAuthorization();

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }
}
