const { readFileSync } = require('fs');
const crypto = require('crypto');
const childProcess = require('child_process');
const path = require('path');

class ConfigManager {
  constructor() {
    this.configFile = 'config.json';
    this.placeholderRegex = /__([a-zA-Z0-9_]+)__/g;
    this.passwordAlgorithm = 'aes-256-cbc';
    this.logger = console.log.bind(console);
  }

  async replacePlaceholders(config, values) {
    for (const [placeholder, value] of Object.entries(values)) {
      config = config.replace(this.placeholderRegex, value);
    }
    return config;
  }

  async encryptPassword(password, salt) {
    const cipher = crypto.createCipher(this.passwordAlgorithm, salt);
    let encrypted = '';
    while ((encrypted += cipher.update(password, 'utf8', 'hex')) && cipher.finish() === false) {}
    return { algorithm: this.passwordAlgorithm, value: encrypted };
  }

  async generateSalt() {
    return crypto.randomBytes(16).toString('hex');
  }

  async encryptConfig(config, salt) {
    const cipher = crypto.createCipher(this.passwordAlgorithm, salt);
    let encrypted = '';
    while ((encrypted += cipher.update(JSON.stringify(config), 'utf8', 'hex')) && cipher.finish() === false) {}
    return { algorithm: this.passwordAlgorithm, value: encrypted };
  }

  async loadConfig(filename) {
    try {
      const config = JSON.parse(readFileSync(filename, 'utf8'));
      return config;
