import os
import logging
from cryptography.fernet import Fernet
from flask import Flask, request, jsonify
from flask_cors import cross_origin
from kafka import KafkaProducer
from redis import StrictRedis

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)
redis_client = StrictRedis(host='localhost', port=6379, db=0)

# Define encryption/decryption functions using Fernet
fernet_key = Fernet.generate_key()
encryption_key = Fernet(fernet_key)
decryption_key = Fernet(fernet_key)

@app.route('/process_file', methods=['POST'])
@cross_origin(origin='*', headers=['Content-Type'])
def process_file():
    try:
        file_path = request.json['file_path']
        command = request.json['command']

        # Sanitize and validate the command
        sanitized_command = sanitize_command(command)

        # Encrypt the command using Fernet
        encrypted_command = encryption_key.encrypt(sanitized_command.encode())

        # Send the encrypted command to Kafka for processing
        producer = KafkaProducer(bootstrap_servers=['localhost:9092'])
        producer.send('file_processing', value=encrypted_command, key=file_path)

        return jsonify({'message': 'File processed successfully'})
    except Exception as e:
        logging.error(f'Error processing file: {str(e)}')
        return jsonify({'error': str(e)})

@app.route('/get_file_status', methods=['GET'])
@cross_origin(origin='*', headers=['Content-Type'])
def get_file_status():
    try:
        file_path = request.args.get('file_path')

        # Get the file status from Redis
        file_status = redis_client.hgetall(file_path)

        return jsonify({'status': file_status})
    except Exception as e:
        logging.error(f'Error getting file status: {str(e)}')
        return jsonify({'error': str(e)})

@app.route('/shutdown', methods=['POST'])
@cross_origin(origin='*', headers=['Content-Type'])
def shutdown():
    try:
        # Shutdown the service
        app.shutdown()

        return jsonify({'message': 'Service shut down successfully'})
    except Exception as e:
        logging.error(f'Error shutting down service: {str(e)}')
        return jsonify({'error': str(e)})

if __name__ == '__main__':
    app.run(debug=True)
```

