use tracing::{info, warn};

struct CloudStorage {
    api_key: String,
    api_secret: String,
    bucket_name: String,
}

impl CloudStorage {
    async fn new(api_key: &str, api_secret: &str, bucket_name: &str) -> Result<Self, reqwest::Error> {
        Ok(CloudStorage {
            api_key: api_key.to_string(),
            api_secret: api_secret.to_string(),
            bucket_name: bucket_name.to_string(),
        })
    }

    async fn upload_file(&self, file_path: &PathBuf, object_key: &str) -> Result<(), reqwest::Error> {
        let client = reqwest::Client::new();
        let url = format!("https://example.com/{}/{}/{}", self.api_key, self.bucket_name, object_key);
        let file_content = tokio::fs::read_dir(file_path).await.unwrap().next().unwrap().unwrap();
        client.put(&url).send().await?;
        Ok(())
    }

    async fn get_file(&self, object_key: &str) -> Result<String, reqwest::Error> {
        let client = reqwest::Client::new();
        let url = format!("https://example.com/{}/{}/{}", self.api_key, self.bucket_name, object_key);
        let response = client.get(url).send().await?;
        if response.status() == 404 {
            warn!("File not found");
            return Ok("".to_string());
        }
        let content = response.text().await?;
        Ok(content)
    }

    async fn delete_file(&self, object_key: &str) -> Result<(), reqwest::Error> {
        let client = reqwest::Client::new();
        let url = format!("https://example.com/{}/{}/{}", self.api_key, self.bucket_name, object_key);
        client.delete(url).send().await?;
        Ok(())
    }
}

