// Modular library implementation
void manage_user_profiles(int user_id, UserProfile* profile) {
    // Check if the user exists in local cache
    int is_local = 0;
    for (int i = 0; i < PROFILE_CACHE_SIZE; i++) {
        if (strcmp(profiles[i].username, profile->username) == 0) {
            is_local = 1;
            break;
        }
    }

    // If not local, fetch from cloud DB and IDP
    if (!is_local) {
        int cloud_db_status = cloud_db_connect(username, password);
        if (cloud_db_status != 0) {
            printf("Cloud DB connection failed\n");
            return;
        }

        int idp_status = idp_authenticate(username, password);
        if (idp_status != 0) {
            printf("IDP authentication failed\n");
            return;
        }
    }

    // Update local cache
    for (int i = 0; i < PROFILE_CACHE_SIZE; i++) {
        if (profiles[i].user_id == user_id) {
            strcpy(profiles[i].username, profile->username);
            strcpy(profiles[i].password, profile->password);
            profiles[i].user_id = user_id;
            break;
        }
    }

    // Evict least recently used profile
    for (int i = 0; i < PROFILE_CACHE_SIZE - 1; i++) {
        profiles[i] = profiles[i + 1];
    }
}

// Cache management function
void cache_profile(UserProfile* profile) {
    // Check if the profile already exists in local cache
    int is_local = 0;
    for (int i = 0; i < PROFILE_CACHE_SIZE; i++) {
        if (strcmp(profiles[i].username, profile->username) == 0) {
            is_local = 1;
            break;
        }
    }

    // If not local, add to cache and evict least recently used
    if (!is_local) {
        for (int i = PROFILE_CACHE_SIZE - 1; i > 0; i--) {
            profiles[i] = profiles[i - 1];
        }
        strcpy(profiles[0].username, profile->username);
        strcpy(profiles[0].password, profile->password);
        profiles[0].user_id = profile->user_id;
    }
}

