// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for the dynamic array
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int capacity;
    int size;
} DynamicArray;

// Function to create a new dynamic array
DynamicArray* create_dynamic_array(int initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->elements = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->capacity = initial_capacity;
    arr->size = 0;
    return arr;
}

// Function to insert an element into the dynamic array
void insert_element(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    if (arr->size == arr->capacity) {
        // Resize the array if it's full
        int new_capacity = arr->capacity * 2;
        arr->elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arr->capacity = new_capacity;
    }
    arr->elements[arr->size] = element;
    arr->size++;
}

// Function to remove an element from the dynamic array
void remove_element(DynamicArray* arr) {
    if (arr->size > 0) {
        // Shift all elements down by one position and free the last element
        for (int i = 1; i < arr->size; i++) {
            arr->elements[i - 1] = arr->elements[i];
        }
        arr->size--;
    }
}

// Function to print the dynamic array contents
void print_array(DynamicArray* arr) {
    for (int i = 0; i < arr->size; i++) {
        printf("Element %d: %p\n", i, &arr->elements[i]);
    }
}

// Function to serialize the dynamic array to a file
void serialize_array_to_file(DynamicArray* arr, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        for (int i = 0; i < arr->size; i++) {
            fwrite(&arr->elements[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        }
        fclose(file);
    } else {
        // Handle error
    }
}

// Function to deserialize the dynamic array from a file
DynamicArray* deserialize_array_from_file(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        DynamicArray* arr = create_dynamic_array(10);
        int element_count;
        fread(&element_count, sizeof(int), 1, file);
        for (int i = 0; i < element_count; i++) {
            NFAPI_CRC_INDICATION_PDU_T element;
            fread(&element, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
            insert_element(arr, element);
        }
        fclose(file);
        return arr;
    } else {
        // Handle error
    }
}

// Function to print a meaningful error message and log the critical event
void handle_error(const char* message) {
    printf("%s\n", message);
    // Log the error using a centralized logging framework
}

int main() {
    DynamicArray* arr = create_dynamic_array(5);

    // Insert elements into the array
    NFAPI_CRC_INDICATION_PDU_T element1;
    // ...
    NFAPI_CRC_INDICATION_PDU_T element2;
    insert_element(arr, element1);
    insert_element(arr, element2);

    // Remove an element from the array
    remove_element(arr);

    // Serialize the array to a file
    serialize_array_to_file(arr, "array.bin");

    // Deserialize the array from a file
    DynamicArray* deserialized_arr = deserialize_array_from_file("array.bin");

    // Print the array contents
    print_array(deserialized_arr);

    return 0;
}
