def compute_md5(file_path):
    with open(file_path, 'rb') as file:
        md5_hash = hashlib.md5(file.read()).hexdigest()
    return md5_hash

def monitor_directory(directory_path, filter_file_types=None, filter_paths=None):
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            if filter_file_types and not any(filter_file_type.lower() in file.lower() for filter_file_type in filter_file_types):
                continue
            if filter_paths and any(filter_path in root for filter_path in filter_paths):
                continue
            file_path = os.path.join(root, file)
            md5_hash = compute_md5(file_path)
            logging_service.info(f"Modified file: {file_path} - MD5 Hash: {md5_hash}")
    return

if __name__ == "__main__":
    # Configure logging settings
    logging.basicConfig(level=logging.INFO)

    # Monitor directory and log changes
    monitor_directory('/path/to/directory', filter_file_types=['.txt'], filter_paths ['/path/to/exclude'])
