#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

#define N 1000 // Maximum number of elements in the dynamic array

typedef struct {
    int field1;
    char field2[10];
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic array structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data[N];
    int size; // Current size of the array
    int capacity; // Maximum size of the array
} DynamicArray;

// Initialize the dynamic array with a given initial capacity
DynamicArray* init_dynamic_array(int capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    arr->data = (NFAPI_CRC_INDICATION_PDU_T**)malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    arr->size = 0;
    arr->capacity = capacity;
    return arr;
}

// Free the dynamic array
void free_dynamic_array(DynamicArray* arr) {
    if (arr != NULL) {
        for (int i = 0; i < arr->size; i++) {
            if (arr->data[i] != NULL)
                free(arr->data[i]);
        }
        free(arr->data);
        free(arr);
    }
}

// Resize the dynamic array to a new capacity
void resize_dynamic_array(DynamicArray* arr, int new_capacity) {
    DynamicArray* temp = init_dynamic_array(new_capacity);
    for (int i = 0; i < arr->size; i++) {
        temp->data[i] = arr->data[i];
    }
    free(arr->data);
    arr->data = temp->data;
    arr->capacity = new_capacity;
    free(temp);
}

// Insert an element into the dynamic array
int insert_dynamic_array(DynamicArray* arr, NFAPI_CRC_INDICATION_PDU_T* elem) {
    if (arr->size == arr->capacity) {
        resize_dynamic_array(arr, arr->capacity * 2 + 1); // Double the capacity and add 1 for growth
    }
    arr->data[arr->size++] = elem;
    return arr->size - 1; // Return the index of the inserted element
}

// Remove an element from the dynamic array
void remove_dynamic_array(DynamicArray* arr, int index) {
    if (index >= 0 && index < arr->size) {
        for (int i = index; i < arr->size - 1; i++) {
            arr->data[i] = arr->data[i + 1];
        }
        free(arr->data[arr->size - 1]);
        arr->size--;
    }
}

// Serialize the dynamic array to a file
void serialize_dynamic_array(DynamicArray* arr, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file != NULL) {
        for (int i = 0; i < arr->size; i++) {
            fwrite(&arr->data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        }
        fclose(file);
    } else {
        printf("Error: Unable to open file %s for serialization.\n", filename);
    }
}

// Deserialize the dynamic array from a file
DynamicArray* deserialize_dynamic_array(const char* filename) {
    DynamicArray* arr = NULL;
    FILE* file = fopen(filename, "rb");
    if (file != NULL) {
        int size = 0;
        fread(&size, sizeof(int), 1, file);
        arr = init_dynamic_array(size);
        for (int i = 0; i < size; i++) {
            NFAPI_CRC_INDICATION_PDU_T* elem = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            fread(elem, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
            arr->data[i] = elem;
        }
        fclose(file);
    } else {
        printf("Error: Unable to open file %s for deserialization.\n", filename);
    }
    return arr;
}

// Main function
int main() {
    // Initialize the dynamic array with an initial capacity of 100
    DynamicArray* arr = init_dynamic_array(100);

    // Insert elements into the dynamic array
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* elem = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        // Initialize the element fields
        elem->field1 = i;
        strcpy(elem->field2, "Field 2 value");
        int index = insert_dynamic_array(arr, elem);
        printf("Inserted element at index %d.\n", index);
    }

    // Remove elements from the dynamic array
    for (int i = arr->size - 1; i >= 0; i--) {
        remove_dynamic_array(arr, i);
    }

    // Serialize the dynamic array to a file
    serialize_dynamic_array(arr, "dynamic_array.dat");

    // Deserialize the dynamic array from the file
    DynamicArray* deserialized_arr = deserialize_dynamic_array("dynamic_array.dat");
    free_dynamic_array(deserialized_arr);

    return 0;
}
```

