    std::mutex lock;
    std::condition_variable cv;

public:
    void addResponse(HTTP_RESPONSE_PDU* response) {
        {
            std::unique_lock<std::mutex> uniqueLock(lock);
            responses.push_back(response);
        }
        cv.notify_one();
    }

    void processResponses() {
        while (true) {
            HTTP_RESPONSE_PDU* response = nullptr;
            {
                std::unique_lock<std::mutex> uniqueLock(lock);
                if (!responses.empty()) {
                    response = responses.front();
                    responses.pop_front();
                } else {
                    cv.wait(uniqueLock);
                }
            }

            if (response != nullptr) {
                // Process the response
                std::cout << "Processed response: " << response->STATUS_CODE << std::endl;
            }
        }
    }
};

