// Structure to represent a device status update
typedef struct {
    char *deviceId;
    int signalStrength;
    time_t timestamp;
} DeviceStatus;

// Hash table to store device status updates
typedef struct {
    int capacity;
    int size;
    struct DeviceStatus **devices;
} DeviceStatusHash;

DeviceStatusHash *deviceStatusInit(int capacity) {
    DeviceStatusHash *hash = malloc(sizeof(DeviceStatusHash));
    hash->capacity = capacity;
    hash->size = 0;
    hash->devices = (struct DeviceStatus **)malloc(capacity * sizeof(struct DeviceStatus *));
    return hash;
}

void deviceStatusAdd(DeviceStatusHash *hash, char *deviceId, int signalStrength) {
    // Hash function to determine the index for the given deviceId
    int index = (int)deviceId[0];
    if (!hash->devices[index]) {
        hash->size++;
        hash->devices[index] = malloc(sizeof(struct DeviceStatus));
        strcpy(hash->devices[index]->deviceId, deviceId);
        hash->devices[index]->signalStrength = signalStrength;
        hash->devices[index]->timestamp = time(NULL);
    } else {
        // Update existing device status
        strcpy(hash->devices[index]->deviceId, deviceId);
        hash->devices[index]->signalStrength = signalStrength;
        hash->devices[index]->timestamp = time(NULL);
    }
}

void deviceStatusUpdate(DeviceStatusHash *hash, char *deviceId, int signalStrength) {
    // Find the device in the hash table
    for (int i = 0; i < hash->capacity; i++) {
        if (!hash->devices[i]) continue;
        if (strcmp(hash->devices[i]->deviceId, deviceId) == 0) {
            hash->devices[i]->signalStrength = signalStrength;
            hash->devices[i]->timestamp = time(NULL);
            return;
        }
    }
}

void deviceStatusGet(DeviceStatusHash *hash, char *deviceId, DeviceStatus **status) {
    // Find the device in the hash table
    for (int i = 0; i < hash->capacity; i++) {
        if (!hash->devices[i]) continue;
        if (strcmp(hash->devices[i]->deviceId, deviceId) == 0) {
            *status = hash->devices[i];
            return;
        }
    }
}

void deviceStatusDestroy(DeviceStatusHash *hash) {
    for (int i = 0; i < hash->capacity; i++) {
        free(hash->devices[i]);
    }
    free(hash->devices);
    free(hash);
}
