```javascript
const { spawn } = require('child_process');
const express = require('express');

app = express();

// Define the API endpoint for executing shell commands
app.get('/execute', (req, res) => {
    const command = req.query.command;
    if (!command) return res.status(400).send({ message: 'Missing command' });

    // Execute the shell command using child_process.spawn()
    spawn(command, (error, stdout, stderr) => {
        if (error) {
            return res.status(500).send({ message: `Error executing command: ${error}` });
        }
        res.send(stdout);
    });
});

// Define API endpoint for inspecting logs
