    db->metrics = (Metric*)realloc(db->metrics, sizeof(Metric) * (db->count + 1));
    db->metrics[db->count] = *new_metric;
    db->count++;
    pthread_mutex_unlock(&db->lock);
}

int get_metric_count(MetricsDB* db) {
    return db->count;
}

void clear_old_metrics(MetricsDB* db, int current_timestamp) {
    for (int i = 0; i < db->count; i++) {
        if (current_timestamp - db->metrics[i].timestamp > db->retention_period) {
            free(db->metrics[i]);
            memmove(&db->metrics[i], &db->metrics[i+1], sizeof(Metric) * (db->count - i - 1));
            db->count--;
