ServiceState service_state = SERVICE_STOPPED;
int next_interface_id = 0;
pthread_mutex_t service_mutex;
sem_t start_service_sem;

void* service_thread_func(void* arg) {
    while (1) {
        int delay = rand() % 10000 + 1; // configurable delay range
        sleep(delay);
        pthread_mutex_lock(&service_mutex);
        if (service_state == SERVICE_RUNNING) {
            service_state = SERVICE_STOPPING;
            printf("Service stopping...\n");
            pthread_cond_signal(&start_service_sem); // signal start service
        } else {
            service_state = SERVICE_STARTING;
            printf("Service starting...\n");
        }
        pthread_mutex_unlock(&service_mutex);
    }
}

void start_service() {
    if (service_state == SERVICE_STOPPED) {
        pthread_mutex_lock(&service_mutex);
        if (sem_wait(&start_service_sem) == 0) { // block until service is stopped
            printf("Service started...\n");
            service_state = SERVICE_RUNNING;
        } else {
            printf("Error starting service...\n");
        }
        pthread_mutex_unlock(&service_mutex);
    }
}

void stop_service() {
    if (service_state == SERVICE_RUNNING) {
        pthread_mutex_lock(&service_mutex);
        service_state = SERVICE_STOPPING;
        printf("Service stopping...\n");
        sem_post(&start_service_sem); // signal start service
        pthread_mutex_unlock(&service_mutex);
    } else {
        printf("Error stopping service...\n");
