typedef struct {
    pthread_mutex_t lock;
    MetricData* metrics;
    size_t num_metrics;
    size_t capacity;
    time_t retention_period;
} MetricsLib;

// Initialize the metrics library
MetricsLib* init_metrics_lib(size_t capacity) {
    MetricsLib* lib = malloc(sizeof(MetricsLib));
    lib->lock = PTHREAD_MUTEX_INITIALIZER;
    lib->metrics = calloc(capacity, sizeof(MetricData));
    lib->num_metrics = 0;
    lib->capacity = capacity;
    lib->retention_period = time(NULL) - (60 * 60); // default retention period: 1 hour
    return lib;
}

// Add a new metric to the library
void add_metric(MetricsLib* lib, int cell_id, double latitude, double longitude) {
    pthread_mutex_lock(&lib->lock);
    MetricData* new_metric = &lib->metrics[lib->num_metrics];
    new_metric->cell_id = cell_id;
    new_metric->timestamp = time(NULL);
    new_metric->latitude = latitude;
    new_metric->longitude = longitude;
    lib->num_metrics++;
    pthread_mutex_unlock(&lib->lock);
}

// Retrieve the most recent metric for a given cell ID
MetricData* get_most_recent_metric(MetricsLib* lib, int cell_id) {
    pthread_mutex_lock(&lib->lock);
    MetricData* result = NULL;
    for (size_t i = 0; i < lib->num_metrics; i++) {
        if (lib->metrics[i].cell_id == cell_id) {
            result = &lib->metrics[i];
            break;
        }
    }
    pthread_mutex_unlock(&lib->lock);
    return result;
}

// Clear outdated metrics based on the retention period
void clear_outdated_metrics(MetricsLib* lib) {
    pthread_mutex_lock(&lib->lock);
    time_t current_time = time(NULL);
    size_t i = 0;
    while (i < lib->num_metrics) {
        if (current_time - lib->metrics[i].timestamp > lib->retention_period) {
            // remove outdated metric
            memmove(&lib->metrics[i], &lib->metrics[i + 1], sizeof(MetricData) * (lib->num_metrics - i - 1));
            lib->num_metrics--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&lib->lock);
}

