```rust
use tokio::sync::{mpsc, channel};
use tokio::task;
use serde_json;

#[derive(Debug)]
struct Event {
    id: u32,
    timestamp: chrono::DateTime<chrono::Local>,
    data: String,
}

async fn process_events(mut events_rx: mpsc::Receiver<Event>) -> Result<(), ()> {
    let (tx, _) = channel(100);

    while let Some(event) = events_rx.recv().await {
        // Process the event
        println!("Processing event: {:?}", event);

        // Send a response back
        tx.send("Event processed").await.unwrap();
    }

    Ok(())
}

async fn filter_events(events_rx: mpsc::Receiver<Event>) -> Result<(), ()> {
    let (tx, _) = channel(100);

    while let Some(event) = events_rx.recv().await {
        // Filter the event
        if event.data.contains("filter") {
            println!("Filtered event: {:?}", event);
            tx.send("Event filtered").await.unwrap();
        } else {
            tx.send(event).await.unwrap();
        }
    }

    Ok(())
}

async fn aggregate_events(events_rx: mpsc::Receiver<Event>) -> Result<(), ()> {
    let (tx, _) = channel(100);

    while let Some(event) = events_rx.recv().await {
        // Aggregate the event
        println!("Aggregating event: {:?}", event);

        // Send a response back
        tx.send("Event aggregated").await.unwrap();
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), ()> {
    let (events_tx, events_rx) = channel(100);

    task::spawn(async move {
        process_events(events_rx).await?;
    });

    task::spawn(async move {
        filter_events(events_rx).await?;
    });

    task::spawn(async move {
        aggregate_events(events_rx).await?;
    });

    for _ in 0..10000000 {
        events_tx.send(Event { 
            id: rand::random::<u32>(), 
            timestamp: chrono::Local::now(), 
            data: format!("Hello, {}!", "World"),
        }).await.unwrap();
    }

    Ok(())
}
