        return client.cluster();
    }

    @Bean
    public Node node(Cluster cluster, EtcdClient client) {
        RequestOptions options = RequestOptions.builder()
                .setTimeout(10000)
                .setConnectTimeout(5000)
                .setReadTimeout(5000)
                .build();
        return client.request().get(options);
    }
}

