    Node(const std::string& id) : id(id) {}

    // Update memory usage and request latency based on real-time metrics
    void updateMetrics(int memoryUsage, int requestLatency) {
        this->memoryUsage = memoryUsage;
        this->requestLatency = requestLatency;
    }
