    std::unordered_map<std::string, Node*> nodes; // Map of nodes with their IDs
    std::mutex mutex; // Mutex for synchronization
    std::condition_variable cv; // Condition variable for signaling

public:
    // Constructor for creating a new distributed cache
    DistributedCache() {}

    // Add a node to the distributed cache
    void addNode(const std::string& id) {
        nodes[id] = new Node(id);
    }

    // Remove a node from the distributed cache
    void removeNode(const std::string& id) {
        if (nodes.find(id) != nodes.end()) {
            delete nodes.at(id);
            nodes.erase(id);
        }
    }

