    Node(std::string id) : id_(id), leader_(true), lock_() {}

    void start() {
        std::cout << "Node " << id_ << " started." << std::endl;
        std::thread t(&Node::run, this);
        t.detach();
    }

    void run() {
        while (true) {
            if (leader_) {
                // leader node duties
                std::unique_lock<std::mutex> lock(lock_);
                while (!ready_.wait_for(std::chrono::microseconds, [this] { return !ready_; })) {}
                if (ready_) {
                    // start consensus algorithm here
                }
                ready_ = false;
            } else {
                // follower node duties
                std::unique_lock<std::mutex> lock(lock_);
                while (!ready_.wait_for(std::chrono::microseconds, [this] { return !ready_; })) {}
                if (ready_) {
                    // start consensus algorithm here
                }
                ready_ = false;
            }
        }
    }

private:
    std::string id_;
    bool leader_;
    std::mutex lock_;
    std::condition_variable ready_;
};

