                await _sftpClient.UploadFileAsync(sourcePath, destinationUrl, options);
            }
            else if (destinationUrl.StartsWith("ftps://"))
            {
                await _ftpClient.UploadFileAsync(sourcePath, destinationUrl, options);
            }
            else
            {
                await _httpClient.UploadFileAsync(sourcePath, destinationUrl, options);
            }
