                await _sftpClient.DownloadFileAsync(sourceUrl, destinationPath, options);
            }
            else if (sourceUrl.StartsWith("ftps://"))
            {
                await _ftpClient.DownloadFileAsync(sourceUrl, destinationPath, options);
            }
            else
            {
                await _httpClient.DownloadFileAsync(sourceUrl, destinationPath, options);
            }
