<?php

class PasswordUpdateModule {
    private $db;
    private $logger;
    private $authServices;
    private $rateLimiter;

    public function __construct($db, $logger, $authServices, $rateLimiter) {
        $this->db = $db;
        $this->logger = $logger;
        $this->authServices = $authServices;
        $this->rateLimiter = $rateLimiter;
    }

    public function updatePassword($username, $oldPassword, $newPassword) {
        // Validate password strength
        if (!isValidPasswordStrength($newPassword)) {
            return ['error' => 'Weak password'];
        }

        // Check if user exists and old password is correct
        $user = $this->db->getUserByUsername($username);
        if (!$user || !$this->validateOldPassword($oldPassword, $user['password'])) {
            return ['error' => 'Invalid username or password'];
        }

        // Check rate limiting
        if ($this->rateLimiter->isRateLimited($username)) {
            return ['error' => 'Too many attempts. Try again later'];
        }

        // Update password and lockout mechanism
        $newHashedPassword = hash_password($newPassword);
        $this->db->updateUserPassword($username, $newHashedPassword);

        // Multi-factor verification (MFA) integration
        foreach ($authServices as $service) {
            if (!$service->verifyMFA($username)) {
                return ['error' => 'MFA failed'];
            }
        }

        // Secure logging
        $this->logger->log('Password updated: ' . $username);

        return ['success' => true];
    }

    private function validateOldPassword($oldPassword, $hashedPassword) {
        return password_verify($oldPassword, $hashedPassword);
    }

    private function isValidPasswordStrength($password) {
