```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>

// Define a struct to hold network statistics metrics
typedef struct {
    int cell_id;
    long timestamp;
    char* metric_name;
    double value;
} Metric;

// Define the data structure for storing metrics
typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    Metric** metrics;
} MetricsContainer;

// Function to add a new metric to the container
void add_metric(MetricsContainer* container, int cell_id, long timestamp, char* metric_name, double value) {
    // Lock the container
    pthread_mutex_lock(&container->lock);

    // Allocate memory for the new metric
    Metric* new_metric = malloc(sizeof(Metric));
    new_metric->cell_id = cell_id;
    new_metric->timestamp = timestamp;
    new_metric->metric_name = strdup(metric_name);
    new_metric->value = value;

    // Insert the new metric at the end of the container
    if (container->count >= container->capacity) {
        container->metrics = realloc(container->metrics, (container->capacity * 2 + 1) * sizeof(Metric*));
        container->capacity *= 2;
    }
    container->metrics[container->count] = new_metric;
    container->count++;

    // Unlock the container
    pthread_mutex_unlock(&container->lock);
}

// Function to update an existing metric in the container
void update_metric(MetricsContainer* container, int cell_id, long timestamp, char* metric_name, double value) {
    // Lock the container
    pthread_mutex_lock(&container->lock);

    // Find the metric with the matching cell ID and name
    for (int i = 0; i < container->count; i++) {
        if (container->metrics[i]->cell_id == cell_id && strcmp(container->metrics[i]->metric_name, metric_name) == 0) {
            container->metrics[i]->value = value;
            break;
        }
    }

    // Unlock the container
    pthread_mutex_unlock(&container->lock);
}

// Function to retrieve a metric from the container
Metric* get_metric(MetricsContainer* container, int cell_id, char* metric_name) {
    // Lock the container
    pthread_mutex_lock(&container->lock);

    // Find the metric with the matching cell ID and name
    for (int i = 0; i < container->count; i++) {
        if (container->metrics[i]->cell_id == cell_id && strcmp(container->metrics[i]->metric_name, metric_name) == 0) {
            Metric* result = malloc(sizeof(Metric));
            *result = *container->metrics[i];
            return result;
        }
    }

    // Unlock the container
    pthread_mutex_unlock(&container->lock);
    return NULL; // Metric not found
}

// Function to clear metrics older than a specified retention period
void clear_metrics(MetricsContainer* container, long retention_period) {
    // Lock the container
    pthread_mutex_lock(&container->lock);

    // Iterate through the metrics and remove those that are older than the retention period
    for (int i = 0; i < container->count; i++) {
        if (container->metrics[i]->timestamp + retention_period <= time(NULL)) {
            free(container->metrics[i]->metric_name);
            free(container->metrics[i]);
            container->metrics[i] = NULL;
        }
    }

    // Reallocate memory to remove null entries
    size_t new_count = 0;
    for (int i = 0; i < container->count; i++) {
        if (container->metrics[i]) {
            new_count++;
        } else {
            for (int j = i + 1; j < container->count; j++) {
                if (container->metrics[j]) {
                    container->metrics[i] = container->metrics[j];
                    container->metrics[j] = NULL;
                    break;
                }
            }
        }
    }

    // Update the count and capacity of the container
    container->count = new_count;
    size_t new_capacity = new_count / 2 + 1;
    container->metrics = realloc(container->metrics, new_capacity * sizeof(Metric*));

    // Unlock the container
    pthread_mutex_unlock(&container->lock);
}
```']

