```javascript
// Package imports
const express = require('express');
const multer = require('multer');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Express app setup
const app = express();

// Set up Multer for file uploads
const upload = multer({ dest: './uploads/' });

// Define a function to generate unique encryption keys
function generateEncryptionKey() {
  return crypto.randomBytes(32).toString('hex');
}

// Define a function to encrypt files
async function encryptFile(fileBuffer, encryptionKey) {
  const encryptedBuffer = await crypto.createCipher('aes-256-cbc', encryptionKey)
    .update(fileBuffer, 'utf8', 'utf8')
    .final();
  return encryptedBuffer;
}

// Define a function to decrypt files
async function decryptFile(encryptedBuffer, encryptionKey) {
  const decryptedBuffer = await crypto.createDecipher('aes-256-cbc', encryptionKey)
    .update(encryptedBuffer, 'utf8', 'utf8')
    .final();
  return decryptedBuffer;
}

// Define a route for uploading files
app.post('/upload', upload.single('file'), (req, res) => {
  const file = req.file;
  const encryptionKey = generateEncryptionKey();
  const encryptedFileBuffer = encryptFile(file.buffer, encryptionKey);

  // Store the encrypted file and encryption key in the database
  // ...

  res.send(`File uploaded successfully! Encryption key: ${encryptionKey}`);
});

// Define a route for retrieving files
app.get('/file/:filename', (req, res) => {
  const filename = req.params.filename;
  const encryptionKey = generateEncryptionKey(); // Generate a new encryption key

  // Retrieve the encrypted file and encryption key from the database
  // ...

  const decryptedFileBuffer = decryptFile(encryptedFileBuffer, encryptionKey);

  // Send the decrypted file buffer to the client
  res.send(decryptedFileBuffer);
});

// Start the Express server
app.listen(3000, () => {
  console.log('Server started on port 3000!');
});
