    pthread_mutex_init(&mm->lock, NULL);
}

// Function to add a new metric
int add_metric(MetricManager* mm, const char* cell_id, time_t timestamp, int priority_level) {
    Metric* new_metric = (Metric*)malloc(sizeof(Metric));
    if (!new_metric) return -1; // Out of memory

    strcpy(new_metric->cell_id, cell_id);
    new_metric->timestamp = timestamp;
    new_metric->priority_level = priority_level;

    pthread_mutex_lock(&mm->lock); // Acquire the lock
    mm->metrics = (Metric*)realloc(mm->metrics, (mm->num_metrics + 1) * sizeof(Metric));
    if (!mm->metrics) {
        free(new_metric);
        return -1; // Out of memory
    }
    mm->metrics[mm->num_metrics++] = *new_metric;
    pthread_mutex_unlock(&mm->lock); // Release the lock

    free(new_metric);
    return 0; // Success
}

// Function to retrieve a metric by cell ID and timestamp
Metric* get_metric(MetricManager* mm, const char* cell_id, time_t timestamp) {
    pthread_mutex_lock(&mm->lock); // Acquire the lock
    for (size_t i = 0; i < mm->num_metrics; i++) {
        if (!strcmp(mm->metrics[i].cell_id, cell_id) && mm->metrics[i].timestamp == timestamp) {
            Metric* result = malloc(sizeof(Metric));
            *result = mm->metrics[i];
            return result;
        }
    }
    pthread_mutex_unlock(&mm->lock); // Release the lock
    return NULL; // Not found
}

// Function to release memory and close the metric manager
void close_metric_manager(MetricManager* mm) {
    pthread_mutex_lock(&mm->lock);
    free(mm->metrics);
    mm->num_metrics = 0;
    pthread_mutex_unlock(&mm->lock);
    pthread_mutex_destroy(&mm->lock);
}

// Define the custom allocator for large-scale data sets
#include "custom_allocator.h"

int main() {
    MetricManager* mm = malloc(sizeof(MetricManager));
    init_metric_manager(mm);

    // Add some sample metrics
    add_metric(mm, "cell-123", 1643723400, 1);
    add_metric(mm, "cell-456", 1643730000, 2);
    add_metric(mm, "cell-789", 1643736600, 3);

    // Retrieve and print a metric
    Metric* retrieved_metric = get_metric(mm, "cell-123", 1643723400);
    if (retrieved_metric) {
        printf("Retrieved metric: cell_id=%s, timestamp=%ld, priority_level=%d\n",
               retrieved_metric->cell_id, retrieved_metric->timestamp, retrieved_metric->priority_level);
        free(retrieved_metric);
    }

    close_metric_manager(mm);
    free(mm);

    return 0;
}
