class EventBatcher {
public:
    void push(const std::string& event) {
        std::unique_lock<std::mutex> lock(mutex_);
        batch_.push(event);
        if (batch_.size() >= batch_size_) {
            flush();
        }
    }

    void flush() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (!batch_.empty()) {
            // Send the batch to the network
            std::cout << "Sent: " << batch_.front() << std::endl;
            batch_.pop();
        }
    }

private:
    int batch_size_ = 100; // Adjust according to your needs
    mutable std::mutex mutex_;
    std::queue<std::string> batch_;
};

class EventProcessor {
public:
    void process(const std::string& event) {
        if (is_critical_event(event)) {
            // Critical events need immediate processing
            process_critical(event);
        } else {
            // Non-critical events can be batched and processed later
            batch_.push(event);
        }
    }

private:
    bool is_critical_event(const std::string& event) {
        // Implement your critical event detection logic here
        return false; // Default: non-critical event
    }

    void process_critical(const std::string& event) {
        // Process the critical event immediately
        std::cout << "Processed critical event: " << event << std::endl;
    }

    EventBatcher batch_;
};

int main() {
    EventProcessor processor;

    processor.process("Event 1"); // Non-critical event
    processor.process("Event 2"); // Critical event
    processor.process("Event 3"); // Non-critical event

