    private static final int MAX_INFLIGHT_REQUESTS = 10;
    private static final int REQUEST_TIMEOUT_MILLISECONDS = 3000; // 3 seconds

    private final BlockingQueue<LogRecord> logRecords = new LinkedBlockingQueue<>();
    private final ExecutorService executorService = Executors.newFixedThreadPool(MAX_INFLIGHT_REQUESTS);

