        // Start the log processing pipeline
        executorService.submit(() -> {
            try {
                while (true) {
                    LogRecord logRecord = logRecords.take();
                    processLogRecord(logRecord);
                }
            } catch (InterruptedException e) {
                logger.error("Interrupted during log processing");
