// Define the maximum number of states allowed in an FSA
#define MAX_STATES 1000

// Define the maximum number of transitions allowed in an FSA
#define MAX_TRANSITIONS 5000

// Define a union to represent disjoint sets of states using Union-Find data structure
typedef struct {
    int parent;
    int rank;
} Set;

// Function to create a new set and initialize its parent and rank
Set* create_set() {
    Set* new_set = (Set*)malloc(sizeof(Set));
    new_set->parent = -1;
    new_set->rank = 0;
    return new_set;
}

// Function to find the representative of a given set using path compression
int find_set(int parent, int x) {
    if (parent[x] == -1)
        return x;
    else {
        parent[x] = find_set(parent, parent[x]);
        return parent[x];
    }
}

// Function to union two sets using rank-based optimization
void union_sets(int* parent, int* rank, int x, int y) {
    if (rank[find_set(parent, x)] < rank[find_set(parent, y)])
        parent[find_set(parent, x)] = find_set(parent, y);
    else if (rank[find_set(parent, x)] > rank[find_set(parent, y)]) {
        parent[find_set(parent, y)] = find_set(parent, x);
    } else {
        parent[find_set(parent, y)] = find_set(parent, x);
        rank[find_set(parent, x)]++;
    }
}

