NFAPI_CRC_INDICATION_PDU_T* generateNFACRCIndications(int N) {
    // Initialize array of structures for sessions
    NFAPI_CRC_INDICATION_PDU_T* sessions = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Generate and validate session data
    for (int i = 0; i < N; i++) {
