        sessions[i].RNTI = i;
        strcpy(sessions[i].CRC_INDICATION_REL8_TAG, "CRC_INDREL8_TAG");
    }

    // Validate RNTI values for uniqueness
    int uniqueRTNI = 0;
    for (int i = 0; i < N; i++) {
        if (uniqueRTNI == sessions[i].RNTI) {
            printf("Error: RNTI values are not unique\n");
            return NULL;
        }
        uniqueRTNI++;
    }

    // Return the generated session data
    return sessions;
}

