    int N = 1000;
    for (int i = 0; i < 10; i++) {
        int arg = N / 10;
        pthread_create(&threads[i], NULL, concurrentSessionGenerator, &arg);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
