function asyncReduce(arr, initialValue, reduceCallback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    (function loop(index) {
      if (index >= arr.length) {
        resolve(accumulator);
      } else {
        asyncApply(reduceCallback, accumulator, arr[index]).then((result) => {
          accumulator = result;
          loop(index + 1);
        }).catch((error) => {
          reject(error);
        });
      }
    })(0);
  });
}

function asyncApply(callback, arg1, arg2) {
  return new Promise((resolve, reject) => {
    callback(arg1, arg2, (result) => {
      resolve(result);
    }, (error) => {
      reject(error);
    });
  });
}
