// Forward declarations
class Node;
class KVStore;

// Key-Value Store class definition
class KVStore {
public:
    // Constructor
    KVStore();

    // Destructor
    ~KVStore();

    // Put a key-value pair into the store
    void put(const std::string& key, const std::string& value);

    // Get the value for a given key
    std::string get(const std::string& key) const;

private:
    // Map of nodes in the distributed KVStore
    std::map<std::string, Node*> nodes_;

    // Mutex for thread-safe operations
    std::mutex mtx_;

    // Condition variable for node creation and shutdown
    std::condition_variable cv_;
};

// Node class definition
class Node {
public:
    // Constructor
    Node(const std::string& id);

    // Destructor
    ~Node();

    // Put a key-value pair into the local node
    void put(const std::string& key, const std::string& value);

    // Get the value for a given key from this node
    std::string get(const std::string& key) const;

private:
    // Map of key-value pairs stored on this node
    std::map<std::string, std::string> store_;

    // Mutex for thread-safe operations
    std::mutex mtx_;
};

// KVStore implementation
KVStore::KVStore() {
    // Initialize nodes map
    nodes_.clear();
}

KVStore::~KVStore() {
    // Shut down all nodes in the distributed store
    for (auto& node : nodes_) {
        node.second->shutdown();
    }
}

void KVStore::put(const std::string& key, const std::string& value) {
    // Find or create a node to handle the put operation
    auto it = nodes_.find(key);
    if (it == nodes_.end()) {
        Node* newNode = new Node(key);
        nodes_[key] = newNode;
    }
    it->second->put(key, value);
}

std::string KVStore::get(const std::string& key) const {
    // Find the node responsible for the given key
    auto it = nodes_.find(key);
    if (it != nodes_.end()) {
        return it->second->get(key);
    }
    // Key not found, return an empty string
    return "";
}

// Node implementation
Node::Node(const std::string& id) {
    // Initialize local store and node ID
    store_.clear();
    id_ = id;
}

Node::~Node() {
    // Shutdown this node
}

void Node::put(const std::string& key, const std::string& value) {
    // Store the key-value pair locally
    store_[key] = value;
}

std::string Node::get(const std::string& key) const {
    // Return the value for the given key from this node's store
    return store_.at(key);
}
