class EventProcessor {
public:
    void processEvent(Message event) {
        // Process the event asynchronously using a separate thread
        auto t = std::thread([this, event]() {
            // Simulate some processing time
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            // Print the processed event data
            std::cout << "Processed event: " << event.eventData << std::endl;
        });
        t.detach();
    }

private:
    std::mutex mtx;
    std::condition_variable cv;
};

class MessageBroker {
public:
    void sendMessage(Message message) {
        // Simulate some message processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
        // Print the sent message data
        std::cout << "Sent message: " << message.eventData << std::endl;
    }
};

class System {
public:
    void start() {
        // Create an event processor and message broker instance
        EventProcessor ep;
        MessageBroker mb;

        // Start processing events asynchronously
        for (int i = 0; i < 10; i++) {
            ep.processEvent(Message{i, "Event data"});
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }

        // Send messages to the message broker
        for (int i = 0; i < 5; i++) {
            mb.sendMessage(Message{i, "Message data"});
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    }
};

