using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public enum RandomType { Float, Int, Long, Decimal }

public sealed class DynamicSecureRandomValueGenerator
{
    private readonly Random _random = new Random();
    private readonly Dictionary<RandomType, Random> _typeRan = new Dictionary<RandomType, Random>();
    private readonly object _lock = new object();

    public static DynamicSecureRandomValueGenerator Instance { get; } = new DynamicSecureRandomValueGenerator();

    public void Initialize()
    {
        foreach (var type in Enum.GetValues(typeof(RandomType)))
            _typeRan.Add((RandomType)type, new Random());
    }

    public T Generate<T>(RandomType type, double lowerBound, double upperBound)
    {
        if (!_typeRan.TryGetValue(type, out var ran))
            throw new ArgumentException($"Unsupported type: {type}", nameof(type));

        lock (_lock)
        {
            var range = (double)upperBound - lowerBound;
            return (T)System.Convert.ChangeType(ran.NextDouble() * range + lowerBound, typeof(T));
        }
    }

