class VideoStreamManager {
public:
    VideoStreamManager() : transcodingServicePrimary_("primary"), transcodingServiceBackup_("backup"), 
                           transcodingServiceMonitor_("monitor"), workerThreadPool_(1) {}

    void addVideoStream(const VIDEO_STREAM_PDU& stream) {
        std::unique_lock<std::mutex> lock(mutex_);
        videoStreams_.emplace_back(stream);
        lock.unlock();

        // Start a new thread to process the added stream
        std::thread([this, &stream]() {
            processVideoStream(stream);
        }).detach();
    }

    void removeVideoStream(const VIDEO_STREAM_PDU& stream) {
        std::unique_lock<std::mutex> lock(mutex_);
        auto it = videoStreams_.begin();
        while (it != videoStreams_.end()) {
            if (&(*it) == &stream) {
                videoStreams_.erase(it);
                break;
            }
            ++it;
        }
    }

    void transcodeVideoStream(const VIDEO_STREAM_PDU& stream, bool primaryService = true) {
        if (primaryService) {
            transcodingServicePrimary_.transcode(stream);
        } else {
            transcodingServiceBackup_.transcode(stream);
        }
    }

    void startWorkerThreads(int numThreads) {
        workerThreadPool_ = numThreads;
    }

    void stopWorkerThreads() {
        workerThreadPool_ = 0;
    }

private:
    void processVideoStream(const VIDEO_STREAM_PDU& stream) {
        // Implement video processing logic here
    }

