NFAPI_CONFIG_T config = {0, 0, "XXXX"};

pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;

void *generateNFACRCIndications(void *args) {
    // Thread-safe session generation and validation
    pthread_mutex_lock(&config_lock);
    int N = 10; // Default number of sessions
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T session;
        // Generate RNTI values with uniqueness check
        sprintf(session.RNTI, "%05d", rand() % 100000);
        // Validate RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG formats
        if (strlen(session.RNTI) > 5 || strlen(config.tagFormat) != 4) {
            printf("Invalid tag format: %s\n", config.tagFormat);
            return NULL;
        }
        pthread_mutex_unlock(&config_lock);
        // Process session data asynchronously to handle concurrent requests
        pthread_t thread;
        if (pthread_create(&thread, NULL, processSession, &session)) {
            printf("Error creating thread\n");
            return NULL;
        }
        pthread_join(thread, NULL);
    }
    return NULL;
}

int main() {
    // Load configuration from JSON file
    FILE *fp = fopen("config.json", "r");
    if (!fp) {
        printf("Failed to load configuration file\n");
        return 1;
    }
    fread(&config, sizeof(NFAPI_CONFIG_T), 1, fp);
    fclose(fp);

    // Start generating CRC indications in parallel
    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pthread_create(&threads[i], NULL, generateNFACRCIndications, NULL);
    }
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void processSession(void *session) {
    // Asynchronous processing of session data
    printf("Processing session: %s\n", ((NFAPI_CRC_INDICATION_PDU_T *)session)->RNTI);
    // Validate RNTI against external authentication service
    if (!validateRNTI(((NFAPI_CRC_INDICATION_PDU_T *)session)->RNTI)) {
        printf("Invalid RNTI: %s\n", ((NFAPI_CRC_INDICATION_PDU_T *)session)->RNTI);
        return;
    }
    // Send CRC indications to external API
    sendCRCIndications(((NFAPI_CRC_INDICATION_PDU_T *)session));
}

