    // This function may occasionally fail, so implement retries and exponential backoff strategies
    if (!send_CRC_indications(session->RX_UE_INFORMATION_TAG, session->RNTI, session->CRC_INDICATION_REL8_TAG)) {
        return 0; // Failed to send CRC indication
    }
    return 1; // Sent CRC indication successfully
}

