#define MAX_CERT_LENGTH 1024

int combine_private_key_and_certificate(char *private_key_file, char *certificate_file, char *combined_cert_file) {
    // read private key file
    FILE *private_key_fp = fopen(private_key_file, "rb");
    if (!private_key_fp) return -1;

    // read certificate file
    FILE *certificate_fp = fopen(certificate_file, "rb");
    if (!certificate_fp) return -2;

    // combine private key and certificate into a single PEM file
    FILE *combined_cert_fp = fopen(combined_cert_file, "wb");
    if (!combined_cert_fp) return -3;

    // write combined PEM file
    fprintf(combined_cert_fp, "-----BEGIN CERTIFICATE-----\n");
    char cert_buffer[MAX_CERT_LENGTH];
    int cert_len = fread(cert_buffer, 1, MAX_CERT_LENGTH, certificate_fp);
    fwrite(cert_buffer, 1, cert_len, combined_cert_fp);
    fclose(certificate_fp);

    fprintf(combined_cert_fp, "-----END CERTIFICATE-----\n");

    // write private key into the PEM file
    fprintf(combined_cert_fp, "-----BEGIN RSA PRIVATE KEY-----\n");
    int priv_key_len = fread(cert_buffer, 1, MAX_CERT_LENGTH, private_key_fp);
    fwrite(cert_buffer, 1, priv_key_len, combined_cert_fp);
    fclose(private_key_fp);

    fprintf(combined_cert_fp, "-----END RSA PRIVATE KEY-----\n");

    fclose(combined_cert_fp);

    return 0;
}

int main() {
    char *private_key_file = "path/to/private/key.pem";
    char *certificate_file = "path/to/certificate.pem";
    char *combined_cert_file = "path/to/combined_cert.pem";

    int result = combine_private_key_and_certificate(private_key_file, certificate_file, combined_cert_file);

    if (result < 0) {
        // handle error
    }

    return 0;
}
