NFAPI_CRC_INDICATION_PDU_T *generate_pdu_t(int count) {
    // Create memory pool manager
    struct malloc_heap *heap = malloc(sizeof(struct malloc_heap));
    heap->base = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize array
    NFAPI_CRC_INDICATION_PDU_T *pdu_ts = (NFAPI_CRC_INDICATION_PDU_T *)malloc(heap->base, count);
    for (int i = 0; i < count; i++) {
        pdu_ts[i].RX_UE_INFORMATION_TAG = rand() % RAND_MAX;
        for (int j = 0; j < MAX_RNTI_LENGTH; j++) {
            pdu_ts[i].RNTI[j] = rand() % RAND_MAX;
        }
        pdu_ts[i].CRC_INDICATION_REL8_TAG = rand() % RAND_MAX;
        pdu_ts[i].CRCFLAG = rand() % RAND_MAX;
    }

    return pdu_ts;
}

int validate_rnti(NFAPI_CRC_INDATION_PDU_T *pdu_t) {
    // Validate RNTI against predefined range
    for (int i = 0; i < MAX_RNTI_LENGTH; i++) {
        if (pdu_t->RNTI[i] < 0 || pdu_t->RNTI[i] > RAND_MAX) {
            return -1;
        }
    }

