    // Determine the CRC handling strategy based on incoming data characteristics
    if (pdu->data_length > 1024) {
        return 1; // Fast recovery for large data packets
    } else {
        return 0; // Normal CRC validation for small data packets
    }
}

void handleCrcNormalCRC(nfaapi_crc_indication_pdu_t *pdu, void *ue_info) {
    // Perform normal CRC validation and processing
    uint16_t calculated_crc = calculateCRC(pdu->data);
    if (crc_value == calculated_crc) {
        // Valid CRC - process data
        processData(pdu->data, ue_info);
    } else {
        // Invalid CRC - log error and skip processing
        logError("Invalid CRC");
    }
}

void handleCrcFastRecovery(nfaapi_crc_indication_pdu_t *pdu, void *ue_info) {
    // Perform fast recovery for large data packets
    uint16_t calculated_crc = calculateCRC(pdu->data);
    if (crc_value == calculated_crc) {
        // Valid CRC - process data
        processData(pdu->data, ue_info);
    } else {
        // Invalid CRC - retransmit data and try again
        logError("Invalid CRC - retransmitting");
    }
}

void handleCrcDefault(nfaapi_crc_indication_pdu_t *pdu, void *ue_info) {
    // Default strategy for unknown or invalid data
    logError("Unknown data type");
}

void handleCrcError(nfaapi_crc_indication_pdu_t *pdu, void *ue_info) {
    // Handle CRC error indication
    logError("CRC error");
}
