#include <sys/socket.h>
#include <netdb.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16

typedef struct {
    char ip_address[MAX_IP_ADDRESS];
} IpAddress;

int perform_dns_resolution(const char* hostname, IpAddress* ip_address) {
    struct hostent* host;
    struct sockaddr_in sa;
    int sd;
    char buf[1024];

    // Check for null pointer
    if (hostname == NULL || ip_address == NULL) {
        return -1;  // Error: invalid input
    }

    // Perform DNS resolution
    host = gethostbyname(hostname);
    if (host == NULL) {
        return -2;  // Error: hostname not found
    }

    // Get IP address from DNS response
    inet_ntop(AF_INET, host->h_addr_list[0], buf, sizeof(buf));
    strcpy(ip_address->ip_address, buf);

    return 0;  // Success
}

int main() {
    IpAddress ip;
    const char* hostname = "example.com";
    int result;

    result = perform_dns_resolution(hostname, &ip);
    if (result == -1) {
        printf("Error: invalid input\n");
    } else if (result == -2) {
        printf("Error: hostname not found\n");
    } else {
        printf("IP address: %s\n", ip.ip_address);
    }

    return 0;
}
