char* getMd5Hash(const char* input) {
    MD5_CTX ctx;
    unsigned char md5[16];
    char *hash = (char*)malloc(33);

    MD5_Init(&ctx);
    MD5_Update(&ctx, input, strlen(input));
    MD5_Final(md5, &ctx);

    for(int i = 0; i < 16; i++) {
        sprintf(hash + i*2, "%02x", md5[i]);
    }
    hash[32] = '\0';

