    if(pdu == NULL) {
        printf("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T structure.\n");
        return NULL;
    }
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000; // randomly set CRCFLAG
    pdu->CRCFLAG = rand() % 2; // randomly set CRCFLAG
    return pdu;
}

// Function to check for duplicate RNTI in the list
int is_rnti_duplicate(NFAPI_CRC_INDICATION_PDU_T* head, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while(temp != NULL) {
        if(temp->RNTI == rnti)
            return 1; // found duplicate RNTI
        temp = temp->next;
    }
    return 0; // no duplicate RNTI found
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
void add_pdu(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    if(*head == NULL || is_rnti_duplicate(*head, new_pdu->RNTI)) {
        // duplicate RNTI found or list is empty, create a new node
        new_pdu->next = *head;
        *head = new_pdu;
    } else {
        // find the last node in the list and add the new node after it
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_pdu;
    }
}

// Function to free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* temp = *head;
    while(temp != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = temp->next;
        free(temp);
        temp = next;
    }
    *head = NULL; // set the head to NULL after freeing
}

// Function to create a new list of NFAPI_CRC_INDICATION_PDU_T structures and add pdu's to it
NFAPI_CRC_INDICATION_PDU_T* create_list(int num_pdus) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for(int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_pdu(i, i+1); // set RNTI and other fields
        add_pdu(&head, new_pdu);
