    if (*head == NULL || newNode->data.RNTI > (*head)->data.RNTI) {
        newNode->next = *head;
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next && temp->next->data.RNTI >= newNode->data.RNTI)
            temp = temp->next;
        newNode->next = temp->next;
        temp->next = newNode;
    }
}

// Define the function to check for duplicate RNTI
int isDuplicate(Node* head, int RNTI) {
    Node* temp = head;
    while (temp) {
        if (temp->data.RNTI == RNTI)
