        return;
    }
    free(rtp);
}

int rtp_append(RealTimeDataProcessor* rtp, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    if (new_data == NULL) {
        printf("Invalid data for appending.\n");
        return -1; // Error
    }

    if (rtp->size >= rtp->capacity) {
        int new_capacity = rtp->capacity * 2; // Double the capacity
        rtp->data = realloc(rtp->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (rtp->data == NULL) {
            printf("Memory allocation failed for RealTimeDataProcessor.\n");
            return -1; // Error
        }
        rtp->capacity = new_capacity;
