  function getConnectionStatusNotifications() {
    return [...connectionStatusNotifications];
  }

  async function handleNotification(notification) {
    try {
      // Validate and process notification
      if (!notification || !notification.ue_id || !notification.timestamp || !notification.status) {
        console.error('Invalid connection status notification:', notification);
        return;
      }

      addConnectionStatusNotification(notification);

      // Trigger reconnection attempts for failed connections
      const failedConnections = getConnectionStatusNotifications().filter((conn) => conn.status === 'failed');
      if (failedConnections.length > 0) {
        // Reconnect failed connections and update status
        failedConnections.forEach((conn) => {
          networkMonitoringService.post('/reconnect', { ue_id: conn.ue_id })
            .then((response) => {
              const newConn = response.data;
              addConnectionStatusNotification(new ConnectionStatusNotification(newConn.ue_id, Date.now(), 'connected'));
