#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <memory>

class MediaStream {
public:
    virtual ~MediaStream() {}
    virtual void startStreaming() = 0;
    virtual void stopStreaming() = 0;
};

class VideoStream : public MediaStream {
public:
    void startStreaming() override {
        std::cout << "Video streaming started." << std::endl;
    }
    void stopStreaming() override {
        std::cout << "Video streaming stopped." << std::endl;
    }
};

class AudioStream : public MediaStream {
public:
    void startStreaming() override {
        std::cout << "Audio streaming started." << std::endl;
    }
    void stopStreaming() override {
        std::cout << "Audio streaming stopped." << std::endl;
    }
};

class Transcoder {
private:
    std::shared_ptr<MediaStream> videoStream;
    std::shared_ptr<MediaStream> audioStream;

public:
    Transcoder(std::shared_ptr<MediaStream> video, std::shared_ptr<MediaStream> audio) : 
        videoStream(video), audioStream(audio) {}

    void startTranscoding() {
        std::thread videoThread([this] { videoStream->startStreaming(); });
        std::thread audioThread([this] { audioStream->startStreaming(); });

        // Wait for both streams to finish
        videoThread.join();
        audioThread.join();

        // Stop the streams
        videoStream->stopStreaming();
        audioStream->stopStreaming();
    }
};

int main() {
    auto video = std::make_shared<VideoStream>();
    auto audio = std::make_shared<AudioStream>();

    Transcoder transcoder(video, audio);
    transcoder.startTranscoding();

    return 0;
}
```

