#define MAX_PENDING_EVENTS 100000

typedef struct {
    int rnti;
    uint32_t crc_indication_rel8_tag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG event;
    uint64_t timestamp;
} EVENT;

typedef struct {
    EVENT *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} QUEUE;

QUEUE* queue_init(size_t initial_capacity) {
    QUEUE* q = (QUEUE*)malloc(sizeof(QUEUE));
    q->capacity = initial_capacity;
    q->size = 0;
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
    return q;
}

void queue_destroy(QUEUE* q) {
    free(q->events);
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->cond);
    free(q);
}

int queue_enqueue(QUEUE* q, EVENT* event) {
    if (q->size == q->capacity) {
        // dynamic resizing
        q->capacity *= 2;
        q->events = (EVENT*)realloc(q->events, sizeof(EVENT) * q->capacity);
    }
    pthread_mutex_lock(&q->mutex);
    q->events[q->size++] = *event;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

int queue_dequeue(QUEUE* q, EVENT** event) {
    pthread_mutex_lock(&q->mutex);
    if (q->size == 0) {
        pthread_cond_wait(&q->cond, &q->mutex);
    }
    *event = &q->events[--q->size];
    pthread_mutex_unlock(&q->mutex);
    return 0;
}

