      console.error('Error sending message:', err);
    }
  });
});

// Consumer
const { KafkaConsumer } = require('kafkadirect');
const consumer = new KafkaConsumer({
  clientId: 'ecommerce-platform',
  brokers: ['localhost:9092'],
  groupId: 'transactions-group',
});

consumer.connect((err) => {
  if (err) {
    console.error('Error connecting to Kafka:', err);
    return;
  }
  // Consume messages
  consumer.subscribe({ topic: 'transactions' }, () => {
    consumer.consume(() => {
      const message = consumer.message();
      if (!message) return;
      // Process transaction data
      console.log(`Received transaction: ${JSON.parse(message.value)}`);
    });
  });
});
