using namespace std;

class DistributedKVStore {
public:
    DistributedKVStore(size_t numNodes) : nodes(numNodes) {}

    void put(const string& key, const string& value) {
        for (size_t i = 0; i < nodes.size(); i++) {
            nodes[i]->put(key, value);
        }
    }

    string get(const string& key) {
        for (size_t i = 0; i < nodes.size(); i++) {
            string result = nodes[i]->get(key);
            if (!result.empty()) {
                return result;
            }
        }
        return "";
    }

private:
    vector<shared_ptr<Node>> nodes;

    class Node {
    public:
        Node(size_t id) : id(id), lock(false) {}

        void put(const string& key, const string& value) {
            if (lock) {
                // Handle write conflict
                cout << "Write conflict detected. Node " << id << " will retry." << endl;
                this_thread::sleep_for(chrono::milliseconds(100));
                return put(key, value);
            }
            kvStore[key] = value;
        }

        string get(const string& key) {
            lock = true;
            auto it = kvStore.find(key);
            if (it != kvStore.end()) {
                lock = false;
                return it->second;
            }
            lock = false;
            return "";
        }

    private:
        size_t id;
        map<string, string> kvStore;
        mutex lockMutex;

        mutex lock;
    };
};

int main() {
    DistributedKVStore kvStore(3);
    // Put and get operations
    kvStore.put("key1", "value1");
    cout << "Value: " << kvStore.get("key1") << endl;
    return 0;
}
