// Define a custom lock-free queue
class LockFreeQueue {
private:
    std::queue<std::string> queue;
    std::mutex mutex;
    std::condition_variable cv;

public:
    void push(const std::string& data) {
        std::unique_lock<std::mutex> lock(mutex);
        queue.push(data);
        cv.notify_one();
    }

    bool try_pop(std::string& data) {
        std::unique_lock<std::mutex> lock(mutex);
        if (queue.empty()) {
            return false;
        }
        data = queue.front();
        queue.pop();
        return true;
    }
};

