    DistributedKeyValueStore(size_t numNodes, size_t cacheSize) : numNodes_(numNodes), cacheSize_(cacheSize), nodes_(numNodes) {}

    void put(const std::string& key, const std::string& value) {
        for (size_t i = 0; i < numNodes_; ++i) {
            nodes_[i]->put(key, value);
        }
    }

