        for (size_t i = 0; i < numNodes_; ++i) {
            auto nodeValue = nodes_[i]->get(key);
            if (!nodeValue.empty()) {
                return nodeValue;
            }
        }
        return "";
    }

private:
    struct Node {
        std::mutex mtx_;
        std::condition_variable cv_;
        std::atomic<std::string> data_;
        size_t id_;

