#define MAX_STRUCTURES 1000

typedef struct {
    char RX_UE_INFORMATION_TAG[17];
    int RNTI;
    struct {
        int CRCFLAG;
        char CRC_INDICATION_REL8_TAG[16];
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int parent;
    int rank;
} DisjointSetNode;

void initializeNFAPIStructures(int numStructures, NFAPI_CRC_INDICATION_PDU_T* structures);
int findDisjointSet(DisjointSetNode* set, int node);

int main() {
    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T structures[MAX_STRUCTURES];
    DisjointSetNode disjointSet[MAX_STRUCTURES];

    initializeNFAPIStructures(MAX_STRUCTURES, structures);
    // Initialize the disjoint set
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        disjointSet[i].parent = i;
        disjointSet[i].rank = 0;
    }

    clock_t start_time = clock();

    // Perform operations on the structures and disjoint set

    clock_t end_time = clock();

    double execution_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    printf("Execution time: %.2f milliseconds\n", execution_time * 1000);

    return 0;
}

void initializeNFAPIStructures(int numStructures, NFAPI_CRC_INDICATION_PDU_T* structures) {
    for (int i = 0; i < numStructures; i++) {
        // Initialize RX_UE_INFORMATION_TAG
        sprintf(structures[i].RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG_%d", i);

        structures[i].RNTI = rand() % 1000;

        // Initialize CRC_INDICATION_REL8_TAG with a random CRCFLAG and fill the tag
        structures[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        for (int j = 0; j < 16; j++) {
            structures[i].CRC_INDICATION_REL8_TAG.CRC_INDICATION_REL8_TAG[j] = 'X';
        }
    }
}

int findDisjointSet(DisjointSetNode* set, int node) {
    if (set[node].parent == node) {
        return node;
    }

    // Path compression
    set[node].parent = findDisjointSet(set, set[node].parent);

    return set[node].parent;
}
