// Distributed Cache Mechanism
class DistributedCache {
public:
    explicit DistributedCache(size_t cacheSize) : cacheSize_(cacheSize), cache_() {}

    void put(const string& key, const any& value) {
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            it->second = value;
        } else {
            cache_[key] = value;
            cache_.erase(remove(cache_.begin(), cache_.end(), nullptr), cache_.end());
            if (cache_.size() > cacheSize_) {
                cache_.erase(rbegin(cache_), rend(cache_));
            }
        }
    }

    any get(const string& key) {
        auto it = cache_.find(key);
        if (it != cache_.end()) {
            return it->second;
        } else {
            // Handle cache miss
            return nullptr;
        }
    }

private:
    size_t cacheSize_;
    map<string, any> cache_;
};

