            continue;
        }
        sleep(60 * 1000); // Submit metrics every hour
    }

    return NULL;
}

// Add a new metric to the system
void add_metric(struct cache* cache) {
    // Get unique cell identifier and metric value from user input
    char id[16];
    double value;

    // Insert the metric into in-memory storage
    struct metric_cell* cell = malloc(sizeof(struct metric_cell));
    strcpy(cell->id, id);
    cell->value = value;
    sem_wait(&cache->in_memory->read_write_lock);
    cache->in_memory->cells[cache->in_memory->num_cells++] = cell;
    sem_post(&cache->in_memory->read_write_lock);

    // Update the metric on disk and cloud storage
    pthread_mutex_lock(&disk->write_lock);
    fwrite(cell, sizeof(struct metric_cell), 1, disk->file);
    pthread_mutex_unlock(&disk->write_lock);
    sem_wait(&cloud->read_lock);
    memcpy(cloud->data, cell, sizeof(struct metric_cell));
    sem_post(&cloud->read_lock);

    // Release memory allocated for the cell
    free(cell);
}

// Update an existing metric in the system
void update_metric(struct cache* cache) {
    // Get unique cell identifier and new metric value from user input
    char id[16];
    double value;

    // Find the metric to be updated in in-memory storage
    sem_wait(&cache->in_memory->read_write_lock);
    for (int i = 0; i < cache->in_memory->num_cells; i++) {
        if (strcmp(cache->in_memory->cells[i]->id, id) == 0) {
            // Update the metric value in memory
            cache->in_memory->cells[i]->value = value;
            break;
        }
    }
    sem_post(&cache->in_memory->read_write_lock);

    // Update the metric on disk and cloud storage
    pthread_mutex_lock(&disk->write_lock);
    fseek(disk->file, sizeof(struct metric_cell), SEEK_SET);
    fwrite(&value, sizeof(double), 1, disk->file);
    pthread_mutex_unlock(&disk->write_lock);
    sem_wait(&cloud->read_lock);
    memcpy(cloud->data, &value, sizeof(double));
    sem_post(&cloud->read_lock);
}

// Retrieve a metric from the system
void retrieve_metric(struct cache* cache) {
    // Get unique cell identifier from user input
    char id[16];

    // Find the metric in in-memory storage
    sem_wait(&cache->in_memory->read_write_lock);
    for (int i = 0; i < cache->in_memory->num_cells; i++) {
        if (strcmp(cache->in_memory->cells[i]->id, id) == 0) {
            // Retrieve the metric value in memory
            double value = cache->in_memory->cells[i]->value;
            break;
        }
    }
    sem_post(&cache->in_memory->read_write_lock);

    // Retrieve the metric from disk and cloud storage
    pthread_mutex_lock(&disk->write_lock);
    fseek(disk->file, sizeof(struct metric_cell), SEEK_SET);
    double value = fread(&value, sizeof(double), 1, disk->file);
    pthread_mutex_unlock(&disk->write_lock);
    sem_wait(&cloud->read_lock);
    memcpy(&value, cloud->data, sizeof(double));
    sem_post(&cloud->read_lock);

    // Print the retrieved metric value
    printf("%s: %f\n", id, value);
}

// Get user input for adding, updating, or retrieving metrics
int get_user_input() {
    // Implement a menu-based interface to allow users to choose operations
}
