#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>

class Node {
public:
    std::string id;
    int port;
    bool connected;

    Node(std::string id, int port) : id(id), port(port), connected(false) {}
};

class KeyValueStore {
private:
    std::map<std::string, std::string> data;
    std::vector<Node> nodes;
    std::mutex mtx;
    std::condition_variable cv;

public:
    void put(const std::string& key, const std::string& value) {
        // Lock-free implementation using compare-and-swap (CAS)
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            if (!data[key].empty()) {
                // Conflict detected
                break;
            }
            data[key] = value;
            cv.notify_one();
            return;
        }

        // Resolve conflict using last-writer-wins approach
        while (true) {
            std::this_thread::sleep_for(std::chrono::microseconds(10));
            lock.unlock();
            if (!data[key].empty()) {
                break;
            }
        }
    }

    std::string get(const std::string& key) {
        // Use a read-only transaction to minimize contention
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]{ return !nodes.empty(); });
        return data[key];
    }

    void connect(Node node) {
        nodes.push_back(node);
    }

    void disconnect(Node node) {
        for (auto it = nodes.begin(); it != nodes.end();) {
            if (&(*it) == &node) {
                it = nodes.erase(it);
                break;
            } else {
                ++it;
            }
        }
    }
};
