class DistributedKeyValueStore {
public:
    DistributedKeyValueStore(vector<string> nodes) : nodes_(nodes), lock_(make_unique<mutex>()) {}

    void put(string key, string value) {
        thread([this, key, value]() {
            for (string node : nodes_) {
                // Try to write to each node
                tryWrite(node, key, value);
            }
        }).detach();
    }

    string get(string key) {
        return getFromRandomNode(key);
    }

private:
    vector<string> nodes_;
    unique_ptr<mutex> lock_;

    void tryWrite(string node, string key, string value) {
        // Write to the node
        cout << "Writing to " << node << endl;
    }

    string getFromRandomNode(string key) {
        // Choose a random node and read from it
        int index = rand() % nodes_.size();
        return tryRead(nodes_[index], key);
    }

    string tryRead(string node, string key) {
        // Read from the node
        cout << "Reading from " << node << endl;
        return "";
    }
};

int main() {
    vector<string> nodes = {"node1", "node2", "node3"};
    DistributedKeyValueStore store(nodes);

    store.put("key1", "value1");
