#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to hold network statistics metrics
typedef struct {
    char cell_id[32];
    uint64_t timestamp;
    double value;
} Metric;

// Define a structure to manage the dynamic list of metrics
typedef struct {
    pthread_mutex_t lock; // Read-write lock for concurrent access
    int capacity; // Capacity of the metric array
    Metric* metrics; // Array to store network statistics metrics
    int count; // Number of valid metrics
} Metrics;

// Initialize the metrics structure
Metrics* init_metrics(int capacity) {
    Metrics* metrics = (Metrics*)malloc(sizeof(Metrics));
    pthread_mutex_init(&metrics->lock, NULL);
    metrics->capacity = capacity;
    metrics->metrics = (Metric*)malloc(capacity * sizeof(Metric));
    metrics->count = 0;
    return metrics;
}

// Add a new metric to the dynamic list
void add_metric(Metrics* metrics, const char* cell_id, uint64_t timestamp, double value) {
    pthread_mutex_lock(&metrics->lock);

    // Check if the array is full and needs resizing
    if (metrics->count == metrics->capacity) {
        int new_capacity = metrics->capacity * 2;
        Metric* new_metrics = (Metric*)malloc(new_capacity * sizeof(Metric));
        memcpy(new_metrics, metrics->metrics, metrics->capacity * sizeof(Metric));
        free(metrics->metrics);
        metrics->metrics = new_metrics;
        metrics->capacity = new_capacity;
    }

    // Add the new metric
    metrics->metrics[metrics->count].cell_id[0] = '\0';
    strcpy(metrics->metrics[metrics->count].cell_id, cell_id);
    metrics->metrics[metrics->count].timestamp = timestamp;
    metrics->metrics[metrics->count].value = value;
    (metrics->count)++;

    pthread_mutex_unlock(&metrics->lock);
}

// Update an existing metric
void update_metric(Metrics* metrics, const char* cell_id, double value) {
    pthread_mutex_lock(&metrics->lock);

    // Find the metric with matching cell ID
    for (int i = 0; i < metrics->count; i++) {
        if (strcmp(metrics->metrics[i].cell_id, cell_id) == 0) {
            metrics->metrics[i].value = value;
            break;
        }
    }

    pthread_mutex_unlock(&metrics->lock);
}

// Retrieve the latest metric for a given cell
Metric* get_latest_metric(Metrics* metrics, const char* cell_id) {
    pthread_mutex_lock(&metrics->lock);

    // Find the metric with matching cell ID and maximum timestamp
    Metric* latest_metric = NULL;
    uint64_t max_timestamp = 0;
    for (int i = 0; i < metrics->count; i++) {
        if (strcmp(metrics->metrics[i].cell_id, cell_id) == 0 && metrics->metrics[i].timestamp > max_timestamp) {
            max_timestamp = metrics->metrics[i].timestamp;
            latest_metric = &metrics->metrics[i];
        }
    }

    pthread_mutex_unlock(&metrics->lock);
    return latest_metric;
}

// Clear all metrics older than a specified retention period
void clear_metrics(Metrics* metrics, uint64_t retention_period) {
    pthread_mutex_lock(&metrics->lock);

    // Find and remove metrics older than the retention period
    for (int i = 0; i < metrics->count; i++) {
        if (metrics->metrics[i].timestamp <= retention_period) {
            memmove(metrics->metrics + i, metrics->metrics + i + 1, (metrics->count - i - 1) * sizeof(Metric));
            (metrics->count]--;
            i--; // Decrement and re-check
        }
    }

    pthread_mutex_unlock(&metrics->lock);
}

// Submit data to the external API
void submit_data_to_api(Metrics* metrics) {
    // Implement the logic to submit data to the API
}

int main() {
    Metrics* metrics = init_metrics(1000); // Initialize with a capacity of 1000

    // Add, update, and retrieve metrics
    add_metric(metrics, "cell1", 1643723400, 10.5);
    add_metric(metrics, "cell2", 1643723410, 20.7);
    update_metric(metrics, "cell1", 12.3);

    Metric* latest_metric = get_latest_metric(metrics, "cell1");
    printf("Latest metric for cell 'cell1': timestamp=%llu, value=%.2f\n",
           latest_metric->timestamp, latest_metric->value);

    // Clear metrics older than a retention period
    clear_metrics(metrics, 1643723300);

    return 0;
}

