import org.apache.commons.io.FileUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.core.task.SimpleAsyncTaskExecutor;
import org.springframework.core.task.TaskExecutor;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RestController;

import java.io.File;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.RejectedExecutionHandler;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

@RestController
public class FileHashingService {

    private static final int MAX_CONCURRENT_WORKERS = 10;
    private static final String HASH_ALGORITHM = "MD5";

    @Autowired
    private TaskExecutor taskExecutor;

    @PostMapping("/hash")
    public ResponseEntity<String> hashFile(@RequestParam("path") String filePath, @RequestParam("chunkSize") int chunkSize) {
        try {
            File file = new File(filePath);
            if (!file.exists()) {
                return new ResponseEntity<>("File not found", HttpStatus.NOT_FOUND);
            }
            MessageDigest md = MessageDigest.getInstance(HASH_ALGORITHM);
            ExecutorService executor = getThreadPoolExecutor();
            LinkedBlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
            for (int i = 0; i < file.length(); i += chunkSize) {
                int endIndex = Math.min(i + chunkSize, file.length());
                Runnable task = new HashFileTask(file, md, i, endIndex);
                executor.execute(task);
            }
            return new ResponseEntity<>("Hashing completed", HttpStatus.OK);
        } catch (IOException | NoSuchAlgorithmException e) {
            return new ResponseEntity<>(e.getMessage(), HttpStatus.INTERNAL_SERVER_ERROR);
        }
    }

    private ExecutorService getThreadPoolExecutor() {
        return new ThreadPoolExecutor(MAX_CONCURRENT_WORKERS, MAX_CONCURRENT_WORKERS,
                0L, TimeUnit.MILLISECONDS,
                new LinkedBlockingQueue<Runnable>(),
                new RejectedExecutionHandler() {
                    @Override
                    public void rejectedExecution(Runnable r, ThreadPoolExecutor executor) {
                        try {
                            FileUtils.write(r, "hashing_task_failed.txt", true);
                        } catch (IOException e) {
                            // Handle error
                        }
                    }
                });
    }

    private class HashFileTask implements Runnable {

        private File file;
        private MessageDigest md;
        private int start;
        private int end;

        public HashFileTask(File file, MessageDigest md, int start, int end) {
            this.file = file;
            this.md = md;
            this.start = start;
            this.end = end;
        }

        @Override
        public void run() {
            try {
                byte[] chunk = FileUtils.readByteSource(file, start, end).read();
                md.update(chunk);
            } catch (IOException e) {
                // Handle error
            }
        }
    }
}
