    int dscp;
    int flow_priority;

    QosFlow(std::string id, int d, int p) : flow_id(id), dscp(d), flow_priority(p) {}
};

class QosFlowManager {
private:
    int num_flows;
    std::vector<QosFlow> flows;
    std::mutex flow_mutex;
    std::condition_variable flow_cond;

    void initialize_flows(int num) {
        for (int i = 0; i < num; i++) {
            // Initialize QoS flow attributes
            flows.push_back(QosFlow("FLOW_" + std::to_string(i), 0, 0));
        }
    }

public:
    QosFlowManager(int num_flows_in) : num_flows(num_flows_in) {
        initialize_flows(num_flows);
    }

    void add_flow(std::string flow_id, int dscp, int flow_priority) {
        std::unique_lock<std::mutex> lock(flow_mutex);
        flows.push_back(QosFlow(flow_id, dscp, flow_priority));
        lock.unlock();
        flow_cond.notify_all();
    }

