void QosFlowManager::updateFlow(uint32_t flowId, uint8_t newDscp, uint8_t newPriority) {
    std::unique_lock<std::mutex> lock(flowMutex);
    if (flows.find(flowId) != flows.end()) {
        flows[flowId].dscp = newDscp;
        flows[flowId].priority = newPriority;
    }
    lock.unlock();
}

void QosFlowManager::removeFlow(uint32_t flowId) {
    std::unique_lock<std::mutex> lock(flowMutex);
    if (flows.find(flowId) != flows.end()) {
        flows.erase(flowId);
    }
    lock.unlock();
