#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <boost/program_options.hpp>

namespace po = boost::program_options;

class EventProcessor {
public:
    EventProcessor(int numThreads, int queueSize)
        : eventQueue_(queueSize), threadPool_(numThreads) {}

    void start() {
        for (int i = 0; i < numThreads_; ++i) {
            threadPool_.push([this]() { processEvents(); });
        }
    }

    void stop() {
        for (int i = 0; i < numThreads_; ++i) {
            threadPool_.pop();
        }
    }

private:
    int processEvents() {
        while (true) {
            std::string event;
            if (!eventQueue_.try_pop(event)) {
                break;
            }
            // Process the event
            std::cout << "Processed event: " << event << std::endl;
        }
        return 0;
    }

private:
    int numThreads_;
    boost::asio::io_service ioService;
    boost::asio::io_service::work work(ioService);
    std::vector<boost::thread> threadPool_;
    std::queue<std::string> eventQueue_;
};

class Event {
public:
    Event(std::string data, int type) : data_(data), type_(type) {}

    std::string getData() const { return data_; }
    int getType() const { return type_; }

private:
    std::string data_;
    int type_;
};

int main(int argc, char** argv) {
    po::options_description desc("Options");
    desc.add_options()
        ("num-threads", po::value<int>(), "Number of threads")
        ("queue-size", po::value<int>(), "Queue size");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    int numThreads = vm["num-threads"].as<int>();
    int queueSize = vm["queue-size"].as<int>();

    EventProcessor eventProcessor(numThreads, queueSize);
    eventProcessor.start();

    // Process events
    for (int i = 0; i < 1000; ++i) {
        Event event("Event data", 1);
        eventProcessor.eventQueue_.push(event.getData());
    }

    sleep(5);

    eventProcessor.stop();
    return 0;
}
```

