['Here is a sample C++ code for implementing a modular, extensible task queue system:

```cpp
#include <iostream>
#include <string>
#include <map>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

class TaskQueue {
public:
    TaskQueue(int maxJobs) : maxJobs(maxJobs), jobs(), jobCondition() {}

    void addJob(const std::string& task, const std::string& data) {
        // Add task to queue
        if (jobs.size() >= maxJobs) {
            // Queue is full, wait for a slot to open
            std::unique_lock<std::mutex> lock(jobMutex);
            jobCondition.wait(lock, [this] { return jobs.size() < maxJobs; });
        }
        jobs.emplace(task, data);
    }

    void processJobs() {
        while (true) {
            // Wait for a job to be available
            std::unique_lock<std::mutex> lock(jobMutex);
            jobCondition.wait(lock, [this] { return !jobs.empty(); });
            const auto& task = jobs.front();
            jobs.pop();

            // Process the job
            processTask(task.first, task.second);

            // Unlock and notify others that a slot is available
            lock.unlock();
            jobCondition.notify_one();
        }
    }

private:
    int maxJobs;
    std::queue<std::pair<std::string, std::string>> jobs;
    std::mutex jobMutex;
    std::condition_variable jobCondition;

    void processTask(const std::string& task, const std::string& data) {
        // Process the task
        std::cout << "Processing task: " << task << std::endl;
    }
};

int main() {
    TaskQueue queue(5);

    // Add some jobs to the queue
    queue.addJob("job1", "data1");
    queue.addJob("job2", "data2");
    queue.addJob("job3", "data3");

    // Start processing jobs in a separate thread
    std::thread processThread(&TaskQueue::processJobs, &queue);

    // Wait for the thread to finish
    processThread.join();

    return 0;
}
