#include <functional>

using namespace std;

class Node {
public:
    Node(int id) : id(id), data(), lock(false) {}

    void put(const string& key, const string& value) {
        unique_lock<mutex> ul(mutex);
        if (!lock) {
            data[key] = value;
            lock = true;
        } else {
            cout << "Node " << id << ": Conflict detected. Waiting for resolution.\n";
            cv.wait(ul);
            lock = false;
        }
    }

    void get(const string& key, function<void(string)> callback) {
        unique_lock<mutex> ul(mutex);
        if (data.count(key)) {
            callback(data.at(key));
        } else {
            cout << "Node " << id << ": Key not found.\n";
        }
    }

private:
    int id;
    map<string, string> data;
    mutex mutex;
    condition_variable cv;
    bool lock;

};

class DistributedKVStore {
public:
    void put(const string& key, const string& value) {
        for (auto node : nodes) {
            if (!node->put(key, value)) {
                cout << "Put operation failed. Node is busy resolving conflict.\n";
                return;
            }
        }
    }

    void get(const string& key, function<void(string)> callback) {
        for (auto node : nodes) {
            node->get(key, [this, &callback](string value) {
                if (!value.empty()) {
                    callback(value);
                } else {
                    cout << "Key not found.\n";
                }
            });
        }
    }

private:
    vector<Node*> nodes;

};

class ReplicationManager {
public:
    void replicate(Node* node) {
        for (auto other : nodes) {
            if (other != node) {
                other->put(node->data.begin()->first, node->data.begin()->second);
            }
        }
    }

private:
    vector<Node*> nodes;
};

int main() {
    ReplicationManager rm;
    DistributedKVStore store;

    Node* node1 = new Node(1);
    Node* node2 = new Node(2);

    rm.nodes.push_back(node1);
    rm.nodes.push_back(node2);

    store.nodes.push_back(node1);
    store.nodes.push_back(node2);

    // Simulate put operations
    store.put("key1", "value1");
    store.put("key2", "value2");

    return 0;
}
