**Distributed Monitoring Application in Python:**
```python
import os
import hashlib
import threading

class FileMonitor:
  def __init__(self, directory_path):
    self.directory_path = directory_path
    self.file_hash_map = {}
    self.monitor_thread = None

  def start_monitoring(self):
    if not self.monitor_thread:
      self.monitor_thread = threading.Thread(target=self.monitor_files)
      self.monitor_thread.start()

  def stop_monitoring(self):
    if self.monitor_thread:
      self.monitor_thread.join()
      self.monitor_thread = None

  def monitor_files(self):
    for root, dirs, files in os.walk(self.directory_path):
      for file in files:
        file_path = os.path.join(root, file)
        file_hash = self.compute_file_hash(file_path)
        if file_hash not in self.file_hash_map:
          self.file_hash_map[file_hash] = [file]
        else:
          self.file_hash_map[file_hash].append(file)

  def compute_file_hash(self, file_path):
    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as f:
      while True:
        chunk = f.read(4096)
        if not chunk:
          break
        md5_hash.update(chunk)
    return md5_hash.hexdigest()

  def get_files_with_anomalies(self):
    anomaly_report = {}
    for file_hash, files in self.file_hash_map.items():
      if len(files) > 1:
        anomaly_report[file_hash] = files
    return anomaly_report

# Example usage
monitor = FileMonitor('/path/to/directory')
monitor.start_monitoring()
while True:
  time.sleep(10)
  anomalies = monitor.get_files_with_anomalies()
  print(anomalies)
```

