bool validateOAuth2Token(const std::string& jsonToken) {
    nlohmann::json tokenJson = nlohmann::json::parse(jsonToken);

    if (!tokenJson.is_object()) return false;

    if (!tokenJson.contains("access_token") || !tokenJson["access_token"].is_string())
        return false;

    std::string accessToken = tokenJson["access_token"];

    if (!tokenJson.contains("expires_in") || !tokenJson["expires_in"].is_number_integer()) 
        return false;

    int expiresIn = tokenJson["expires_in"];

    if (expiresIn <= 0) return false;

    if (!tokenJson.contains("token_type") || !tokenJson["token_type"].is_string())
        return false;

    std::string tokenType = tokenJson["token_type"];

    if (tokenType != "Bearer") return false;

    // Optional refresh_token verification
    if (tokenJson.contains("refresh_token")) {
        if (!tokenJson["refresh_token"].is_string()) return false;
    }

    return true;
}
