    private readonly Dictionary<string, ConfigService> _configServices = new();
    private readonly Dictionary<string, CacheEntry> _cacheEntries = new();

    public async Task<Configuration> GetConfigurationAsync(string tenantId)
    {
        var cacheEntry = _cacheEntries.TryGetValue(tenantId, out CacheEntry entry);
        if (cacheEntry && !entry.IsStale())
            return entry.Value;

        var configService = _configServices.GetValueOrDefault(tenantId);
        if (configService == null)
        {
            // Handle unknown tenant
            throw new Exception($"Unknown tenant '{tenantId}'");
        }

        try
        {
            var response = await FetchConfigAsync(configService, tenantId);
            return ParseResponse(response);
        }
        catch (Exception ex)
        {
            // Handle API failures
            await HandleApiFailureAsync(ex);
            return null;
        }
    }

    public async Task UpdateConfigurationAsync(string tenantId, Configuration config)
    {
        var cacheEntry = _cacheEntries.TryGetValue(tenantId, out CacheEntry entry);
        if (cacheEntry)
        {
            // Update in-memory cache
            entry.Value = config;
        }

        foreach (var service in _configServices.Values)
        {
            try
            {
                await UpdateServiceAsync(service, tenantId, config);
            }
            catch (Exception ex)
            {
                // Handle API failures
                await HandleApiFailureAsync(ex);
            }
        }

        // Refresh cache based on service stability and frequency of changes
