<?php

require_once 'vendor/autoload.php';

use PhpAmqpLib\Connection\AMQPStreamConnection;
use PhpAmqpLib\Message\AMQPMessage;

class ClinicStatusUpdater {
    private $rabbitMqConnection;
    private $mysqlConnection;
    private $redisClient;

    public function __construct() {
        // Initialize connections
        $this->rabbitMqConnection = new AMQPStreamConnection('localhost', 5672, 'guest', 'guest');
        $this->mysqlConnection = mysqli_connect('localhost', 'root', 'password', 'clinic_status_db');
        $this->redisClient = Redis::connect('localhost');

        // Initialize event listeners
        $this->rabbitMqConnection->setOnMessageCallback($this->handleRabbitMqMessage);
        $this->mysqlConnection->setOnQueryErrorCallback($this->handleMysqlError);

        // Start consuming messages from RabbitMQ queue
        $this->rabbitMqConnection->startConsuming('clinic_status_queue');
    }

    public function updateClinicStatus($clinicId, $newStatus) {
        // Update clinic status in MySQL database
        $query = "UPDATE clinics SET status = '$newStatus' WHERE id = $clinicId";
        mysqli_query($this->mysqlConnection, $query);

        // Cache updated clinic status using Redis
        $this->redisClient->set('clinic_status_' . $clinicId, $newStatus);
    }

    private function handleRabbitMqMessage(AMQPMessage $message) {
        // Consume message from RabbitMQ queue
        $body = json_decode($message->body, true);

        // Update clinic status based on received message
        if (isset($body['clinic_id']) && isset($body['new_status'])) {
            $this->updateClinicStatus($body['clinic_id'], $body['new_status']);
        }

        // Acknowledge message consumption
        $message->ack();
    }

    private function handleMysqlError(mysqli_sql_exception $exception) {
        // Handle MySQL error and retry query if necessary
    }
}

// Initialize ClinicStatusUpdater instance
$updater = new ClinicStatusUpdater();

// Consume messages from RabbitMQ queue
$updater->rabbitMqConnection->startConsuming('clinic_status_queue');

?>
