#include <nlohman/json.hpp>
#include <stdexcept>

using json = nlohman::json;

// Define constants for required token fields
const std::string REQUIRED_FIELDS[] = {"access_token", "expires_in", "token_type"};

// Define constants for valid token types
const std::string VALID_TOKEN_TYPES[] = {"Bearer"};

// Function to validate OAuth2 access tokens
bool validateOAuth2Token(const json& token) {
    // Check if the token contains all required fields
    bool hasRequiredFields = true;
    for (const auto& field : REQUIRED_FIELDS) {
        if (!token.contains(field)) {
            hasRequiredFields = false;
            break;
        }
    }

    // Check if the token type is valid
    bool isValidTokenType = false;
    for (const auto& tokenType : VALID_TOKEN_TYPES) {
        if (token["token_type"] == tokenType) {
            isValidTokenType = true;
            break;
        }
    }

    // Check if expires_in is a positive integer
    bool isExpiresInPositiveInteger = true;
    try {
        int expiresIn = token["expires_in"].get<int>();
        if (expiresIn <= 0) {
            isExpiresInPositiveInteger = false;
        }
    } catch (const std::exception& e) {
        isExpiresInPositiveInteger = false;
    }

    // Return true if the token is valid, false otherwise
    return hasRequiredFields && isValidTokenType && isExpiresInPositiveInteger;
}

int main() {
    // Example usage: validate an OAuth2 access token
    json token = {{ "access_token", "my_access_token" },
                   { "expires_in", 3600 },
                   { "token_type", "Bearer" }};

    if (validateOAuth2Token(token)) {
        std::cout << "The token is valid." << std::endl;
    } else {
        std::cerr << "The token is not valid." << std::endl;
    }

    return 0;
}
```

