#include <atomic>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>
#include <vector>
#include <map>
#include <unordered_map>

// Message structure
struct Message {
    std::string data;
    int priority;
};

class MessageQueue {
public:
    MessageQueue(size_t capacity) : _capacity(capacity), _messages() {}

    // Enqueue message
    void enqueue(const Message& msg) {
        if (_messages.size() >= _capacity) {
            // Handle queue full condition
            return;
        }
        std::unique_lock<std::mutex> lock(_mutex);
        _messages.push(msg);
        lock.unlock();
        _cond.notify_one(); // Notify waiting threads that a message is available
    }

    // Dequeue message
    Message dequeue() {
        std::unique_lock<std::mutex> lock(_mutex);
        while (_messages.empty()) {
            // Handle queue empty condition
            _cond.wait(lock); // Wait until a message is available or timeout occurs
        }
        Message msg = _messages.front();
        _messages.pop();
        return msg;
    }

private:
    size_t _capacity;
    std::queue<Message> _messages;
    std::mutex _mutex;
    std::condition_variable _cond;
};

int main() {
    // Create a message queue with capacity 10
    MessageQueue queue(10);

    // Enqueue and dequeue messages
    queue.enqueue(Message("Hello", 1));
    queue.enqueue(Message("World", 2));

    Message msg = queue.dequeue();
    if (msg.data == "Hello") {
        std::cout << "Received message: " << msg.data << std::endl;
    } else {
        std::cerr << "Error receiving message" << std::endl;
    }

    return 0;
}
```

This code provides a basic MessageQueue class with methods for enqueueing and dequeuing messages. It uses a queue to store the messages, along with a mutex and condition variable for thread-safe operations.']

