using System;
using System.Threading.Tasks;
using Microsoft.Azure.Cosmos;
using Newtonsoft.Json;

public class DynamicRandomValueGenerator : IDynamicRandomValueGenerator
{
    private readonly CosmosClient _cosmosClient;
    private readonly Random _random;

    public DynamicRandomValueGenerator(CosmosClient cosmosClient, Random random)
    {
        _cosmosClient = cosmosClient;
        _random = random;
    }

    public async Task<string> GenerateRandomValueAsync(string range, int count, CancellationToken cancellationToken = default)
    {
        // Validate and normalize the range
        var validatedRange = ValidateAndNormalizeRange(range);

        // Generate the random values
        var results = new List<string>();
        for (int i = 0; i < count; i++)
        {
            var value = _random.NextDouble() * (validatedRange.Max - validatedRange.Min) + validatedRange.Min;
            results.Add(value.ToString("F"));
        }

        // Store the generated values in Cosmos DB
        await _cosmosClient.GetContainer("RandomValues").UpsertItem(new RandomValue { Range = validatedRange, Values = results }, cancellationToken);

        return string.Join(", ", results);
    }

    private (double Min, double Max) ValidateAndNormalizeRange(string range)
    {
        // Implement validation and normalization logic here
    }

    public override string ToString()
    {
        return $"Random Value Generator: Range ({_random.NextDouble() * 100})";
    }
}

public class RandomValue
{
    public (double Min, double Max) Range { get; set; }
    public List<string> Values { get; set; }
}
