```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Event structure for RX_UE_INFORMATION_TAG events
typedef struct {
    int RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} event_t;

// Priority queue node
typedef struct {
    event_t event;
    int priority;
    struct node* next;
} node_t;

// Priority queue data structure
node_t* head = NULL;
node_t* tail = NULL;
int size = 0;

void enqueue(int RNTI, uint32_t CRC_INDICATION_REL8_TAG, int priority) {
    node_t* new_node = (node_t*) malloc(sizeof(node_t));
    if (!new_node) {
        printf("Error: Memory allocation failed\n");
        return;
    }
    new_node->event.RNTI = RNTI;
    new_node->event.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->priority = priority;
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    size++;
}

int dequeue() {
    int RNTI, CRC_INDICATION_REL8_TAG;
    node_t* temp = head;

    if (head == NULL) {
        printf("Error: Queue is empty\n");
        return -1;
    }

    RNTI = temp->event.RNTI;
    CRC_INDICATION_REL8_TAG = temp->event.CRC_INDICATION_REL8_TAG;
    head = temp->next;

    if (head == NULL)
        tail = NULL;

    free(temp);
    size--;
    return CRC_INDICATION_REL8_TAG;
}

void process_events() {
    while (size > 0) {
        int RNTI, CRC_INDICATION_REL8_TAG;
        CRC_INDICATION_REL8_TAG = dequeue();
        printf("Processing event: %d - %u\n", RNTI, CRC_INDICATION_REL8_TAG);
    }
}

int main() {
    // Initialize and populate the priority queue
    for (int i = 0; i < 10; i++) {
        enqueue(i, (uint32_t) i * i, i + 1);
    }

    // Process events from the priority queue
    process_events();

    return 0;
}
```

This code provides a basic implementation of a priority queue using linked lists and dynamic memory allocation. The `enqueue` function adds new elements to the end of the queue based on their priority, while the `dequeue` function removes and returns the element with the highest priority from the front of the queue.']

