#include <iostream>
#include <vector>
#include <algorithm>

void insertSortedValue(std::vector<int>& sortedVector, int value) {
    auto it = std::lower_bound(sortedVector.begin(), sortedVector.end(), value);
    if (*it == value) {
        // If the value already exists in the vector, move all occurrences to the beginning
        while (std::next(it, 1) != sortedVector.end() && *std::next(it, 1) == value) {
            std::swap(*it, *std::next(it, 1));
            it = std::lower_bound(sortedVector.begin(), sortedVector.end(), value);
        }
    } else if (value < *it) {
        // If the value is less than the current element, insert at the beginning
        sortedVector.insert(it, value);
    } else {
        // If the value is greater than or equal to the current element, insert after the current element
        it = std::next(it, 1);
        sortedVector.insert(it, value);
    }
}

int main() {
    std::vector<int> vec = {1, 2, 3};
    insertSortedValue(vec, 4);
    for (const auto& val : vec) {
        std::cout << val << " ";
    }
    return 0;
}
