        public UpdateUserPasswordService(ILogger<UpdateUserPasswordService> logger, IConfiguration config)
        {
            _logger = logger;
            _config = config;
            _dbConn = new NpgsqlConnection(_config.GetConnectionString("Database"));
        }

        public async Task<bool> UpdateUserPasswordAsync(string userId, string oldPassword, string newPassword)
        {
            try
            {
                // Validate password complexity and length
                if (!IsValidPassword(newPassword))
                {
                    _logger.LogError("Invalid password format");
                    return false;
                }

                // Hash new password using bcrypt
                byte[] salt = Guid.NewGuid().ToByteArray();
                string hashedNewPassword = Bcrypt.Hash(newPassword, salt);

                // Update user password in the database
                await using (NpgsqlCommand cmd = _dbConn.CreateCommand())
                {
                    cmd.CommandText = "UPDATE users SET password_hash = @hashed_password WHERE id = @user_id";
                    cmd.Parameters.AddWithValue("@user_id", userId);
                    cmd.Parameters.AddWithValue("@hashed_password", hashedNewPassword);

                    await cmd.ExecuteNonQueryAsync();
                }

                return true;
            }
            catch (NpgsqlException ex)
            {
                _logger.LogError(ex, "Error updating user password");
                throw;
            }
