class HealthMonitor {
public:
    HealthMonitor(boost::asio::io_context& io) : io_(io), timer_(io, boost::posix_time::seconds(1)) {}

    void startMonitoring() {
        while (true) {
            for (auto& endpoint : endpoints_) {
                std::cout << "Evaluating health of endpoint: " << endpoint.ip << endl;
                // Evaluate latency and throughput
                int latency = evaluateLatency(endpoint);
                int throughput = evaluateThroughput(endpoint);

                // Update endpoint with new values
                endpoint.latency = latency;
                endpoint.throughput = throughput;

                // Print results
                std::cout << "Endpoint: " << endpoint.ip << ", Latency: " << latency << ", Throughput: " << throughput << endl;
            }

            // Wait for 1 second before re-evaluating
            timer_.expires_at(boost::get_system_time() + boost::posix_time::seconds(1));
            timer_.async_wait([this](boost::system::error_code ec) {
                if (!ec) {
                    startMonitoring();
                }
            });
        }
    }

private:
    boost::asio::io_context& io_;
    boost::asio::deadline_timer timer_;

    int evaluateLatency(NetworkEndpoint& endpoint) {
