#include <semaphore.h>
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Custom serialization format for semaphore states
typedef struct {
    int value;
} SemaphoreState;

// Function to serialize a semaphore state
void* serializeSemaphore(sem_t* sem) {
    SemaphoreState* state = (SemaphoreState*)malloc(sizeof(SemaphoreState));
    *state = (SemaphoreState){semctl(sem, 0, GETVAL, 0)};
    return state;
}

// Function to deserialize a semaphore state
int deserializeSemaphore(void* serialized_state) {
    SemaphoreState* state = (SemaphoreState*)serialized_state;
    semctl(NULL, 0, SETVAL, state->value);
    free(state);
    return 0;
}

// Thread function for waiting on a semaphore
void* wait_on_semaphore(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
    sem_t* sem = (sem_t*)arg;
    while (1) {
        sem_wait(sem);
        // Process semaphore value here
        printf("Semaphore value: %d\n", semctl(sem, 0, GETVAL, 0));
    }
    return NULL;
}

// Thread function for signaling a semaphore
void* signal_semaphore(void* arg) {
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
    sem_t* sem = (sem_t*)arg;
    while (1) {
        sem_post(sem);
        // Process semaphore value here
        printf("Semaphore value: %d\n", semctl(sem, 0, GETVAL, 0));
    }
    return NULL;
}

int main() {
    // Initialize semaphores with a given initial value
    sem_t* semaphore = sem_open("/my_semaphore", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR, 1);

    // Create threads for waiting on and signaling the semaphore
    pthread_t wait_thread, signal_thread;
    pthread_create(&wait_thread, NULL, wait_on_semaphore, (void*)semaphore);
    pthread_create(&signal_thread, NULL, signal_semaphore, (void*)semaphore);

    // Wait for threads to finish
    pthread_join(wait_thread, NULL);
    pthread_join(signal_thread, NULL);

    return 0;
}
