    DynamicStringContainer() : uuidGen_(boost::uuids::random_generator()) {}

    // Insert a string into the container
    void insertAfterOrAppend(const std::string& str, const boost::uuids::uuid& id) {
        if (str.empty())
            throw InvalidOperation("Empty string");

        if (str.length() > maxStrLen_)
            throw InvalidOperation("String exceeds allowed length limits");

        // Log the operation
        logOperation(id, "inserted", str);

        // Handle concurrent access with lock-free data structure
        std::unique_lock<std::shared_mutex> locker(mutex_);
        map_[id] = str;
    }

    // Remove a string from the container
