        // Log the operation
        logOperation(id, "removed");

        // Handle concurrent access with lock-free data structure
        std::unique_lock<std::shared_mutex> locker(mutex_);
        if (map_.erase(id))
            logOperation(id, "successfully removed");
        else
            throw InvalidOperation("String not found in container");
    }

    // Get a string from the container
