#include <iostream>
#include <random>
#include <thread>
#include <mutex>
#include <chrono>

class RandomEngine {
public:
    static constexpr uint64_t DEFAULT_SEED = 0x123456789abcdef;

    struct SeedStrategy {
        virtual ~SeedStrategy() {}
        virtual uint64_t generateSeed() const = 0;
    };

    class ConstantSeed : public SeedStrategy {
    public:
        explicit ConstantSeed(uint64_t seed) : seed_(seed) {}

        uint64_t generateSeed() const override { return seed_; }

    private:
        uint64_t seed_;
    };

    class SystemSeed : public SeedStrategy {
    public:
        explicit SystemSeed() {}

        uint64_t generateSeed() const override {
            // Acquire system-provided seed from /dev/urandom or equivalent
            return 0; // Replace with actual implementation
        }
    };

    class CustomSeed : public SeedStrategy {
    public:
        explicit CustomSeed(std::function<uint64_t()> seedGenerator) : seedGenerator_(seedGenerator) {}

        uint64_t generateSeed() const override { return seedGenerator_(); }

    private:
        std::function<uint64_t()> seedGenerator_;
    };

    RandomEngine(SeedStrategy& seedStrategy, bool cachingEnabled = true)
        : seedStrategy_(seedStrategy), rng_(nullptr), cache_(cachingEnabled) {
        initialize();
    }

    ~RandomEngine() {
        cleanup();
    }

    uint32_t uniformInt(uint32_t min, uint32_t max) {
        if (!cache_.isInitialized()) {
            generateAndCache();
        }
        return std::uniform_int_distribution<>(min, max)(rng_);
    }

    double uniformFloat(double min, double max) {
        if (!cache_.isInitialized()) {
            generateAndCache();
        }
        return std::uniform_real_distribution<>(min, max)(rng_);
    }

private:
    void initialize() {
        uint64_t seed = seedStrategy_.generateSeed();
        rng_ = new std::mt19937(seed);
        cache_.initialize(*rng_);
    }

    void cleanup() {
        if (cache_.isInitialized()) {
            cache_.cleanup();
        }
        delete rng_;
        rng_ = nullptr;
    }

    void generateAndCache() {
        std::uniform_int_distribution<> intDist(0, INT_MAX);
        uint32_t randomInt = intDist(*rng_);
        cache_.store(randomInt);

        std::uniform_real_distribution<> floatDist(0.0, 1.0);
        double randomFloat = floatDist(*rng_);
        cache_.store(randomFloat);
    }

    SeedStrategy& seedStrategy_;
    std::unique_ptr<std::mt19937> rng_;
    class Cache {
    public:
        Cache(bool cachingEnabled) : initialized_(false), maxAge_(10000), queueSize_(0) {
            if (cachingEnabled) {
                // Initialize cache with a default capacity
                capacity_ = 1024;
                // Set up the underlying data structure
                data_.resize(capacity_);
            }
        }

        void initialize(std::mt19937& rng) {
            initialized_ = true;
            std::generate_n(data_.begin(), capacity_, [&rng]() { return static_cast<uint32_t>(rng()); });
        }

        void store(uint32_t value) {
            if (!initialized_) {
                // Cache not initialized, no-op
                return;
            }
            // Check for expired entries and remove them from the cache
            while (queueSize_ > 0 && (data_[queueSize_ - 1].time + maxAge_) < std::chrono::steady_clock::now().count) {
                --queueSize_;
                data_[--queueSize_] = uint32_t{0}; // Zero out the removed entry
            }
            // Add the new value to the cache
            data_[queueSize_++] = value;
        }

        void cleanup() {
            if (!initialized_) {
                // Cache not initialized, no-op
                return;
            }
            for (size_t i = 0; i < queueSize_; ++i) {
                data_[i] = uint32_t{0}; // Zero out all cache entries
            }
            queueSize_ = 0;
        }

        bool isInitialized() const { return initialized_; }

    private:
        bool initialized_;
        size_t capacity_;
        size_t maxAge_;
        size_t queueSize_;
        std::array<uint32_t, 1024> data_;
    };
};
