// Concurrency and Synchronization:
class CustomRWLock {
public:
    void readLock() {
        while (readers_ > 0 || writers_.load()) {
            std::this_thread::yield();
        }
        readers_++;
    }

    void writeLock() {
        while (!writers_.exchange(true)) {
            std::this_thread::yield();
        }
    }

    void unlock() {
        if (readers_-- == 0) {
            writers_.store(false);
        }
    }

private:
    std::atomic<bool> writers{false};
    std::atomic<int> readers{0};
};

