["Here is the code block for the `renderDynamicGrid` function:

```javascript
function renderDynamicGrid(items) {
  const gridTemplateColumns = [];
  const gridItems = [];

  items.forEach((item) => {
    if (!isValidItem(item)) return;

    const sanitizedText = sanitizeText(item.text);
    const imageLoader = item.image_url ? loadImage(item.image_url) : null;
    const gridItem = document.createElement('div');
    gridItem.dataset.id = item.id;
    gridItem.style.gridColumn = `${item.width}fr`;
    gridItem.textContent = sanitizedText;

    if (imageLoader) {
      gridItem.appendChild(imageLoader);
    }

    gridItems.push(gridItem);

    gridTemplateColumns.push(`${item.width}fr`);
  });

  const gridContainer = document.createElement('div');
  gridContainer.style.display = 'grid';
  gridContainer.style.gridTemplateColumns = gridTemplateColumns.join(' ');
  gridContainer.append(...gridItems);

  return gridContainer;
}

function isValidItem(item) {
  if (!item.id || !item.text) {
    console.error('Invalid item: missing id or text');
    return false;
  }

  if (isNaN(Number(item.width)) || isNaN(Number(item.height))) {
    console.error('Invalid item: width or height must be a number');
    return false;
  }

  if (!/^[a-zA-Z0-9]+$/.test(item.id)) {
    console.error('Invalid item: id must only contain letters and numbers');
    return false;
  }

  if (!/^[a-zA-Z0-9\s]+$/.test(item.text)) {
    console.error('Invalid item: text must only contain letters, numbers, and spaces');
    return false;
  }

  return true;
}

function sanitizeText(text) {
  // Sanitize text to prevent XSS attacks
  return text.replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

async function loadImage(url) {
  const image = new Image();
  await new Promise((resolve) => {
    image.onload = resolve;
    image.onerror = () => console.error(`Error loading image: ${url}`);
    image.src = url;
  });
  return image;
}
