// Define the data ingestion pipeline
class DataIngestionPipeline {
    // Initialize the pipeline with external sources and cloud storage
    public DataIngestionPipeline(List<ExternalSource> externalSources, CloudStorage cloudStorage) {
        this.externalSources = externalSources;
        this.cloudStorage = cloudStorage;
        this.dataQueue = new ConcurrentLinkedQueue<>();
        this.processingThreads = new ArrayList<>();
    }

    // Start the pipeline with pause and resume functionality
    public void start() {
        for (ExternalSource source : externalSources) {
            source.start();
        }
        // Initialize processing threads
        for (int i = 0; i < numProcessingThreads; i++) {
            ProcessingThread thread = new ProcessingThread(dataQueue, cloudStorage);
            processingThreads.add(thread);
            thread.start();
        }
    }

    // Pause the pipeline
    public void pause() {
        for (ExternalSource source : externalSources) {
            source.pause();
        }
        // Interrupt processing threads
        for (ProcessingThread thread : processingThreads) {
            thread.interrupt();
        }
    }

    // Resume the pipeline
    public void resume() {
        for (ExternalSource source : externalSources) {
            source.resume();
        }
        // Restart processing threads
        for (ProcessingThread thread : processingThreads) {
            thread.start();
        }
    }

