#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for ConnectionStatusNotification
typedef struct {
    int UE_ID;
    time_t timestamp;
    enum { ESTABLISHED, DISCONNECTED } status;
} ConnectionStatusNotification;

// Define a thread-safe data structure to manage notifications
typedef struct {
    ConnectionStatusNotification *notifications;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NotificationList;

// Initialize the notification list
NotificationList *notification_list_init(size_t initial_capacity) {
    NotificationList *list = (NotificationList *)malloc(sizeof(NotificationList));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Add a new notification to the list
void notification_list_add(NotificationList *list, ConnectionStatusNotification *notification) {
    if (list->size >= list->capacity) {
        // Resize the list if it's full
        size_t new_capacity = list->capacity * 2;
        NotificationList *new_list = (NotificationList *)malloc(sizeof(NotificationList));
        new_list->capacity = new_capacity;
        new_list->size = list->size;
        new_list->notifications = (ConnectionStatusNotification *)malloc(new_capacity * sizeof(ConnectionStatusNotification));
        memcpy(new_list->notifications, list->notifications, list->size * sizeof(ConnectionStatusNotification));
        free(list);
        list = new_list;
    }
    pthread_mutex_lock(&list->lock);
    list->notifications[list->size++] = *notification;
    pthread_mutex_unlock(&list->lock);
}

// Retrieve a notification from the list
ConnectionStatusNotification *notification_list_get(NotificationList *list, size_t index) {
    if (index >= list->size) {
        return NULL; // Index out of bounds
    }
    pthread_mutex_lock(&list->lock);
    ConnectionStatusNotification *notification = &list->notifications[index];
    pthread_mutex_unlock(&list->lock);
    return notification;
}

// Free the notification list
void notification_list_free(NotificationList *list) {
    free(list->notifications);
    free(list);
}

// Define a thread-safe function to process notifications
void *process_notifications(void *arg) {
    NotificationList *list = (NotificationList *)arg;
    // Process notifications here
    return NULL;
}

int main() {
    // Initialize the notification list with an initial capacity of 1000
    NotificationList *list = notification_list_init(1000);

    // Add some sample notifications to the list
    ConnectionStatusNotification notification1 = {12345, time(NULL), ESTABLISHED};
    ConnectionStatusNotification notification2 = {67890, time(NULL), DISCONNECTED};
    notification_list_add(list, &notification1);
    notification_list_add(list, &notification2);

    // Retrieve and process a notification from the list
    size_t index = 0;
    while (ConnectionStatusNotification *notification = notification_list_get(list, index++)) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_notifications, list);
        pthread_join(thread);
    }

    // Free the notification list when done
    notification_list_free(list);

    return 0;
}

