import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class BattleReportGeneratorController {

    @Autowired
    private TypeEffectivenessService typeEffectivenessService;

    @Autowired
    private MoveDatasetService moveDatasetService;

    @Autowired
    private InGameEventService inGameEventService;

    @GetMapping("/battle-reports")
    public List<BattleReport> generateBattleReports(@RequestHeader String apiKey) {
        // Validate API key and rate limit
        if (!validateApiKey(apiKey)) {
            return new ArrayList<>();
        }

        // Retrieve current in-game events
        InGameEvents inGameEvents = inGameEventService.getLatestEvents();

        // Generate battle reports using type effectiveness, move datasets, and in-game events
        List<BattleReport> battleReports = new ArrayList<>();
        for (InGameEvent event : inGameEvents) {
            BattleReport report = generateBattleReport(event, typeEffectivenessService, moveDatasetService);
            battleReports.add(report);
        }

        return battleReports;
    }

    @Caching(cacheNames = "battle-reports", keyGenerator = "org.springframework.cache.support.SimpleKeyGenerator")
    public BattleReport generateBattleReport(InGameEvent event, TypeEffectivenessService typeEffectivenessService, MoveDatasetService moveDatasetService) {
        // Calculate type effectiveness for each Pokémon
        List<TypeEffectiveness> typeEffectivenesses = typeEffectivenessService.calculateTypeEffectiveness(event.getPokémon());

        // Retrieve relevant moves from the move dataset
        List<Move> moves = moveDatasetService.getRelevantMoves(typeEffectivenesses);

        // Generate battle report based on type effectiveness, moves, and in-game event
        BattleReport report = new BattleReport(event, typeEffectivenesses, moves);
        return report;
    }

