package com.example.api_gateway;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.gateway.*;
import org.springframework.security.oauth2.client.registration.*;
import org.springframework.web.reactive.function.server.*;

@SpringBootApplication
public class ApiGatewayApplication {

    public static void main(String[] args) {
        SpringApplication.run(ApiGatewayApplication.class, args);
    }
}

// Dynamic Routing Configuration
@Configuration
public class GatewayConfig {

    @Bean
    public RouteLocator dynamicRouting(RouteLocatorBuilder builder) {
        return builder.routes()
                .route("legacy_system", r -> r.path("/v1/legacy").uri("http://localhost:8080"))
                .route("third_party_api", r -> r.path("/v2/third-party").uri("https://api.thirdparty.com"))
                .route("real_time_data_processing", r -> r.path("/v3/processing").uri("ws://data-processing-server:9080"));
    }
}

// OAuth2 and JWT Authentication Configuration
