public class SecurityConfig {

    @Bean
    public OAuth2ClientRegistrationRepository oAuth2ClientRegistrationRepository() {
        return new InMemoryOAuth2ClientRegistrationRepository(
                Registration.withRegistrationId("client")
                        .clientId("client-id")
                        .clientSecret("client-secret")
                        .authorizationUri("https://example.com/oauth/authorize")
                        .tokenUri("https://example.com/oauth/token")
                        .build());
    }

    @Bean
    public SecurityWebFilterChain securityWebFilterChain(SecurityWebFilterChain chain) {
        return chain.build();
    }
}

// Rate Limiting Configuration
@Configuration
public class RateLimiterConfig {

    @Bean
    public RateLimiter rateLimiter() {
        return new DefaultRateLimiter(100, 60);
    }
}

// Caching Strategy using Distributed Caches
@Configuration
public class CacheConfig {

    @Bean
    public RedisTemplate<String, String> redisTemplate() {
        return new RedisTemplate<>();
    }
}

// Query Pattern Optimization and Latency Reduction
@Configuration
