void process_log_file(const char *filename) {
    // Open the log file and read its contents
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening log file");
        return;
    }

    // Parse the log entries and compute moving averages
    LogEntry log_entry;
    while (fscanf(file, "%d %s %ld", &log_entry.service_id, log_entry.service_name, &log_entry.timestamp) == 3) {
        for (int i = 0; i < log_entry.num_fields; i++) {
            fscanf(file, "%lf", &log_entry.values[i]);
        }

        // Compute the moving average
        compute_moving_average(&log_entry);
    }

    // Store the results in the time-series database
    store_results_in_timeseries_db();
}

void compute_moving_average(LogEntry *log_entry) {
    double sum = 0.0;
    for (int i = 0; i < log_entry->num_fields; i++) {
        sum += log_entry->values[i];
    }

    // Compute the moving average
    double avg = sum / log_entry->num_fields;

    // Update the log entry with the moving average
    log_entry->values[4] = avg;
}

