#include <iostream>
#include <filesystem>
#include <opencv2/opencv.hpp>
#include <boost/filesystem.hpp>

namespace fs = boost::filesystem;

int main(int argc, char* argv[]) {
    if (argc != 3) {
        std::cerr << "Usage: " << argv[0] << " input_directory output_directory" << std::endl;
        return 1;
    }

    try {
        fs::path input_dir(argv[1]);
        fs::path output_dir(argv[2]);

        if (!fs::is_directory(input_dir)) {
            std::cerr << "Input directory does not exist or is not a directory." << std::endl;
            return 1;
        }

        if (!fs::is_directory(output_dir)) {
            std::cerr << "Output directory does not exist or is not a directory." << std::endl;
            return 1;
        }

        for (const auto& entry : fs::directory_iterator(input_dir)) {
            if (entry.is_directory()) {
                continue; // Skip directories
            }

            const auto& file_path = entry.path();
            const auto& file_name = file_path.filename();

            // Check supported formats
            cv::String format;
            if (file_name.endswith(".jpg") || file_name.endswith(".jpeg")) {
                format = "JPEG";
            } else if (file_name.endswith(".png")) {
                format = "PNG";
            } else if (file_name.ends_with(".bmp")) {
                format = "BMP";
            } else if (file_name.ends_with(".heic") || file_name.ends_with(".heif")) {
                format = "HEIC";
            } else {
                std::cerr << "Unsupported file format: " << file_path.filename().string() << std::endl;
                continue;
            }

            // Process the image
            cv::Mat image = cv::imread(file_path.string());
            if (image.empty()) {
                std::cerr << "Failed to load image: " << file_path.filename().string() << std::endl;
                continue;
            }

            // Convert to SVG
            cv::String svg_file_name = output_dir / (file_name.stem().string() + ".svg");
            cv::imwrite(svg_file_name.string(), image);

        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

