public class Workflow {
    private List<Task> tasks = new ArrayList<>();

    public void addTask(Task task) {
        tasks.add(task);
    }

    public Map<String, Future<Boolean>> execute(ExecutorService executor) {
        Map<String, Future<Boolean>> futures = new HashMap<>();
        for (Task task : tasks) {
            futures.put(task.getName(), executor.submit(() -> task.execute()));
        }
        return futures;
    }
}

