#include "file_system_resource.h"
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

int file_system_resource_init(int fd) {
    if (fd < 0) {
        // invalid or closed file descriptor
        LOG_ERR("Invalid file descriptor");
        return -1;
    }

    int ret = fstat(fd, &st);
    if (ret == -1) {
        // failed to stat the file
        LOG_ERR("Failed to stat the file");
        close(fd);
        return -1;
    }

    if (!S_ISREG(st.st_mode)) {
        // not a regular file
        LOG_WARN("Not a regular file");
        close(fd);
        return -1;
    }

    // reopen the file descriptor if it's closed or invalid
    int new_fd = open(path, O_RDONLY);
    if (new_fd < 0) {
        // failed to reopen the file
        LOG_ERR("Failed to reopen the file");
        close(new_fd);
        return -1;
    }

    return new_fd;
}

