['Here is the code block for the distributed caching framework:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <chrono>
#include <thread>

class CacheNode {
public:
    std::unordered_map<std::string, std::pair<std::string, int>> cache;
    int hitCount = 0;
    int lastAccessedTime = 0;

    void put(const std::string& key, const std::string& value) {
        if (cache.find(key) != cache.end()) {
            // Update existing entry
            cache[key].first = value;
            cache[key].second = ++hitCount;
            lastAccessedTime = std::chrono::system_clock::now().time_since_epoch().count();
        } else {
            // New entry
            cache[key] = {value, 1};
            hitCount = 1;
            lastAccessedTime = std::chrono::system_clock::now().time_since_epoch().count();
        }
    }

    bool get(const std::string& key) {
        if (cache.find(key) != cache.end()) {
            // Hit
            hitCount++;
            lastAccessedTime = std::chrono::system_clock::now().time_since_epoch().count();
            return true;
        }
        return false;
    }

    void expire(int maxAge) {
        for (auto& entry : cache) {
            if (std::chrono::system_clock::now().time_since_epoch().count() - lastAccessedTime > maxAge * 1000) {
                // Expired
                cache.erase(entry.first);
            }
        }
    }

    void evict(int threshold) {
        for (auto& entry : cache) {
            if (hitCount < threshold) {
                // Evict
                cache.erase(entry.first);
            }
        }
    }
};

class DistributedCache {
public:
    std::unordered_map<std::string, CacheNode*> nodes;
    int maxSize = 1000;

    void put(const std::string& key, const std::string& value) {
        for (auto& node : nodes) {
            if (node.second->put(key, value)) {
                return;
            }
        }
        // Fallback to primary node
        nodes.begin()->second->put(key, value);
    }

    bool get(const std::string& key) {
        for (auto& node : nodes) {
            if (node.second->get(key)) {
                return true;
            }
        }
        return false;
    }

    void expire(int maxAge) {
        for (auto& node : nodes) {
            node.second->expire(maxAge);
        }
    }

    void evict(int threshold) {
        for (auto& node : nodes) {
            node.second->evict(threshold);
        }
    }
};

int main() {
    DistributedCache cache;

    // Initialize nodes
    for (int i = 0; i < 3; i++) {
        CacheNode* node = new CacheNode();
        cache.nodes.insert({std::to_string(i), node});
    }

    // Add entries to the cache
    cache.put("key1", "value1");
    cache.put("key2", "value2");

    // Check if key-value pairs exist in the cache
    if (cache.get("key1")) {
        std::cout << "Key 'key1' exists in the cache." << std::endl;
    } else {
        std::cout << "Key 'key1' does not exist in the cache." << std::endl;
    }

    // Expire entries in the cache
    cache.expire(3600);  // Expire after 1 hour

    return 0;
}

