extern crate cloud_storage;
extern crate logging;
extern crate monitoring;
extern crate alerting;

use cloud_storage::FileStorage;
use logging::Logger;
use monitoring::Monitor;
use alerting::Alert;

struct FileService {
    file_storage: FileStorage,
    logger: Logger,
    monitor: Monitor,
    alert: Alert,
}

impl FileService {
    fn new(file_storage: FileStorage, logger: Logger, monitor: Monitor, alert: Alert) -> Self {
        FileService { file_storage, logger, monitor, alert }
    }

    fn create_dir(&self, dir_path: &str) -> Result<(), String> {
        match self.file_storage.create_dir(dir_path) {
            Ok(_) => Ok(()),
            Err(err) => Err(err.to_string()),
        }
    }

    fn list_dirs(&self, path: &str) -> Result Vec<String>, String {
        match self.file_storage.list_dirs(path) {
            Ok(dirs) => Ok(dirs),
            Err(err) => Err(err.to_string()),
        }
    }

    fn delete_dir(&self, dir_path: &str) -> Result<(), String> {
