        }
    }

    bool isValidSession(int userId) {
        unique_lock<mutex> lock(mutex_);
        return sessions_.count(userId);
    }

private:
    mutex mutex_;
    condition_variable cv_;
    map<int, unique_ptr<Session>> sessions_;

    class Session {
    public:
        string data_;
    };
};

int main() {
    // usage example
    SessionManager sessionManager;

    sessionManager.startSession(123);
    sessionManager.updateSession(123, "logged in");
    if (sessionManager.isValidSession(123)) {
        cout << "User 123 is logged in" << endl;
    }

    return 0;
}
