@Path("/users")
public class UserProfileService {

    private static final Logger LOGGER = LoggerFactory.getLogger(UserProfileService.class);

    @Inject
    private AuthenticationManager authenticationManager;

    @Inject
    private DatabaseConnection databaseConnection;

    @GET
    @Path("/{id}")
    public Response getUserProfile(@PathParam("id") String userId) {
        try {
            User user = databaseConnection.getUserProfile(userId);
            if (user == null) {
                return Response.status(404).build();
            }
            return Response.ok(user).build();
        } catch (Exception e) {
            LOGGER.error("Error fetching user profile: {}", e.getMessage());
            return Response.status(500).build();
        }
    }

    @GET
    public Response getAllUserProfiles() {
        try {
            List<User> users = databaseConnection.getAllUserProfiles();
            if (users == null || users.isEmpty()) {
                return Response.status(404).build();
            }
            return Response.ok(users).build();
        } catch (Exception e) {
            LOGGER.error("Error fetching all user profiles: {}", e.getMessage());
            return Response.status(500).build();
        }
    }

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    public Response createUserProfile(JsonNode jsonNode) {
        try {
            User user = new User(jsonNode);
            databaseConnection.createUserProfile(user);
            return Response.status(201).build();
        } catch (Exception e) {
            LOGGER.error("Error creating user profile: {}", e.getMessage());
            return Response.status(500).build();
        }
    }

    @PUT
    @Path("/{id}")
    @Consumes(MediaType.APPLICATION_JSON)
    public Response updateUserProfile(@PathParam("id") String userId, JsonNode jsonNode) {
        try {
            User user = databaseConnection.getUserProfile(userId);
            if (user == null) {
                return Response.status(404).build();
            }
            user.update(jsonNode);
            databaseConnection.updateUserProfile(user);
            return Response.ok().build();
        } catch (Exception e) {
            LOGGER.error("Error updating user profile: {}", e.getMessage());
            return Response.status(500).build();
        }
    }

    @DELETE
    @Path("/{id}")
    public Response deleteUserProfile(@PathParam("id") String userId) {
        try {
            User user = databaseConnection.getUserProfile(userId);
            if (user == null) {
                return Response.status(404).build();
            }
            databaseConnection.deleteUserProfile(user);
            return Response.ok().build();
        } catch (Exception e) {
            LOGGER.error("Error deleting user profile: {}", e.getMessage());
            return Response.status(500).build();
        }
    }

    @Path("/auth")
    public class AuthenticationEndpoint {

        @POST
        @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
        public Response authenticateUser(JsonNode jsonNode) {
            try {
                String username = jsonNode.get("username").asText();
                String password = jsonNode.get("password").asText();
                if (authenticationManager.authenticate(username, password)) {
                    return Response.ok().build();
                } else {
                    return Response.status(401).build();
                }
            } catch (Exception e) {
                LOGGER.error("Error authenticating user: {}", e.getMessage());
                return Response.status(500).build();
            }
        }
    }

    @Path("/mfa")
    public class MFAEndpoint {

        @POST
        @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
        public Response authenticateUserWithMFA(JsonNode jsonNode) {
            try {
                String username = jsonNode.get("username").asText();
                String mfaToken = jsonNode.get("mfaToken").asText();
                if (authenticationManager.authenticateWithMFA(username, mfaToken)) {
                    return Response.ok().build();
                } else {
                    return Response.status(401).build();
                }
            } catch (Exception e) {
                LOGGER.error("Error authenticating user with MFA: {}", e.getMessage());
                return Response.status(500).build();
            }
        }
    }
