#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>
#include <queue>

class SessionManager {
public:
    SessionManager(size_t poolSize) : pool_(poolSize), gcFrequency_(1000) {}

    void start() {
        thread_ = std::thread([this]() {
            while (true) {
                // Garbage collection
                if (gcCount_++ >= gcFrequency_) {
                    gc();
                    gcCount_ = 0;
                }
                // Session operations
                sessionQueue_.wait_and_pop();
            }
        });
    }

    void putSession(const std::string& sessionId, const std::string& data) {
        std::unique_lock<std::mutex> lock(pool_mutex_);
        sessions_[sessionId] = data;
        pool_.push(sessionId);
        lock.unlock();
        sessionQueue_.notify_one();
    }

    std::string getSession(const std::string& sessionId) {
        std::unique_lock<std::mutex> lock(pool_mutex_);
        if (sessions_.count(sessionId)) {
            return sessions_[sessionId];
        }
        return ""; // or throw an exception
    }

private:
    void gc() {
        while (!pool_.empty()) {
            size_t sessionId = pool_.front();
            pool_.pop();
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
            if (gcSessions_.count(sessionId)) {
                sessions_.erase(sessionId);
                gcSessions_.erase(sessionId);
            }
        }
    }

    void expireSessions(size_t threshold) {
        for (const auto& session : sessions_) {
            if (session.second.size() > threshold) {
                sessions_.erase(session.first);
                pool_.push(session.first);
            }
        }
    }

    std::mutex pool_mutex_;
    std::condition_variable sessionQueue_;
    std::queue<std::string> pool_;
    std::map<std::string, std::string> sessions_;
    size_t gcCount_ = 0;
    size_t gcFrequency_ = 1000;
    std::map<std::string, size_t> gcSessions_;
};

int main() {
    SessionManager sessionManager(100);
    sessionManager.start();

    // Usage
    sessionManager.putSession("session1", "some data");
    sessionManager.putSession("session2", "another data");

    return 0;
}
```

