#include <iostream>
#include <string>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

class DNSCache {
public:
    DNSCache(int cacheSize, int flushInterval) : 
        cache_(cacheSize), flushInterval_(flushInterval) {}

    void set(const std::string& domain, const std::string& ip) {
        cache_[domain] = ip;
    }

    std::string get(const std::string& domain) {
        if (auto it = cache_.find(domain); it != cache_.end()) {
            return it->second;
        } else {
            // DNS lookup failed, try again later
            return "";
        }
    }

private:
    class Cache {
    public:
        int size;
        std::mutex mutex;
        std::condition_variable cond;
        bool shouldFlush;

        Cache(int size) : size(size), shouldFlush(false) {}

        void set(const std::string& domain, const std::string& ip) {
            std::unique_lock<std::mutex> lock(mutex);
            cache_[domain] = ip;
            size--;
            if (size <= 0) {
                shouldFlush = true;
            }
        }

        std::string get(const std::string& domain) {
            std::unique_lock<std::mutex> lock(mutex);
            if (auto it = cache_.find(domain); it != cache_.end()) {
                return it->second;
            } else {
                // DNS lookup failed, try again later
                return "";
            }
        }

        void flush() {
            std::lock_guard<std::mutex> lock(mutex);
            cache_.clear();
            size = 0;
            shouldFlush = false;
        }

    private:
        std::map<std::string, std::string> cache_;
    };

    Cache* cache_;

    int flushInterval_;

    void asyncFlush() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(flushInterval_));
            if (!cache_->shouldFlush) continue;
            cache_->flush();
            break;
        }
    }

    void runAsyncFlush() {
        thread_ = std::thread(&DNSCache::asyncFlush, this);
    }

    std::thread thread_;

    DNSCache(int cacheSize, int flushInterval) : 
        cache_(new Cache(cacheSize)), flushInterval_(flushInterval), runAsyncFlush() {}
};

int main() {
    // Initialize the cache and start the async flush
    DNSCache dnsCache(1000, 60); // 1k entries, flush every minute

    return 0;
}
```']

