    time_t start_time = time(NULL);

    // Update the record(s)
    for (int i = 0; i < 10; i++) {
        Record* record = malloc(sizeof(Record));
        record->value = rand() % 100;
        printf("Updated record value: %d\n", record->value);
        // Save the updated record to disk or database
        fwrite(record, sizeof(Record), 1, fopen("records.txt", "wb"));
    }

    // Get the end time of the update process
    time_t end_time = time(NULL);

    // Calculate the duration of the update process
    double duration = difftime(end_time, start_time);

    printf("Update and persist records took %.2f seconds\n", duration);
}

int main() {
    // Create a thread pool for concurrent updates
    pthread_t threads[5];
    int i;
    for (i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, update_and_persist_records, NULL);
    }

    // Wait for all threads to complete
    for (i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
