    private static final String MQTT_HOST = "tcp://localhost:1883";

    public void start() {
        // Start Kafka Consumer
        KafkaConsumer<String, String> kafkaConsumer = new KafkaConsumer<>(KAFKA_BOOTSTRAP_SERVERS,
                new StringDeserializer(), new StringSerializer());
        kafkaConsumer.subscribe(Collections.singleton("iot_data_topic"));

