// Define the NFAPI_CRC_INDICATION_PDU_T structure
struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    std::string CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

class DoublyLinkedList {
public:
    DoublyLinkedList() : head_(nullptr), tail_(nullptr) {}

    // Create and populate the list
    void createAndPopulate(int numNodes, bool verbose = false) {
        for (int i = 0; i < numNodes; ++i) {
            NFAPI_CRC_INDICATION_PDU_T* node = new NFAPI_CRC_INDICATION_PDU_T;
            // Initialize node fields with random values
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(1, 100);
            node->RX_UE_INFORMATION_TAG = "Node_" + std::to_string(i);
            node->RNTI = dis(gen);
            node->CRC_INDICATION_REL8_TAG = "Tag_" + std::to_string(i);
            node->CRCFLAG = (dis(gen) % 2 == 0);

            // Add the node to the list
            if (head_ == nullptr) {
                head_ = node;
                tail_ = node;
            } else {
                NFAPI_CRC_INDICATION_PDU_T* prevTail = tail_;
                tail_ = node;
                prevTail->next = node;
                node->prev = prevTail;
            }

            // Handle memory allocation failures
            if (verbose) {
                std::cout << "Node created: " << i << std::endl;
            }
        }
    }

    // Insert a new node at the beginning of the list
    void insertAtBeginning(NFAPI_CRC_INDICATION_PDU_T* newNode) {
        if (head_ == nullptr) {
            head_ = newNode;
            tail_ = newNode;
        } else {
            newNode->next = head_;
            head_->prev = newNode;
            head_ = newNode;
        }
    }

    // Insert a new node at the end of the list
    void insertAtEnd(NFAPI_CRC_INDICATION_PDU_T* newNode) {
        if (tail_ == nullptr) {
            head_ = newNode;
            tail_ = newNode;
        } else {
            newNode->prev = tail_;
            tail_->next = newNode;
            tail_ = newNode;
        }
    }

    // Delete a node from the list
    void deleteNode(NFAPI_CRC_INDICATION_PDU_T* node) {
        if (node == head_) {
            head_ = node->next;
        }
        if (node == tail_) {
            tail_ = node->prev;
        }
        node->prev = nullptr;
        node->next = nullptr;

        // Handle memory deallocation
        delete node;
    }

private:
    NFAPI_CRC_INDICATION_PDU_T* head_;
    NFAPI_CRC_INDICATION_PDU_T* tail_;
};

int main() {
    DoublyLinkedList dll;
    int numNodes = 1000000; // Create a list with up to 1 million nodes

    // Create and populate the list
    dll.createAndPopulate(numNodes);

    return 0;
}
