        if (rt_dp->nfa_pi_crc_indication_pdu_ts == NULL) {
            rt_dp->nfa_pi_crc_indication_pdu_ts = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            rt_dp->nfa_pi_crc_indication_pdu_ts = new_pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *current_pdu = rt_dp->nfa_pi_crc_indication_pdu_ts;
            while (current_pdu) {
                if (current_pdu->RNTI == RNTI) break;
                current_pdu = current_pdu->next;
            }
            if (!current_pdu || current_pdu->RNTI != RNTI) {
                rt_dp->nfa_pi_crc_indication_pdu_ts = realloc(rt_dp->nfa_pi_crc_indication_pdu_ts, (rt_dp->data_processor_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                rt_dp->nfa_pi_crc_indication_pdu_ts[rt_dp->data_processor_count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
                rt_dp->nfa_pi_crc_indication_pdu_ts[rt_dp->data_processor_count].RNTI = RNTI;
                int random_flag = rand() % 2; // generate a random CRCFLAG
