                rt_dp->data_processor_count++;
            } else {
                free(new_pdu);
                pthread_mutex_unlock(&rt_dp->mutex);
                return;
            }
        }
        pthread_mutex_unlock(&rt_dp->mutex);
        break;
    }
}

// Function to print the linked list of DataProcessors
