// Structure definitions
typedef struct {
    int timestamp;
    char sensor_id[16];
    int status_flag;
} DataProcessor;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Dynamic list of DataProcessors and NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    DataProcessor* data_processors;
    size_t capacity;
    size_t size;
} RealTimeDataProcessor;

// Function prototypes
RealTimeDataProcessor* real_time_data_processor_create(size_t initial_capacity);
int real_time_data_processor_insert(RealTimeDataProcessor* processor, DataProcessor* data_processor);
int real_time_data_processor_remove(RealTimeDataProcessor* processor, DataProcessor* data_processor);
NFAPI_CRC_INDICATION_PDU_T* real_time_data_processor_get_nfa_pdu(RealTimeDataProcessor* processor, int RNTI);
void real_time_data_processor_destroy(RealTimeDataProcessor* processor);

// Implementation
RealTimeDataProcessor* real_time_data_processor_create(size_t initial_capacity) {
    RealTimeDataProcessor* processor = (RealTimeDataProcessor*)malloc(sizeof(RealTimeDataProcessor));
    processor->data_processors = (DataProcessor*)malloc(initial_capacity * sizeof(DataProcessor));
    processor->capacity = initial_capacity;
    processor->size = 0;
    return processor;
}

int real_time_data_processor_insert(RealTimeDataProcessor* processor, DataProcessor* data_processor) {
    if (processor->size >= processor->capacity) {
        // Reallocate memory with increased capacity
        size_t new_capacity = processor->capacity * 2;
        processor->data_processors = (DataProcessor*)realloc(processor->data_processors, new_capacity * sizeof(DataProcessor));
        processor->capacity = new_capacity;
    }
    memcpy(&processor->data_processors[processor->size], data_processor, sizeof(DataProcessor));
    processor->size++;
    return 0;
}

int real_time_data_processor_remove(RealTimeDataProcessor* processor, DataProcessor* data_processor) {
    // Find the target data processor
    for (size_t i = 0; i < processor->size; i++) {
        if (memcmp(&processor->data_processors[i], data_processor, sizeof(DataProcessor)) == 0) {
            // Shift all subsequent elements down
            memmove(&processor->data_processors[i], &processor->data_processors[i + 1], (processor->size - i - 1) * sizeof(DataProcessor));
            processor->size--;
            return 0;
        }
    }
    return -1; // Data processor not found
}

NFAPI_CRC_INDICATION_PDU_T* real_time_data_processor_get_nfa_pdu(RealTimeDataProcessor* processor, int RNTI) {
    for (size_t i = 0; i < processor->size; i++) {
        if (processor->data_processors[i].RNTI == RNTI) {
            return &processor->data_processors[i];
        }
    }
    // Generate a new NFAPI_CRC_INDICATION_PDU_T with unique RNTI
    int crcflag = rand();
    int rnti = rand();
    while (rnti < 0 || rnti >= processor->size) {
        rnti = rand();
    }
    NFAPI_CRC_INDICATION_PDU_T* nfa_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nfa_pdu->RX_UE_INFORMATION_TAG = 0;
    nfa_pdu->RNTI = rnti;
    nfa_pdu->CRC_INDICATION_REL8_TAG = crcflag;
    return nfa_pdu;
}

void real_time_data_processor_destroy(RealTimeDataProcessor* processor) {
    for (size_t i = 0; i < processor->size; i++) {
        free(&processor->data_processors[i]);
    }
    free(processor->data_processors);
    free(processor);
}
