    Node* prev = head;
    Node* curr = head;

    while (curr != NULL) {
        if (curr == node_to_remove) {
            if (prev->next == curr) {
                prev->next = curr->next;
                free(curr);
                return;
            } else {
                prev = curr;
                curr = curr->next;
            }
        } else {
            prev = curr;
