use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

fn check_file existence(dir_path: &str) -> Result<(String, String), io::Error> {
    let dir = Path::new(dir_path);
    if !dir.exists() {
        fs::create_dir_all(dir.as_path())?;
    }

    let file_path = dir.join("file.txt");
    if file_path.exists() {
        let meta = fs::metadata(&file_path)?;
        Ok((file_path.to_str().unwrap().to_string(), format!("{:?}", meta.modified()))
    } else {
        fs::create_file(file_path.as_path())?;
        let created_at = fs::metadata(&file_path)?.modified();
        Ok((file_path.to_str().unwrap().to_string(), format!("{:?}", created_at))
    }
}

fn main() {
    if let Err(e) = check_file existence("path/to/directory") {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    } else {
        println!("File exists: {:?}", file_path);
    }
}
