public:
    DistributedLogger(std::string name) : name_(name), storage_(nullptr), ingestionPipelines_(), filters_() {}

    void configureStorage(std::unique_ptr<BackendStorage> storage) { storage_ = std::move(storage); }

    void addIngestionPipeline(const IngestionPipeline& pipeline) {
        ingestionPipelines_.emplace_back(pipeline);
    }

    void applyFilter(const FilterRule& rule) {
        filters_.emplace_back(rule);
    }

    void ingestLogEntry(const LogEntry& entry) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& pipeline : ingestionPipelines_) {
            if (pipeline.apply(entry)) {
                processLogEntry(entry);
                break;
            }
        }
    }

    void processLogEntry(const LogEntry& entry) {
        // Process the log entry, can be modified to handle different backend storage
        if (storage_) {
            storage_->storeLogEntry(entry);
        } else {
            // Handle error if storage is not configured
        }
    }

private:
    std::string name_;
    std::unique_ptr<BackendStorage> storage_;
    std::vector<IngestionPipeline> ingestionPipelines_;
    std::vector<FilterRule> filters_;
    std::mutex mutex_;
