        };
    }

    for (tx_id, tx) in blockchain_ledger.clone() {
        update_ui_field(tx_id).await;
    }

    // Handle varying loads and scale effectively
    let thread_pool = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()?;
    let mut task_queue = Arc::new(atomic::AtomicUsize::new(0));

    async fn process_task(tx_id: &str) {
        // Acquire a lock to ensure thread safety and synchronization
        let lock = thread_pool.lock().await;

        if lock.fetch_add(1, atomic::Ordering::Relaxed) == 1 {
            // Process task only once
            println!("Processing task for transaction {}", tx_id);
        }
    }

    for (tx_id, _) in blockchain_ledger.clone() {
        process_task(tx_id).await;
