    def upload_file(self, file_path, bucket_name):
        if bucket_name == 'aws':
            self.s3.upload_file(file_path, bucket_name, os.path.basename(file_path))
        elif bucket_name == 'gcp':
            bucket = self.gcs.get_bucket(bucket_name)
            blob = bucket.blob(os.path.basename(file_path))
            blob.upload_from_string(open(file_path, 'rb').read())
        elif bucket_name == 'azure':
            container_client = self.az_blob.get_container_client(bucket_name)
            blob_client = container_client.get_blob_client(os.path.basename(file_path))
            with open(file_path, 'rb') as file:
                blob_client.upload_blob(file.read(), overwrite=True)

    def download_file(self, file_path, bucket_name):
        if bucket_name == 'aws':
            self.s3.download_file(bucket_name, os.path.basename(file_path), file_path)
        elif bucket_name == 'gcp':
            bucket = self.gcs.get_bucket(bucket_name)
            blob = bucket.blob(os.path.basename(file_path))
            with open(file_path, 'wb') as file:
