            container_client = self.az_blob.get_container_client(bucket_name)
            blob_client = container_client.get_blob_client(os.path.basename(file_path))
            with open(file_path, 'wb') as file:
                file.write(blob_client.download_blob().readall())

    def delete_file(self, file_path, bucket_name):
        if bucket_name == 'aws':
            self.s3.delete_object(Bucket=bucket_name, Key=os.path.basename(file_path))
        elif bucket_name == 'gcp':
            bucket = self.gcs.get_bucket(bucket_name)
            blob = bucket.blob(os.path.basename(file_path))
            blob.delete()
        elif bucket_name == 'azure':
            container_client = self.az_blob.get_container_client(bucket_name)
            blob_client = container_client.get_blob_client(os.path.basename(file_path))
            blob_client.delete_blob()

