import java.util.concurrent.atomic.AtomicLong;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.lang3.RandomStringUtils;

public class RealTimeFinancialMarketDataProcessingPlatform {
    private static final int THREAD_COUNT = 50;
    private static List<AtomicLong> atomicLongList = new ArrayList<>();

    public void start() {
        for (int i = 0; i < THREAD_COUNT; i++) {
            atomicLongList.add(new AtomicLong());
            Thread thread = new Thread(() -> {
                // Process data
                int currentValue = atomicLongList.get(i).incrementAndGet();
                System.out.println("Processing data: " + currentValue);
            });
            thread.start();
        }
    }

    public void stop() {
        for (Thread thread : Thread.currentThread().getStackTrace()) {
            thread.interrupt();
        }
    }

    public static void main(String[] args) {
        RealTimeFinancialMarketDataProcessingPlatform platform = new RealTimeFinancialMarketDataProcessingPlatform();
        platform.start();
        // Process data
        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            platform.stop();
        }
    }
}

