#include <iostream>
#include <fstream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <boost/asio.hpp>

class FileProcessor {
public:
    FileProcessor(const std::string& directoryPath) : directoryPath_(directoryPath), processing_(false) {}

    void start() {
        std::thread t([this]() { processFiles(); });
        t.detach();
    }

private:
    void processFiles() {
        while (true) {
            if (processing_) {
                std::this_thread::sleep_for(std::chrono::seconds(1));
                continue;
            }
            processing_ = true;

            boost::asio::io_context io;
            boost::asio::deadline_timer timer(io, std::chrono::milliseconds(1000));

            auto fileIterator = directoryPath_.begin();
            while (fileIterator != directoryPath_.end()) {
                if (!timer.expires_at(timer.expires_after(boost::posix_time::milliseconds(1000)))) {
                    break;
                }
                fileIterator++;
            }

            processing_ = false;
        }
    }

    std::string directoryPath_;
    bool processing_;
};

int main() {
    FileProcessor fp("path/to/directory");
    fp.start();
    return 0;
}
