#include <map>

class DeviceStatus {
public:
    std::string id;
    int signalStrength;
    std::chrono::time_point<std::chrono::system_clock> timestamp;

    DeviceStatus(const std::string& id, int signalStrength)
        : id(id), signalStrength(signalStrength),
          timestamp(std::chrono::system_clock::now()) {}
};

class DistributedDeviceStatus {
public:
    static const int MAX_DEVICES = 1000;
    static const int MAX_SIGNAL_STRENGTH = 100;

    std::mutex mtx;
    std::condition_variable cv;
    std::deque<DeviceStatus> devices[MAX_DEVICES];
    std::map<std::string, int> signalStrengths[MAX_DEVICES];

    void addDevice(const DeviceStatus& device) {
        int deviceId = -1;
        for (int i = 0; i < MAX_DEVICES; ++i) {
            if (devices[i].empty()) {
                deviceId = i;
                break;
            }
        }

        if (deviceId == -1) {
            throw std::runtime_error("Maximum number of devices reached.");
        }

        devices[deviceId].push_back(device);
        signalStrengths[deviceId][device.id] = device.signalStrength;
    }

    void updateSignalStrength(const std::string& deviceId, int newSignalStrength) {
        if (devices.size() <= stoi(deviceId)) {
            throw std::runtime_error("Invalid device ID.");
        }

        devices[stoi(deviceId)].front().signalStrength = newSignalStrength;
    }
};

int main() {
    DistributedDeviceStatus dd;

    try {
        DeviceStatus device1("device-1", 50);
        DeviceStatus device2("device-2", 75);

        dd.addDevice(device1);
        dd.addDevice(device2);

        dd.updateSignalStrength("0", 60);

        std::cout << "Updated signal strength: " << device1.signalStrength << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}

