#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for NetworkDeviceEvent
typedef struct {
    int eventType;
    long timestamp;
    char srcIP[16];
    char dstIP[16];
    int portNums[2];
    int severity;
} NetworkDeviceEvent;

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int CRC_INDICATION_PDU_TYPE;
    long timestamp;
    char srcMAC[18];
    char dstMAC[18];
    int portNums[2];
    int rfMetrics[10];
} NFAPI_CRC_INDICATION_PDU_T;

// Define structure for EventStream
typedef struct {
    NetworkDeviceEvent* networkEvents;
    NFAPI_CRC_INDICATION_PDU_T* crcIndications;
    int eventCount;
    pthread_mutex_t mutex;
} EventStream;

// Initialize event stream structure
void initEventStream(EventStream* es) {
    es->networkEvents = NULL;
    es->crcIndications = NULL;
    es->eventCount = 0;
    pthread_mutex_init(&es->mutex, NULL);
}

// Add network device event to the event stream
void addNetworkDeviceEvent(EventStream* es, NetworkDeviceEvent* event) {
    pthread_mutex_lock(&es->mutex);
    // Dynamically resize and append event array if necessary
    if (es->eventCount >= 10 * 1000000) {
        int newSize = es->eventCount + 100000;
        NetworkDeviceEvent* newEvents = realloc(es->networkEvents, newSize * sizeof(NetworkDeviceEvent));
        es->networkEvents = newEvents;
    }
    es->networkEvents[es->eventCount++] = *event;
    pthread_mutex_unlock(&es->mutex);
}

// Add NFAPI CRC indication PDU to the event stream
void addNFAPI_CRC_INDICATION_PDU_T(EventStream* es, NFAPI_CRC_INDICATION_PDU_T* indication) {
    pthread_mutex_lock(&es->mutex);
    // Dynamically resize and append indication array if necessary
    if (es->eventCount >= 10 * 1000000) {
        int newSize = es->eventCount + 100000;
        NFAPI_CRC_INDICATION_PDU_T* newIndications = realloc(es->crcIndications, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        es->crcIndications = newIndications;
    }
    es->crcIndications[es->eventCount++] = *indication;
    pthread_mutex_unlock(&es->mutex);
}

// Print event stream statistics
void printEventStreamStats(EventStream* es) {
    printf("Total events: %d\n", es->eventCount);
    printf("Network device events: %d\n", es->eventCount - 5000000);
    printf("NFAPI CRC indication PDUs: %d\n", 5000000);
}

// Main function
int main() {
    EventStream es;
    initEventStream(&es);

    // Simulate adding network device events and NFAPI CRC indication PDUs to the event stream
    for (int i = 0; i < 10 * 1000000; i++) {
        NetworkDeviceEvent event;
        // Fill in event fields...
        addNetworkDeviceEvent(&es, &event);

        if ((i % 50000) == 0) {
            NFAPI_CRC_INDICATION_PDU_T indication;
            // Fill in indication fields...
            addNFAPI_CRC_INDICATION_PDU_T(&es, &indication);
        }
    }

    printEventStreamStats(&es);

    return 0;
}

