        private readonly RSACryptoService _rsaCryptoService;

        public SecureDataProcessor()
        {
            _aes = Aes.Create();
            _hmacSha256 = HMACSHA256.Create();
            _rsaCryptoService = new RSACryptoService();
        }

        public async Task ProcessTransactionAsync(Transaction transaction)
        {
            // Encrypt transaction data using AES
            var encryptedData = Encrypt(transaction.Data, _aes);

            // Sign the transaction with HMAC-SHA256
            var signedData = Sign(encryptedData, _hmacSha256);

            // Use RSA for asymmetric key exchange
            var rsaKeyPair = _rsaCryptoService.GenerateKeyPair();
            var encryptedTransaction = Encrypt(signedData, rsaKeyPair.PublicKey);

            // Handle data drift and schema evolution gracefully
            await HandleSchemaEvolutionAsync(encryptedTransaction);

            // Log the transaction
            await LogTransactionAsync(encryptedTransaction);
        }

        private string Encrypt(string data, Aes aes)
