                    logging.info(f"Attack successful")
                    break
                else:
                    logging.warning(f"Attack failed: {attack_data}")
                    await asyncio.sleep(1)  # wait before retrying
            except Exception as e:
                logging.error(f"Error executing attack: {e}")
                await asyncio.sleep(1)  # wait before retrying

    async def select_attack_strategy(self):
        if self.config['attack_strategy'] == 'A':
            self.attack_strategy = strategy_a()
        elif self.config['attack_strategy'] == 'B':
            self.attack_strategy = strategy_b()
        else:
            raise Exception("Invalid attack strategy")

    async def main_loop(self):
