['Here is the C++ code block for the `DynamicNetworkHealthMonitor` service:

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include "protocol_module_base.h"
#include "metric_collector.h"
#include "alert_system.h"
#include "api_integration.h"

class DynamicNetworkHealthMonitor {
public:
    DynamicNetworkHealthMonitor();
    ~DynamicNetworkHealthMonitor();

    void startMonitoring();
    void stopMonitoring();

    void addProtocolModule(ProtocolModuleBase* module);
    void removeProtocolModule(ProtocolModuleBase* module);

private:
    std::vector<ProtocolModuleBase*> protocolModules_;
    MetricCollector metricCollector_;
    AlertSystem alertSystem_;
    APIIntegration apiIntegration_;

    std::mutex mutex_;
    std::condition_variable conditionVariable_;
    std::queue<std::function<void()>> tasksQueue_;
};

DynamicNetworkHealthMonitor::DynamicNetworkHealthMonitor() {
    // Initialize protocol modules
    addProtocolModule(new HTTPProtocolModule());
    addProtocolModule(new TCPProtocolModule());
    addProtocolModule(new UDPProtocolModule());
    addProtocolModule(new MQTTProtocolModule());
    addProtocolModule(new WebSocketProtocolModule());

    // Start metric collector and alert system
    metricCollector_.start();
    alertSystem_.start();

    // Initialize API integration
    apiIntegration_.init();
}

DynamicNetworkHealthMonitor::~DynamicNetworkHealthMonitor() {
    // Stop monitoring
    stopMonitoring();

    // Remove protocol modules
    for (auto& module : protocolModules_) {
        removeProtocolModule(module);
    }

    // Clean up metric collector and alert system
    metricCollector_.stop();
    alertSystem_.stop();

    // Shutdown API integration
    apiIntegration_.shutdown();
}

void DynamicNetworkHealthMonitor::startMonitoring() {
    // Start monitoring tasks in a separate thread
    std::thread monitorThread([this]() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            conditionVariable_.wait(lock);
            if (!tasksQueue_.empty()) {
                auto task = tasksQueue_.front();
                task();
                tasksQueue_.pop();
            }
        }
    });
    monitorThread.detach();
}

void DynamicNetworkHealthMonitor::stopMonitoring() {
    // Stop monitoring tasks
    tasksQueue_.clear();

    // Notify the monitoring thread to stop
    conditionVariable_.notify_one();
}

void DynamicNetworkHealthMonitor::addProtocolModule(ProtocolModuleBase* module) {
    protocolModules_.push_back(module);
}

void DynamicNetworkHealthMonitor::removeProtocolModule(ProtocolModuleBase* module) {
    auto it = std::find(protocolModules_.begin(), protocolModules_.end(), module);
    if (it != protocolModules_.end()) {
        protocolModules_.erase(it);
    }
}
