['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a bundle
typedef struct {
    char* data;
    int size;
} Bundle;

// Define the structure for a resource manager
typedef struct {
    pthread_mutex_t lock;
    Bundle* bundles;
    int bundle_count;
    int max_bundle_size;
    int cache_size;
    int compression_level;
    pthread_cond_t cond;
} ResourceManager;

// Initialize the resource manager
ResourceManager* init_resource_manager(int max_bundle_size, int cache_size) {
    ResourceManager* rm = (ResourceManager*) malloc(sizeof(ResourceManager));
    rm->bundle_count = 0;
    rm->max_bundle_size = max_bundle_size;
    rm->cache_size = cache_size;
    pthread_mutex_init(&rm->lock, NULL);
    pthread_cond_init(&rm->cond, NULL);
    return rm;
}

// Load a bundle into the resource manager
void load_bundle(ResourceManager* rm, char* data, int size) {
    Bundle* bundle = (Bundle*) malloc(sizeof(Bundle));
    bundle->data = (char*) malloc(size);
    memcpy(bundle->data, data, size);
    bundle->size = size;
    pthread_mutex_lock(&rm->lock);
    rm->bundles = realloc(rm->bundles, (rm->bundle_count + 1) * sizeof(Bundle));
    rm->bundles[rm->bundle_count] = *bundle;
    rm->bundle_count++;
    free(bundle->data);
    free(bundle);
    pthread_mutex_unlock(&rm->lock);
}

//Unload a bundle from the resource manager
void unload_bundle(ResourceManager* rm, int index) {
    if (index >= 0 && index < rm->bundle_count) {
        pthread_mutex_lock(&rm->lock);
        Bundle* bundle = &rm->bundles[index];
        free(bundle->data);
        free(bundle);
        memmove(&rm->bundles[index], &rm->bundles[index + 1], (rm->bundle_count - index - 1) * sizeof(Bundle));
        rm->bundle_count--;
        pthread_mutex_unlock(&rm->lock);
    }
}

// Get a bundle from the resource manager
Bundle* get_bundle(ResourceManager* rm, int index) {
    Bundle* bundle;
    if (index >= 0 && index < rm->bundle_count) {
        pthread_mutex_lock(&rm->lock);
        bundle = &rm->bundles[index];
        pthread_mutex_unlock(&rm->lock);
    } else {
        bundle = NULL;
    }
    return bundle;
}

// Check if a resource manager is empty
int is_empty(ResourceManager* rm) {
    int result = 1;
    pthread_mutex_lock(&rm->lock);
    result = (rm->bundle_count == 0);
    pthread_mutex_unlock(&rm->lock);
    return result;
}

// Destroy the resource manager
void destroy_resource_manager(ResourceManager* rm) {
    for (int i = 0; i < rm->bundle_count; i++) {
        unload_bundle(rm, i);
    }
    free(rm->bundles);
    pthread_mutex_destroy(&rm->lock);
    pthread_cond_destroy(&rm->cond);
    free(rm);
}

// Thread function to load bundles concurrently
void* thread_load_bundles(void* arg) {
    ResourceManager* rm = (ResourceManager*) arg;
    // Load bundles concurrently
    for (int i = 0; i < 10; i++) {
        load_bundle(rm, "Bundle_data", 1024);
    }
    return NULL;
}

// Main function to test the resource manager
int main() {
    ResourceManager* rm = init_resource_manager(100, 10000);
    pthread_t thread;

    // Create a new thread to load bundles concurrently
    pthread_create(&thread, NULL, thread_load_bundles, rm);

    // Load bundles sequentially
    for (int i = 0; i < 10; i++) {
        load_bundle(rm, "Bundle_data", 1024);
    }

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Unload bundles
    for (int i = 0; i < rm->bundle_count; i++) {
        unload_bundle(rm, i);
    }

    // Destroy the resource manager
    destroy_resource_manager(rm);

    return 0;
}
