        private readonly IMongoDatabase _mongoDatabase;
        private readonly IAmazonS3 _amazonS3;
        private readonly CloudBlobClient _azureBlobClient;

        public MediaProcessingService(IMongoDatabase mongoDatabase, IAmazonS3 amazonS3, CloudBlobClient azureBlobClient)
        {
            _mongoDatabase = mongoDatabase;
            _amazonS3 = amazonS3;
            _azureBlobClient = azureBlobClient;
        }

        public async Task ProcessMediaFilesAsync(List<string> filePaths)
        {
            // Validate and generate metadata for each file
            var filesWithMetadata = new List<FileWithMetadata>();
            foreach (var filePath in filePaths)
            {
                try
                {
                    var fileMetadata = GenerateFileMetadata(filePath);
                    filesWithMetadata.Add(new FileWithMetadata { FilePath = filePath, Metadata = fileMetadata });
                }
                catch (Exception ex)
                {
                    // Log error and skip invalid file
                    await LogErrorAsync(ex, filePath);
                    continue;
                }
            }

            // Store metadata securely in MongoDB
            await _mongoDatabase.GetCollection<FileWithMetadata>("files").InsertManyAsync(filesWithMetadata);

            // Apply transformations and filters to media files asynchronously
            var tasks = new List<Task>();
            foreach (var fileWithMetadata in filesWithMetadata)
            {
                try
                {
                    var task = ProcessMediaFileAsync(fileWithMetadata);
                    tasks.Add(task);
                }
                catch (Exception ex)
                {
                    // Log error and skip failed processing
                    await LogErrorAsync(ex, fileWithMetadata.FilePath);
                    continue;
                }
            }

            // Wait for all tasks to complete and handle any exceptions
            try
            {
                await Task.WhenAll(tasks);
            }
            catch (AggregateException ex)
            {
                // Handle aggregate exception
                foreach (var innerEx in ex.InnerExceptions)
