// Define the NFAPI_CRC_INDICATION_PDU_T struct
typedef struct {
    int rnti;
    char data[256];
} NFAPI_CRC_INDICATION_PDU_T;

// Function to populate CRC indications
void populate_crc_indications(int num_instances, int* instances) {
    for (int i = 0; i < num_instances; i++) {
        // Initialize the NFAPI_CRC_INDICATION_PDU_T struct
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = i + 1;
        strcpy(pdu.data, "CRC Indication PDU");

        // Asynchronous execution using pthreads
        #ifdef _WIN32
            _beginthread(&populate_crc_indications_thread, 0, &pdu);
        #else
            pthread_create(&instances[i], NULL, (void*)populate_crc_indications_thread, &pdu);
        #endif

    }
}

// Thread function to handle CRC indications
void* populate_crc_indications_thread(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)arg;
    // Simulate asynchronous execution and data processing
    sleep(1);
    printf("Instance %d: CRC Indication PDU processed\n", pdu->rnti);

    return NULL;
}
